ll disp(ll n, ll k){
	ll res=1;
	if(k<n/2)k=n-k;
	for(ll i=k+1; i<=n; ++i)res*=i;
	for(ll i=2; i<=n-k; ++i)res/=i;
	return res;
}


int main(){
