bool solve(vector<int> &a)
{
	map<int, int> cnt;
	for(int x:a)
	{
		cnt[-x]++;
	}

	if (cnt.begin()->second > 1) return false;
	int c = 1;
	auto it = cnt.begin();
	it++;
	while (it != cnt.end())
	{
		if (it->second > c) return false;
		c+=it->second;

		it++;
	}

	return true;
}

