  }

  std::sort(all(s),std::greater<ll>());

  BinaryIndexedTree<ll> count((1<<n));

  count.add(s[0],1);

  ll now=1;

  rep(i,0,n){
    std::vector<P> temp;
    ll prev=s[now],cnt=1;
    rep(j,now+1,now+(1<<i)){
      if(s[j]!=prev){
