void solve() {
	cin >> N;
	rep(i, 1 << N) cin >> S[i];
	sort(S, S + (1 << N));
	reverse(S, S + (1 << N));
	ans[0] = S[0];
	rep(i, N) {
		lar[i] = 1 << i;
	}
	rep(i, 1 << N) {
		rep(j, N) {
			if (lar[j] == (1 << (j + 1))) continue;
			if (ans[lar[j] - (1 << j)] > S[i]) {
				ans[lar[j]] = S[i];
				lar[j]++;
				break;
			}
		}
	}
	judge = true;
	rep(i, N) {
		if (lar[i] != (1 << (i + 1))) judge = false;
	}
	if (judge) {
		cout << "Yes" << endl;
	}
	else {
		cout << "No" << endl;
	}
}

