void compress(vector<int> &v){
    int N = v.size(), mn = 1000000000;
    vector<pair<int,int>> a(N);
    for(int i=0; i<N; ++i){
        a[i].first = v[i];
        a[i].second = i;
        mn = min(mn, v[i]);
    }
    sort(a.begin(), a.end());

    int prev = mn-1, n = -1;
    for(int i=0; i<N; ++i){
        if(a[i].first == prev) v[a[i].second] = n;
        else{
            n++;
            prev = a[i].first;
            v[a[i].second] = n;
        }
    }
}

void Main(){
    int N; cin >> N;
    VI S(1<<N); REP(i,1<<N) cin >> S[i]; SORT(S); compress(S);

    VI b(S);
    queue<P> q; q.emplace(b.back(), N); b.pop_back();
    while(q.size()){
        P p = q.front(); q.pop();
        int h = p.first, n = p.second;
        REP(i,n){
            if(b.back() < h){
                q.emplace(b.back(), n-1-i);
                b.pop_back();
            }
        }
    }

    if(b.size() && b.back()>0){
        cout << "No" << en;
        return;
    }

    int t = b.size();

    deque<int> a; REP(i,1<<N) a.push_back(S[i]);

    q.emplace(a.back(), N); a.pop_back();
    while(q.size()){
        P p = q.front(); q.pop();
        int h = p.first, n = p.second;
        if(h == 0){
            cout << "No" << en;
            return;
        }
        REP(i,n){
            P nxt = q.front();
            if(i == n-1 && t>0 && a.size() && a.back()<nxt.first){
                t--;
                a.pop_front();
            }
            else if(a.back() < h){
                if(i<n-1) q.emplace(a.back(), n-1-i);
                a.pop_back();
            }
        }
    }

    cout << (a.empty() ? "Yes" : "No") << en;
    return;
}

