int N;
ll S[1<<18];

void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N;
	FOR(i,1<<N) cin>>S[i];
	sort(S,S+(1<<N));
	int M=(1<<N)-1;
	multiset<int> T;
	FOR(i,M) T.insert(S[i]);

	vector<int> V;
	V.push_back(S[M]);
	FOR(i,N) {
		vector<int> W=V;

		FORR(v,V) {
			auto it=T.lower_bound(v);
			if(it==T.begin()) return _P("No\n");
			it--;
			W.push_back(*it);
			T.erase(it);
		}

		sort(ALL(W));
		reverse(ALL(W));
		swap(V,W);
	}
	_P("Yes\n");

}


