bool Valid(vector<int> &vec)
{
    sort(vec.begin(), vec.end(), greater<int>());

    int limit = 1;
    int index = 0;

    for (size_t i = 1; i < vec.size(); i += 1) {
        if (vec[i] >= vec[index]) {
            return false;
        }

        index += 1;
        if (index >= limit) {
            limit *= 2;
            index = 0;
        }
    }
    return true;
}

