  cin >> N;

  priority_queue<int> seq;
  priority_queue<int, vector<int>, greater<int> > slime;
  priority_queue<int> slime_done;
  priority_queue<int> slime_hold;
  for (int i = 0; i < (int)pow(2, N); i++) {
    cin >> temp;
    seq.push(temp);
  }
  slime.push(seq.top());
  seq.pop();

  for (int i = 0; i < N; i++) {
    for (int j = 0; j < (int)pow(2, i); j++) {
      if (seq.empty()) {
        puts("No");
        return 0;
      } else if (seq.top() >= slime.top()) {
        while (!slime.empty() && seq.top() >= slime.top()) {
          slime_hold.push(slime.top());
          slime.pop();
        }
        if (slime.empty() && slime_done.empty()) {
          puts("No");
          return 0;
        } else if (slime.empty()) {
          while (!slime_hold.empty()) {
            slime.push(slime_hold.top());
            slime_hold.pop();
          }
          break;
        } else {
          slime_done.push(seq.top());
          seq.pop();
          slime_done.push(slime.top());
          slime.pop();
          while (!slime_hold.empty()) {
            slime.push(slime_hold.top());
            slime_hold.pop();
          }
        }
      } else {
        slime_done.push(seq.top());
        seq.pop();
        slime_done.push(slime.top());
        slime.pop();
      }
    }
    while (!slime_done.empty()) {
      slime.push(slime_done.top());
      slime_done.pop();
    }
  }
  if (!seq.empty()) {
    puts("No");
    return 0;
  }
  puts("Yes");

  return 0;
}

