	reverse(s,s+(1<<n));
	//最初は最大で固定
	v[0].push_back(s[0]);
	st.erase(s[0]);
	int cnt=0;
	while(st.size()>(1<<(n-1)))
	{
		cnt++;
		//cerr<<"loop"<<cnt<<endl;
		v[cnt&1].clear();
		for(int i=0;i<v[(cnt+1)&1].size();i++)
		{
			v[cnt&1].push_back(v[(cnt+1)&1][i]);
			//上回らない最大の数を探す
			auto itr=st.lower_bound(v[(cnt+1)&1][i]);
			if(itr==st.begin())
			{
				ans=false;
				break;
			}
			itr--;
			//cerr<<(*itr)<<endl;
			v[cnt&1].push_back(*itr);
			st.erase(*itr);
		}
		if(!ans)
			break;
		sort(v[cnt&1].begin(),v[cnt&1].end());
		reverse(v[cnt&1].begin(),v[cnt&1].end());
	}
	//最後に残ったものを順番に割付
	sort(v[cnt&1].begin(),v[cnt&1].end());
	auto itr=st.begin();
	for(int i=0;i<v[cnt&1].size();i++)
	{
		if((*itr)>=v[cnt&1][i])
		{
			ans=false;
			break;
		}
		itr++;
	}
	if(ans)
		cout<<"Yes"<<endl;
	else
		cout<<"No"<<endl;
	return 0;
}

