long long n;
vector<long long> s;

bool solve();

int main() {
  cin >> n;
  s.resize(1LL << n);
  for(long long i = 0; i < (1LL << n); ++i) cin >> s[i];
  sort(s.begin(), s.end(), greater<long long>());
  if(solve())
    cout << "Yes" << endl;
  else
    cout << "No" << endl;
  return 0;
}

bool solve() {
  vector<long long> memo(1LL << n, 0);
  long long now = n, next = n;
  for(long long i = 0; i < n; ++i) {
    memo[i] = now--;
    if(now == 0) now = max(--next, 0LL);
  }
  now = 1;
  for(int i = 0; i < n; ++i) {
    if(now >= n) break;
    if(s[i] == s[now]) return 0;
    now += memo[i];
  }
  return 1;
}

