	}

	AVL_tree<int> cm;
	cm.insert(mm.prev(mm.end())->value);
	mm.erase(mm.prev(mm.end()));

	bool ans = true;
	while (ans && !mm.empty()) {
		AVL_tree<int> nm;
		auto it = cm.prev(cm.end());
		while (it) {
			auto tar = mm.lower_bound(it->value);

			if (tar == mm.begin()) {
				ans = false;
				break;
			}
			else {
				tar = mm.prev(tar);
				nm.insert(it->value);
				nm.insert(tar->value);
				mm.erase(tar);
			}
			it = cm.prev(it);
		}

		cm = nm;

	}

	puts(ans ? "Yes": "No");


	return 0;
}

