  sort(S.begin(), S.end());
  vector<ll> vec;
  ll t = -1;
  {
    ll prev = -1;
    for (ll x : S) {
      if (x == prev) {
	vec[t]++;
      }else {
	t++;
	vec.push_back(1);
	prev = x;
      }
    }
  }
  ll top = t;
  vector<ll> leaf(top + 1);
  leaf[top] = 1;
  vec[top]--;
  DLOG("leaf=", leaf);
  DLOG("vec=", vec);
  for (ll r = 0; r < N; r++) {
    vector<pair<ll, ll>> newleaf;
    t = top;
    for (ll i = top; i >= 0 && leaf[i] > 0; i--) {
      ll rest = leaf[i];
      while (true) {
	for (t = min(t, i-1); t >= 0 && vec[t] == 0; t--);
	if (t < 0) {
	  cout << "No\n";
	  return 0;
	}
	if (rest <= vec[t]) {
	  newleaf.emplace_back(t, rest);
	  vec[t] -= rest;
	  break;
	}else {
	  rest -= vec[t];
	  newleaf.emplace_back(t, vec[t]);
	  vec[t] = 0;
	}
      }
    }
    for (auto [tt, nn] : newleaf) leaf[tt] += nn;
    DLOG("r=", r);
    DLOG("leaf=", leaf);
    DLOG("vec=", vec);
  }
  cout << "Yes\n";

