int intlog2(int x){
  if(x==0 ) return 1;
  FOR(i,1,31){
    if( (x>>i)==0 && (x>>(i-1))>0 ) return i; 
  }
  return 0;
}


void solve(){
  int n; cin >> n;
  V<ll> a((1<<n));
  FOR(i,0,(1<<n)) cin >> a[i];
  sort(ALL(a));
  reverse(ALL(a));
  if(a[0]==a[1]){
    cout << "No" << '\n';
    return;
  }
  if(n>1){
  FOR(i,1, (1<<(n-1)) ){
    int p = intlog2(i);
    if( a[i] == a[(1<<(p))+i]) {
      cout << "No" << '\n';
      return;
    }
  }
  }
  cout << "Yes" << '\n';
}

