int m, a[N];
vector<int> f;
int g[N];

inline int Lowbit(int x)
{
    return x & -x;
}

void AddFenwick(int p)
{
    for(; p <= m; p += Lowbit(p))
        g[p] ++;

    return;
}

int SumFenwick(int p)
{
    int o;

    for(o = 0; p; p -= Lowbit(p))
        o += g[p];

    return o;
}

int BSFindA(int v)
{
    int l, m, r;

    for(l = 0, r = ::m; l + 1 < r; )
    {
        m = (l + r) >> 1;
        if(a[m] < v)
            r = m;
        else
            l = m;
    }

    return r;
}

int BSFindB(int p)
{
    int l, m, r;
    int v;

    v = SumFenwick(p);
    for(l = p - 1, r = ::m; l + 1 < r; )
    {
        m = (l + r) >> 1;
        if(SumFenwick(m + 1) - v != m - p + 1)
            r = m;
        else
            l = m;
    }

    return r;
}

int main(void)
{
    int n;
    int i, j, k, p;

    scanf("%d", &n);
    m = 1 << n;
    for(i = 0; i < m; i ++)
        scanf("%d", &a[i]);
    sort(a, a + m, greater<int>());

    f.push_back(a[0]);
    AddFenwick(1);
    for(i = 0, j = 1; i < n; i ++, j = k)
    {
        sort(f.begin(), f.end());
        for(k = j; k < j + (1 << i); k ++)
        {
            // printf("%d : %d %d\n", k, f.at(k - j), a[k]);
            p = BSFindB(BSFindA(f.at(k - j)));
            // printf("%d : %d\n", f.at(k - j), p);
            if(p == m)
            {
                printf("No\n");

                return 0;
            }
            AddFenwick(p + 1);
            f.push_back(a[p]);
        }
    }
    printf("Yes\n");

    return 0;
}

