  vector<int64> parent;
  parent.push_back(s.top());
  s.pop();
  for (int t = 0; t < n; ++t)
  {
    vector<int64> currentParent = parent;
    for (int64 i = 0; i < currentParent.size(); ++i)
    {
      int64 child = s.top();
      if (child < currentParent[i])
      {
        s.pop();
        parent.push_back(child);
      }
      else
      {
        cout << "No" << endl;
        return 0;
      }
    }
  }

  cout << "Yes" << endl;
  return 0;
}

