using namespace std;

vector<int> groupby(vector<int> ss) {
  vector<int> ss_counts; // 同じ数値をひとまとめに
  int count = 0;
  int old_s = ss[0];
  for (const auto& s : ss) {
    if (s == old_s) {
      count++;
    } else {
      ss_counts.emplace_back(count);
      count = 1;
    }

    old_s = s;
  }
  ss_counts.emplace_back(count);

  return ss_counts;
}

int main() {
  int n;
  cin >> n;
  vector<int> ss(pow(2,n));

  for (int i = 0; i < pow(2,n); i++) {
    cin >> ss[i];
  }
  sort(ss.begin(), ss.end(), greater<>()); // 大きい順に並べる

  const vector<int>& ss_counts = groupby(ss);

  priority_queue<int> slims; // 連結成分。値は完全二分木の木の高さ。要素が大きい方から使う。
  slims.push(n); // 最初は完全2分木の根。

  bool result = true;

  for (const auto& ss_count : ss_counts) {
    if (slims.size() < ss_count) {
      // 同じ数値を処理しきれない
      result = false;
      break;
    }

    stack<int> same_ss;
    for (int i = 0; i < ss_count; i++) {
      // 今あるところから処理するため、いったんstackに貯める
      int slim = slims.top();
      slims.pop();
      same_ss.push(slim);
    }

    while (!same_ss.empty()) {
      int slim = same_ss.top();
      same_ss.pop();

      if (slim > 0) { // 葉っぱじゃなければ
        // 2個の子ツリーに分割して、再度候補とする
        slims.push(slim - 1);
        slims.push(slim - 1);
