struct Node
{
	int count = 1;
	Node* lesser = nullptr;
	int v;
};

bool Check( int n, Node* nodeList )
{
	do
	{
		if( nodeList == nullptr ) return false;
		if( nodeList->count > 0 ) break;
		nodeList = nodeList->lesser;
	} while( true );
	for( int i = n - 1; i >= 0; i-- )
		if( ! Check( i, nodeList->lesser ) ) return false;
	nodeList->count--;
	return true;
}

bool Judge( int n, const std::vector<int>& _values )
{
	std::vector<int> values = _values;
	std::sort( values.begin(), values.end() );
	Node* nodeList = nullptr;
	int prev = -1;
	for( int v : values )
	{
		if( prev == v ) { nodeList->count++; }
		else
		{
			Node* n = new Node;
			n->v = v;
			n->lesser = nodeList;
			nodeList = n;
			prev = v;
		}
	}
	return Check( n, nodeList );
}

