const int MAXN=1000010,INF=1e9;
int n,mx,x,rt,tot,val[MAXN<<3],ch[MAXN<<3][2];
priority_queue < pair<int,int> > q;
void add (int &p,int l,int r,int pos,int v) {
	if (pos==0) {return;}
	if (!p) {p=++tot;}
	val[p]+=v;
	if (l==r) {return;}
	int mid=(l+r)>>1;
	if (pos<=mid) {add(ch[p][0],l,mid,pos,v);}
	else {add(ch[p][1],mid+1,r,pos,v);}
	return;
}
int query (int p,int l,int r,int xl,int xr) {
	if (xl>xr) {return 0;}
	if (xr<l||r<xl) {return 0;}
	if (xl<=l&&r<=xr) {return val[p];}
	int mid=(l+r)>>1;
	return query(ch[p][0],l,mid,xl,xr)+query(ch[p][1],mid+1,r,xl,xr);
}
int kth (int p,int l,int r,int k) {
	if (k==0) {return 0;}
	if (l==r) {return l;}
	int mid=(l+r)>>1;
	if (val[ch[p][0]]>=k) {return kth(ch[p][0],l,mid,k);}
	else {return kth(ch[p][1],mid+1,r,k-val[ch[p][0]]);}
}
int main () {
	scanf("%d",&n);
	for (int i=1;i<=(1<<n);i++) {
		scanf("%d",&x);
		add(rt,1,INF,x,1);
		mx=max(mx,x);
	}
	add(rt,1,INF,mx,-1);
	q.push(make_pair(mx,n));
	while (!q.empty()) {
		pair<int,int> a=q.top();
		q.pop();
		for (int i=1;i<=a.second;i++) {
			int k=query(rt,1,INF,1,a.first-1);
			int pos=kth(rt,1,INF,k);
			add(rt,1,INF,pos,-1);
			q.push(make_pair(pos,a.second-i));
		}
	}
	if (query(rt,1,INF,1,INF)) {printf("No\n");}
	else {printf("Yes\n");}
	return 0;
}

