namespace nt {
    template<typename T, typename U>
    T pow(T n, U p) {
        T res = 1;
        while (p > 0) {
            if (p % 2 == 1) {
                res *= n;
            }
            n *= n;
            p /= 2;
        }
        return res;
    }
}

int main() {
    int n;
    std::cin >> n;
    int m = nt::pow(2, n);
    std::vector<int> s(m);
    std::map<int, int> num;
    for (int i = 0; i < m; i++) {
        std::cin >> s[i];
        s[i] *= -1;
        num[s[i]]++;
    }
    std::sort(s.begin(), s.end());

    std::vector<int> now;
    now.push_back(s[0]);
    num[s[0]]--;
    if (num[s[0]] == 0) {
        num.erase(s[0]);
    }

    bool can = true;
    for (int i = 1; i <= n; i++) {
        int k = now.size();
        // k 個作る
        for (int j = 0; j < k; j++) {
            auto it = num.upper_bound(now[j]);
            if (it == num.end())  {
                can = false;
                goto end;
            }
            int cr = it->first;
            now.push_back(cr);
            num[cr]--;
            if (num[cr] == 0) {
                num.erase(cr);
            }
        }
    }

  end:
    if (can) {
        std::cout << "Yes" << std::endl;
    } else {
        std::cout << "No" << std::endl;
    }

    return 0;
}

