	for(int i = 0; i < sz; ++i) {
		if(i < sz / 2) {
			left.push_back(arr[i]);
		} else {
			right.push_back(arr[i]);
		}
	}

	int l = 0, r = (sz / 2) - 1;

	for(int i = 0; i < sz / 2; ++i) {
		if(right[i] != left[l]) {
			++l;
		} else if(right[i] != left[r]) {
			--r;
		} else {
			return 0;
		}
	}

	return check(right);
}

