    vector<int> s(V);
    rep(i, V) input(s[i]);

    sort(all(s));

    Node *tree = buildTree(nullptr, N);

    auto itr = s.begin();

    reps(i, 0, N) {
        for (Node *v : nodep[i]) {
            v->value = *(itr++);
        }
    }

    bool can = true;
    reps(i, 0, N - 1) {
        for (Node *v : nodep[i]) {
            Node *par = v->par;
            if (v->value >= par->value) can = false;
        }
    }

    print(can ? "Yes" : "No");

    deleteTree(tree);

    return 0;
}

