int mpow(int a, int b) {
	int res = 1;
	rep(i, b)res *= a;
	return res;
}

bool judge(priority_queue<int>& me, priority_queue<int>& opp) {
	priority_queue<int> me_clear, opp_leave;
	while (!me.empty()) {
		int now = me.top(); me.pop();
		while (!opp.empty() && opp.top() >= now) {
			opp_leave.push(opp.top());
			opp.pop();
		}
		if (opp.empty()) {
			return false;
		}
		me_clear.push(now);
		me_clear.push(opp.top()); opp.pop();
	}
	me = me_clear;
	while (!opp_leave.empty()) {
		opp.push(opp_leave.top());
		opp_leave.pop();
	}
	return true;
}

int main()
{
	int N;
	cin >> N;

	int total = mpow(2, N);
	vector<int> S(total);
	rep(i, total)cin >> S[i];
	priority_queue<int> me, opp;
	for (int num : S)opp.push(num);
	me.push(opp.top()); opp.pop();

	bool res = true;
	rep(i, N)if (!judge(me, opp)) {
		res = false;
		break;
	}
	cout << (res ? "Yes" : "No") << endl;
	return 0;
}

