				if(div+nx[k]> counter[k])
				{
					div-=counter[k]-nx[k];
					nx[k] = counter[k];
				}
				else
				{
					nx[k] += div;
					break;
				}
			}
		}
		for(j=1;j<=N;++j)
		{
			caps[j] = nx[j];
		}
	}

	for(i=0;i<N;++i)
	{
		if(caps[i] != counter[i])
		{
			cout << "No" << endl;
			return 0;
		}
	}
	cout << "Yes" << endl;
	return 0;
}

