//nを0に
void segchange(int n, int k = 1, int l = 0, int r = -1) {
	if(r == -1)r = seg.size() / 2 - 1;
	if (l == n && r == n)seg[k] = 0;
	else if (l <= n && n <= r) {
		segchange(n, 2 * k, l, (l + r) / 2);
		segchange(n, 2 * k + 1, (l + r) / 2 + 1, r);
		seg[k] = max(seg[2 * k], seg[2 * k + 1]);
	}
}

int segget(int a, int b, int k = 1, int l = 0, int r = -1) {
	if (r == -1)r = seg.size() / 2 - 1;
	if (r < a || b < l)return 0;
	if (a <= l && r <= b)return seg[k];
	else return max(segget(a, b, 2 * k, l, (l + r) / 2), segget(a, b, 2 * k + 1, (l + r) / 2 + 1, r));
}

void solve() {
	cin >> N;
	seg.clear();
	seg.resize(1 << (N+1));
	for (int n = 0; n < (1 << N); n++)cin >> seg[n+(1 << N)];
	sort(seg.begin()+(1 << N), seg.end());
	for (int k = (1 << N) - 1; k >= 1; k--)seg[k] = max(seg[2 * k], seg[2 * k + 1]);
	arr.clear();
	arr.resize(1 << N);
	arr[0].t = 0;
	int arrpos = 1;
	queue<pair<int, int>> q;
	q.push(pair<int, int>(0, 0));
	while (!q.empty()) {
		int cur = q.front().first;
		int cn = q.front().second;
		q.pop();
		arr[cur].t = cn;
		arr[cur].childs.resize(N - arr[cur].t);
		if (cn == N)continue;
		for (int n = 0; n < arr[cur].childs.size(); n++) {
			arr[cur].childs[n] = arrpos++;
			q.push(pair<int, int>(arr[cur].childs[n], arr[cur].t + n + 1));
		}
	}
	arr[0].p = INT_MAX;
	queue<int> qq;
	qq.push(0);
	while (!qq.empty()) {
		int cur = qq.front();
		qq.pop();
		int s = 0, e = (1 << N) - 1;
		//seg[s]まで<p,seg[e]から>=p
		while (e - s > 1) {
			int m = (e + s) / 2;
			if (segget(0, m) < arr[cur].p)s = m;
			else e = m;
		}
		if (segget(0, s) == 0) {
			cout << "No" << endl;
			return;
		}
		int ss = 0, ee = s;
		while (e - s > 1) {
			int m = (ee + ss) / 2;
			if (segget(m, s) == 0)ee = m;
			else ss = m;
		}
		segchange(ss);
		arr[cur].my = segget(0, s);
		if (arr[cur].my >= arr[cur].p) {
			cout << "No" << endl;
			return;
		}
		for (int i = 0; i < arr[cur].childs.size(); i++) {
			arr[arr[cur].childs[i]].p = arr[cur].my;
			qq.push(arr[cur].childs[i]);
		}
	}
	cout << "Yes" << endl;
	return;
}

