const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n;
vl as;
vl cnt, exist, locs;

void solve(){
    ll m = 1LL << n;
    as = vl(m);
    rep(i, m) in1(as[i]);
    sort(rall(as));

    cnt.pb(1); ll idx = 0;
    rep(i, m - 1){
        if (as[i + 1] == as[i]) cnt[idx]++;
        else cnt.pb(1), idx++;
    }

    exist = locs = vl(cnt.size(), 0);
    ll n_types = cnt.size();
    rep(i, n_types) locs[i] = i - 1;

    cnt[n_types - 1]--, exist[n_types - 1]++;
    rep(_, n){
        vl nxt(n_types, 0);

        revrep(i, n_types){
            if(exist[i]){
                ll num = exist[i]; ll& loc = locs[i];

                while (num > 0){
                    if (loc < 0){prl("No"); return;}
                    if (0 < cnt[loc] && cnt[loc] < num) 
                        nxt[loc] += cnt[loc], num -= cnt[loc], cnt[loc] = 0;
                    else if (cnt[loc] >= num) 
                        nxt[loc] += num, cnt[loc] -= num, num = 0;
                    else loc--;
                }
            }
        }
        rep(i, n_types) exist[i] += nxt[i];
    }

    okay = true;
    rep(i, n_types) if (cnt[i]) okay = false; 

    yn(okay);
}

int main(void){
    in1(n);
    // assert(k <= 100000);
    solve();
    return 0;
}

