#define MAXN (1 << 18) + 3

bool solve(int S[], int l, int r) {
  int half = (r - l + 1)/2;
  if (half == 0)
    return true;

  int mid = (l + r)/2;

  bool valid = true;
  for (int i = 0; i < half; i++) {
    if (S[mid - i] >= S[r - i])
      valid = false;
  }

  if (!valid)
    return false;
  else
    return solve(S, mid + 1, r);
}

int main() {
  int N, S[MAXN + 3];

  cin >> N;
  for (int i = 0; i < (1 << N); i++)
    cin >> S[i];

  sort(S, S + (1 << N));

  if (solve(S, 0, (1 << N) - 1))
    cout << "Yes\n";
  else
    cout << "No\n";
}

