int main() {
    int N;
    cin >> N;
    int M = pow(2, N);
    multiset<int> A;
    rep(i, M) {
        int x;
        cin >> x;
        A.insert(x);
    }
    ll possible = 1;
    set<int> st;
    for (int a : A) {
        st.insert(a);
    }
    int coef = N;
    auto it = st.rbegin();
    while (it != st.rend() && coef >= 0) {
        int x = *it;
        int cnt = A.count(x);
        if (cnt > possible) {
            puts("No");
            return 0;
        }
        int next = possible * coef;
        rep(i, N - coef) next /= 2; // テスト
        possible -= cnt;
        it++;
        while (possible > 0 && it != st.rend()) {
            x = *it;
            cnt = A.count(x);
            if (cnt > possible) {
                // 途中で終わり
                // possible -= cnt;
                // next += cnt * coef + possible;
                rep(i, cnt) {
                    A.erase(A.find(x));
                }
                break;
            } else {
                possible -= cnt;
                // next += cnt * coef;
                it++;
            }
        }
        possible = next;
        coef--;
        // 次のターンへ
    }
    puts("Yes");
    return 0;
