        for (auto i : children) {
            auto it = par.upper_bound(i);
            if (it == par.end()) continue;
            par.erase(it);
        }
        if (!valid)
            break;

        for (auto i : children) {
            parents.push_back(i);
        }
        s++;
    }
    if (parents.size() == (1 << n)) {
        cout << "Yes";
    }
    else {
        cout << "No";
    }

}

