typedef long long ll;
struct segtree{
private:
  ll siz,add,n_pos,width;
  vector<ll> node;
  vector<bool> used;
public:
  segtree(ll n){
    siz=1;
    while(siz<=n) siz*=2;
    node.resize(siz*2+1,0);
    used.resize(n+5,false);
    n_pos=0;
    add=siz/2;
    width=n;
  }
  bool upd(ll pos,ll x){
    pos+=siz-1;
    node[pos]=x;
    bool ret=true;
    while(pos>0){
      pos=(pos-1)/2;
      node[pos]=max(node[2*pos+1],node[2*pos+2]);
      if(node[2*pos+1]==node[2*pos+2]) ret=false;
    }
    return ret;
  }
  bool seg_set(ll x){
    while(used[n_pos]){
      n_pos+=add;
      if(n_pos>=width){
        n_pos=0;
        add/=2;
        if(add<1) return false;
      }
    }
//    cout<<n_pos<<" "<<x<<"\n";
    used[n_pos]=true;
    return upd(n_pos,x);
  }
};
