        cin >> arr[i];
    sort(arr, arr + n);
    for (int i = 0; i != n; ++i)
    {
        int l = 0;
        int r = n;
        while (r - l != 1)
        {
            if (arr[l + r >> 1] > arr[i])
                r = l + r >> 1;
            else
                l = l + r >> 1;
        }

        arr[i] = l;
    }

    Node *st = new Node(0, n);
    for (int i = 0; i != n - 1; ++i)
        st->update(arr[i], 1);

    vector<int> slimes;
    slimes.push_back(arr[n - 1]);
    bool ok = 1;
    for (int i = 1; i != m; ++i)
    {
        for (int slime : slimes)
        {
            int qry = st->query(0, slimes[i]);
            if (qry == -1)
                ok = 0;
            else
            {
                st->update(qry, -1);
                slimes.push_back(qry);
            }
        }
    }

    if (ok)
        cout << "Yes" << '\n';
    else
        cout << "No" << '\n';

    return 0;
}

