#include <bits/stdc++.h>

using namespace std;

const int N = 1e6 + 10;

typedef pair<int, int> pi;

struct Point {
  int vl, id;
} p[N];

bool cmp(Point a, Point b) {
  if (a.vl != b.vl) return a.vl < b.vl;
  return a.id > b.id;
}

int a[N], vis[N];
set<pi> s;

void solve(int n) {
  if (!n) return;
  int m = (1 << n);
  s.clear();
  sort(a + 1, a + n + 1);
  for (int i = 1; i <= m; i++) {
    vis[i] = 0;
    p[i].vl = a[i];
    p[i].id = i;
    s.insert(pi(a[i], i));
  }
  sort(p + 1, p + m + 1, cmp);
  int cnt = 0;
  for (int i = 1; i <= m; i++) if (!vis[p[i].id]) {
    s.erase(pi(p[i].vl, p[i].id));
    auto cur = s.lower_bound(pi(p[i].vl, p[i].id));
    if (cur == s.end()) {
      puts("No");
      exit(0);
    }
    s.erase(cur);
    vis[(*cur).second] = 1;
  }
  for (int i = 1; i <= m; i++) {
    if (vis[p[i].id]) {
      a[++cnt] = p[i].vl;
    }
  }
  solve(n - 1);
}

int main() {
  int n, m;
  cin >> n;
  m = (1 << n);
  for (int i = 1; i <= m; i++) {
    scanf("%d", &a[i]);
  }
  solve(n);
  puts("Yes");
  return 0;
}

