int factorial_p( int n, int m ){
	if (n < 2 || m == 0)
		return 1;
	return n * factorial_p( n - 1, m - 1 );
}

int main( void ){
	int n;
	if(!scanf( "%d", &n ))
		return -1;
	int num = std::pow( 2, n );
	std::vector <unsigned int> vec( num, 0 );
	rep( i, 0, num ){
		if(!scanf( "%d", &vec[ i ] ))
			return -1;
	}
	std::sort( vec.begin(), vec.end());
	if (vec[ num ] == vec[ num - 1 ]){
		printf( "No\n" );
		return 0;
	}
	else if(vec[ num - 1 ] == vec[ num - 1 - n ]){
		printf( "No\n" );
		return 0;
	}
	int* array = new int[ num ]();
	array[ 0 ] = 1;
	rep( i, 1, num ){
		static int pre = 0;
		static int index = 0;
		if (pre != vec[ i ]){
			printf( "%d,%d,%d,%d\n", array[ index ], factorial_p( n, index ), index, n );
			if (array[ index ] > factorial_p( n, index )){
				printf( "No\n" );
				return 0;
			}
			if (index >= n){
				printf( "Yes\n" );
				return 0;
			}
			index++;
		}
		array[ index ]++;
		pre = vec[ i ];
	}
	printf( "Yes\n" );
	return 0;
}

