bool solve(int N, const vector<int>& S) {
  vector<int> ch(1 << N, -1);
  multiset<int> todo(S.begin(), S.end());
  ch[0] = *todo.rbegin();
  todo.erase(todo.find(ch[0]));
  REP(t, N) {
    REP(i, 1 << t) {
      auto it = todo.lower_bound(ch[i]);
      if (it == todo.begin()) return false;
      --it;
      ch[(1 << t) + i] = *it;
      todo.erase(it);
    }
  }
  return true;
}

