inline int comb(int N, int K) {
	if (N<K) return 0;
	if (dp[N][K] != 0) return dp[N][K];
	if (N==1) return 1;
	if (K==0 || K==N) return 1;

	return dp[N][K] = comb(N-1, K-1) + comb(N-1, K);
}

