#include<bits/stdc++.h>
using namespace std;

struct Node
{
    int l, r
    int val, mi;
    Node *lnode, *rnode;

    Node(int l, int r) : l(l), r(r), val(0), ma(-1)
    {
        if (r - l != 1)
        {
            lnode = new Node(l, l + r >> 1);
            rnode = new Node(l + r >> 1, r);
        }
    }

    void update(int idx, int delta)
    {
        if (r - l == 1)
        {
            val += delta;
            if (val)
                ma = l;
            else
                ma = -1
        }
        else
        {
            if (idx < lnode->r)
                lnode->update(idx, delta);
            else
                rnode->update(idx, delta);

            val = lnode->val + rnode->val;
            ma = max(lnode->ma, rnode->ma);
        }
    }

    int query(int L, int R)
    {
        if (R <= l || r <= L)
            return -1;
        else if (L <= l && r <= R)
            return ma;
        else
            return max(lnode->query(L, R), rnode->query(L, R));
    }
}

