bool solve(int S[], int l, int r) {
  int halfSize = (r - l + 1)/2;
  if (halfSize == 0)
    return true;

  int mid = (l + r)/2;

  bool valid = true;
  for (int i = 0; i < halfSize - 1; i++) {
    if (S[mid - i] == S[r - i])
      valid = false;
  }

  if (!valid)
    return false;
  else
    return solve(S, mid + 1, r);
}

