int n, arr[800005];

struct Pnode
{
    Pnode *l,*r;
    int val;
    Pnode(int v=0){l=r=NULL;val=v;}
    Pnode(Pnode *L,Pnode *R)
    {
        l=L;r=R;val=0;
        if (l!=NULL)///modify
            val+=l->val;
        if (r!=NULL)val+=r->val;
    }
};

Pnode *build(int si,int ei)
{
    if (si==ei)return new Pnode(0);
    int mid=(si+ei)>>1;
    return new Pnode(build(si,mid),build(mid+1,ei));
}
Pnode *update(Pnode *cur,int si,int ei,int idx,int val)
{
    if (si==ei)return new Pnode(val);
    int mid=(si+ei)>>1;
    if (idx<=mid)return new Pnode(update(cur->l,si,mid,idx,val),cur->r);
    else return new Pnode(cur->l,update(cur->r,mid+1,ei,idx,val));
}
int query(Pnode *cur,int si,int ei,int l,int r)
{
    if (l>r || si>r||ei<l)return 0;
    if (si>=l&&ei<=r)return cur->val;
    int mid=(si+ei)>>1;return query(cur->l,si,mid,l,r)+query(cur->r,mid+1,ei,l,r);
}

Pnode *root[800005];

void compress()
{
	int c = 0;
	map<int,int> M;
	rep(i,0,(1<<n))M[arr[i]]++;
	for (auto &x:M)x.ss = ++c;
	rep(i,0,(1<<n))arr[i] = M[arr[i]];
}

void solve()
{
    cin>>n;
    rep(i,0,(1<<n))
    	cin>>arr[i];

    compress();
    sort(arr, arr+(1<<n));

    root[0]=build(0,800004);
    root[0]=update(root[0], 0, 800004, arr[0], 1);

    rep(i,1,(1<<n))
    {
    	int val = query(root[i-1], 0, 800004, arr[i], arr[i]);
    	root[i] = update(root[i-1], 0, 800004, arr[i], val + 1);
    }

    int ind = 0, sz = (1<<(n-1));
    while(1)
    {
    	int R = ind + sz;


    	int left_ct = query(root[R-1], 0, 800004, arr[R-1], arr[R-1]) - 
    				(ind == 0 ? 0 : query(root[ind-1], 0, 800004, arr[R-1], arr[R-1]));

    	int right_ct = query(root[(1<<n)-1], 0, 800004, arr[R-1], arr[R-1]) - 
    					query(root[R-1], 0, 800004, arr[R-1], arr[R-1]);

    	//cout << ind << " " << R << " " << arr[R-1] << " " << left_ct << " " << right_ct<<"\n";
    	if (left_ct + right_ct > sz)
    	{
    		cout << "No\n";
    		return;
    	}

    	ind = R;
    	sz >>= 1;
    	if (ind == (1<<n)-1)break;
    }
    cout << "Yes\n";
}


