#define MAX (1<<19)
int BIT[MAX+1];

int sum(int k) {
  int ret = 0;
  for(++k; k > 0; k -= k & -k) ret += BIT[k];
  return ret;
}

void add(int k, int x) {
  for(++k; k < MAX; k += k & -k) BIT[k] += x;
}

bool debug = 0;
int mm;

bool check(int sp, int x) {
  x += sp;
  if( x >= mm ) return false;
  return sum(x) - ((sp-1)>=0?sum(sp-1):0) == 0;
}

void solve(int n,vector<int> &vec) {
  mm = vec.size();
  vector<int> mvec = vec;
  rep(i,(int)mvec.size()) mvec[i] = mvec[i] * -1;

  vector<int> cur;
  cur.pb(0);
  add(0,1);
  rep(_,n) {
    if( debug ) {
      cout << "* Phase " << _ << ": "<< endl;
    }
    vector<int> nex = cur;
    rep(i,(int)cur.size()) {
      int v = mvec[cur[i]];
      int sp = upper_bound(ALL(mvec),v) - mvec.begin();
      if( debug ) {
	cout << "  v  = " << v << endl;
	cout << "  sp = " << sp << " ( " << ((sp<(int)vec.size())?vec[sp]:-123) << " )" << endl;
      }
      if( sp >= (int)mvec.size() ) { puts("No"); return; }

      ll L = 0, R = (int)mvec.size();
      while( L + 1 < R ) {
	ll M = ( L + R ) / 2LL;
	if( check(sp, M) ) R = M;
	else               L = M;
	//cout << "[" << L << "," << R << "]" << endl;
      }
      int x = -1;
      if( check(sp,L) ) x = L;
      else if( check(sp,(L+R)/2) ) x = (L+R)/2;
      else x = R;
      x += sp;
      if( debug ) {
	cout << "  x  = " << x << " ( " << ((x<(int)vec.size())?vec[sp]:-123) << " )" << endl;
      }
      if( x >= (int)vec.size() ||  sum(x) - ((x-1)>=0?sum(x-1):0) > 0 ) { puts("No"); return; }
      add(x,1);
      nex.pb(x);
    }
    cur = nex;
  }
  puts("Yes");
}

