  //各秒を貪欲で考える
  rep(i,0,n){
    //この秒で生成するスライムを保管しておくtemp
    std::vector<ll> temp;

    //今いるスライム各々が生成できる最大のスライムを作る
    for(auto itr=slime.rbegin();itr!=slime.rend();itr++){
      auto itr2=unused.lower_bound(*itr);

      //自分より小さいスライムがいないならNo
      if(itr2==unused.begin()){
        std::cout<<"No";
        return 0;
      }
      itr2--;
      temp.push_back(*itr2);
      unused.erase(itr2);
    }

    rep(j,0,1<<i)slime.insert(temp[j]);
  }

  std::cout<<"Yes";

  return 0;
}

