#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e6+9, INFIN = 1e8+9;
int a[MAXN], tree[4*MAXN];
void build(int idx, int l, int r){
	if(l==r){
		tree[idx] = a[l];
		return;
	}
	int fe = 2*idx;
	int fd = fe+1;
	int mid = (l+r)/2;
	build(fe, l, mid);
	build(fd, mid+1, r);
	tree[idx] = max(tree[fe],tree[fd]);
}
int query(int idx, int l, int r, int ql, int qr){
	if(l>qr || r<ql)return -INFIN;
	if(l>=ql && r<=qr)return tree[idx];
	int fe = 2*idx;
	int fd = fe+1;
	int mid = (l+r)/2;
	return max(query(fe,l,mid,ql,qr), query(fd,mid+1,r,ql,qr));
}

