using namespace std;

bool solve(int n, const vector<int> & s) {
    multiset<int, greater<int> > a(ALL(s));
    vector<int> cur, prv;
    cur.push_back(*a.begin());
    a.erase(a.begin());
    REP (i, n) {
        prv = cur;
        for (int x : prv) {
            auto it = a.upper_bound(x);
            if (it == a.end()) return false;
            cur.push_back(*it);
            a.erase(it);
        }
    }
    return true;
}

