ll modpow(ll a, ll b){
    if(b == 0) return 1;
    else if(b % 2 == 0){
        ll d = modpow(a, b/2) % MOD;
        return (d * d) % MOD;
    }
    else{
        return (a * modpow(a, b-1)) % MOD;
    }
}

const int MAX_N = 30;

ll fact[MAX_N], finv[MAX_N];
ll comb(int n, int r){
    if(n < r || r < 0) return 0;
    return fact[n] * finv[n-r] % MOD * finv[r] % MOD;
}

void calc(int n){
    fact[0] = finv[0] = 1;
    for(int i=1; i<=n; i++){
        fact[i] = (fact[i-1] * i) % MOD;
        finv[i] = modpow(fact[i], MOD-2);
    }
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    calc(20);

    int n; cin>>n;
    vector<int> s(1 << n);
    map<int, int, greater<int>> cnt;
    for(int i=0; i<(1 << n); i++){
        cin>>s[i];
        cnt[s[i]]++;
    }

    sort(s.begin(), s.end(), greater<int>());

    /*
    for(int i=0; i<(1 << n); i++){
        cout << s[i] << endl;
    }
    */

    vector<int> v;
    for(int i=0; i<=n; i++){
        v.emplace_back(comb(n, i));
    }

    int id = 1;
    ll vsum = 1;

    int pre = -1;
    for(auto i : cnt){

        if(pre != -1){
            int cur = i.first;
            int dist = pre - cur;
            while(id <= n && 0 < dist){
                dist--;
                vsum += v[id];
                id++;
            }
        }

        if(vsum < i.second){
            cout << "No" << endl;
            return 0;
        }

        vsum -= i.second;
        pre = i.first;
    }

    cout << "Yes" << endl;
}

