struct ss {
  int v, u=-1;
  bool operator>(const ss &an) const {
    return v > an.v;
  };
};

int main(){
  int N; cin >> N; int K = pow(2,N);
  ss S[K]; for(int i=0; i<K; i++) cin >> S[i].v;
  sort(S, S+K, std::greater<ss>());
  S[0].u = N;
  for(int i=0; i<K-1; i++) {
    //for(int k=0; k<K; k++) cout << S[k].v << " " << S[k].u << "\n";
    //cout << i << endl;
    if (S[i].u == -1) {cout << "No" << endl; return 0;}
    for(int j=i; j<K && S[i].u!=0; j++) {
      if (S[i].v > S[j].v) {
        S[i].u--; S[j].u=S[i].u;
      }
    }
  }
  cout << "Yes" << endl;
}

