int cnt[1 << 18];
int main() {
	int N;
	cin >> N;
	int M = 1 << N;
	vector<int> S(M);
	for (int i = 0; i < M; i++) {
		cin >> S[i];
	}
	vector<int> v = S;
	sort(v.begin(), v.end());
	v.erase(unique(v.begin(), v.end()), v.end());
	int k = v.size();
	for (int i = 0; i < M; i++) {
		int idx = lower_bound(v.begin(), v.end(), S[i]) - v.begin();
		cnt[idx]++;
	}
	if (cnt[k - 1] > 1) {
		cout << "No" << endl;
		return 0;
	}
	set<int> need;
	for (int i = 0; i < k - 1; i++) if (cnt[i] > 0) need.insert(-i);
	multiset<int> now;
	now.insert(k - 1);
	for (int i = 0; i < N; i++) {
		vector<int> next;
		for (int e : now) {
			auto itr = need.upper_bound(-e);
			if (itr == need.end()) continue;
			int v = -(*itr);
			cnt[v]--;
			next.push_back(v);
			if (cnt[v] == 0) need.erase(itr);
		}
		for (int v : next) now.insert(v);
	}
	if (need.empty()) cout << "Yes" << endl;
	else cout << "No" << endl;
}

