        cin >> S[i];
    }
    sort(S.rbegin(), S.rend());

    ll bound = S[0];
    ll num = 0;
    ll pascal_num = 1;
    ll next_num = 1;

    for (ll i = 0; i <= N; i++) {
        //next_numまでのうち
        ll next_bound = S[num] - 1;
        for (ll j = num; j < next_num; j++) {
            if (S[j] > bound) {
                cout << "No" << endl;
                return 0;
            }
        }

        num = next_num;
        pascal_num = pascal_num * (N - i) / (i + 1);
        next_num += pascal_num;
        bound = next_bound;
    }

    cout << "Yes" << endl;
}

