		vector<SINT64> lms_seed;					// LMS ソート前
		vector<SINT64> lms_sort;					// LMS ソート後
		vector<SINT64> lms_long(Vstr.size(),0);		// LMS 長さ
		vector<SINT64> lms_type(Vstr.size(),1);		// 0:L 1:S 2:LMS
		vector<SINT64> lms_posi(Vstr.size(),-1);		// LMS内での位置

