    LL D = (int) pow(2, N);

    vector<LL> S(D);
    for (int i = 0; i < D; i++)cin >> S[i], S[i] = -S[i];
    sort(S.begin(), S.end());

    multiset<LL> mst;
    for (int i = 1; i < D; i++) mst.insert(S[i]);

    vector<LL> already;
    already.push_back(S[0]);

    for (int i = 0; i < N; i++) {
        vector<LL> time;
        for (int j = 0; j < already.size(); j++) {
            LL x = already[j];
            auto it = mst.upper_bound(x);
            if (it == mst.end()) continue;
            time.push_back(*it);
            mst.erase(it);
        }
        for (int j = 0; j < time.size(); j++) already.push_back(time[j]);
    }

    if (mst.size() == 0) cout << "Yes" << endl;
    else cout << "No" << endl;

}

