int N, M, S[1<<18];
std::vector<int> v;

bool can(){    
    v.emplace_back(S[0]);
    S[0] = -1;

    for(int i=1;i<M;i*=2){
        int k = 0;

        for(int j=0;j<i;++j){
            while(k < M && (S[k] == -1 || S[k] == v[j])){
                k += 1;
            }

            if(k == M){
                return false;
            }

            v.emplace_back(S[k]);
            S[k] = -1;
        }
    }

    return true;
}

int main(){
  std::cin.tie(nullptr);
