  std::cin >> N;

  for(int i=0;i<(1<<N);++i){
      std::cin >> S[i];
  }

  M = 1 << N;

  std::sort(S, S + M);
  std::reverse(S, S + M);

  if(can()){
      std::cout << "Yes" << std::endl;
  }else{
      std::cout << "No" << std::endl;
  }
}

