			}
		}

		// SORT済みLMSでInduced Sorting
		r_sais.resize(Vstr.size(),-1);
		induced_sort(Vstr, lms_sort, r_sais, lms_type, type);
		r_sais.erase(r_sais.begin());	// 番兵削除   
