const int N = 1e6 + 5;

int n, MAX;
int a[N];

int maxv[N << 2];

void push_up(int o) {
    maxv[o] = max(maxv[o << 1], maxv[o << 1|1]);
}

void build(int o, int l, int r) {
    if(l == r) {
        maxv[o] = a[l];
        return;
    }
    int mid = (l + r) >> 1;
    build(o << 1, l, mid);
    build(o << 1|1, mid + 1, r);
    push_up(o);
}

int query(int o, int l, int r, int L, int R) {
    if(L <= l && r <= R) return maxv[o];
    int mid = (l + r) >> 1;
    int res = 0;
    if(L <= mid) res = max(res, query(o << 1, l, mid, L, R));
    if(R > mid) res = max(res, query(o << 1|1, mid + 1, r, L, R));
    return res;
}

bool chk(int l, int r, int v) {
    if(l <= 0) l = 1;
    int now = query(1, 1, MAX, l, r);
    return now < v;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    cin >> n;
    MAX = 1 << n;
    for(int i = 1; i <= MAX; i++) cin >> a[i];
    sort(a + 1, a + MAX + 1);
    build(1, 1, MAX);
    int cur = MAX;
    if(!chk(cur - n, cur - 1, a[cur])) {
        cout << "No"; return 0;
    }
    int pw = 1, cnt = 1, tot = 1;
    int p = cur - n - 1; --cur;
    while(p > 0) {
        if(cnt == n) {
            cout << "No"; return 0;
        }
        int l = p - (n - cnt) + 1, r = p;
        if(chk(l, r, a[cur])) {
            --cur; --tot;
            if(tot == 0) {
                pw *= 2; tot = pw; ++cnt;
            }
        } else {
            cout << "No"; return 0;
        }
        p = l - 1;
    }
    cout << "Yes";
    return 0;
}

