void solve(){
	int n;
	cin>>n;
	map<int,int>mp;
	vector<int>v,s;
	int c=0;
	rep(i,(1<<n)){
		int x;
		cin>>x;
		v.pb(x);
	}
	sort(v.begin(), v.end());
	for(int i:v){
		if(mp[i]==0)mp[i]=++c;
		s.pb(c);
	}
	for(int i:s){
		a[i]++;
		//cout<<i<<" ";
	}//cout<<"\n";
	for(int i=c;i;i--)nxt[i]=i-1;
	a[0]=1;
	queue<int>q;
	q.push(s[(1<<n)-1]);
	a[q.front()]--;
	int f=0;
	for(int i=1;i<=n;i++){
		priority_queue<int>pq;
		while(!q.empty()){
			int u=q.front();
			q.pop();
			pq.push(u);
			//cout<<nxt[4]<<" "<<nxt[3]<<" "<<nxt[2]<<" "<<nxt[1]<<"\n";
			int v=find(u-1);
			//cout<<u<<" "<<v<<"\n";
			if(v==0){f=1;break;}
			a[v]--;
			pq.push(v);
			if(a[v]==0)nxt[u]=find(nxt[v-1]);
			//cout<<nxt[4]<<" "<<nxt[3]<<" "<<nxt[2]<<" "<<nxt[1]<<"\n";
		}
		if(f)break;
		while(!pq.empty()){
			//cout<<pq.top();
			q.push(pq.top());
			pq.pop();
		}
	}
	for(int i=1;i<=c;i++)if(a[i]){cout<<"No";return;}
		cout<<"Yes";
}
