int main() {
  std::ios::sync_with_stdio(false), std::cin.tie(0);
  int n;
  cin >> n;
  int m = 1 << n;
  vector<int> a(m);
  for(int i = 0; i < m; i++) cin >> a[i];
  sort(rbegin(a), rend(a));
  vector<int> bigger(m);
  for(int i = 1; i < m; i++) {
    if(a[i-1] != a[i]) {
      bigger[i] = i;
    } else {
      bigger[i] = bigger[i-1];
    }
  }

  vector<int> v;
  queue<pair<int, int>> q;
  q.emplace(0, n);

  while(q.size()) {
    int x, t;
    tie(x, t) = q.front();
    q.pop();
    v.emplace_back(x);
    for(int i = 0; i < t; i++) q.emplace(x + 1, t - 1 - i);
  }
  assert(v.size() == m);
  sort(begin(v), end(v));

  bool ok = 1;
  for(int i = 0; i < m; i++) ok &= v[i] <= bigger[i];

  if(ok)
    cout << "Yes" << endl;
  else
    cout << "No" << endl;
  return 0;
}

