pair < int , int > merge ( pair < int , int > p1 , pair < int , int > p2 ) {
    if ( p1.second > p2.second ) {
        return p1 ;
    }
    else {
        return p2 ;
    }
}

class Tree {
    public :
    pair < int , int > tr[ 5 * MAXN ] ;
    void init ( int where , int IL , int IR ) {
        tr[ where ] = { IL , 0 } ;
        if ( IL == IR ) { return ; }
        int mid = ( IL + IR ) / 2 ;
        init ( 2 * where , IL , mid ) ;
        init ( 2 * where + 1 , mid + 1 , IR ) ;
    }
    void update ( int where , int IL , int IR , int pos , int val ) {
        if ( IR < pos || pos < IL ) { return ; }
        if ( IL == IR ) {
            tr[ where ] = { pos , val } ;
            return ;
        }
        int mid = ( IL + IR ) / 2 ;
        if ( pos <= mid ) {
            update ( 2 * where , IL , mid , pos , val ) ;
        }
        else {
            update ( 2 * where + 1 , mid + 1 , IR , pos , val ) ;
        }
        tr[ where ] = merge ( tr[ 2 * where ] , tr[ 2 * where + 1 ] ) ;
    }
    pair < int , int > query ( int where , int IL , int IR , int CURL , int CURR ) {
        if ( IR < CURL || CURR < IL ) { return { 0 , 0 } ; }
        if ( CURL <= IL && IR <= CURR ) { return tr[ where ] ; }
        int mid = ( IL + IR ) / 2 ;
        return merge ( query ( 2 * where , IL , mid , CURL , CURR ) , query ( 2 * where + 1 , mid + 1 , IR , CURL , CURR ) ) ;
    }
};

Tree w ;

void input ( ) {
    scanf ( "%d" , &n ) ;
    sz = (1<<n) ;
    for ( int i = 1 ; i <= sz ; ++ i ) {
        scanf ( "%d" , &a[ i ] ) ;
        a[ i ] *= -1 ;
    }
    sort ( a + 1 , a + sz + 1 ) ;
}

void solve ( ) {
    w.init ( 1 , 1 , sz ) ;
    w.update ( 1 , 1 , sz , 1 , n ) ;
    int en = 0 ;
    for ( int i = 2 ; i <= sz ; ++ i ) {
        while ( a[ en + 1 ] < a[ i ] ) {
            ++ en ;
        }
        pair < int , int > ret = w.query ( 1 , 1 , sz , 1 , en ) ;
        if ( ret.second <= 0 ) { printf ( "No\n" ) ; return ; }
        else {
            w.update ( 1 , 1 , sz , i , ret.second - 1 ) ;
            w.update ( 1 , 1 , sz , ret.first , ret.second - 1 ) ;
        }
    }
    printf ( "Yes\n" ) ;
}

