     map<int,int> mp;
     for(int i = 0; i < len; i++){
       cin>>arr[i];
       mp[arr[i]]++;
     }

     sort(arr.rbegin(),arr.rend());
     if(mp[arr[0]]>1){
       cout<<"No";
       return 0;
     }
     ll r = 0;
     for(int i = 1; i < n; i++){
       if(arr[i]<n-i-1){
	 cout<<"No";return 0;
       }
       if(mp[arr[i]]>n+1+r-i){
	 cout<<"No";return 0;
       } else {
	 r -= max(0LL,r - (ll)(n+1-i - mp[arr[i]]));
	 r += max(0LL,(ll)n+1-i - (ll)mp[arr[i]]);
       }
     }
     cout<<"Yes";
}

