                if(v[cur] > S[j]){
                    v.push_back(S[j]);
                    made[j] = 1;
                    cur++;
                }
                if(cur == s) break;
            }
            if(j == 0){
                cout << "No\n";
                return 0;
            }
        }
        sort(v.begin(), v.end(), greater<int>());
    }
    cout << "Yes\n";
