& (AND), | (OR), ^ (XOR)
- (REVERSE), >> (SMALLER SHIFT)
<< (BIGGER SHIFT)


     x1: 0000 0001 0010 0101 0110 0111 0111
     x2: xxxx 0001 0011 0100 0101 1000 0110
x1 & x2: 0000 0001 0010 0100 0100 0000 0110

      x: 1001 1010  1100 1011 1101  1111
x & - x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

x << y is x * 2 ** y
x >> y is rep(i, y) x = x // 2 

####### Attention #######
1 << i and 1LL << i is different. If programs show WA, try switch to this one.
Let S be a bit sequence and i be a non-negative integer
S & (1 << i) -> if true, i in S
S | (1 << i) -> S union {i}
S & -(1 << i) -> S - {i}
__builtin_popcount(S) -> the number of elements in S
S = 0 -> S is an empty set
__builtin_popcountl(i) -> the number of 1 in binary
S = (1 << n) - 1 -> S includes all the elements up to the n-th

#Conditional Operator
condition ? true : false;

#iterator
type declaration: auto
value reference: *itr
increment: itr++
decrement: itr--
substitution of value: *itr = smt

# inclusion-exclusion principle
|U[i = 1 to n] Ai| = sum[i = 1 to n] |Ai| - sum[i < j]|Ai ^ Aj| + ... + (-1)^(n - 1) |^[i = 1 to n]Ai|
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n;
vl as;
vl cnt, exist, locs;

void solve(){
    ll m = 1LL << n;
    as = vl(m);
    rep(i, m) in1(as[i]);
    sort(all(as));

    cnt.pb(1); ll idx = 0;
    rep(i, m - 1){
        if (as[i + 1] == as[i]) cnt[idx]++;
        else cnt.pb(1), idx++;
    }

    ll n_types = cnt.size();
    exist = locs = vl(n_types, 0);
    rep(i, n_types) locs[i] = i - 1;

    cnt[n_types - 1]--, exist[n_types - 1]++;
    rep(_, n){
        vl nxt(n_types, 0);

        revrep(i, n_types){
            if (i < n_types) chmin(locs[i], locs[i + 1]);
            if(exist[i]){
                ll num = exist[i]; ll& loc = locs[i];

                while (num > 0){
                    if (loc < 0){prl("No"); return;}
                    if (0 < cnt[loc] && cnt[loc] <= num)
                        nxt[loc] += cnt[loc], num -= cnt[loc], cnt[loc] = 0, loc--;
                    else if (cnt[loc] > num)
                        nxt[loc] += num, cnt[loc] -= num, num = 0;
                    else loc--;
                }
            }
        }

        revrep(i, n_types - 1) chmin(locs[i], locs[i + 1]);
        rep(i, n_types) exist[i] += nxt[i];
    }

    okay = true;
    rep(i, n_types) if (cnt[i]) okay = false; 

    yn(okay);
}

int main(void){
    in1(n);
    // assert(k <= 100000);
    solve();
    return 0;
}

