        vector<int> s(1<<n);
        forn(i, 1<<n) {
            cin >> s[i];
        }

        sort(s.begin(), s.end(), greater<int>());
        vector<int> c(s.size());
        c[0] = n;
        forr(i, 1, s.size()) {
            c[i] = n - (int)floorl(log2l(i)) - 1;
        }

        int p = 1;
        bool ok = true;
        forn(i, s.size()) {
            forn(j, c[i]) {
                assert(p > i);
                if (s[p] >= s[i]) {
                    ok = false;
                    break;
                }
                p++;
            }
            if (!ok) {
