class Solution {
public:
    bool solve(vector<int>& A) {
        int N = A.size();
        int n = 0;
        while (1 << n < N) {
            ++n;
        }
        sort(A.begin(), A.end(), greater<int>());


        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < (1 << i); ++j) {
                if (A[j] == A[j + (1 << i)]) {
                    return false;
                }
            }
        }

        return true;
    }
};

int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<int> A(1 << n);
    for (int i = 0; i < (1 << n); ++i) {
        cin >> A[i];
    }
    Solution sol;
    if (sol.solve(A)) {
        cout << "Yes\n";
    } else {
        cout << "No\n";
    }
    return 0;
}

