			mx=A[i];
	}
	ll counter[32] = {0};

	for(i=0;i<S;++i)
	{
		if(A[i] < mx-N)
		{
			counter[N]++;
		}
		else
		{
			counter[mx-A[i]]++;
		}
	}
	ll cap = 1;
	ll cur = 1;
	ll div = 1;
	for(i=0;i<=N;++i)
	{
		if(cap < counter[i])
