template <class T>
class SegTree {
    int n;
    vector<T> node;
    T def;
    function<T(T, T)> operation;
    function<T(T, T)> update;

public:
    SegTree(unsigned int _n, T _def, function<T(T, T)> _operation,
            function<T(T, T)> _update)
        : def(_def), operation(_operation), update(_update) {
        n = 1;
        while (n < _n) {
            n *= 2;
        }
        node = vector<T>(n * 2, def);
    }
    SegTree(vector<int> &initvec, function<T(T, T)> _operation,
            function<T(T, T)> _update)
        : operation(_operation), update(_update) {
        n = 1;
        while (n < initvec.size()) {
            n *= 2;
        }
        node = vector<T>(n * 2, def);
        for (int i = n; i < n + initvec.size(); i++) {
            node[i] = initvec[i - n];
        }
        for (int i = n - 1; i >= 1; i--) {
            node[i] = operation(node[i * 2], node[i * 2 + 1]);
        }
    }
    void change(int i, T x) {
        i += n;
        node[i] = update(node[i], x);
        while (i >= 1) {
            i >>= 1;
            node[i] = operation(node[i * 2], node[i * 2 + 1]);
        }
    }
    T query(int l, int r) {
        l += n;
        r += n;
        T rx = def, lx = def;
        while (l < r) {
            if (l & 1) {
                lx = operation(lx, node[l]);
                l++;
            }
            if (r & 1) {
                r--;
                rx = operation(node[r], rx);
            }
            l >>= 1;
            r >>= 1;
        }
        return operation(lx, rx);
    }
    T operator[](const int &x) {
        return node[x + n];
    }
    void fill(T x) {
        std::fill(ALL(node), x);
    }
    void print() {
        rep(i, n) std::cout << operator[](i) << " ";
        std::cout << std::endl;
    }
};

class Union_Find {
    vector<int> par;
    vector<int> rankmy;
    vector<int> ookisa;

public:
    Union_Find(int size) {
        par = vector<int>(size);
        rankmy = vector<int>(size);
        ookisa = vector<int>(size);
        for (int i = 0; i < size; i++) {
            par[i] = i;
            ookisa[i] = 1;
        }
    }

    int find(int x) {
        if (par[x] == x) {
            return x;
        }
        return par[x] = find(par[x]);
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) {
            return;
        }
        if (rankmy[x] < rankmy[y]) {
            par[x] = y;
            ookisa[y] += ookisa[x];
            ookisa[x] = 0;
        } else {
            par[y] = x;
            ookisa[x] += ookisa[y];
            ookisa[y] = 0;
            if (rankmy[x] == rankmy[y]) {
                rankmy[x]++;
            }
        }
    }
    int size(int i) {
        i = find(i);
        return ookisa[i];
    }
    bool same(int x, int y) {
        return find(x) == find(y);
    }
};

class BIT {
    vector<int> data;
    int size = 0;

public:
    BIT(int _size) {
        data = vector<int>(_size + 1);
        size = _size;
    }
    void add(int i, int x) {
        while (i <= size) {
            data[i] += x;
            i += i & -i;
        }
    }
    int sum(int i) {
        assert(i <= size);
        int s = 0;
        while (i > 0) {
            s += data[i];
            i -= i & -i;
        }
        return s;
    }
    int lower_bound(int x) {
        if (x <= 0) {
            return 0;
        } else {
            int i = 0;
            int r = 1;
            while (r < size)
                r = r << 1;
            for (int len = r; len > 0; len = len >> 1) {
                if (i + len < size && data[i + len] < x) {
                    x -= data[i + len];
                    i += len;
                }
            }
            return i + 1;
        }
    }
};

