inline int read()
{
	int out=0,fh=1;
	char jp=getchar();
	while ((jp>'9'||jp<'0')&&jp!='-')
		jp=getchar();
	if (jp=='-')
		fh=-1,jp=getchar();
	while (jp>='0'&&jp<='9')
		out=out*10+jp-'0',jp=getchar();
	return out*fh;
}
const int MAXN=(1<<18)+10;
int n,m,s[MAXN];
priority_queue<int> Q;
int stk[MAXN],tp=0;
int main()
{
	n=read();
	m=(1<<n);
	for(int i=1;i<=m;++i)
		s[i]=read();
	sort(s+1,s+1+m);
	reverse(s+1,s+1+m);
	Q.push(s[1]);
	for(int i=1;i<=n;++i)
	{
		tp=0;
		int R=1<<i;
		int L=(R>>1)+1;
		for(int j=L;j<=R;++j)
		{
			int x=s[j];
			int y=Q.top();
			Q.pop();
			if(y<=x)
			{
				puts("No");
				return 0;
			}
			stk[++tp]=y;
			stk[++tp]=x;
		}
		for(int j=1;j<=tp;++j)
			Q.push(stk[j]);
	}
	puts("Yes");
	return 0;
}

