/* nCk for small n
    n は 50 程度まで
    計算量: O(k)
*/
long long nCk(int n, int k) {
    long long ret = 1;
    for (int i = 0; i < k; i++) {
        ret = ret * (n - i) / (i + 1);
    }
    return ret;
}
