    for(auto &&ele : S) init_v[get_id(ele)]++;
    V<ll> cur = { get_id(max_v) };
    init_v[get_id(max_v)]--;
    DEBUG(init_v);
    SegmentTree<ll> st(init_v, [](ll a, ll b) { return a + b; }, 0);
