			tmp.push_back(S);
		}
		sort(tmp.begin(), tmp.end());
		reverse(tmp.begin(), tmp.end());

		int v = 0;
		for (int i = 0; i < M;)
		{
			int j = i + 1;
			while (j < M && tmp[i] == tmp[j])j++;

			FOR(k, i, j)
				V.push_back(v);

			i = j;
			v++;
		}
	}

	// do drzewa przedzialowego
	n = V.back() + 1;
	modify(0, N);

	FOR(i, 1, M)
	{
		// znajdz max wartosc slotow dla potencjalnych rodzicow (wartosci < akt)
		// zamiana > na <, bo mamy odwrotnie posortowany wektor V
		auto mx = query(0, V[i]);

		int tmp = mx.first - 1;

		if (tmp < 0)
		{
			printf("No\n");
			return 0;
		}

		// zmien stara wartosc
		modify(mx.second, tmp);

		// zobacz, czy mozesz dodac nowa
