int t[N];
inline int lowbit(int x) { return x & -x; }
inline void change(int x, int val)
{
    while (x <= tot)
    {
        t[x] += val;
        x += lowbit(x);
    }
}
inline int query(int x)
{
    int ret = 0;
    while (x)
    {
        ret += t[x];
        x -= lowbit(x);
    }
    return ret;
}

void solve()
{
    cin >> n;
    for (int i = 1; i <= st(n); ++i)
        scanf("%d", &s[i]);
    sort(s + 1, s + st(n) + 1);
    for (int i = 1; i <= st(n); ++i)
        if (!h.count(s[i]))
            h[s[i]] = ++tot;
    for (int i = 1; i <= tot; ++i)
        change(i, 1);
    for (int i = 1; i <= st(n); ++i)
        S1.insert(h[s[i]]);
    sort(s + 1, s + st(n) + 1, greater<int>());
    S2.insert(h[s[1]]);
    S1.erase(S1.find(h[s[1]]));
    int tim = 1;
    while (tim <= n)
    {
        // puts("flag");
        vector<int> tmp;
        for (auto &i : S2)
        {
            int x = query(i - 1);
            if (S1.count(x) == 0)
                return puts("No"), void();
            S1.erase(S1.find(x));
            if (!S1.count(x))
                change(x, -1);
            if (S1.empty())
                return puts("Yes"), void();
            tmp.push_back(x);
        }
        for (auto &i : tmp)
            S2.insert(i);
        tim++;
    }
    puts("No");
}

