	rep( i, 0, num ){
		if(!scanf( "%d", &vec[ i ] ))
			return -1;
	}
	std::sort( vec.begin(), vec.end());
	if (vec[ num ] == vec[ num - 1 ]){
		printf( "No\n" );
		return 0;
	}
	else if(vec[ num - 1 ] == vec[ num - 1 - n ]){
		printf( "No\n" );
		return 0;
	}
