    MaxHeap<Int> heap;
    for (Int i = 0; i < m; ++i) {
        Int s;
        std::cin >> s;
        heap.push(s);
    }

    MaxHeap<Pair<Int, Int>> slimes;
    slimes.emplace(heap.top(), n);
    heap.pop();
    while (!slimes.empty()) {
        Int s, t;
        std::tie(s, t) = slimes.top();
