[[noreturn]] void impossible() {
    PRINTLN("No");
    exit(0);
}

void solve() {
    i64 N = RD();
    multiset<i64,greater<>> s;
    REP(_, 1LL<<N) {
        s.emplace(RD());
    }

    auto pre = vec_reserve<i64>(1LL<<N);
    pre.emplace_back(*begin(s));
    s.erase(begin(s));

    REP(i, N) {
        i64 m = 1LL<<i;  // 新たに生まれる数

        ALL(sort, pre, greater<>{});
        DBG(pre,s);

        auto cur = vec_reserve<i64>(m);
        auto it = begin(s);
        REP(j, m) {
            if(it == end(s)) impossible();
            while(*it >= pre[j]) {
                ++it;
                if(it == end(s)) impossible();
            }
            cur.emplace_back(*it);
            it = s.erase(it);
        }

        pre.insert(end(pre), begin(cur), end(cur));
    }

    PRINTLN("Yes");
}

