const int INF=0x3f3f3f3f;
int arr[maxn],sum[maxn*4],val[maxn*4];
void push_up(int rt) {
    int l=lson,r=rson;
    sum[rt]=sum[l]+sum[r];
    val[rt]=min(val[l],val[r]);
}
void build(int rt,int l,int r) {
    if(l==r) {
        sum[rt]=1;
        val[rt]=l;
        return ;
    }
    int mid=(l+r)/2;
    build(lson,l,mid);
    build(rson,mid+1,r);
    push_up(rt);
}
void update(int rt,int l,int r,int pos) {
    if(l==r) {
        sum[rt]=0;
        val[rt]=INF;
        return ;
    }
    int mid=(l+r)/2;
    if(pos<=mid)update(lson,l,mid,pos);
    else update(rson,mid+1,r,pos);
    push_up(rt);
}
pii query(int rt,int l,int r,int ql,int qr) {
    if(ql<=l&&qr>=r) {
        return pii(sum[rt],val[rt]);
    }
    int mid=(l+r)/2;
    pii ans=pii(0,0);
    if(ql<=mid)ans=query(lson,l,mid,ql,qr);
    if(qr>mid&&ans.first==0)ans=query(rson,mid+1,r,ql,qr);
    return ans;
}
vector<int>vec;
int find_pos(int x,int l,int r){
    int ans=-1;
    while(r>=l){
        int mid=(l+r)/2;
        if(arr[mid]>=x){
            ans=mid;
            l=mid+1;
        }
        else r=mid-1;
    }
    return ans;
}
