	sort(begin(s), end(s)); reverse(begin(s), end(s));

	std::vector<int> latte = s;
	sort(begin(latte), end(latte)); latte.erase(unique(begin(latte), end(latte)), end(latte));

	auto getIndex = [latte](int x) {
		return lower_bound(begin(latte), end(latte), x) - begin(latte);
	};

