	for(auto v: s) cnt[getIndex(v)]++;

	if(cnt.back() != 1) {
		printf("No\n");
		return 0;
	}

	std::vector<std::pair<int, int>> malta;
	for(int i = 0; i < n - 1; i++) malta.push_back({s[i], i});
	sort(begin(malta), end(malta));

	std::vector<std::queue<int>> vec(m + 1);
	std::vector<int> rank(m + 1);
	for(auto p: malta) {
		int id = p.second, val = p.first;

		bool f = false;
		for(int i = 0; i < m; i++) {
			if(rank[i] == (1 << (m - i - 1))) continue;
			if(i == 0) {
				vec[0].push(val);
				rank[0]++;
				f = true;
				break;
			}
			if(vec[i - 1].empty()) {
				continue;
			}
			auto q = vec[i - 1].front(); vec[i - 1].pop();
			if(val <= q) {
				continue;
			}

			vec[i].push(val);
			rank[i]++;
			f = true;
			break;
		}
		if(!f) {
			printf("No\n");
			return 0;
		}
	}

	printf("Yes\n");
//	else printf("No\n");
