int sanku[19][300000];//3*9=27
void sankaku(int n){
  sanku[0][0] = 1;
  sanku[1][0] = 1;
  sanku[1][1] = 1;
  for(int i = 2; n > i; i++){
    for(int j = 0; i+1 > j; j++){
      if(j == 0 || j==i)sanku[i][j] = 1;
      sanku[i][j] = sanku[i-1][j-1]+sanku[i-1][j];
    }
  }
}

int main(){
