bool solve() {
    int N; cin >> N;
    multiset<int> ms;
    rep(i, 0, 1 << N) {
        int s; cin >> s;
        ms.insert(s);
    }
    auto mx = ms.end();
    --mx;
    vector<int> used;
    used.push_back(*mx);
    ms.erase(mx);
    rep(loop, 0, N) {
        vector<int> add;
        sort(used.begin(), used.end(), greater<int>());
        for(auto u : used) {
            auto e = ms.lower_bound(u);
            --e;
            if(*e >= u) return false;
            add.push_back(*e);
            ms.erase(e);
        }
        for(auto a : add) used.push_back(a);
    }
    return true;
}

