  vl a(n2);
  rep(i, 0, pow(2, N)) { cin >> a[i]; }
  sortAscending(a);

  vl s;
  s.push_back(a.back());
  a.back = -1;

  rep(i, 0, N) {
    vl p = s;
    sortDecending(p);
    ll ai = N - 1;
    while (p.size() > 0) {
      if (a[ai] == -1) {
        --ai;
        continue;
      }
      if (a[ai] < p.back()) {
        s.push_back(a[ai]);
        p.pop_back();
        a[ai] = -1;
      }
      --ai;
    }

    if (p.size() > 0) {
      print("No");
      return 0;
    }
  }

  print("Yes");
  return 0;
}

