	map<ll, ll> S;
	ll s;
	for (ll i = 0; i < 1LL << N; ++i)
	{
		cin >> s;
		if (S.count(s) == 0)
		{
			S[s] = 0;
		}
		++S[s];
	}

	ll limit = 1;
	ll cum_limit = limit;

	auto cum_iter = S.end();
	ll cum_count = 0;

	bool can_make = true;
	for (ll i = 0; i < N; ++i)
	{
		if (cum_iter-- == S.begin())
		{
			can_make = false;
			break;
		}
		cum_count += cum_iter->second;
		if (cum_count < (1LL << i) || cum_count > cum_limit)
		{
			can_make = false;
			break;
		}
		limit = limit * (N - i) / (i + 1);
		cum_limit += limit;
	}

	cout << (can_make ? "Yes" : "No") << endl;

	return 0;
}

