struct Node {
    int value;
    Node *par;
    vector<Node*> ch;

    Node(Node *p, int numChild) : value(-1), par(p), ch(numChild, nullptr) {}
};


vector<Node*> nodep[20];

Node * buildTree(Node *par, int numChild, int depth)
{
    Node *x = new Node(par, numChild);
    nodep[depth].push_back(x);

    rep(i, numChild) {
        x->ch[i] = buildTree(x, i, depth + 1);
    }

    return x;
}

void deleteTree(Node *tree)
{
    auto &ch = tree->ch;
    if (ch.empty()) {
        return;
    }

    rep(i, ch.size()) {
        deleteTree(ch[i]);
        delete ch[i];
    }
}

