    sort(all(s));

    Node *tree = buildTree(nullptr, N, 0);


    auto itr = s.begin();

    for (int dep = N; dep >= 0; --dep) {
        for (Node *v : nodep[dep]) {
            v->value = *(itr++);
        }
    }

    bool can = true;
    for (int i = N; i > 0; --i) {
        for (Node *v : nodep[i]) {
            Node *par = v->par;
            if (v->value >= par->value) can = false;
        }
    }

    print(can ? "Yes" : "No");

    deleteTree(tree);

    return 0;
}

