  }

  std::vector<int> tree(n + 1), temp(n + 1);
  tree[n] = 1;
  for (auto& e : map) {
    for (int i = n; i >= 0; --i) {
      while (tree[i] > 0 && e.second > 0) {
        --e.second;
        --tree[i];
        for (int j = 0; j < i; ++j) {
          ++temp[j];
        }
      }
    }
    if (e.second > 0) {
      std::cout << "No" << std::endl;
      return 0;
    }
    for (int i = 0; i <= n; ++i) {
      tree[i] += temp[i];
    }
    temp.assign(n + 1, 0);
  }
  std::cout << "Yes" << std::endl;

  return 0;
}

