const int N = 1 << 19;  // limit for array size
int n;  // array size
int t[2 * N];

void modify(int p, int value) {  // set value at position p
	for (t[p += n] = value; p > 1; p >>= 1) t[p >> 1] = max(t[p], t[p ^ 1]);
}

PII query(int l, int r) {  // max on interval [l, r)
	PII res(-1, 0);
	for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
		if (l & 1)
		{
			int v = t[l++];
			if (v > res.first)
				res = MP(v, l - 1);
		}
		if (r & 1)
		{
			int v = t[--r];
			if (v > res.first)
				res = MP(v, r);
		}
	}

	return res;
}

int main()
{
	int N;
	scanf("%d", &N);
	vector<int> V;

	int M = 1 << N;

	REP(i, M)
	{
		int S;
		scanf("%d", &S);
		V.push_back(S);
	}
	sort(V.begin(), V.end());
	reverse(V.begin(), V.end());

	// do drzewa przedzialowego
	n = M;
	modify(0, N);

	// pierwsze wystapienia
	map<int, int> Mp;
	Mp[V.front()] = 0;

	FOR(i, 1, M)
	{
		// znajdz max wartosc slotow dla potencjalnych rodzicow (wartosci < akt)
		// zamiana > na <, bo mamy normalnie posortowany wektor V

		if (Mp.find(V[i]) == Mp.end())
			Mp[V[i]] = i;

		int	pos = Mp[V[i]];

		auto mx = query(0, pos);

		int tmp = mx.first - 1;

		if (tmp < 0)
		{
			printf("No\n");
			return 0;
		}

		// zmien stara wartosc
		modify(mx.second, tmp);

		// zobacz, czy mozesz dodac nowa
		if (tmp)
			modify(i, tmp);
	}

	printf("Yes\n");

	return 0;
}

