bool solve(LL n, vector<LL>& s){
    multiset<LL> cand(s.begin(), s.end());
    multiset<LL> used;
    LL v = *cand.begin();
    used.insert(v);
    cand.erase(v);
    for(LL i = 0; i < n; ++i){
        //cerr << "i=" << i << endl;
        vector<LL> tmp(used.begin(), used.end());
        for(LL v: tmp){
            auto it = cand.lower_bound(v+1);
            if(it == cand.end()) return false;
            //cerr << v << ", " << *it << endl;
            used.insert(*it);
            cand.erase(it);
        }
    }
    return true;
}

