inline ll read()
{
	ll x = 0, f = 1;
	char ch = getchar();
	while (ch<'0' || ch>'9') {
		if (ch == '-') f = -1;
		ch = getchar();
	}
	while (ch >= '0' && ch <= '9') {
		x = x * 10 + ch - '0';
		ch = getchar();
	}
	return x * f;
}
ll llpow(ll a, ll b)
{
    ll res=a;
    for(ll i=2;i<=b;i++) res*=a;
    return res;
}
ll a[maxn], tree[2 * maxn];
int main()
{
	//ios_base::sync_with_stdio(false);
	//cin.tie(0);
	//cout.tie(0);
	ll n = read();
	ll cnt = llpow(2, n);
	rep(i, 1, cnt) cin >> a[i];
	sort(a + 1, a + 1 + cnt, greater<ll>());
	//rep(i,1,cnt) prllf("%d ",a[i]);
	tree[1] = a[1];
	ll ptr = 2;
	bool ok = 1;
	rep(j, 1, n) {
		for (ll i = llpow(2, j); i <= llpow(2, j + 1) - 2; i += 2) {
			tree[i] = tree[i / 2];
		}
		for (ll i = llpow(2, j) + 1; i <= llpow(2, j + 1) - 1; i += 2) {
			tree[i] = a[ptr];
			ptr++;
			if (tree[i] >= tree[i - 1]) {
				ok = 0;
				break;
			}
		}
		if (ok == 0) break;
	}
	if (ok == 0) cout << "No" << endl;
	else cout << "Yes" << endl;
	return 0;
}

