ll answer = 0;
ll n;
vl as;

void solve(){
    ll m = 1LL << n;
    as = vl(m);
    rep(i, m) in1(as[i]);
    sort(all(as));

    multiset<ll> s; vl children;
    children.pb(as[m - 1]);
    rep(i, m - 1) s.insert(as[i]);

    rep(_, n){
        vl parents = children;

        for (ll p: parents){
            auto it = s.lower_bound(p);
            if (it == s.begin()) {prl("No"); return;}
            it--; parents.pb(*it);
            s.erase(it);
        }
        sort(rall(parents));
        swap(children, parents);
    }

    prl("Yes");
}

