const int N=3e5+5;

int n;
int a[N],b[N];

struct dis{
    int f[N];
    dis(int k){FOR(i,0,k)f[i]=i;}
    int get(int k){return f[k]==k?k:f[k]=get(f[k]);}
    void merge(int x,int y){f[get(x)]=get(y);}
};


int main(){
    scanf("%d",&n);
    int nn=1<<n;
    dis d(nn+1);
    FOR(i,1,nn)scanf("%d",&a[i]);
    sort(a+1,a+nn+1);
    FOR(i,1,nn){
        int nex=i;
        while(nex<nn&&a[nex]==a[nex+1])a[nex]=a[i-1]+1,++nex;
        a[nex]=a[i-1]+1,i=nex;
    }
    reverse(a+1,a+nn+1);
    b[1]=a[1],d.merge(1,2);//merge 1 to 2
    FOR(i,1,n){
        //printf("i=%d\n",i);
        //找到最大的1<<i个数，和b[1..1<<i]检查
        int lim=1<<(i-1),cur=d.get(1);
        FOR(j,1,lim){
            //int cur=d.get(1);//1 right max number's pos
            while(cur<=nn&&a[cur]>=b[j]){
                cur=d.get(cur+1);
            }
            if(cur>nn)return puts("No"),0;
            b[lim+j]=a[cur],d.merge(cur,cur+1),cur=d.get(cur);
        }
        //FOR(j,1,1<<i)printf("%d%c",b[j]," \n"[j==(1<<i)]);
    }
    puts("Yes");
    return 0;
}
