			cur = S[i];
			S[i] = id;
		}
		else {
			S[i] = id;
		}
	}
	carr c(id + 1);
	for (int i = 0; i < N; i++) {
		c.cadd(S[i]);
	}
	int *t = new int[N];
	t[0] = S[N - 1];
	c.csub(S[N - 1]);
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < 1 << i; j++) {
			int a = c.prev(t[j]);
			if (a < 0) {
				printf("No");
				return 0;
			}
			t[j + (1 << i)] = a;
			c.csub(a);
		}
	}
	printf("Yes");
	return 0;
}

