    VI a(1<<n);
    REP(i,0,1<<n) cin >> a[i];
    sort(all(a));
    VI b(1<<n);
    {
        int cnt = 0;
        REP(i,1,1<<n) {
            if (a[i] != a[i-1]) ++cnt;
            b[i] = cnt; 
        }
    }
    VI cs(1<<n), m(1<<n);
    REP(i,0,1<<n) ++cs[b[i]];

    reverse(all(b));
    if (b[0] == b[1]) {
        cout << "No" << endl;
