    VI ne(1<<n);
    m[b[0]]++;
    REP(i,0,n) {
        int rem = 0;
        RREP(j,0,1<<n) {
            ne[j] = m[j];
            if (rem > 0) {
                int diff = min(cs[j] - ne[j], rem);
                rem -= diff;
                ne[j] += diff;
            }
            rem += m[j];
        }
        if (rem > 0) {
            cout << "No" << endl;
            return;
        }
        REP(j,0,1<<n) {
            m[j] = ne[j];
        } 
    }
    cout << "Yes" << endl;
}

