		A[i] = lower_bound(v.begin(), v.end(), A[i]) - v.begin();
	}

	for (int i=0; i<(1<<N); i++) ++B[A[i]];

	bool flag = true;
	int sum1=0, sum2=0;
	for (int i=1; i<=N+1; i++) {
		sum1 += B[v.size()-i];
