    int l = 1,p = 0;
    bool ans = true;
    for (int i = n;i > 0;--i) {
        int k = (1<<(n-i));
        if (n-i) k -= (1<<(n-i-1));
        for (int j = 0;j < k;++j) {
            // cout << p << "[" << l << ", " << l+i << "]\n";
            int v = seg.getmax(l,l+i);
            if (v >= a[p]) ans = false;
            l += i;
            p++;
        }
    }
    cout << (ans ? "Yes" : "No") << endl;
