int choose(int n,int r)
{
    if(n<r)
        return 0;
    r=min(r,n-r);
    int i,ans=1;
    rep(i,r)
        ans*=(n-i),ans/=(i+1);
    return ans;
}
void solve()
{
    int n,m,i,j,a,k;
    in(n);
    m=(1<<n);
    int f=1;
    multiset<int> st;
    rep(i,m)
        in(a),st.insert(-a);
    vi v;
    v.pb(*st.begin());
    st.erase(st.begin());
    rep(i,n)
    {
        for(auto a : v)
        {
            if(st.upper_bound(a)==st.end())
                f=0;
            else
                v.pb(*st.upper_bound(a)),st.erase(st.upper_bound(a));
        }
    }
    if(f)
        yes;
    else
        no;
}
