  vec.erase(unique(vec.begin(), vec.end()), vec.end());
  BinaryIndexedTree<int> bit(M);
  for (int i = 0; i < M; i++) {
    int j = lower_bound(vec.begin(), vec.end(), S[i]) - vec.begin();
    bit.add(j);
  }
  vector<int> alive;
