    for (int j = 0; j < n; j++) {
      int k = bit.sum(alive[j]);
      if (k == 0) {
        isok = false;
        break;
      }
      x = bit.find(k - 1);
      alive.push_back(x);
      bit.add(x, -1);
    }
  }
  cout << (isok ? "Yes" : "No") << '\n';
