int main(){
  ll N; cin >> N;
  ll t = 1<<N;
  vector<ll> a(t); 
  map<ll,ll> cnt;
  REP(i, t){
    cin >> a[i];
    cnt[a[i]]++;
  }
  vector<ll> vals;
  REP(i, t) vals.push_back(a[i]);
  sort(ALL(vals));
