void add_edge(Graph& G, ll from, ll to, ll cap, bool revFlag, ll revCap, ll col) {
	G[from].push_back(Edge(to, cap, (ll)G[to].size(), col));
	if (revFlag)G[to].push_back(Edge(from, revCap, (ll)G[from].size() - 1, col));
}

