#include <bits/stdc++.h>

using namespace std;

const int N = 1e6 + 10;

typedef pair<int, int> pi;

struct Point {
  int vl, id;
} p[N];

bool cmp(Point a, Point b) {
  if (a.vl != b.vl) return a.vl < b.vl;
  return a.id > b.id;
}

int a[N], vis[N];
set<pi> s;

void solve(int n) {
  if (!n) return;
  int m = (1 << n);
  s.clear();
  for (int i = 1; i <= m; i++) {
    vis[i] = 0;
    p[i].vl = a[i];
    p[i].id = i;
    s.insert(pi(a[i], i));
  }
  sort(p + 1, p + m + 1, cmp);
  int cnt = 0;
  for (int i = 1; i <= m; i++) if (!vis[p[i].id]) {
    // cout << p[i].vl << " " << p[i].id << endl;
    auto cur = s.upper_bound(pi(p[i].vl, p[i].id));
    if (cur == s.end()) {
      puts("No");
      exit(0);
    }
    // cout << p[i].vl << " " << (*cur).first << endl;
    s.erase(pi(p[i].vl, p[i].id));
    s.erase(cur);
    vis[p[i].id] = 1;
    vis[(*cur).second] = 2;
  }
  for (int i = 1; i <= m; i++) {
    if (vis[p[i].id] == 2) {
      a[++cnt] = p[i].vl;
    }
  }
  solve(n - 1);
}

