signed main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    ll n; cin >> n;
    multiset<ll> mst;
    rep(i,0,1LL << n){
        ll a; cin >> a;
        mst.insert(-a);
    }
    vector<ll> v;
    bool ok = true;
    rep(i, 0, n+1){
        if(v.size() == 0){
            auto itr = mst.begin();
            v.emplace_back(*itr);
            mst.erase(itr);
            continue;
        }
        vector<ll> temp;
        for(auto &k : v){
            auto itr = mst.upper_bound(k);
            if(itr == mst.end()){
                ok = false;
                break;
            }
            temp.emplace_back(*itr);
            mst.erase(itr);
        }
        copy(all(temp), back_inserter(v));
        debug(v);
    }

    YES(ok);
}

