    ll bound = S[0];
    ll num = 0;
    ll pascal_num = 1;
    ll next_num = 1;

    for (ll i = 0; i <= N; i++) {
        //numまではbound以下でないといけない
        for (ll j = num; j < next_num; j++) {
            if (S[j] > bound) {
