void solve(){
    int N;cin>>N;
    vector<int> S(1<<N);
    multiset<int> makable;
    REP(i, 1<<N) cin >> S[i],makable.insert(S[i]);
    priority_queue<int> V;
    auto itr=makable.end();itr--;
    V.push(*itr);
    makable.erase(itr);
    bool ok=true;
    REP(i,N){
        priority_queue<int> tmp=V;
        while(!tmp.empty()){
            int slime=tmp.top();tmp.pop();
            auto it=makable.lower_bound(slime);
            if(it==makable.begin()){
                ok=false;break;
            }
            it--;
            V.push(*it);
            makable.erase(it);
        }
        if(!ok) break;
    }
    Yn(ok);
}

