// 1-indexed
struct BIT {
    int size;
    int pow2_less;
    vector<int> data;
    BIT(int n): size(n + 1), data(n + 1, 0) {
        pow2_less = 1;
        while ((pow2_less << 1) <= size)
            pow2_less <<= 1;
    }
    void add(int i, int x) {
        while (i < size) {
            data[i] += x;
            i += i & -i;
        }
    }
    int sum(int i) {
        int ret = 0;
        while (i > 0) {
            ret += data[i];
            i -= i & -i;
        }
        return ret;
    }
    // sum(x) >= w となる最小のxを返す
    int lower_bound(int w) {
        if (w <= 0) return 0;
        int x = 0;
        for (int k = pow2_less; k > 0; k >>= 1) {
            if (x + k < size && data[x + k] < w) {
                w -= data[x + k];
                x += k;
            }
        }
        return x + 1;
    }
};
signed main() {
    int N;
    cin >> N;
    N = 1 << N;
    vi S(N);
    cin >> S;
    sort(all(S));

    auto compress = S;
    compress.erase(unique(all(compress)), compress.end());
    auto get_idx = [&](int x) { return lower_bound(all(compress), x) - compress.begin() + 1; };

    BIT bit(N + 1);
    rep(i, 0, N) {
        bit.add(get_idx(S[i]), 1);
        S[i] = get_idx(S[i]);
    }

    priority_queue<int> started;
    started.push(S.back());
    bit.add(S.back(), -1);

    rep(i, 0, N) {
        if (sz(started) == N) break;
        priority_queue<int> next_started = started;
        while (sz(started)) {
            int x = started.top(); started.pop();
            int s = bit.sum(x - 1);
            int y = bit.lower_bound(s);
            if (y == 0) {
                cout << "No" << endl;
                return 0;
            }
            next_started.push(y);
            bit.add(y, -1);
        }
        started.swap(next_started);
    }

    cout << "Yes" << endl;
    return (0^_^0);
}

