int main() {
	int N;
	std::cin >> N;

	const int L = std::pow(2, N);
	std::vector<int> S(L);
	for(auto &s : S) {
		std::cin >> s;
	}

	std::sort(S.begin(), S.end(), [](int &a, int &b) {
		return a > b;
	});

	for(int a = 0; a < N; a++) {
		const int b = std::pow(2, a);
		if(S[b - 1] == S[b]) {
			const int value = S[b];
			int left = 0;
			int i = b - 1;
			while(true) {
				if(i < 0) {
					break;
				}
				if(S[i] != value) {
					break;
				}
				left++;
				i--;
			}
			left = b - left;
			int right = 0;
			i = b;
			while(true) {
				if(i >= L || S[i] != value) {
					break;
				}
				right++;
				i++;
			}

			if(left < right) {
				std::cout << "No" << std::endl;
				return 0;
			}
		}
	}

	std::cout << "Yes" << std::endl;

	return 0;
}

