const static ui SMAX = 1000000000;

static ui N;
static multiset<ui> Si;

bool solve(void) {
  multiset<ui> confirmed;
  multiset<ui> remain = Si;

  auto first = max(remain);
  confirmed.insert(*first);
  remain.erase(first);

  FOR0(i, N) {
    multiset<ui> next;

    for (auto it = confirmed.rbegin(); it != confirmed.rend(); it++) {
      auto max_elem = *it;
      auto t = remain.lower_bound(max_elem);
      if (t == remain.begin()) { // nothing possible slime
        return false;
      }
      t = prev(t);
      next.insert(*t);
      remain.erase(t);
    }

    for (auto it = next.begin(); it != next.end(); it++) {
      confirmed.insert(*it);
    }
  }

  return confirmed.size() == Si.size();
}

