ll S[1000005];
ll N;
ll D[25];
ll E[30];

string solve()
{
    ll M = pow(2, N);
    sort(S, S + M, [](ll a, ll b) { return a > b; });

    ll n = 0;
    E[N + 1] = 1;
    REP(i, M)
    {
        n++;
        if (i < M - 1 && S[i] == S[i + 1])
        {
            continue;
        }
        //! 生成したn体が何回操作ができるか？
        memset(D, 0, sizeof(D));
        for (int i = N + 1; i > 0; --i)
        {
            ll k = std::min(E[i], n);
            E[i] -= k;
            E[i - 1] += k;
            n -= k;
        }
        if (n > 0)
            return "No";
        n = 0;
    }
    FOR(i, N + 1, 1)
    {
        if (E[i] > 0)
            return "No";
    }
    return "Yes";
}

