    ll num = 0;
    ll pascal_num = 1;
    ll next_num = 1;

    vector<ll> bounds;
    bounds.push_back(S[0]);

    vector<ll> birth_date;
    birth_date.push_back(0);

    for (ll i = 0; i <= N; i++) {
        assert(bounds.size() == next_num);
        for (ll j = num; j < next_num; j++) {
            if (S[j] > bounds[j]) {
                cout << "No" << endl;
                return 0;
            } else {
                for (ll k = 0; k < N - birth_date[j]; k++) {
                    bounds.push_back(S[j] - 1);
                    birth_date.push_back(birth_date[j] + k + 1);
                }
            }
        }

        num = next_num;
        pascal_num = pascal_num * (N - i) / (i + 1);
        next_num += pascal_num;
    }

    cout << "Yes" << endl;
}

