const int MAXM = 3e5+5;
std::multiset<int> here, next, prev;
int M, N, S;
std::multiset<int>::iterator big;

bool solve() {
  if (here.empty()) {
    return true;
  }
  big = here.end();
  --big;
  next.insert(*big);
  here.erase(big);
  for (int i = 0; i < N; ++i) {
    prev = std::move(next);
    int m = 1 << i;
    big = here.end();
    for (int j = 0; j < m; ++j) --big;
    for (int j = 0; j < m; ++j) {
      auto ptr = prev.upper_bound(*big);
      if (ptr == prev.end()) {
        return false;
      }
      next.insert(*big);
      big = here.erase(big);
      next.insert(*ptr);
      prev.erase(ptr);
    }
  }
  return true;
}

