#include <bits/stdc++.h>
using namespace std;

priority_queue<int, vector<int>, greater<int>> coletado;
multiset<int> valores; 
int N, M, impossivel;

int main(){

	scanf("%d", &M);
	N = (1 << M);
	for(int i = 1;i<=N;i++){
		int x;
		scanf("%d", &x);
		valores.insert(x);
	}

	coletado.push(*prev(valores.end()));
	valores.erase(prev(valores.end()));


	while(!valores.empty()){

		queue<int> fila;

		while(!coletado.empty()){
			int v = coletado.top();
			coletado.pop();
			multiset<int>::iterator it = valores.lower_bound(v);
			if(it == valores.begin()){
				impossivel = 1;
				break;
			}
			it = prev(it);
			fila.push(*it);
			valores.erase(it);
			fila.push(v);
		}

		if(impossivel) break;

		while(!fila.empty()){
			int v = fila.front();
			fila.pop();
			coletado.push(v);
		}

	}

	if(impossivel) printf("No\n");
	else printf("Yes\n");

	return 0;

}

#include <bits/stdc++.h>
using namespace std;

void solve() {
    int n;scanf("%d",&n);
    n = (1<<n);
    multiset<int> ms;
    for(int i=0;i<n;++i) {
        int x;
        scanf("%d",&x);
        ms.insert(x);
    }
    priority_queue<int> pq[2];
    int bit = 0;
    pq[bit].push(*prev(ms.end()));
    ms.erase(prev(ms.end()));
    while(!ms.empty()) {
        int nbit = bit^1;
        while(!pq[bit].empty()) {
            int top = pq[bit].top();pq[bit].pop();
            pq[nbit].push(top);
            multiset<int>::iterator it = ms.lower_bound(top);
            if(it== ms.begin()) {
                printf("No\n");
                return;
            }
            it = prev(it);
            pq[nbit].push(*it);
            ms.erase(it);
        }
        bit = nbit;
    }
    printf("Yes\n");
}
int main() {
    solve();
    return 0;
}

