int main() {
	int K; cin >> K;
	int N = 1;
	for (int i = 0; i < K; i++) { N *= 2; }

	int* S = new int[N];
	for (int i = 0; i < N; i++) { cin >> S[i]; }

	map<int, int, greater<int>> mp;
	for (int i = 0; i < N; i++) {
		auto itr = mp.find(S[i]);
		if (itr == mp.end()) {
			mp.insert(make_pair(S[i], 1));
		}
		else {
			itr->second++;
		}
	}

	vector<int> v1, v2;

	for (auto itr = mp.begin(); itr != mp.end(); itr++) {
		if (itr == mp.begin()) {
			v1.push_back(1);
		}
		else { v1.push_back(0); }

		v2.push_back(itr->second);
	}

	N = v1.size();

	for (int k = 0; k < K; k++) {
		int carry = 0;
		for (int i = 0; i < N; i++) {
			if (v1[i] + carry >= v2[i]) {
				carry -= v2[i] - v1[i];
				v1[i] = v2[i];
			}
			else {
				v1[i] += carry;
				carry = 0;
			}
			carry += v1[i];
		}
	}

	for (int i = 0; i < N; i++) {
		if (v1[i] != v2[i]) {
			cout << "No" << endl;
			return 0;
		}
	}
	cout << "Yes" << endl;

	return 0;
}

