int N;
int A[1<<19], B[1<<19];
int dp[20][20];
vector<int> v;

inline int comb(int N, int K) {
	if (dp[N][K] != 0) return dp[N][K];
	if (N==1) return 1;
	if (K==0 || K==N) return 1;

	return dp[N][K] = comb(N-1, K-1) + comb(N-1, K);
}

int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(0);

	cin >> N;
	for (int i=0; i<(1<<N); i++) {
		cin >> A[i];
		v.push_back(A[i]);
	}

	sort(v.begin(), v.end());
	v.erase(unique(v.begin(), v.end()), v.end());

	for (int i=0; i<(1<<N); i++) {
		A[i] = lower_bound(v.begin(), v.end(), A[i]) - v.begin();
	}

	for (int i=0; i<(1<<N); i++) ++B[A[i]];

	bool flag = true;
	int sum1=0, sum2=0;

	for (int i=0; i<=N; i++) {
		if (v.size() < 1+i) {
			flag = false;
			break;
		}

		sum1 += B[v.size()-1-i];
		sum2 += comb(N, i);
		if (sum1 > sum2) flag = false;
	}

	if (flag) cout << "Yes";
	else cout << "No";
}

