ll comb(ll N, ll K){
  if(N<K) return 0;
  if(N<0 || K<0) return 0;
  ll ans = 1;
  K = min(K, N-K);
  for(int i=0; i<K; ++i){
    ans *= (N-i);
    ans /= (i+1);
  }
  return ans;
}

vll calc_combs(ll N){
  vll ans(N+1);
  REP(i,N+1){
    ans[i] = comb(N,i);
  }
  return ans;
}

