int numOfMax(vector<int> S) {
	int size = S.size() - 1;
	int count = 0, i = size;

    if (S.size() == 1) return 1;
	while (S.at(size) == S.at(i)) {
		count++;
      if(i == 0) {
        break;
      }
		i--;
		if(size == 0) break;
	}

	return count;
}

