int pow2(int n) {
	if (n == 0) return 1;
	if (n == 1) return 2;
	int t = pow2(n / 2);
	if (t & 1)
		return t * t * 2;
	return t * t;
}

signed main() {
	int n; cin >> n;
	int m = pow2(n);
	vector<ll> s(m);
	for (int i = 0; i < m; ++i)
		cin >> s[i];

	sort(s.begin(), s.end(), greater<int>());

	if (s[0] == s[1]) {
		cout << "No" << endl;
		return 0;
	}

	if (s[(m / 2) - 1] == s[m - 1]) {
		cout << "No" << endl;
		return 0;
	}

	bool ans = true;
	for (int i = 1; i < m; i *= 2) {
		for (int j = 0; j < i; ++j) {
			ans = ans && (s[j] > s[i + j]);
		}
		if (!ans) break;
	}

	if (ans) {
		cout << "Yes" << endl;
		return 0;
	}
	else {
		cout << "No" << endl;
		return 0;
	}

	return 0;
}

