vector<int> v;
vector<vector<int>> g;

int dfs(int i) {
  for(auto j : g[i]) {
    v[i] += dfs(j);
  }
  v[i]++;
  return v[i];
}

int main() {
  std::ios::sync_with_stdio(false), std::cin.tie(0);
  int n;
  cin >> n;
  int m = 1 << n;
  vector<int> a(m);
  g.resize(m);
  for(int i = 0; i < m; i++) cin >> a[i];
  sort(rbegin(a), rend(a));
  vector<int> smaller(m);
  smaller[m-1] = 0;
  for(int i = m - 2; i >= 0; i--) {
    if(a[i+1] != a[i]) {
      smaller[i] = m - i - 1;
    } else {
      smaller[i] = smaller[i+1];
    }
  }
  vector<int> bigger(m);
  for(int i = 1; i < m; i++) {
    if(a[i] == a[i - 1]) {
      bigger[i] = bigger[i - 1];
    } else {
      bigger[i] = bigger[i - 1] + 1;
    }
  }

  queue<tuple<int, int, int>> q;
  v.resize(m);
  vector<int> w;
  q.emplace(0, n, 0);

  int f = 1;
  while(q.size()) {
    int x, t, j;
    tie(x, t, j) = q.front();
    q.pop();
    w.emplace_back(x);
    for(int i = 0; i < t; i++) {
      g.at(j).push_back(f);
      q.emplace(x + 1, t - 1 - i, f);
      f++;
    }
  }
  assert(v.size() == m);
  assert(w.size() == m);
  assert(f == m);
