    BSR binary_search(int128_t L, int128_t R, std::function<bool(int128_t)> func) {
        const bool res_L = func(L);
        const bool res_R = func(R);
        if (res_L && res_R) {
            return BSR(true, L, R);
        } else if (!res_L && !res_R) {
            return BSR(false, 0, 0);
        } else {
            int128_t lb = L;
            int128_t ub = R;
            while (lb + 1 < ub) {
                int128_t mid = (lb + ub) / 2;
                if (res_L == func(mid)) {
                    lb = mid;
                } else {
                    ub = mid;
                }
            }
            return res_L ? BSR(true, L, lb) : BSR(true, ub, R);
        }
    }

