int main() {
	int n; std::cin >> n;
	std::vector<int> set(1 << n); for (auto& s : set) std::cin >> s;
	std::multiset<int> map;
	std::sort(set.begin(), set.end(), std::greater<int>());
	std::vector<bool> is_generated(1 << n, false);
	map.insert(set.front());
	is_generated[0] = true;
	bool can_generate = true;
	for (auto i = 1; i <= n && can_generate; ++i){
		std::stack<int> generated;
		for (auto j = 0; j < set.size() && generated.size() < (1 << i); ++j) {
			if (!is_generated[j]) {
				auto pos = map.upper_bound(set[j]);
				if (pos != map.end()) {
					is_generated[j] = true;
					generated.push(set[j]);
					generated.push(*pos);
					map.erase(pos);
				}
			}
		}
		if (generated.size() != (1 << i)) can_generate = false;
		while (!generated.empty()) {
			map.insert(generated.top());
			generated.pop();
		}
	}
	if (can_generate) std::cout << "Yes\n";
	else std::cout << "No\n";
}

