const static ui SiMAX = 1<<18;
const static ui SMAX = 1000000000;

static ui N;
static multiset<ui> Si;

bool solve(void) {
  multiset<ui> confirmed;
  multiset<ui> remain = Si;

  auto first = max(remain);
  confirmed.insert(*first);
  remain.erase(first);

  FOR0(i, N) {
    ui k = confirmed.size();
    auto max_elem = confirmed.rbegin();

    FOR0(j, k) {
      auto next_gen = remain.lower_bound(*max_elem);
      if (next_gen == remain.begin()) { // nothing possible slime
        return false;
      }
      next_gen = prev(next_gen);
      confirmed.insert(*next_gen);
      remain.erase(next_gen);
      max_elem++;
    }
  }

  return confirmed.size() == Si.size();
}

