  map<int,int> cnt; 
  for(int i=0;i<(1<<n);i++){
    int x; cin>>x; 
    cnt[x]++; 
  }
  vector<int> cc; 
  for(auto p:cnt){
    cc.push_back(p.second); 
  }
  reverse(all(cc)); 
  bool pos=1; 
  ll lim=1; 
  int cur=n; 
  for(int i=0;i<sz(cc);i++){
    if(cc[i]>lim){
      pos=0; 
      break; 
    }
    else {
      lim=lim-cc[i]+(ll)cur*cc[i]; 
      if(lim > inf) break; 
      cur--; 
      if(cur<0) break; 
    }
  }
  if(pos){
    cout<<"Yes"<<endl; 
  }
  else {
    cout<<"No"<<endl; 
  }
}

