    sort(A.rbegin(), A.rend());
    ll possible = 1;
    set<int> st;
    for (int a : A) {
        st.insert(a);
    }
    int coef = N;
    auto it = st.rbegin();
    while (it != st.rend() && coef >= 0) {
        int x = *it; it++;
