    set<int> st;
    for (int a : A) {
        st.insert(a);
    }
    int coef = N;
    auto it = st.rbegin();
    while (it != st.rend() && coef >= 0) {
        int x = *it;
        int cnt = A.count(x);
        if (cnt > possible) {
            puts("No");
            return 0;
        }
        int next = possible * coef;
        if (coef < N - 2) next /= 3;
