        return Yes(1);
    }

    if (N == 1) {
        if (S[0] > S[1]) Yes(1);
        else Yes(0);
        return 0;
    }

    int M = 1 << N;

    for (int i = 0; i < M / 2; ++i) {
        int piv = i;
        int pw = 0;
        int ii = i;
        while (ii) {
            pw++;
            ii>>=1;
        } 
        int prv = S[i];
        while (true) {
            int nxt = piv + (1 << pw);
            if (nxt > M) break;
            if (prv <= S[nxt]) {
                return Yes(0);
            }
            prv = S[nxt];
            pw++;
        }
    }
    Yes(1);

}

