template<class T>
struct ModComb {
	vector<T> fact;
	vector<T> facti;
	ModComb(int n) : fact(n+1), facti(n+1) {
		fact[0] = 1;
		for (int i = 1; i < n + 1; i++) {
			fact[i] = fact[i-1] * i;
		}
		facti[n] = 1 / fact[n];
		for (int i = n-1; i >= 0; i--) {
			facti[i] = facti[i+1] * (i + 1);
		}
	}
	T C(int n, int r) const {
		if(n < 0 || r < 0 || n < r) return 0;
		return fact[n] * facti[r] * facti[n-r];
	}
	T P(int n, int r) const {
		if(n < 0 || r < 0 || n < r) return 0;
		return fact[n] * facti[n-r];
	}
	T H(int n, int r) const {
		if(n < 0 || r < 0) return 0;
		return C(n + r - 1, r);
	}
};
using modcomb = ModComb<modint>;

bool solve() {
	int N;
	cin >> N;
	map<int, int> m;
	vector<int> v(1 << N);
	rep(i, 1 << N) {
		cin >> v[i];
		m[v[i]] = 1;
	}
	int cnt = 0;
	for (auto& p: m) {
		p.second = cnt++;
	}
	if (cnt < N + 1) {
		return false;
	}
	rep(i, 1 << N) {
		v[i] = m[v[i]];
	}
	vector<int> c(1 << 20);
	rep(i, 1 << N) {
		c[v[i]]++;
	}
	cnt = 0;
	modint f = 0;
	modcomb comb(2*N);
	int ma = *max_element(all(v));
	rep(i, N+1) {
		f = f + comb.C(N, i);
		cnt += c[ma - i];
		if (cnt > f.x) return false;
	}
	return true;
}


