#define REP(k,m,n) for(int (k)=(m);(k)<(n);(k)++)
#define rep(i,n) REP((i),0,(n))

int mpow(int a, int b) {
	int res = 1;
	rep(i, b)res *= a;
	return res;
}

bool judge(int size, vector<int>& S) {
	priority_queue<int, vector<int>, greater<int>> l, r;
	rep(i, size) l.push(S[i]);
	REP(i, size, size * 2)r.push(S[i]);
	while (!l.empty()) {
		int nl = l.top(); l.pop();
		int nr = r.top(); r.pop();
		if (nl <= nr)return false;
	}
	return true;
}

int main()
{
	int N;
	cin >> N;

	int total = mpow(2, N);
	vector<int> S(total);
	rep(i, total)cin >> S[i];
	sort(S.begin(), S.end(), greater<int>());

	bool res = true;
	rep(i, N)res &= judge(mpow(2, i), S);
	cout << (res ? "Yes" : "No") << endl;
	return 0;
}

