// 配列がソートされたときに移動するインデックスの配列を返す
// 配列自体はソートされない
template<typename T>
vi sortIndex(const vector<T>& vec){
    vi idx(SZ(vec));
    iota(ALL(idx), 0);
    stable_sort(ALL(idx), [vec](int l, int r){
        return vec[l] < vec[r];
    });
    return idx;
}


