    cin.tie(0);
    int n;
    cin >> n;
    vector<node*> tree = {new node()};
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < (1 << i); j++) {
            tree.push_back(new node());
            tree[j]->children.push_back(tree.back());
        }
    }
    vector<int> parent = {-1};
    int id = 0;
    queue<node*> q({tree[0]});
    while(not q.empty()) {
        node* u = q.front();
        q.pop();
        for(node* v : u->children) {
            parent.push_back(id);
            q.push(v);
        }
        id++;
    }
    vector<int> s(1 << n);
    cin >> s;
    sort(s.begin(), s.end(), greater<int>());
    bool can = true;
    for(int i = 1; i < (1 << n) and can; i++) {
        can &= s[i] < s[parent[i]];
    }
    cout << (can ? "Yes" : "No") << endl;
    for(node* n : tree) delete n;
    return 0;
}

