	while (c<'0'||c>'9') { if (c=='-') f=-1; c=getchar(); }
	while (c>='0'&&c<='9') { x=(x<<3)+(x<<1)+(c^48); c=getchar(); }
	return x*f;
}
int q[MAXN],cnt[MAXN],a[MAXN],b[MAXN],c[MAXN];
vector<int> e[MAXN];
struct Segment_Tree
{
	struct treenode{int l,r,sum,q; } tree[MAXN<<2];
	void up(int x)
	{  
	    tree[x].sum=tree[x<<1].sum+tree[x<<1|1].sum;  
	    if (tree[x<<1|1].sum>0) tree[x].q=tree[x<<1|1].q;
	    else if (tree[x<<1].sum>0) tree[x].q=tree[x<<1].q;
	    else tree[x].q=-1;
	}
	void build(int x,int l,int r)
	{
		if ((tree[x].l=l)==(tree[x].r=r))
		{
			tree[x].sum=c[l];
			tree[x].q=l;
			return;
		}
		int mid=(l+r)>>1;
		build(x<<1,l,mid);
		build(x<<1|1,mid+1,r);
		up(x);
	}
	void change(int x,int y,int z)
	{
		if (tree[x].l==tree[x].r)
		{
			tree[x].sum+=z;
			if (tree[x].sum==0) tree[x].q=-1;
			return;
		}
		int mid=(tree[x].l+tree[x].r)>>1;
		if (y<=mid) change(x<<1,y,z);
		else change(x<<1|1,y,z);
		up(x);
	}
	int query(int x,int l,int r)
	{
		if (tree[x].l>=l&&tree[x].r<=r) return tree[x].q;
		int mid=(tree[x].l+tree[x].r)>>1;
		if (r<=mid) return query(x<<1,l,r);
		else if (l>mid) return query(x<<1|1,l,r);
		else return max(query(x<<1,l,mid),query(x<<1|1,mid+1,r));
	}
	void print()
	{
		for (int i=1;i<=10;i++) 
		    cout<<tree[i].l<<" "<<tree[i].r<<":"<<tree[i].q<<" "<<tree[i].sum<<endl;
	}
} segment;
