int qsort_int_compare_ascend(const void* a, const void* b) {
	return *(int*)a - *(int*)b;
}
int qsort_int_compare_descend(const void* a, const void* b) {
	return *(int*)b - *(int*)a;
}
void ascendOrder(int size, int* array) {//昇順
	qsort(array, size, sizeof(int), qsort_int_compare_ascend);
}
void descendOrder(int size, int* array) {//降順
	qsort(array, size, sizeof(int), qsort_int_compare_descend);
}

int main() {
	int K; cin >> K;
	int N;
	{
		N = 1;
		for (int i = 0; i < K; i++) {
			N *= 2;
		}
	}
	int* s = new int[N];
	for (int i = 0; i < N; i++) {
		cin >> s[i];
	}

	descendOrder(N, s);

	vector<int> n;

	int c = 0;
	{
		int past = -1;
		for (int i = 0; i < N; i++) {
			if (s[i] != past) {
				past = s[i];
				n.push_back(1);
				c++;
			}
			else {
				n[c - 1]++;
			}
		}
	}

	if (n[0] != 1) { cout << "No" << endl; return 0; }
	int sum = 1;

	vector<int> a;
	for (int i = 0; i < c; i++) {
		if (i == 0) { a.push_back(1); }
		else {
			a.push_back(0);
		}
	}

	for (int k = 0; k < K; k++) {
		vector<int> p;
		for (int i = 0; i < c; i++) {
			p.push_back(a[i]);
		}
		int sum = 0;
		for (int i = 0; i < c; i++) {
			int _p = p[i];
			if (p[i] + sum >= n[i]) {
				sum -= (n[i] - p[i]);
				p[i] = n[i];
			}
			else {
				p[i] += sum;
				sum = 0;
			}
			sum += _p;
		}
		if (sum > 0) { cout << "No" << endl; return 0; }
		for (int i = 0; i < c; i++) {
			a[i] = p[i];
		}
	}

	for (int i = 0; i < c; i++) {
		if (a[i] != n[i]) {
			cout << "No" << endl;
			return 0;
		}
	}

	cout << "Yes" << endl;

	return 0;
}

