typedef long long ll;
using namespace std;

vector<vector<ll>> comb;

void init_comb(int n) {
    comb = vector<vector<ll>>(n + 1, vector<ll>(n + 1));
    comb[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        comb[i][0] = 1;
        for (int j = 1; j <= n; ++j) {
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]);
        }
    }
}

int main() {
    int n;
    cin >> n;
    int size = 1 << n;
    map<ll, ll> ma;
    for (int i = 0; i < size; i++) {
        int tmp;
        cin >> tmp;
        ma[tmp]++;
    }
    vector<ll> v;
    for (auto x:ma)v.push_back(x.second);
    reverse(v.begin(), v.end());

    bool ret = true;
    ll remain = 0;
    init_comb(20);
    for (int i = 0; i < n; i++) {
        if (n >= v.size()) {
            ret = false;
            break;
        }
        remain += comb[n][i] - v[i];
        if (remain < 0)ret = false;
    }
    cout << (ret ? "Yes" : "No") << endl;
    return 0;
}

