string solve()
{
    ll M = pow(2, N);
    sort(S, S + M, [](ll a, ll b) { return a > b; });

    // REP(i, M)
    // {
    //     cout << S[i] << " ";
    // }
    ll n = 0;
    ll m = 0;
    ll num = 1;
    REP(i, M)
    {
        n++;
        if (i < M - 1 && S[i] == S[i + 1])
        {
            continue;
        }
        //cout << num << endl;
        //cout << n << endl;

        //! n体生成できる？
        //! num回操作ができる
        if (n > num)
        {
            return "No";
        }
        num -= n;
        //! 生成したn体が何回操作ができるか？
        ll k = std::max(N - n, 0LL);
        // cout << "s" << D[N] - D[k] << endl;
        num += D[N] - D[k];
        //cout << num << endl;
        N--;
        n = 0;
    }
    //cout << num << endl;
    if (num > 0)
        return "No";
    return "Yes";
}

