bool solve(LL n, vector<LL>& s){
    LL cur = 0;
    LL depth = 0;
    LL w = 1;
    while(cur < (1LL << n)){
        for(LL i = 0; i < w; ++i){
            for(LL j = 0; j < n-depth; ++j){
                if(s[cur+i] <= s[cur+w+i*(n-depth)+j]) return false;
            }
        }
        cur += w * (n-depth);
        w = w * (n-depth);
    }
    return true;
}

