using ll = long long;

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    int m = (1 << n);
    vector<ll> s(m);
    for (int i = 0; i < m; i++) cin >> s[i];
    sort(s.begin(), s.end(), greater<>());

    vector<ll> val(m, -1);
    val[0] = s[0];
    vector<int> itr(n, 0);

    int cur = 1;
    for (int i = 0; i < n; i++) {
        int num = (1 << i);
        for (int j = 0; j < num; j++) {
            if (val[j] == -1) {
                assert(false);
                cout << "No\n";
                return 0;
            }
        }
        sort(val.begin(), val.begin() + num, greater<>());

        int& j = itr[i];
        while (j < num) {
            if (cur == m) {
                break;
            }

            if (val[j] > s[cur]) {
                val[j + num] = s[cur];
                cur++;
                j++;
            } else {
                bool f = false;
                for (int k = i + 1; k < n; k++) {
                    if (itr[k] < j) {
                        val[itr[k] + (1 << k)] = s[cur];
                        itr[k]++;
                        cur++;
                        f = true;
                        break;
                    }
                }
                if (!f) {
                    assert(false);
                    cout << "No\n";
                    return 0;
                }
            }
        }

        if (cur == m) break;
    }

    for (int i = 0; i < m; i++) {
        if (val[i] == -1) {
            assert(false);
            cout << "No\n";
            return 0;
        }
    }
    cout << "Yes\n";

    return 0;
}

