bool read() {
    if (!(cin >> n))
        return false;

    for (int i = 0; i < (1 << n); ++i)
        cin >> a[i];

    return true;
}

void solve() {
    m = (1 << n);
    sort(a, a + m);
    reverse(a, a + m);

    for (int i = 0, r = 1; i < n; r += (1 << i++)) {
        sort(a, a + r);
        multiset<int> sex;

        for (int j = r; j < r + (1 << i); ++j)
            sex.insert(-a[j]);

        for (int j = 0; j < r; ++j) {
            auto it = sex.upper_bound(-a[j]);

            if (it != sex.end()) {
                sex.erase(it);
            } else {
                cout << "No\n";
                return ;
            }
        }
    }

    cout << "Yes\n";
}

