  for(int i = 0; i < (1 << N); i++){
    cin >> S[i];
  }

  sort(S, S + (1 << N));
  reverse(S, S + (1 << N));

  priority_queue <int> pq;
  vector <int> buf;
  long long prev =S[0];
  buf.push_back(N);
  for(int i = 1; i < (1 << N); i++){
    if(prev != S[i]){
      for(int j = 0; j < buf.size(); j++){
        pq.push(buf[j]);
      }
      buf.clear();
    }
