	scanf("%d", &N);
	std::vector<int> S(1 << N);
	for (auto& e: S) scanf("%d", &e);
	std::sort(S.rbegin(), S.rend());
	int right{1}, prev_l{}, prev_r{1};
	std::vector<int> rest(1 << N);
	rest[0] = N;
	for (int i{}; i < N; i++)
	{
		for (int j{prev_l}; j < prev_r; j++)
		{
			if (rest[j] == 0) return false;
			for (int k{}; k < rest[j]; k++)
			{
				if (S[j] == S[right + k])
					return false;
				rest[right + k] = rest[j] - 1;
			}
			right += N - i;
		}
		prev_l = prev_r;
		prev_r *= 2;
	}
	return true;
}

