int main() {
	llong N;
	vector<llong> S;

	cin >> N;
	llong beki = 1;
	for (llong i = 0; i < N; ++i)
		beki *= 2ll;

	S.resize(beki);
	for (llong i = 0; i < beki; ++i)
		cin >> S[i];
	sort(ALL(S), greater<>());

	vector<vector<llong>> edge(beki);
	queue<llong> que;
	que.push(0ll);
	llong next = 1;
	while (next < beki) {
		llong now = que.front();
		que.pop();
		edge[now].push_back(next);
		que.push(now);
		que.push(next);
		++next;
	}

	bool check = true;
	for (llong i = 0; i < beki; ++i) {
		for (auto child : edge[i]) {
			check &= S[i] >= S[child];
		}
	}

	if (check)
		cout << "Yes" << endl;
	else
		cout << "No" << endl;

	return 0;
}

