using namespace std;
const int N=(1<<20)+5;
int a[N],b[N],q[N],st[N],vis[N],top,n;
void solve(){
	if(top==n)return;
	R int m=top;
//	fp(i,1,top)printf("%d%c",st[i]," \n"[i==top]);
	for(R int i=1,p=1;i<=m;++i){
		while(p<=n&&(vis[p]||a[p]>=a[st[i]]))++p;
//		printf("%d %d\n",st[i],p);
		if(p>n){puts("No");exit(0);}
		st[++top]=p++;
	}
	sort(st+1,st+1+top);
	fp(i,1,top)vis[st[i]]=1;
	solve();
}
int main(){
	scanf("%d",&n),n=1<<n;
	fp(i,1,n)scanf("%d",&a[i]);
	sort(a+1,a+1+n),reverse(a+1,a+1+n);
	st[++top]=1,vis[1]=1;
	solve();
	puts("Yes");
