const int N = 1 << 18;
int c[N];

void insert(int x, int y) {
  for (; x < N; x += x & -x) {
    c[x] += y;
  }
}

int query(int x) {
  int ret = 0;
  for (; x; x -= x & -x) {
    ret += c[x];
  }
  return ret;
}

int main() {
  int n, m;
  scanf("%d", &m);
  n = 1 << m;
  vector<int> a(n), A;
  for (int i = 0; i < n; ++i) {
    scanf("%d", &a[i]);
    A.push_back(a[i]);
  }
  sort(A.begin(), A.end());
  A.erase(unique(A.begin(), A.end()), A.end());
  for (int i = 0; i < n; ++i) {
    a[i] = lower_bound(A.begin(), A.end(), a[i]) - A.begin() + 1;
    insert(a[i], 1);
    // trace(i, a[i]);
  }

  int x = *max_element(a.begin(), a.end());
  A = {x};
  insert(x, -1);
  vector<int> B;
  for (int k = 0; k < m; ++k) {
    B.clear();
    for (auto& x : A) {
      int target = query(x - 1);
      if (target == 0) {
        puts("No");
        return 0;
      }
      int low = 1, high = x - 1;
      while (low < high) {
        int mid = (low + high) / 2;
        if (query(mid) < target) {
          low = mid + 1;
        } else {
          high = mid;
        }
      }
      B.push_back(high);
      insert(high, -1);
      // trace(x, high);
    }
    for (auto& it : B) A.push_back(it);
  }
  puts("Yes");
  return 0;
}

