void precompute()
{
	store[1] = n;
	int idx = 2;
	vector<int> v;
	v.push_back(1);
	while(idx <= sz)
	{
		vector<int> nv;
		for(auto &it:v)
		{
			for(int i = 1; i <= store[it]; i++)
			{
				store[idx] = store[it] - i;
				nv.push_back(idx);
				idx++;
			}	
		}
		v = nv;
	}
}

int check()
{
	int makes = n;
	vector<int> v;
	v.push_back(1);
	int idx = 2;
	while(idx <= sz)
	{	
		vector<int> nv;
		for(auto &it:v)
		{
			for(int i = 1; i <= store[it]; i++)
			{
				if(a[it] == a[idx])
					return 0;
				nv.push_back(idx);
				idx++;
			}
		}
		v = nv;
		makes--;
	}
	return 1;
}

