int main(){
    int n;  cin >> n;
    vector<int> s((1 << n));
    set<int> st;
    unordered_map<int, int> mp;
    for(int i = 0; i < (1 << n); i++){
        cin >> s[i];
    }

    std::mt19937 get_rand_mt;
    std::shuffle(s.begin(), s.end(), get_rand_mt);

    for(int i = 0; i < (1 << n); i++){
        st.insert(s[i]);
        if(mp.find(s[i]) == mp.end()){
            mp[s[i]] = 1;
        }
        else{
            mp[s[i]]++;
        }
    }

    vector<int> taken;
    auto itr = st.end();
    itr--;
    taken.push_back(*itr);
    if(mp[*itr] == 1){
        st.erase(*itr);
    }
    else{
        mp[*itr]--;
    }

    int count = 1;
    while(true){
        vector<int> new_taken;
        for(auto v: taken){
            auto itr = lower_bound(st.begin(), st.end(), v);
            if(itr == st.begin()){
                cout << "No" << endl;
                return 0;
            }
            itr--;
            new_taken.push_back(*itr);
            count++;

            if(mp[*itr] == 1){
                st.erase(*itr);
            }
            else{
                mp[*itr]--;
            }
        }
        if(count == (1 << n)){
            break;
        }
        for(auto v: new_taken){
            taken.push_back(v);
        }
    }

    cout << "Yes" << endl;


    return 0;
}

