bool solve(long long idx, long long p) {
  vector<long long> memo(1LL << n, 0);
  long long now = n, next = n;
  for(long long i = 0; i < n; ++i) {
    memo[i] = now--;
    if(now == 0) now = max(--next, 0LL);
  }
  now = 1;
  for(int i = 0; i < n; ++i) {
    if(s[i] == s[now]) return 0;
    now += memo[now];
  }
  return 1;
}

