template <typename T>
T power(T x, long long n) {
  T ret = 1;
  while (n) {
    if (n & 1) ret *= x;
    x  *= x;
    n >>= 1;
  }
  return ret;
}

int main(void) {
  int n;
  cin >> n;
  int num = power<int>(2, n);
  vector<int> s(num);
  rep (i, num) cin >> s[i];
  sort(all(s), greater<int>());
  bool ok = true;
  rep (i, n) {
    int x = power<int>(2, i);
    rep (j, x) {
      if (s[j] == s[j + x]) ok = false;
    }
    if (!ok) break;
  }
  cout << (ok ? "Yes" : "No") << endl;
  return 0;
}

