int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    int temp;
    cin >> n;

    multiset<int> a;
    int N = pow(2,n);

    for (int i = 1; i <= N; ++i)
    {
        cin >> temp;
        a.insert(temp);
    }

    bool possible{true};

    vector<int> parent;
    auto mx = max_element(a.begin(), a.end());
    parent.push_back(*mx);
    a.erase(mx);

    for (int i = 1; i <= n; i *= 2)
    {
        vector<int> new_parent;
        for (int i = 0; i < parent.size(); ++i)
        {
            auto next_max = max_element(a.begin(), a.end());
            if (*next_max >= parent[i])
            {
                possible = false;
            }
            else
            {
                new_parent.push_back(*next_max);
                a.erase(next_max);
            }
        }
        parent.insert(parent.end(), new_parent.begin(), new_parent.end());
        sort(parent.begin(),parent.end());
        reverse(parent.begin(),parent.end());
    }

    if (possible and parent.size() == N)
        cout << "Yes\n";
    else
        cout << "No\n";

    return 0;
}

