// 最大公約数
ulint gcd(lint a, lint b){
    if(b!=0){gcd(b, a % b);}
    return a;    
}
ulint gcd(vector<lint> v){
    lint l = v.size();
    if(l>=2){
        v[l-2] = gcd(v[l-2] , v[l-1]);
        v.pop_back();
    }
    if(l==1)return v[0];
    else return 0;
}

//最小公倍数
ulint lcm(lint a, lint b){
    return a / gcd(a, b) * b;
}
ulint lcm(vector<lint> v){
    lint l = v.size();
    if(l>=2){
        v[l-2] = lcm(v[l-2], v[l-1]);
        v.pop_back();
    }
    if(l==1)return v[0];
    else{
        return 0;
    }
}

