ll PowMod(ll n, ll k, ll mod) {
	//繰り返し2乗法
	//n^kをmodで求める
	ll r = 1;

	for (; k > 0; k >>= 1) {
		if (k & 1) {
			r = (r * n) % mod;
		}
		n = (n * n) % mod;
	}
	return r;
}
ll Gcd(ll a, ll b) {//最大公約数
	return b != 0 ? Gcd(b, a % b) : a;
}
ll Lcm(ll a, ll b) {//最小公倍数
	return a / Gcd(a, b) * b;
}
vector<string> Split(string s, string t) {
	//文字列を文字列で分割する
	vector<string> v;
	int p = s.find(t);
	if (p != s.npos) {
		v.push_back(s.substr(0, p));
		s = s.substr(p + t.size());
	}
	v.push_back(s);
	return v;
}
vector<int> Lis(const vector<int>& a) {
	//#define Index_of(as, x) distance(as.begin(), lower_bound(as.begin(), as.end(), x))
#define Index_of(as, x) distance(as.begin(), upper_bound(as.begin(), as.end(), x))
//upper_boundを使用すると、重複を許した最長増加部分列になる
//-1倍した値を入れれば、最長減少部分列になる
	const int n = a.size();
	vector<int> A(n, INF);
	vector<int> id(n);
	for (int i = 0; i < n; ++i) {
		id[i] = Index_of(A, a[i]);
		A[id[i]] = a[i];
	}
	int m = *max_element(id.begin(), id.end());
	vector<int> b(m + 1);
	for (int i = n - 1; i >= 0; --i)
		if (id[i] == m) b[m--] = a[i];
	return b;//最長部分列のどれか1つ
}
string ReplaceString(string s, string target, string replacestring) {
	//1: 置き換え対象
	//2: 検索対象
	//3: 置き換える内容
	string::size_type  Pos(s.find(target));

	while (Pos != string::npos) {
		s.replace(Pos, target.length(), replacestring);
		Pos = s.find(target, Pos + replacestring.length());
	}

	return s;
}
string LcsAlphabeticalMinOrder(string a, string b) {
	if (a.size() < b.size()) { swap(a, b); }

	int n = a.size(), m = b.size();

	vector<string> dp(m + 1);

	for (int i = 0; i < n; i++) {
		vector<string> to(m + 1);
		for (int j = 0; j < m; j++) {
			if (a[i] == b[j]) {
				to[j + 1] = dp[j] + a[i];
			}
			else {
				if (to[j].size() > dp[j + 1].size()) { to[j + 1] = to[j]; }
				else if (to[j].size() < dp[j + 1].size()) { to[j + 1] = dp[j + 1]; }
				else if (to[j] < dp[j + 1]) { to[j + 1] = to[j]; }
				else { to[j + 1] = dp[j + 1]; }
			}
		}
		dp.swap(to);
	}
	return dp[m];
}
string Lcs(const string &s, const string &t) {
	int dp[3001][3001];
	int n = s.size();
	int m = t.size();
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= m; j++) {
			if (s[i - 1] == t[j - 1]) {
				dp[i][j] = dp[i - 1][j - 1] + 1;
			}
			else {
				dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
			}
		}
	}
	string ans = "";
	int i = s.size(), j = t.size();
	while (i > 0 && j > 0) {
		if (s[i - 1] == t[j - 1]) {
			ans += s[i - 1];
			i--;
			j--;
		}
		else if (dp[i - 1][j] >= dp[i][j - 1])
			i--;
		else
			j--;
	}
	reverse(ans.begin(), ans.end());
	return ans;
}
vector<int> LcsInteger(const vector<int> &a, const vector<int> &b) {
#define index_of(as, x) distance(as.begin(), lower_bound(as.begin(), as.end(), x))
	struct node {
		int value;
		node *next;
		node(int value, node *next) : value(value), next(next) { }
	};
	const int n = a.size(), m = b.size();
	map< int, vector<int> > M;
	for (int j = m - 1; j >= 0; --j)
		M[b[j]].push_back(j);
	vector<int> xs(n + 1, INF); xs[0] = -INF;
	vector< node* > link(n + 1);
	for (int i = 0; i < n; ++i) {
		if (M.count(a[i])) {
			vector<int> ys = M[a[i]];
			for (int j = 0; j < (int)ys.size(); ++j) {
				int k = index_of(xs, ys[j]);
				xs[k] = ys[j];
				link[k] = new node(b[ys[j]], link[k - 1]);
			}
		}
	}
	vector<int> c;
	int l = index_of(xs, INF - 1) - 1;
	for (node *p = link[l]; p; p = p->next)
		c.push_back(p->value);
	reverse(c.begin(), c.end());
	return c;
}
bool IsPrime(ll n) {
	//素数かどうかを判定
	//true 素数
	if (n < 2)return false;
	for (ll i = 2; i*i <= n; i++)if (!(n%i))return false;
	return true;
}
vector<bool> Eratosthenes(int n) {
	//エラトステネスの篩
	//返り値はbool
	//return res;として、返り値の型をvector<int>とすれば、
	//素数だけを取り出せる
	vector<int> res;
	vector<bool> Prime(n + 1, true);
	Prime[0] = Prime[1] = false;
	for (int i = 2; i*i <= n; i++) {
		if (Prime[i]) {
			for (int j = 2; i*j <= n; j++) {
				Prime[i*j] = false;
			}
		}
	}
	for (int i = 2; i <= n; i++) {
		if (Prime[i]) {
			res.emplace_back(i);
		}
	}
	return Prime;
}
ll MergeCount(vector<int> &a) {
	//反転数を数える
	ll count = 0;
	int n = a.size();
	if (n > 1) {
		vector<int> b(a.begin(), a.begin() + n / 2);
		vector<int> c(a.begin() + n / 2, a.end());
		count += MergeCount(b);
		count += MergeCount(c);
		for (int i = 0, j = 0, k = 0; i < n; ++i)
			if (k == c.size())       a[i] = b[j++];
			else if (j == b.size())  a[i] = c[k++];
			else if (b[j] <= c[k])   a[i] = b[j++];
			else { a[i] = c[k++]; count += n / 2 - j; }
	}
	return count;
}
bool  WarshallFloyd(vector<vector<ll>> &c) {
	//ワーシャルフロイド法
	//全ての頂点間の最短距離を求める
	//falseの時、負の閉路検出
	int V = c.size();
	for (int i = 0; i < V; i++) {
		c[i][i] = 0;
	}

	for (int i = 0; i < V; i++) {
		for (int j = 0; j < V; j++) {
			for (int k = 0; k < V; k++) {
				if (c[j][k] > c[j][i] + c[i][k]) {
					c[j][k] = c[j][i] + c[i][k];
				}
			}
		}
	}

	for (int i = 0; i < V; i++) {
		if (c[i][i] < 0) {
			return false;
		}
	}



	return true;
}
vector<ll> Dijkstra(int i, vector<vector<edge>> graph) {
	//i:始点
	//graph:重み付きグラフ
	int n = graph.size();
	vector<ll> d(n, LONGINF);
	d[i] = 0;
	priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> q;
	q.push(make_pair(0, i));//第一引数:コスト 第二引数:頂点
	while (!q.empty()) {
		pair<ll, int> p = q.top();
		q.pop();
		int v = p.second;
		if (d[v] < p.first) {
			continue;
		}
		for (auto x : graph[v]) {
			if (d[x.to] > d[v] + x.cost) {
				d[x.to] = d[v] + x.cost;
				q.push(make_pair(d[x.to], x.to));
			}
		}
	}
	return d;
}
bool BellmanFord(int start, int V, int E, vector<edge> Edge, vector<ll> &d) {
	//第一引数:start 始点
	//第二引数:V 頂点数
	//第三引数:E 辺の数
	//第四引数:Edge 辺の重み付きのグラフ
	//第五引数:d 各頂点への距離を入れる配列(答えが入る)
	//負の閉路検出でfalseが返り値
	resize(d, V);
	fill(d.begin(), d.end(), LONGINF);
	d[start] = 0;
	vector<bool> t(V, false);

	for (int i = 0; i < V - 1; i++) {
		for (int j = 0; j < E; j++) {
			edge e = Edge[j];
			if (d[e.from] == LONGINF) { continue; }
			if (d[e.to] > d[e.from] + e.cost) {
				d[e.to] = d[e.from] + e.cost;
			}
		}
	}

	for (int i = 0; i < V; i++) {
		for (int j = 0; j < E; j++) {
			edge e = Edge[j];
			if (d[e.from] == LONGINF) { continue; }
			if (d[e.to] > d[e.from] + e.cost) {
				d[e.to] = d[e.from] + e.cost;
				t[e.to] = true;
				/*
				if (i == V - 1) {//どこかに閉路があることを感知する
					return false;
				}
				*/
			}
			if (t[e.from]) {
				t[e.to] = true;
			}
		}
	}

	if (t[V - 1]) {
		//V-1は頂点番号n-1で、始点からn-1までに負の閉路を検出したい場合には、
		//コメントアウトを解除すること。
		return false;
	}

	return true;
}
bool TopologicalSort(const vector<vector<edge>> &g, vector<int> &ans) {
	//トポロジカルソート
	//trueが帰る時、トポロジカルソートが成功し、その結果がansに渡される
	//falseはトポロジカルソートの失敗
	int n = g.size(), k = 0;
	vector<int> ord(n), in(n);
	for (auto &es : g) {
		for (auto &e : es) {
			in[e.to]++;
		}
	}
	queue<int> q;
	for (int i = 0; i < n; ++i) {
		if (in[i] == 0) q.push(i);
	}
	while (!q.empty()) {
		int v = q.front();
		q.pop();
		ord[k++] = v;
		for (auto &e : g[v]) {
			if (--in[e.to] == 0) q.push(e.to);
		}
	}
	ans = ord;
	if (*max_element(in.begin(), in.end()) == 0) { return true; }
	return false;
}
vector<int> ArticulationNode(const vector<vector<edge>>& g) {
	//グラフの関節点を列挙する
	//最後の2行で、erace uniqueをしない場合は、その分割によって何個のグラフに分かれるかを判定できる(要チェック)。
	int n = g.size(), idx;
	vector<int> low(n), ord(n), art;
	function<void(int)> DFS = [&](int v) {
		low[v] = ord[v] = ++idx;
		for (auto& e : g[v]) {
			int w = e.to;
			if (ord[w] == 0) {
				DFS(w);
				low[v] = min(low[v], low[w]);
				if ((ord[v] == 1 && ord[w] != 2) || (ord[v] != 1 && low[w] >= ord[v])) {
					art.push_back(v);
				}
			}
			else {
				low[v] = min(low[v], ord[w]);
			}
		}
	};
	for (int u = 0; u < n; u++) {
		if (ord[u] == 0) {
			idx = 0;
			DFS(u);
		}
	}

	sort(art.begin(), art.end());//与えられた関節点をソート
	art.erase(unique(art.begin(), art.end()), art.end());//同じ関節点が複数存在することがある,

	return art;
}
