const ll mod = 1000000007LL;

bool f(vector<ll> v){
  ll t = (ll)v.size();
  if(v[t-1]==v[t-2]) return false;
  if(t==2&&v[0]!=v[1]) return true;
  ll s = t/2LL;
  vector<ll> a(s),b(s);
  a[s-1]=v[t-1];
  b[s-1]=v[t-2];
  auto itea = lower_bound(v.begin(),v.end(),b[s-1]);
  ll cnt = (ll)(v.end()-itea)-1LL;
  if(cnt>s) return false;
  for(ll i = 0LL; i < cnt-1; i++){
    a[s-2-i] = b[s-1];
  }
  for(ll i = 0LL; i < s-1;i++){
    b[i]=v[i];
  }
  for(ll i = s-1; i < t-2-cnt;i++){
    a[i-s+1]=v[i];
  }
  return f(a)&&f(b);
}

