  std::priority_queue<int> pq;
  for (auto si: S) pq.push(si);

  std::vector<int> s0, s1;
  std::map<int, size_t> c0;
  while (!pq.empty()) {
    int v = pq.top();
    pq.pop();
    bool second = false;
