void solve(void)
{
  ui N{}; cin >> N;

  using MSet = std::multiset<ll>;
  MSet S{};
  for(ui tmp = 0; tmp < 1U << N; ++tmp)
  {
    ll s; cin >> s;
    S.emplace(s);
  }

  MSet Tree{};
  auto last = S.end(); --last;

  Tree.emplace(*last);
  S.erase(last);

  while(!S.empty())
  {
    MSet work{};
    while(!Tree.empty())
    {
      auto max = Tree.end();
      --max;
      auto it = S.lower_bound(*max);
      if(it == S.begin())
      {
        cout << "No" << CRLF;
        return;
      }
      else
      {
        --it;
        work.emplace(*max);
        work.emplace(*it);
        Tree.erase(max);
        S.erase(it);
      }
    }

    Tree = std::move(work);
  }
  cout << "Yes" << CRLF;

  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

