const int N = 300000;
const int S = N << 2;

#define L(u) ((u) << 1)
#define R(u) ((u) << 1 | 1)

int values[S];
int a[N];
int n, m;

void insert(int u, int l, int r, int x) {
  if (l == r) {
    // values[u] = std::make_pair(1, l);
    values[u] = 1;
  } else {
    int m = (l + r) >> 1;
    if (x <= m) {
      insert(L(u), l, m, x);
    } else {
      insert(R(u), m + 1, r, x);
    }
    values[u] = std::min(values[L(u)], values[R(u)]);
  }
}

int query(int u, int l, int r, int a, int b) {
  if (b < l || a > r || a > b || values[u] == 1) {
    return -1;
  }
  if (l == r) return l;
  int m = (l + r) >> 1;
  int result = query(L(u), l, m, a, b);
  if (result == -1) {
    result = query(R(u), m + 1, r, a, b);
  }
  return result;
}

int right[N];

void run(int case_id = 0) {
  read(n);
  m = 1 << n;
  read_array(a, 1, m);
  std::sort(a + 1, a + m + 1, std::greater<int>());

  for (int i = m; i >= 1; ) {
    int j = i;
    while (j >= 1 && a[j] == a[i]) {
      right[j] = i + 1;
      j --;
    }
    i = j;
  }

  std::vector<int> current[2];
  current[1].push_back(1);
  insert(1, 1, m, 1);
  for (int days = 1; days <= n; ++ days) {
    int now = days & 1;
    int next = now ^ 1;
    std::sort(current[now].begin(), current[now].end());
    current[next] = current[now];
    for (auto x : current[now]) {
      int y = query(1, 1, m, right[x], m);
      if (y == -1 || a[x] <= a[y]) {
        print("No");
        return;
      }
      current[next].push_back(y);
      insert(1, 1, m, y);
    }
  }
  print("Yes");
}

int main() {
  std::ios::sync_with_stdio(false);
  run();
  return 0;
}

