    nxt = cur;
    REP(j, cur.size()) {
      auto it = st.upper_bound(cur[j]);
      if (it == st.end()) {
        puts("No");
        return 0;
      }
      nxt.push_back(*it);
      st.erase(st.find(*it));
    }
    cur = nxt;
  }
  puts("Yes");
  return 0;
}

