    return atoi(_buf);
}

int loadvec(vector<int>& v, int N=-1) {
    if (N == 0) {
        v.clear();
        return 0;
    }
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    return i;
}

bool solve(int N, int P, vi& s) {
    vi u; u.reserve(P);
    u.pb(0);
    priority_queue<int> pq;
    rep(i,P) pq.push(s[i]);

    rep(lev,N){
        int w = 1 << lev;
        rep(i,w){
            u.pb(u[i]+1);
        }
        sort(ALL(u));
    }

    map<int,int> st;
    for(int x:u) st[x]++;

    vvi z(N+1);
    for(int lev=0; lev<=N; ++lev){
        int cn = st[lev];
        rep(i,cn){
            z[lev].pb( pq.top() ); pq.pop();
        }
    }
    for(int lev=0; lev<N; ++lev){
        int t=N-lev;
        for (int i=0,u=0; i<st[lev]; ++i){
            for(int j=0; j<t; ++j){
                if (z[lev][i] <= z[lev+1][u]) return false;
                ++u;
            }
            --t;
        }
    }
    return true;

    priority_queue<int> food;
    rep(i,P) {
        food.push(s[i]);
    }
    int root = food.top(); food.pop();

    vector<priority_queue<int>> pred(N+1);
    pred[0].push(root);

    rep(lev,N){
        int Q = 1 << lev;
        while (!pred[lev].empty()){
            --Q;
            int ph = pred[lev].top(); pred[lev].pop();
            pred[lev+1].push(ph);
            assert(!food.empty());
            if (ph > food.top()) {
                int y = food.top(); food.pop();
                pred[lev+1].push(y);
            } else {
                return false;
            }
