using namespace std;

int A[1000006], B[1000006];
queue< pair<int, int> > Q, R;

int solve(int left, int right)
{
    if(left == right)
        return 1;

    int sz = (right - left + 1) / 2;
    int mid = left + sz - 1;

    if(B[mid] >= B[right])
        return 0;

    return solve(left, mid) && solve(mid + 1, right);
}

int main() {

    ios::sync_with_stdio(0);
    cin.tie(NULL), cout.tie(NULL);

    int N;
    cin >> N;

    int M = (1 << N);

    for(int i=1; i<=M; i++)
        cin >> A[i];

    sort(A+1, A+1+M);
    Q.push({1, M});
    int sz = M;

    for(int i=1; i<=N; i++)
    {
        sz /= 2;
        int q = Q.size();

        while(q--)
        {
            pair<int, int> pr = Q.front();
            Q.pop();

            Q.push({pr.second - sz + 1, pr.second});
            R.push({pr.first, pr.second - sz});
        }

        while(!R.empty())
        {
            Q.push(R.front());
            R.pop();
        }
    }

    int k = M;

    while(!Q.empty())
    {
        B[ Q.front().first ] = A[k--];
        Q.pop();
    }

    if(solve(1, M))
        cout << "Yes\n";
    else
        cout << "No\n";

    return 0;
}

