bool solve(void) {
  multiset<ui> confirmed;
  multiset<ui> remain = Si;

  auto first = max(remain);
  confirmed.insert(*first);
  remain.erase(first);

  FOR0(i, N) {
    ui k = confirmed.size();
    auto max_elem = max(confirmed);

    FOR0(j, k) {
      auto next_gen = remain.lower_bound(*max_elem);
