    }
    std::sort(S.begin(), S.end(), std::greater<int>());
dump(S);

    // HPのヒストグラム (HP降順)
    std::vector<int> hp;
    int prev = -1;
    int count = 0;
    for (int i=0; i<total; ++i) {
        if (prev == S[i]) {
            count += 1;
        } else {
            if (count > 0) {
                hp.push_back(count);
            }
            count = 1;
            prev = S[i];
        }
    }
    hp.push_back(count);
dump(hp);

    // 世代のヒストグラム (世代昇順)
    std::vector<int> gen(N+1, 0);
    gen[0] = 1;
    for (int i=0; i<N; ++i) {
        for (int j=i+1; j>0; --j) {
            gen[j] += gen[j-1];
        }
    }
dump(gen);

    bool ok = true;
    if (hp[0] > 1) { ok = false; }
    int ngen = 1;
    int genpop = gen[ngen];
    int genleft = genpop;
    for (int i=1; i<hp.size(); ++i) {
        int hppop = hp[i];
        if (hppop > 0 && genleft == 0) {
            if (ngen < gen.size()) {
                ngen += 1;
                genpop = gen[ngen];
                genleft = genpop;
            } else {
LOG("A");
                ok = false; break;
            }
        }
        if (genleft >= hppop) {
            genleft -= hppop;
            continue;
        }
        if (ngen == gen.size() - 1) {
LOG(ngen == gen.size() - 1);
            ok = false; break;
        }
        if (gen[ngen] < hppop) {
LOG(ngen);
LOG(gen[ngen] < hppop);
            ok = false; break;
        } else if (hppop - genleft > gen[ngen+1]) {
LOG(ngen);
LOG(hppop - genleft > gen[ngen+1]);
            ok = false; break;
        } else {
            hppop -= genleft;
            ngen += 1;
            genpop = gen[ngen];
            genleft = genpop - hppop;
        }
    }    
    std::cout << (ok ? "Yes" : "No") << std::endl;
    return 0;
}

