string solve(){
    vector < int > mot;// mothers
    mot.push_back(*slime.begin());
    slime.erase(slime.begin());
    while(!slime.empty()){
        vector < int > nxt;// new born slime
        for(int i=0;i<mot.size();++i){
            int mom=mot[i];
            ms :: iterator son = slime.upper_bound(mom);
            if(son==slime.end()){
                // since total time is p and total number is 2^p.
                // in this case I can say "No".
                return "No";
            }else{
                nxt.push_back(*son);
                slime.erase(son);
            }
        }
        mot.insert(mot.end(),nxt.begin(),nxt.end());
    }
    return "Yes";
}

