long pow2(int n){
    long res = 1;
    for(int i=0; i < n; i++){
        res *= 2;
    }
    return res;
}

int main(){
    int n;
    long temp;
    priority_queue<long> s;
    scanf("%d", &n);
    for(long i=0; i < pow2(n); i++){
        scanf("%ld", &temp);
        s.push(temp);
    }
    priority_queue<long> farm;
    priority_queue<long> evac;
    farm.push(s.top());
    bool impossible = false;
    s.pop();
    while(!s.empty()){
        while(!farm.empty()){
            auto popped_farm = farm.top();
            farm.pop();
            evac.push(popped_farm);
            auto popped_s = s.top();
            s.pop();
            if(popped_s < popped_farm){
                evac.push(popped_s);
            }else{
                impossible = true;
                goto FIN;
            }
        }
        while(!evac.empty()){
            farm.push(evac.top());
            evac.pop();
        }
    }
    FIN:
    if(impossible){
        printf("No\n");
    }else{
        printf("Yes\n");
    }
    return 0;
}

