    REP(i, 0, len) {
        cin >> S[i];
    }
    sort(S, S + len);
    reverse(S, S + len);
    ll smod[len];
    ll modnum = 0;
    smod[0] = 0;
    REP(i, 1, len) {
        if (S[i] != S[i - 1]) {
            modnum++;
        }
        smod[i] = modnum;
    }
