	cin.tie(0);

	ll n;
	cin >> n;
	Array s(1 << n);
	map<ll, ll> mp;
	REP(i, 1 << n) {
		cin >> s[i];
		mp[-s[i]]++;
	}
	Array a(mp.size());
	int i = 0;
	for (auto itr : mp) {
		a[i] = itr.second;
		i++;
	}
	if (a[0] != 1) {
		cout << "No" << endl;
		return 0;
	}
	Array num(a.size(), 0);
	num[0] = 1;
	set<ll> rest;
	REP(i, a.size()-1)rest.insert(i+1);
	Array slime;
	slime.push_back(0);
	REP(i, n) {
		Array next;
		REP(j, slime.size()) {
			auto itr = rest.upper_bound(slime[j]);
			if (itr == rest.end()) {
				cout << "No" << endl;
				return 0;
			}
			num[*itr]++;
			next.push_back(*itr);
			if (num[*itr] == a[*itr])rest.erase(*itr);
		}
		REP(j, next.size())slime.push_back(next[j]);
	}
	cout << "Yes" << endl;



	return 0;
}

