		ll cnt = n - 1, c2 = -1;
		REP(j, 25) {
			if (i & (1ll << j)) c2 = j;
		}
		cnt -= c2;
		//cout << cnt << endl;
		ll a = query(now, now + cnt, 0, 0, sz);
		now += cnt;
		if (s[i] <= a) {
			cout << "No" << endl;
			return 0;
		}
	}
	cout << "Yes" << endl;
}

