	}
	for(i=0;i<mypow(2,n);i++){
		b.push(h[i]);
	}
	ma=a.top(); mb=b.top();
	a.pop(); b.pop();
	for(i=1;i<mypow(2,n);i++){
		if(ma>a.top()) ca++;
		if(mb>b.top()) cb++;
		if(cb>ca){
			cout << "No" << endl;
			return 0;
		}
		ma=a.top(); mb=b.top();
		a.pop(); b.pop();
	}
	cout << "Yes" << endl;
	return 0;
}

