const int nCk_MAX = 22;
long long comb[nCk_MAX + 1][nCk_MAX + 1];
void calcomb() {
	for (int i = 0; i <= nCk_MAX; i++) {
		for (int j = 0; j <= i; j++) {
			if (j == 0 || j == i)
				comb[i][j] = 1;
			else
				comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
		}
	}
}
#undef nCk_MAX
int PW(int x, int n) {
	int ret = 1;
	FOR(i, 0, n)ret *= x;
	return ret;
}
int main() {
	calcomb();

	int N;
	cin >> N;
	int NS = PW(2, N);
	vector<int> input(NS);
	for (int i = 0; i < NS; ++i) {
		cin >> input[i];
	}

	priority_queue<int>pq;
	FOR(i, 0, NS)pq.push(input[i]);
	bool ok = 1;
	function<void(int, int, int)>f = [&](int dep, int now, int top) {
		if (now >= top)ok = 0;
		vector<int>left;
		if (dep < 1)return;
		int cb = comb[dep - 1][1];
		FOR(x, 0, cb) {
			int v = pq.top(); pq.pop();
			left.emplace_back(v);
		}
		FOR(x, 0, cb) {
			f(dep - 1 - x, left[x], now);
		}
	};
	using tp = tuple<int, int, int>;
	queue<tp>q;
	int fi = pq.top(); pq.pop();
	q.push(tp(N + 1, fi, fi + 1));
	while (!q.empty()) {
		int dep, now, top;
		tie(dep, now, top) = q.front(); q.pop();
		if (now >= top)ok = 0;
		vector<int>left;
		if (dep < 1)continue;
		int cb = comb[dep - 1][1];
		FOR(x, 0, cb) {
			int v = pq.top(); pq.pop();
			left.emplace_back(v);
		}
		FOR(x, 0, cb) {
			q.push(tp(dep - 1 - x, left[x], now));
		}

	}
	cout << (ok ? "Yes" : "No") << endl;

}

