bool check(VEC(int)& S, int l, int r)
{
    if (l == r)
        return true;

    if (S[l + 1] >= S[l])
        return false;

    int a = S[l], b = S[l + 1];
    int n = (r + 1 - l);
    int mid = l + n / 2 - 1;
    swap(S[l + 1], S[mid + 1]);
    sort(S.begin() + l + 1, S.begin() + mid + 1, greater<int>());
    sort(S.begin() + mid + 1, S.begin() + r + 1, greater<int>());
    return check(S, l, mid) && check(S, mid + 1, r);
}

