long long fast_power(long long a, long long b) {
	long long ret = 1;
	// aが負の場合
	if (a < 0) {
		a = -a;
		if (b % 2 == 1) ret = -1;
	}
	// 累乗計算 (MODを取るときはコメントを外す)
	while (b>0) {
		if (b & 1) {
			ret *= a;
		}
		a *= a;
		//a %= MOD;
		//ret %= MOD;
		b >>= 1;
	}
	return ret;
}

