  for (int t = 0; t < n; ++t)
  {
    vector<int64> currentParent(parent);
    auto it_end = currentParent.end();
    for (auto it = currentParent.begin(); it != it_end; ++it)
    {
      int64 child = s.top();
      if (child < *it)
      {
        s.pop();
        parent.push_back(child);
      }
      else
      {
        cout << "No" << endl;
        return 0;
      }
    }
  }

  cout << "Yes" << endl;
  return 0;
}

