using namespace std;
const int MAXN = 1e6+9, INFIN = 1e9+9;
int a[MAXN], pont[MAXN];
vector<int> prox[MAXN],quem,td;

int main(){
	int n; cin>>n;
	int sz = 1;

	for(int i=1; i<=n; i++){
		sz = 2*sz;
	}

	for(int i=0; i<sz; i++){
		cin>>a[i];
	}

	sort(a, a+sz);



	for(int i = sz-2; i>=sz-n-1; i--){
		prox[sz-1].push_back(i);
	}
	pont[sz-1]=0;

	int cur = sz-n-2;
	int tam = n-1;
	quem.push_back(sz-1);

	while( pont[sz-1] < (int)prox[sz-1].size() ){

		for(int k = 0; k<(int)quem.size(); k++){
			int i = quem[k];

			if(a[i] <= a[ prox[i][pont[i]] ]){
				cout<<"No"<<endl;
				return 0;
			}else{
				//cout<<a[i]<<" > "<<a[ prox[i][pont[i]] ]<<endl;
				//cout<<"NOTE "<<i<<"   "<<prox[i][pont[i]]<<endl;
			}

			int atual = prox[i][pont[i]];
			td.push_back(atual);
			int ccur = cur;
			for(int j=cur; j > max(cur-tam,0); j--){
				prox[atual].push_back(j);
				ccur = min(ccur,j);
			} 
			cur = ccur-1;
			pont[i]++;
		}
		tam--;
		for(int k=0; k<(int)td.size(); k++){
			quem.push_back(td[k]);
			pont[td[k]]=0;
		}
		td.clear();
	}
	cout<<"Yes"<<endl;
}

