bool search(std::vector<long long>& S, int tmp, int M)
{
    if(tmp*2 >= M) return true;

    if(S[tmp] == S[2*tmp]) return false;
    if(S[tmp] == S[2*tmp+1]) return false;
    if(!search(S, 2*tmp  , M)) return false;
    if(!search(S, 2*tmp+1, M)) return false;

    return true;
}

int main()
{
    int N;
    std::cin >> N;
    int M = std::pow(2, N);
    std::vector<long long> S(M);
    for(int i=0; i<M; i++) scanf(" %lld", &S[i]);

    std::sort(S.begin(), S.end(), std::greater<long long>());
    // for(long long s: S) printf("%lld\n", s);
    if(S[0] <= S[1]){
        std::cout << "No" << std::endl; return 0;
    }

    bool flag = search(S, 1, M);
    if(flag) std::cout << "Yes" << std::endl;
    else std::cout << "No" << std::endl;
}

