//エラトステネスのふるいによりn以下の素数を全てベクトルに入れて返す
vector<long long> eratos(long long n){
    if(n<2) return {};
    vll v(n-1);
    rep(i,n-1){
        v[i]=i+2;//2からnまで
    }
    ll i=0;
    while(i<n-1){
        ll p=v[i];
        for(ll j=i+1;j<n-1;j++){
            if(v[j]%p==0){
                v.erase(v.begin()+j);
                n--;
            }
        }
        i++;
    }
    v.resize(n-1);
    return v;

}

