#define INTSPACE 12
char _buf[INTSPACE*1000000 + 3];

int loadint() {
    if (fgets(_buf, INTSPACE+3, stdin)==NULL) return 0;
    return atoi(_buf);
}

int loadvec(vector<int>& v, int N=-1) {
    if (N == 0) {
        v.clear();
        return 0;
    }
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    return i;
}

bool solve(int N, int P, vi& s) {
    priority_queue<int> food;
    rep(i,P) {
        food.push(s[i]);
    }
    int root = food.top(); food.pop();

    vector<priority_queue<int>> pred(N+1);
    pred[0].push(root);

    rep(lev,N){
        int Q = 1 << lev;
        while (!pred[lev].empty()){
            --Q;
            int ph = pred[lev].top(); pred[lev].pop();
            pred[lev+1].push(ph);
            assert(!food.empty());
            if (ph > food.top()) {
                int y = food.top(); food.pop();
                pred[lev+1].push(y);
            } else {
                return false;
            }
        }
        assert(Q == 0);
    }
    return true;
}

int main() {
    int N; scanf("%d%*c", &N);
    int P = 1 << N;
    vi s(P);
    loadvec(s, P);
    cout << (solve(N,P,s) ? "Yes":"No") << endl;
    return 0;
}

