using namespace std;

class SegTree
{
public:
    SegTree(int size)
        : count_(4 * size + 4, 0), maxes_(4 * size + 4, 0), size_(size) {}

    void Add(int num) { Update(0, 0, size_ - 1, num, 1); }
    void Remove(int num) { Update(0, 0, size_ - 1, num, -1); }

    int GetSmaller(int num) const { return Get(0, 0, size_ - 1, num - 1); }

private:
    void Update(int node, int left, int right, int num, int mod);
    int Get(int node, int left, int right, int limit) const;

    int LeftSon(int node) const { return 2 * node + 1; }
    int RightSon(int node) const { return 2 * node + 2; }

    vector<int> count_;
    vector<int> maxes_;
    int size_;
};

void SegTree::Update(int node, int left, int right, int num, int mod)
{
    if (left == right) {
        count_[node] += mod;
        maxes_[node] = (count_[node] > 0 ? num : -1);
        return;
    }

    int mid = left + (right - left) / 2;
    if (num <= mid) {
        Update(LeftSon(node), left, mid, num, mod);
    } else {
        Update(RightSon(node), mid + 1, right, num, mod);
    }
    maxes_[node] = max(maxes_[LeftSon(node)], maxes_[RightSon(node)]);
}

int SegTree::Get(int node, int left, int right, int num) const
{
    if (left > num) {
        return -1;
    }
    if (right <= num) {
        return maxes_[node];
    }

    int mid = left + (right - left) / 2;
    int res = Get(LeftSon(node), left, mid, num);

    if (num > mid) {
        res = max(res, Get(RightSon(node), mid + 1, right, num));
    }
    return res;
}

int Find(const vector<int> &sorted, int val)
{
    int pos = -1;
    int pow = (1 << 25);

    while (pow > 0) {
        int next_pos = pos + pow;
        pow >>= 1;

        if (next_pos < (int)sorted.size() && sorted[next_pos] <= val) {
            pos = next_pos;
        }
    }
    return pos;
}

int Normalise(vector<int> &vec)
{
    vector<int> sorted(vec.begin(), vec.end());
    sort(sorted.begin(), sorted.end());

    int index = 0;
    for (size_t i = 0; i < sorted.size(); i += 1) {
        if (i == 0 || sorted[i] != sorted[i - 1]) {
            sorted[index] = sorted[i];
            index += 1;
        }
    }
    sorted.resize(index);

    for (auto &num : vec) {
        num = Find(sorted, num);
    }
    return sorted.size();
}

bool Valid(vector<int> &vec, int n)
{
    int distinct = Normalise(vec);
    sort(vec.begin(), vec.end(), greater<int>());

    SegTree tree(distinct);
    for (size_t i = 1; i < vec.size(); i += 1) {
        tree.Add(vec[i]);
    }

    vector<int> slimes{vec[0]};
    while (slimes.size() < vec.size()) {
        int size = slimes.size();
        for (int i = 0; i < size; i += 1) {
            int next = tree.GetSmaller(slimes[i]);
            if (next < 0) {
                return false;
            }

            slimes.push_back(next);
            tree.Remove(next);
        }
    }
    return true;
}

int main()
{
    int n;
    cin >> n;

    vector<int> vec(1 << n);
    for (auto &num : vec) {
        cin >> num;
    }

    auto res = Valid(vec, n);
    cout << (res ? "Yes" : "No") << "\n";

    return 0;
}

