class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}
    void run(){
        int N;
        is >> N;
        if(!is) return;
        vector<int> S(1<<N);
        int fst = 0;
        multiset<int> child, parent;
        for (auto &&s : S) {
            is >> s;
            fst = max(fst, s);
            child.insert(-s);
        } // end s
        parent.insert(-fst);
        child.erase(child.find(-fst));
        while(!child.empty()){
            multiset<int> ngen;
            for (auto &&p : parent) {
                auto gd = child.upper_bound(p);
                if(gd == child.end()) {
                    os << "No\n"; return;
                }
                ngen.insert(*gd);
                child.erase(gd);
            } // end p
            for (auto &&n : ngen) {
                parent.insert(n);
            } // end n
        }
        os << "Yes\n";

    }
};

