    cnt[-x] += 1;
    M = min(-x, M);
  }
  if (cnt[M] > 1) {
    return false;
  }
  S.erase(M);
  vector<int> v;
  v.push_back(M);
  for (int i = 0; i < n; i++) {
    for (auto x: v) {
      auto y = S.upper_bound(x);
      if (y == S.end()) {
        return false;
      }
      cnt[*y] -= 1;
      if (cnt[*y] == 0) {
        S.erase(*y);
      }
      v.push_back(*y);
    }
  }
  return true;
}

