#define REP(i,n) for(int i = 0; i < (int)(n); ++i)
#define FOR(i,a,b) for(int i = (a); i < (int)(b); ++i)
#define ALL(c) (c).begin(), (c).end()
#define SIZE(v) ((int)v.size())

#define pb push_back
#define mp make_pair
#define mt make_tuple

ll solve(int N, vector<int>& S) {
    sort(ALL(S));
    auto used = vector<int>{S.back()};
    multiset<int> unused;
    REP(i, (1<<N) - 1) unused.insert(S[i]);

    int num_of_gen = 1;

    while (SIZE(used) < (1<<N)) {
        vector<int> next_used;
        REP(i, num_of_gen) {
            auto loc = unused.lower_bound(used[i]);
            if (loc == unused.begin()) return false;
            next_used.pb(used[i]);
            auto loc_prev = loc;
            --loc_prev;
            next_used.pb(*loc_prev);
            unused.erase(unused.find(*loc_prev));
        }
        used = next_used;
        num_of_gen *= 2;
    }
    return true;
}

