struct BIT {
    BIT(int n) : b(n + 1), n(n) {}
    void add(int i, int v) {
        for (int k = i + 1; k <= n; k += k & -k) b[k] += v;
    }
    int sum(int k) {
        int s = 0;
        for (; k > 0; k -= k & -k) s += b[k];
        return s;
    }
    int lower_bound(int s) {
        if (s <= 0) return 0;
        int x = 0, w = 1;
        while (w << 1 <= n) w <<= 1;
        do {
            int k = x + w;
            if (k <= n && b[k] < s) {
                s -= b[k];
                x += w;
            }
        } while (w >>= 1);
        return x + 1;
    }
    vector<int> b;
    int n;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    int m = 1 << n;

    vector<int> s(m);
    for (int i = 0; i < m; i++) {
        cin >> s[i];
    }
    sort(s.begin(), s.end());

    int k = -1, p = -1;
    for (int i = 0; i < m; i++) {
        if (s[i] != p) k++;
        p = s[i];
        s[i] = k;
    }
    k++;

    BIT bt(k);
    for (int i = 0; i < m - 1; i++) {
        bt.add(s[i], 1);
    }

    vector<int> c(m);
    c[0] = s.back();
    for (int l = 1; l < m; l <<= 1) {
        for (int i = 0; i < l; i++) {
            int s = bt.sum(c[i]);
            if (s == 0) {
                cout << "No" << endl;
                exit(0);
            }
            int j = bt.lower_bound(s) - 1;
            bt.add(j, -1);
            c[l + i] = j;
        }
    }

    cout << "Yes" << endl;

    return 0;
}

