ll pow(ll a, ll e) {
  if (a < 0 || e < 0) {
    return 0;
  }

  if (e == 0) {
    return 1;
  }

  if (e % 2 == 0) {
    ll half = pow(a, e / 2);
    return half * half;
  }

  return a * pow(a, e - 1);
}

void solve() {
  ll N;
  cin >> N;

  ll length = 1 << N;

  VL ss(length);
  rep(i, length) {
    ll s;
    cin >> s;
    s *= -1;
    ss[i] = s;
  }

  sort(all(ss));

  multiset<ll> used;
  multiset<ll> not_used;

  used.insert(ss[0]);
  repf(i, 1, length) not_used.insert(ss[i]);

  while (!not_used.empty()) {
    VL used_this_time(0);

    for (auto s : used) {
      auto it = not_used.upper_bound(s);
      if (it == not_used.end()) drop("No");
      used_this_time.push_back(*it);
      not_used.erase(it);
    }

    for (auto s : used_this_time) {
      used.insert(s);
    }
  }

  cout << "Yes" << endl;
}

