bool dfs(int i, int N, map<int, int> &count) {
    if (i >= N) {
        return true;
    }

    int a_maxi = 0;
    int b_maxi = 0;
    map<int, int> a;
    int f = true;
    FOE(p, count) {
        if (p.second == 0) {
            continue;
        }
        if (p.second % 2 == 0) {
            a[p.first] = p.second / 2;
            count[p.first] /= 2;

            chmax(a_maxi, p.first);
            chmax(b_maxi, p.first);

        }
        else {
            if (f) {
                a[p.first] = p.second / 2;
                count[p.first] -= a[p.first];

                if (p.second == 1) {
                    chmax(b_maxi, p.first);
                }
                else {
                    chmax(a_maxi, p.first);
                    chmax(b_maxi, p.first);
                }

            }
            else {
                a[p.first] = ceil(p.second, 2);
                count[p.first] -= a[p.first];

                if (p.second == 1) {
                    chmax(a_maxi, p.first);
                }
                else {
                    chmax(a_maxi, p.first);
                    chmax(b_maxi, p.first);
                }
            }

            f = not f;
        }
    }

    if (a_maxi == b_maxi) {
        return false;
    }

    return dfs(i + 1, N, a) and dfs(i + 1, N, count);
}

