struct node {
    int value, subsize;
    vector<node*> children;
};
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<node*> tree = {new node()};
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < (1 << i); j++) {
            tree.push_back(new node());
            tree[j]->children.push_back(tree.back());
        }
    }
    for(int i = tree.size() - 1; i >= 0; i--) {
        tree[i]->subsize = 1;
        for(node* v : tree[i]->children) {
            tree[i]->subsize += v->subsize;
        }
    }
    vector<int> parent = {-1};
    vector<int> s(1 << n);
    cin >> s;
    sort(s.begin(), s.end(), greater<int>());
    int id = 0;
    priority_queue<pair<int, node*>> q;
    q.push({tree[0]->subsize, tree[0]});
    while(not q.empty()) {
        node* u = q.top().second;
        u->value = s[id++];
        q.pop();
        for(node* v : u->children) {
            parent.push_back(id);
            q.push({v->subsize, v});
        }
    }
    bool can = true;
    for(node* u : tree) {
        for(node* v : u->children) {
            can &= u->value > v->value;
        }
    }
    cout << (can ? "Yes" : "No") << endl;
    for(node* n : tree) delete n;
    return 0;
}

