using namespace std;

struct index_t {
    int depth, num;
    bool operator==(index_t x) {
        return depth == x.depth && num == x.num;
    }
};

template<typename T>
class perfectBinaryTree {
private:
    int depth;
    std::deque<T> v;

    inline int index(int depth, int num) {
        assert(depth <= this->depth && depth >= 0);
        int rest = (depth == 0 ? 0 : std::pow(2, depth) - 1);
        int result = rest + num;
        assert(0 <= num && (rest == 0 || num <= rest));
        return result;
    }

    inline int index(index_t x) { return index(x.depth, x.num); }

public:
    perfectBinaryTree(int depth, T value) : depth(depth),
                                            v(std::pow(2, depth + 1) - 1, value) {}

    index_t parent(int depth, int num) {
        assert(depth >= 1 && depth <= this->depth
                    && num < std::pow(2, depth));
        return {depth - 1, num / 2};
    }

    index_t parent(index_t x) { return parent(x.depth, x.num); }

    index_t commonAncestor(index_t x, index_t y) {
        assert(x.depth >= 1 && x.depth <= this->depth
                    && x.num < std::pow(2, x.depth));
        assert(y.depth >= 1 && y.depth <= this->depth
                    && y.num < std::pow(2, y.depth));

        if (x.depth != y.depth) {
            int d = abs(x.depth - y.depth);
            if (x.depth < y.depth) std::swap(x, y);
            assert(x.depth > y.depth);
            for (int i = 0; i < d; ++i) x = parent(x.depth, x.num);
        }
        assert(x.depth == y.depth);
        int i = log2(abs(x.num - y.num) + 1);

        while(x.num / (int)std::pow(2, i) != y.num / (int)std::pow(2, i)) ++i;
        return {x.depth - i, x.num / (int)std::pow(2, i)};
    }

    index_t commonAncestor(int depth1, int num1, int depth2, int num2) {
        return commonAncestor({depth1, num1}, {depth2, num2});
    }

    T &operator[](index_t p) { return v[index(p.depth, p.num)]; }
};

