using namespace std;

int A[1 << 18];
int seg[1 << 19];

int n;

void update(int k, int a) {
	k += (n) - 1;
	seg[k] = a;
	while (k > 0) {
		k = (k - 1) / 2;
		seg[k] = min(seg[k * 2 + 1], seg[k * 2 + 2]);
	}
}

int get(int a, int b, int k, int l, int r) {
	if (r <= a || b <= l)return 2000000000;
	if (a <= l && r <= b)return seg[k];
	else {
		int v1 = get(a, b, k * 2 + 1, l, (l + r) / 2);
		int v2 = get(a, b, k * 2 + 2, (l + r) / 2, r);
		return min(v1, v2);
	}

}

int main() {
	int N;
	cin >> N;
	n = 1 << N;

	for (int i = 0; i < (1 << N); i++) {
		cin >> A[i];
	}

	sort(A, A + (1 << N), greater<int>());

	for (int i = 0; i < n; i++) {
		update(i, A[i]);
	}

	int m = 2000000000;
	if (N == 1) {
		if (A[0] == A[1])cout << "No" << endl;
		else cout << "Yes" << endl;
		return 0;
	}
	for (int i = 0; i < N - 1; i++) {
		int beg = 1 << i, end = 1 << (i + 1);
		m = min(m, get(0, beg, 0, 0, n));
		if (m == get(beg, end, 0, 0, n)) {
			cout << "No" << endl;
			return 0;
		}
	}
	cout << "Yes" << endl;
	return 0;
}

