bool f(vector<ll> v){
  ll t = (ll)v.size();
  if(v[t-1]==v[t-2]) return false;
  if(t==2&&v[0]!=v[1]) return true;
  ll s = t/2LL;
  vector<ll> a(s,0LL),b(s,0LL);
  a[s-1]=v[t-1];
  b[s-1]=v[t-2];
  auto itea = lower_bound(v.begin(),v.end(),b[s-1]);
  ll cnt = (ll)(v.end()-itea)-1LL;
  if(cnt>s) return false;
  for(ll i = 0LL; i < cnt-1; i++){
    a[s-2-i] = b[s-1];
  }
  ll A = 0,B=0;
  for(ll i = 0LL; i < t-1-cnt;i++){
    if(i%2==0) {
      b[B]=v[i];
      B++;
    }
    if(i%2==1){
      if(a[A]!=0) {
        b[B]=v[i];
        B++;
      }
      else {
        a[A]=v[i];
        A++;
      }
    }
  }
  return f(a)&&f(b);
}

