//指数関数をPythonっぽくやるための計算c_pow
//第二引数まで指定した場合はa^bを計算
//第三引数まで指定した場合はa^bをmodで割った余りを計算
template<class T>
T c_pow(T a, long long b){
    if(b == 0) return T(1);
    if(b % 2 == 0){
        T d = c_pow(a,b/2);
        return d*d;
    }else return a*c_pow(a,b-1);
}
long long c_pow(long long a, long long b, long long mod){
    if(b == 0) return 1LL;
    if(b % 2 == 0){
        long long d = c_pow(a,b/2,mod);
        return (d*d)%mod;
    }else return a%mod*c_pow(a,b-1,mod)%mod;
}

/*
[1,2^i]の最小値が重複している個数をa,[2^i + 1, 2^(i+1)]の最大値の個数をbとしたときに、
if(前者の最小値==後者の最大値){
    if(2^i - a < b) judge = false;
}
をしたい
*/

int main(){
    int n; cin >> n;
    int s_size = 1; rep(i,n) s_size *= 2;
    vector<int> s(s_size); rep(i,s_size) cin >> s[i];
    sort(s.begin(),s.end(),greater<int>());
    bool judge = true;
    int Lnot_mincnt,Rmaxcnt;
    int region; //今見ている区間の指数
    for(int i = 0; i < n; i++){
        region = c_pow(2,i);
        Lnot_mincnt = 0, Rmaxcnt = 0;
        for(int j = 0; j < region; j++){ //各区間についてみていく
            if(s[j] > s[region]) Lnot_mincnt++;
            if(s[j + region] == s[region]) Rmaxcnt++;
        }
        if(Lnot_mincnt < Rmaxcnt){
            judge = false;
            break;
        }
    }
    if(judge) cout << "Yes" << endl;
    else cout << "No" << endl;
}

