const int INF = 1e9 + 10;

int build(int u, int sub, int d, int p) {
  dep[u] = d;
  par[u] = p;

  int ht = sub;
  cur.push_back(ht + '0');

  int lim = p == -1 ? INF : ans[p];
  auto it = ss.lower_bound(lim);
  if (it == ss.begin()) NO();
  it--;
  ans[u] = *it;
  ss.erase(it);

  for (int i = 0; i < sub; i++) {
    int v = idx++;
    adj[u].push_back(v);
    build(v, sub - 1 - i, d + 1, u);
  }

  at[d].push_back(u);

  ty[u] = cur;
  reverse(ty[u].begin(), ty[u].end());
  cur.pop_back();

  return ht;
}

