        que.emplace(RD());
    }

    vector<i64> pre(1, POP(que));
    REP(i, N) {
        i64 m = 1LL<<i;  // 新たに生まれる数

        auto cur = vec_reserve<i64>(m);
        ALL(sort, pre, greater<>{});
        DBG(pre);
        REP(j, m) {
            i64 a = POP(que);
            if(pre[j] == a) impossible();
            cur.emplace_back(a);
        }

        pre.insert(end(pre), begin(cur), end(cur));
    }

    PRINTLN("Yes");
}

