const int nCk_MAX = 22;
long long comb[nCk_MAX + 1][nCk_MAX + 1];
void calcomb() {
	for (int i = 0; i <= nCk_MAX; i++) {
		for (int j = 0; j <= i; j++) {
			if (j == 0 || j == i)
				comb[i][j] = 1;
			else
				comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
		}
	}
}
#undef nCk_MAX
int PW(int x, int n) {
	int ret = 1;
	FOR(i, 0, n)ret *= x;
	return ret;
}
int main() {
	calcomb();

	int N;
	cin >> N;
	int NS = PW(2, N);
	vector<int> input(NS);
	for (int i = 0; i < NS; ++i) {
		cin >> input[i];
	}

	priority_queue<int>pq;
	FOR(i, 0, NS)pq.push(input[i]);
	vector<int>a(NS + 1);
