		int cb = comb[dep - 1][1];
		FOR(x, 0, cb) {
			int v = pq.top(); pq.pop();
			left.emplace_back(v);
		}
		FOR(x, 0, cb) {
			f(dep - 1 - x, left[x], now);
		}
	};
	int fi = pq.top(); pq.pop();
