bool judge(int N, const vector<int> &S){
  int L = S.size();
  vector<int> V;
  vector<bool> A(L,false);
  A[0] = true;
  V.push_back(S[0]);
  for(int i = 0; i < N; ++i){
    sort(V.rbegin(), V.rend());
    size_t l = 0;
    vector<int> V_;
    for(int j = 0; j < (1<<N); ++j){
      if(A[j]) continue;
      if(S[j] >= V[l]) continue;
      ++l;
      A[j] = true;
      V_.push_back(S[j]);
      if(l == V.size()) break;
    }
    if(l != V.size()) return false;
    V.insert(V.end(),V_.begin(),V_.end());
  }
  bool ret = true;
  for(auto e : A) ret &= e;
  return ret;
}

