int query(int no,int i,int j,int a,int b){
	if(i>j || i>b || j<a)return 0;
	if(a<=i && j<=b)return tree[no];
	int l = 2*no,r=2*no+1, m =(i+j)/2;
	return max(query(l,i,m,a,b),query(r,m+1,j,a,b));
}

