        it--;
        return *it;
    }
    return -1;
}

void solve()
{
    cin >> n;
    for (int i = 1; i <= st(n); ++i)
        scanf("%d", &s[i]);
    for (int i = 1; i <= st(n); ++i)
        vis.insert(s[i]);
    for (int i = 1; i <= st(n); ++i)
        S1.insert(s[i]);
    sort(s + 1, s + st(n) + 1, greater<int>());
    S2.insert(s[1]);
    S1.erase(S1.find(s[1]));
    if (S1.count(s[1]) == 0)
        vis.erase(s[1]);
    int tim = 1;
    vector<int> tmp;
    while (tim <= n)
    {
        // puts("flag");
        tmp.clear();
        for (auto &i : S2)
        {
            int x = Query(i);
            if (S1.empty())
                return puts("Yes"), void();
            if (x == -1 || S1.count(x) == 0)
                return puts("No"), void();
            S1.erase(S1.find(x));
            if (!S1.count(x))
                vis.erase(x);
            if (S1.empty())
                return puts("Yes"), void();
            tmp.push_back(x);
        }
        for (auto &i : tmp)
            S2.insert(i);
        tim++;
    }
    puts("No");
}

