int n,sum=1;
int tot,root;
struct node{
	int l,r;
	int dat,val;
	int size;
}f[2000010];
void update(int p)
{
	f[p].size=f[f[p].l].size+f[f[p].r].size+1;
}
int New(int val)
{
	f[++tot].val=val;
	f[tot].dat=rand();
	f[tot].size=1;
	return tot;
}
void split(int p,int val,int &x,int &y)
{
	if(p==0)
	{
		x=0,y=0;
		return;
	}
	if(f[p].val<=val)
	{
		x=p;
		split(f[p].r,val,f[p].r,y);
	}
	else
	{
		y=p;
		split(f[p].l,val,x,f[p].l);
	}
	update(p);
}
int merge(int a,int b)
{
	if(!a||!b) return a+b;
	if(f[a].dat<f[b].dat)
	{
		f[a].r=merge(f[a].r,b);
		update(a);
		return a;
	}
	else
	{
		f[b].l=merge(a,f[b].l);
		update(b);
		return b;
	}
}
void insert(int val)
{
	int x,y;
	split(root,val,x,y);
	root=merge(merge(x,New(val)),y);
}
void remove(int val)
{
	int x,y,z;
	split(root,val,x,z);
	split(x,val-1,x,y);
	y=merge(f[y].l,f[y].r);
	root=merge(merge(x,y),z);
}
int getRank(int val)
{
	int x,y;
	split(root,val-1,x,y);
	int ans=f[x].size+1;
	root=merge(x,y);
	return ans;
}
int getVal(int p,int rank)
{
	while(p)
	{
		if(f[f[p].l].size>=rank) p=f[p].l;
		else if(f[f[p].l].size+1==rank) return f[p].val;
		else rank-=f[f[p].l].size+1,p=f[p].r;
	}
}
int getPre(int val)
{
	int x,y;
	split(root,val-1,x,y);
	int ans=getVal(x,f[x].size);
	root=merge(x,y);
	return ans;
}
int getNext(int val)
{
	int x,y;
	split(root,val,x,y);
	int ans=getVal(y,1);
	root=merge(x,y);
	return ans;
}
