void solve() {
	int n; cin >> n;
    vector<int> s(1<<n);
    multiset<int> t;
    rep(i, (1<<n)) {
        cin >> s[i];
        t.insert(s[i]);
    }
    sort(all(s));
    auto it = t.end();
    --it;
    t.erase(it);
    vector<int> u;
    u.push_back(s[(1<<n) - 1]);
    rep(i, n) {
        auto w = u;
        sort(all(u));
        reverse(all(u));
        for(auto j: u) {
            auto ite = t.lower_bound(j);
            if(ite == t.begin()) {
                cout << "No" << endl;
                return;
            }
            --ite;
            t.erase(ite); //erase(iterator)を使いべし！！　//erase(value) だと全valueが消える
            w.push_back(*ite);
        }
        swap(u, w);
    }
    cout << "Yes" << endl;
}

