int pw(int n,int k){
  if(k<0)return pw(n,k+MOD-1);
  int res=1;
  while(k){
    if(k&1)res*=n;//res%=MOD;
    n*=n;//n%=MOD;
    k>>=1;
  }
  return res;
}
//main
signed main(){
  int N;cin>>N;
  int R=pw(2,N);
  typedef pair<int,int> P;
  set<P> s;
  P m=P(0,0);
  for(int i=0;i<R;i++){
    int a;cin>>a;if(m.first<=a)m=P(a,i);
    s.insert(P(a,i));
  }
  std::vector<P> w(R);
  w[0]=m;s.erase(m);
  for(int i=0;i<N;i++){
    for(int j=0;j<pw(2,i);j++){
      if(s.size()==0)fin("No");
      P p=*--s.lower_bound(w[j]);
      if(p.first>=w[j].first)fin("No");
      w[j+pw(2,i)]=p;s.erase(p);
    }
  }
  fin("Yes");
}

