int main()
{
    const int USED = -1;

    int N;
    cin >> N;

    int cnt = 1;
    cnt <<= N;

    vector<int> S(cnt);
    for (int i = 0; i < cnt; ++i) {
        cin >> S[i];
    }

    sort(S.begin(), S.end(), greater<int>());

    vector<int> curr;
    curr.push_back(S[0]);
    S[0] = USED;

    bool ok = true;
    for (int i = 0; ok && i < N; ++i) {
        vector<int> next = curr;
        for (int n : curr) {
            for (int j = 1; j < cnt; ++j) {
                if (S[j] != USED && S[j] < n) {
                    next.push_back(S[j]);
                    S[j] = USED;
                    break;
                } else if (j == cnt-1) {
                    ok = false;
                }
            }
        }
        curr.swap(next);
    }

    cout << (ok ? "Yes" : "No") << endl;

    return 0;
}

