using namespace std;
typedef long long ll;
typedef pair<int, int> PII;

bool solve() {
  int n; cin >> n;
  int N = 1;
  for (int i = 0; i < n; i++) N *= 2;
  set<int> S;
  map<int, int> cnt;
  int M = 0;
  for (int i = 0; i < N; i++) {
    int x; cin >> x;
    S.insert(-x);
    cnt[-x] += 1;
    M = min(-x, M);
  }
  if (cnt[M] > 1) {
    return false;
  }
  S.erase(M);
  vector<int> v;
  v.push_back(M);
  int u = 1;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < u; j++) {
      int x = v[j];
      auto y = S.upper_bound(x);
      if (y == S.end()) {
        return false;
      }
      cnt[*y] -= 1;
      if (cnt[*y] == 0) {
        S.erase(*y);
      }
      v.push_back(*y);
    }
    u *= 2;
  }
  return true;
}

int main() {
  if (solve() == false) {
    cout << "No" << endl;
  } else {
    cout << "Yes" << endl;
  }
}

