void solve(vector<ll> s,ll n,ll k){
    sort(s.begin(),s.end());
    For(i,n){
        k/=2;
        vector<ll> child(k),mother(k);
        For(i,k){
            child.at(i)=s.at(i);
            //cout<<"child"<<i<<" "<<child.at(i)<<endl;
            mother.at(i)=s.at(i+k);
            //cout<<"mother"<<i<<" "<<mother.at(i)<<endl;
            if(child.at(i)>=mother.at(i)){
                cout<<"No"<<endl;
                return;
            }
        }
        s=mother;
        //cout<<i<<endl;
    }
    cout<<"Yes"<<endl;
    return;
}
void solve1(vector<ll> s,ll n,ll k){
    sort(s.begin(),s.end());
    reverse(s.begin(),s.end());
    vector<ll> mother;
    mother.push_back(s.at(0));
    s.erase(s.begin());
    reverse(s.begin(),s.end());
    For(i,n){
        vector<ll> newmother=mother;
        for(auto j:mother){
            auto iter=lower_bound(s.begin(),s.end(),j);
            ll k=distance(s.begin(),iter);
            //cout<<k<<endl;
            if(k==s.size()-1){
                cout<<"No"<<endl;
                return;
            }
            else{
                newmother.push_back(s.at(k-1));
                s.erase(s.begin()+k-1);
            }
        }
        mother=newmother;
    }
    cout<<"Yes"<<endl;
    return;
}
