main() {
  int64_t n;
  cin >> n;

  int64_t k = (1L << n);
  vector<int64_t> s(k);
  for (auto&& ss : s) {
    cin >> ss;
  }

  sort(s.rbegin(), s.rend());

  map<int64_t, int64_t> idxs;
  int64_t prev = -1;
  for (auto ss : s | indexed(0)) {
    auto idx = ss.index();
    auto v = ss.value();
    if (prev != v) {
      idxs[v] = idx;
    }
    prev = v;
  }
  idxs[0] = s.size();


  for (auto i : irange(0L, n)) {
    int64_t l = s[s.size() / 2 - 1];
    int64_t r = s[s.size() / 2];

    if (l == r) {
      auto it = idxs.find(l);
      int64_t m = it->second;
      --it;
      int64_t m2 = it->second - s.size() / 2;

      if (m < m2) {
        cout << "No" << endl;
        return 0;
      }
    }

    s.resize(s.size() / 2);
  }

  cout << "Yes" << endl;
}

