	int s = 0;
	vector<ll> parents;
	parents.push_back(v.back());
	v.pop_back();
	bool valid = true;
	while(v.size()) {
		vector<ll> children;
		for (int i = 0; i < (1 << s); i++) {
			children.push_back(v.back());
			v.pop_back();
		}
		multiset<ll> par;
		for (auto i : parents)
			par.insert(i);

		for (auto i : children) {
			auto it = par.upper_bound(i);
			if (it == par.end()) {
				valid = false;
				break;
			}
			par.erase(it);
		}
		if (!valid)
			break;

		for (auto i : children) {
			parents.push_back(i);
		}
		s++;
	}
	if (valid) {
		cout << "Yes";
	}
	else {
		cout << "No";
	}

