ll solve() {
    ll N;
    cin >> N;
    vector<ll> S(1 << N);
    for ( int i = 0; i < (1 << N); i++ ) {
        cin >> S[i];
    }
    sort(S.begin(), S.end(),greater<>());
    auto flip = [](ll x) {
        x = x | (x >> 1);
        x = x | (x >> 2);
        x = x | (x >> 4);
        x = x | (x >> 8);
        x = x | (x >>16);
        x = x | (x >>32);
        return x ^ (x - (x >> 1));
    };
    for ( ll i = (1 << N) - 1; i > 0; i-- ) {
        if ( S[i] == S[flip(i)] ) return false;
    }
    return true;
}

