#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const ll INF = (1ll << 31) - 1;

struct Segment {
    int n;
    vector<ll> node;

    Segment(int N) {
        n = 1;
        while (n < N) n *= 2;

        // ノード数は ceil(log2(N))^2 * 2 (葉数が2べきとなるよう調整)
        node.assign(2 * n - 1, -INF);
    }

    void update(int k, ll a) {  // k番目の値をaに変更
        // k番目の葉 : k+n-1
        k += n - 1;
        node[k] = a;

        // 子 → 親 : (k-1)/2
        // 親 → 子(1,2) : 2*k + (1,2)
        while (k > 0) {
            k = (k - 1) / 2;
            node[k] = max(node[2 * k + 1], node[2 * k + 2]);
        }
    }

    ll find_max(int a, int b, int k = 0, int l = 0, int r = -1) {  // [a,b)の最大値を返す
        if (r < 0) r = n;

        // 含まない
        if (r <= a || b <= l) return -INF;
        // 完全に含む
        if (a <= l && r <= b)
            return node[k];
        else {
            ll vl = find_max(a, b, 2 * k + 1, l, (l + r) / 2);
            ll vr = find_max(a, b, 2 * k + 2, (l + r) / 2, r);

            return max(vl, vr);
        }
    }
};

int main() {
    int n;
    cin >> n;
    int N = pow(2, n);
    Segment tree(N);
    vector<ll> a(N);
    for (int i = 0; i < N; i++) {
        ll s;
        cin >> a[i];
    }
    sort(a.begin(),a.end());
    for(int i = 0;i < N;i ++){
        tree.update(i,a[i]);
    }
    for (int j = 0; j < n; j++) {
        int d = pow(2, j);
        for (int i = 0; i + d < N; i += d * 2) {
            if (tree.find_max(i, i + d) == tree.find_max(i + d, i + 2 * d)) {
                cout << "No" << endl;
                return 0;
            }
        }
    }
    cout << "Yes" << endl;
    return 0;
}

