        sort(all(have), greater<int>());

        vi get;
        trav (e, have) {
            auto mk = need.lb(e);
            if (mk == need.begin()) { ps("No"); return 0; }
            mk = prev(mk);
            get.pb(*mk);
            need.erase(mk);
        }

        have.insert(have.end(), all(get));
    }

    assert(sz(have) == (1 << N));
    ps("Yes");

    return 0;
}

