void solve()
{
    int n;
    cin >> n;
    int m = 1 << n;
    aoi<int> as;
    aoi<pair<int, int>> pq;
    for (int i = 0; i < m; i++)
    {
        int a;
        cin >> a;
        as.push(a);
    }
    pq.push(make_pair(as.top(), n));
    as.pop();
    while (!as.empty())
    {
        int a = pq.top().first, b = pq.top().second, c = b - 1;
        pq.pop();
        while (b--)
        {
            int na = as.top();
            as.pop();
            if (na >= a)
            {
                cout << "No\n";
                return;
            }
            if (b)
                pq.push(make_pair(na, b));
        }
        if (c)
        {
            pq.push(make_pair(a, c));
        }
    }
    cout << "Yes\n";
}

