template <class T, std::size_t n>
class StaticVector : public boost::container::static_vector<T, n>
{
    using Parent = boost::container::static_vector<T, n>;

public:
    // is_constructible_v >= C++17
    template <class... Args, std::enable_if_t<std::is_constructible<Parent, Args&&...>::value, std::nullptr_t> = nullptr>
    StaticVector(Args&&... args) : Parent(std::forward<Args>(args)...) {}
    StaticVector(input& in, std::size_t n_) : Parent(n_)
    {
        for (std::size_t i = 0; i < n_; ++i) in >> static_cast<Parent&>(*this)[i];
    }
};

int main()
{
    input in;
    output out;

    int N = in.read<int>();
    StaticVector<int, (1 << 18)> S(in, 1 << N);
    std::sort(S.begin(), S.end(), std::greater<>());

    auto it = S.begin() + 1;
    for (int i : boost_irange(N)) {
        auto it2 = it;
        for (int j : boost_irange(1 << i)) {
            it2 = std::lower_bound(it2, S.end(), S[j], std::greater_equal<>());
            if (it2 == S.end()) {
                out << "No";
                return 0;
            }
            if (it != it2) {
                // out << i, j, "swap", S[j], *it, *it2, std::distance(S.begin(), it), std::distance(S.begin(), it2);
                std::swap(*it, *it2);
                ++it;
                for (auto it3 = it2; it3 != it; --it3) {
                    if (*(it3-1) < *it3)
                        std::swap(*it3, *(it3 - 1));
                    else
                        break;
                }
            } else {
                ++it;
                ++it2;
            }
        }
        std::sort(S.begin(), it, std::greater<>());
    }

    // for (auto x : S) std::cout << x << " ";

    out << "Yes";

    return 0;
}

