struct BST {
	int root, totNd;
	int fa[MAX], ch[MAX][2], val[MAX], rec[MAX], size[MAX];
	inline int cre_node(int _val) {
		val[++totNd] = _val, size[totNd] = rec[totNd] = 1;
		return totNd;
	}
	inline void link(int u, int f, bool ind) {
		fa[u] = f, ch[f][ind] = u;
		return;
	}
	inline void upd(int u) {
		size[u] = rec[u] + size[ch[u][0]] + size[ch[u][1]];
		return;
	}
	inline void rotate(int u) {
		int f = fa[u], g = fa[f]; bool ind = ch[f][1] == u;
		link(ch[u][ind ^ 1], f, ind), link(f, u, ind ^ 1), link(u, g, ch[g][1] == f);
		upd(f), upd(u);
		return;
	}
	inline void splay(int u, int tar = 0) {
		int f = fa[u], g;
		while(f != tar) {
			g = fa[f];
			if(g != tar)
				rotate( (ch[g][1] == f) ^ (ch[f][1] == u) ? u : f );
			rotate(u), f = fa[u];
		}
		if(!tar) root = u;
	}
	void insert(int _val) {
		int u = root, f = 0;
		while(u && val[u] != _val) f = u, u = ch[u][_val > val[u]];
		if(u) {
			++rec[u], ++size[u];
		} else {
			u = cre_node(_val);
			link(u, f, _val > val[f]);
		}
		splay(u);
	}
	int find(int _val) {
		int u = root;
		while(val[u] != _val) u = ch[u][_val > val[u]];
		return u;
	}
	int pre(int _val) {
		int u = find(_val); splay(u);
		u = ch[u][0];
		while(ch[u][1]) u = ch[u][1];
		return u;
	}
	int suf(int _val) {
		int u = find(_val); splay(u);
		u = ch[u][1];
		while(ch[u][0]) u = ch[u][0];
		return u;
	}
	void del(int _val) {
		int u = find(_val); splay(u);
		if(rec[u] > 1) --rec[u], --size[u];
		else {
			int p = pre(_val), s = suf(_val);
			splay(p), splay(s, p);
			ch[s][0] = 0, fa[u] = 0;
			upd(s), upd(p);
		}
		return;
	}
	void init() {
		insert(INT_MIN), insert(INT_MAX);
		return;
	}
}lsk;

