	int x = 0; char ch = getchar();
	while(ch < '0' || ch > '9') ch = getchar();
	while(ch >= '0' && ch <= '9') x = x * 10 + ch - '0', ch = getchar();
	return x;
}

int main() {
	//extra_test();
	n = Rd(), upp = 1 << n;
	lsk.init();
	for(reg int i = 1; i <= upp; ++i) lsk.insert(Rd());
	stk[++top] = lsk.val[lsk.pre(INT_MAX)], lsk.del(stk[top]);
	for(reg int i = 1; i <= n; ++i) {
		int tp = top;
		for(reg int j = 1; j <= tp; ++j) {
			lsk.insert(stk[j]);
			stk[++top] = lsk.val[lsk.pre(stk[j])];
			lsk.del(stk[j]);
			if(stk[top] == INT_MIN) {
				puts("No");
				return 0;
			}
			lsk.del(stk[top]);
		}
	}
