int leaf(int n) {
  int a=1;
  while(a<n) a *= 2;
  return a;
}

struct PQ2 {

  vector<int> value;

  PQ2(int n) : value(0) {
    int ct = leaf(n)*2-1;
    rep(i,0,ct) value.pb(0); // 全部0
  }

  void update(int i, int x) {
    int N = (value.size()+1)/2;
    i += N - 1;
    value[i] += x;
    while (i > 0) {
      i = (i - 1) / 2;
      value[i] = value[i * 2 + 1]+value[i * 2 + 2];
    }
    return;
  }

  int at(int i) { //i番目の要素にアクセス
    int N = (value.size()+1)/2;
    return value[i-1+N];
  }

  int count(int i) { //i番目の要素にアクセス
    int N = (value.size()+1)/2;
    return value[i-1+N];
  }

  int RSQ2(int a, int b, int k, int l, int r) {
    // [a, b) の区間に対するクエリについて
    // ノード k （区間 [l, r) 担当）が答える
    if (r <= a || b <= l) return 0; // 区間が被らない場合は0を返す
    if (a <= l && r <= b)
      return value[k]; // ノード k の担当範囲がクエリ区間 [a, b)に完全に含まれる
    else {
      int c1 = RSQ2(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子に値を聞く
      int c2 = RSQ2(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子に値を聞く
      return c1+c2; // 左右の子の値の sum を取る
    }
  }

  int rsum(int a,int b) {
    int N = (value.size()+1)/2;
    return RSQ2(a,b+1,0,0,N);
  }

  void insert(int a) {
    update(a,1);
    return;
  }

  int rank(int i) {
    i++;
    int L=0,R=(value.size()+1)/2-1;
    int mid = (L+R)/2;
    int eq,minus,ct=0;
    while(ct<30){
      eq = rsum(0,mid);
      minus = rsum(0,mid-1);

      if(eq == i && minus <= i-1) {
        break;
      }
      if(eq > i) {
        R = mid;
      }
      if(eq == i && minus == i) {
        R = mid;
      }
      if(eq < i) {
        L = mid;
      }
      mid = (L+R)/2;
      ct++;
    }
    if(ct==30) mid++;
    return mid;
  }

  int rankr(int i) {
    return rank(value[0]-1-i);
  }

  void erase(int a) {
    update(a,-1);
    return;
  }

  int smaller(int k) {
    int L=0,R=k-1;
    if(rsum(0,k-1)==0) return -1;
    int mid = (L+R)/2;
    while(L<R) {
      if(rsum(mid,R) == 0){
        R = mid-1;
      }
      else {
        L = mid;
      }
      mid = (L+R+1)/2;
    }
    return mid;
  }

  int bigger(int k) {
    int L=k+1,R=(value.size()+1)/2-1;
    if(rsum(L,R)==0) return -1;
    int mid = (L+R)/2;
    while(L<R) {
      if(rsum(L,mid) == 0){
        L = mid+1;
      }
      else {
        R = mid;
      }
      mid = (L+R)/2;
    }
    return mid;
  }

};

