void solve()
{
    int n;
    cin >> n;
    int m = 1 << n;
    aoi<int> as;
    aoi<pair<int, int>> pq;
    for (int i = 0; i < m; i++)
    {
        int a;
        cin >> a;
        as.push(a);
    }
    pq.push(make_pair(as.top(), n));
    as.pop();
    while (!as.empty() && !pq.empty())
    {
        int a = pq.top().first, b = pq.top().second;
        pq.pop();
        if (b == 0)
