    ll kazuwa = 0;
    ll limit = 0;
    REP(i, N+1){
    	kazuwa += cnt[i];
    	limit += Combination(N, i);
    	if(kazuwa>limit){
    		cout << "No" <<endl;
    		return 0;
    	}
    }
    cout << "Yes" << endl;
    return 0;
}

