class Shakutori {
public:
  // 全体の範囲
  // [0, end)
  // 注目している範囲
  // [tail, head)
  Int head, tail, end = 0;
  bool moveHead() {
    if (head == end) {
      return false;
    }
    head++;
    return true;
  }
  void moveTail() { tail++; }
  bool valid() {
    if (head == tail)
      return true;
    // [tail, head)
    // が解として適当か検証する
    return true;
  }
  void solve() {
    head = tail = 0;
    Int ans = 0;
    while (moveHead()) {
      while (!valid()) {
        moveTail();
      }
      // ここで解を更新する
    }
  }
};

class Solver {
public:
  bool ans = 0;
  Int N;
  vi S;
  Solver() {}
  void input() {
    cin >> N;
    S = vi(1<<N);
    FOR(s, S)cin >> s;
  }
  void solve() {
    multiset<Int> remain, now;
    sort(S);
    rep(i, S.size() -1){
      remain.insert(S[i]);
    }
    now.insert(S.back());

    while(!remain.empty()){
      vi next;
      for(auto a = now.rbegin(); a != now.rend(); a++){
        auto from = *a;
        Int to = 0;
        auto it = remain.lower_bound(from-1);
        to = *remain.rbegin();
        if(it != remain.end()) {
          to = *it;
        }
        if(to >= from){
          return;
        }
        next.push_back(to);
        remain.erase(remain.lower_bound(to));
      }
      FOR(n, next)now.insert(n);
    }
    ans =1;
    return;
  }
  void output() {
    cout << ans <<endl;
  }
};

