#define FOR0(var, max) for (ui (var) = 0; (var) < (max); ++(var))
#define FORINV(var, min, max) for (ui (var) = (max) - 1; (var) + 1 > (min); --(var))

using namespace std;

using uc = unsigned char;
using ui = unsigned int;
using ul = unsigned long long int;

const static ui NMAX = 18;
const static ui SiMAX = 1<<18;
const static ui SMAX = 1000000000;

static ui N;
static vector<ui> Si;

bool solve(void) {
  multiset<ui> confirmed;

  sort(Si.begin(), Si.end(), greater<ui>());
  multiset<ui> remain (Si.begin(), Si.end());

  auto first = *max_element(remain.begin(), remain.end());
  confirmed.insert(first);
  remain.erase(first);

  FOR0(i, N) {
    multiset<ui> cur;
    multiset<ui> tmp (confirmed);

    FOR0(j, confirmed.size()) {
      ui confirmed_max = *max_element(tmp.begin(), tmp.end());
      auto next_gen = remain.lower_bound(confirmed_max);
      if (next_gen == remain.begin()) {
        return false;
      }
      cur.insert(*--next_gen);
      remain.erase(next_gen);
      tmp.erase(confirmed_max);
    }

    for (auto it = cur.begin(); it != cur.end(); it++) {
      confirmed.insert(*it);
    }
  }

  return true;
}

int main(void) {
  cin >> N;
  FOR0(i, (1U << N)) {
    ui t;
    cin >> t;
    Si.push_back(t);
  }
  cout << (solve() ? "Yes" : "No") << endl;
  return 0;
}

