bool judge(int N, const vector<int> &S){
  int l = 1;
  int L = S.size();
  vector<int> T(L,0);
  T[0] = N;
  for(int i = 0; i < L; ++i){
    for(int j = 0; j < T[i]; ++j){
      if(S[i] <= S[l]) return false;
      T[l] = T[i] - j - 1;
      ++l;
    }
  }
  return true;
}

