bool dfs(llong now, int edge, multiset<llong> &ms) {
	if (edge == 0)
		return true;

	bool check = true;
	for (int i = 0; i < edge; ++i) {
		auto next_it = ms.lower_bound(now);
		if (next_it == ms.begin())
			return false;
		next_it--;
		llong next = *next_it;
		ms.erase(next_it);
		check &= dfs(next, edge-i-1, ms);
	}

	return check;
}

