    qq.push(n);
    for (int i = 1; i < c; i++){
        int x = cnt[i];
        vector < int > b;
        b.clear();
        while(!qq.empty() && x > 0){
            int y = qq.front();
            qq.pop();
            if (y > 1) b.pb(y - 1);
            x--;
            y--;
            if (y != 0) qq.push(y);
        }
        if (x != 0 && qq.size() == 0){
            ans--;
            break;
        }
        for (auto j: b) qq.push(j);
    }
    if (ans == 0){
        cout << "No";
    } else
    cout << "Yes";
}

