int sanku[19][30000];//3*9=27
void sankaku(int n){
  sanku[0][0] = 1;
  sanku[1][0] = 1;
  sanku[1][1] = 1;
  for(int i = 2; n > i; i++){
    for(int j = 0; i+1 > j; j++){
      if(j == 0 || j==i)sanku[i][j] = 1;
      sanku[i][j] = sanku[i-1][j-1]+sanku[i-1][j];
    }
  }
}

int main(){
  int n;cin>>n;
  sankaku(n+1);//using sanku[n][x]
  int KAISU = 1;
  for(int i = 0; n > i; i++)KAISU*=2;
  vector<int> a(KAISU);for(int i = 0; KAISU > i; i++)cin>>a[i];
  sort(a.begin(),a.end());
  int kind = 1;
  for(int i = 1; KAISU > i; i++){
    if(a[i-1]!=a[i])kind++;
  }
  int atu[kind];
  for(int i = 0; kind > i; i++){
    atu[i]=0;
  }
  int nw = 0;
  for(int i = 0; KAISU > i; i++){
    if(i!=0){
      if(a[i-1]!=a[i])nw++;
    }
    atu[nw]++;
  }
  int amari = 0;
  for(int i = kind-1; 0 <= i; i--){
    if(atu[i]>sanku[n][kind-1-i]+amari){
      cout << "No" << endl;
