using P = pair<int, int>;

vector<P> runLength(const vector<int>& s) {
    vector<P> res;
    int now = s[0];
    int cnt = 1;
    rep(i, 1, s.size()) {
        if (now == s[i]) {
            ++cnt;
        }
        else {
            res.emplace_back(now, cnt);
            now = s[i];
            cnt = 1;
        }
    }
