using namespace std;

const bool DEBUG = false;

int main(int argc, char const *argv[]) {
  long long N;
  cin >> N;
  const long long factorial_N = (long long)pow(2, N);
  vector<long long> S(factorial_N);
  for (long long i = 0; i < factorial_N; i++) {
    cin >> S[i];
  }
  sort(S.begin(), S.end(), greater<long long>());

  bool valid = true;
  vector<long long> store(2 * factorial_N - 1);
  long long idx, depth, left_most;
  set<long long> candidates;
  for (long long i = 1; i <= factorial_N; i++) {
    depth = (i == 1) ? 0 : (long long)log2(i - 1) + 1;
    if ((i == 1) || ((long long)log2(i - 1) == log2(i - 1))) {
      if (DEBUG) {
        cout << "left most: " << i << endl;
      }
      candidates.clear();
      left_most = (i == 1) ? 1 : (long long)pow(2, depth) + 1;
      for (size_t j = 0; j < (long long)pow(2, max(depth - 1, 0ll)); ++j) {
        candidates.insert(left_most + j * 2);
      }
    }
    if (DEBUG) {
      cout << "candidate at " << i << ": ";
      for (auto &&c : candidates) {
        cout << c << ", ";
      }
      cout << endl;
    }

    valid = false;
    for (auto &&candidate : candidates) {
      if (DEBUG)
        cout << "compare: " << store[candidate - 2] << " vs " << S[i - 1]
             << endl;
      if (i == 1 || store[candidate - 2] > S[i - 1]) {
        if (DEBUG) cout << "fill by " << S[i - 1] << ": ";
        idx = candidate;
        while (idx <= store.size()) {
          if (DEBUG) cout << idx << ", ";
          store[idx - 1] = S[i - 1];
          idx *= 2;
        }
        if (DEBUG) cout << endl;
        candidates.erase(candidate);
        valid = true;
        break;
      }
    }
    if (!valid) break;
  }

  if (valid)
    cout << "Yes" << endl;
  else
    cout << "No" << endl;

  return 0;
}

