bool res() {
	int n;
	cin >> n;
	if (!cin) return false;

	ll pot = pow(2, n);

	map<int, int> rest;
	int minn = 10;
	for (int i = 0; i < pot; ++i) {
		int num;
		cin >> num;
		minn = min(minn, -num);

		if (rest.find(-num) == rest.end()) rest.insert(mp(-num, 1));
		else ++rest[-num];
	}

	vi act, sig;

	act.push_back(minn);
	sig.push_back(minn);
	--rest[minn];
	if (rest[minn] == 0) rest.erase(minn);

	bool pos = true;

	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < act.size(); ++j) {
			auto it = rest.upper_bound(act[j]);
			if (it == rest.end()) {
				pos = false;
				break;
			}
			else {

				sig.push_back(it->first);
				--rest[it->first];
				if (rest[it->first] == 0) rest.erase(it->first);
			}
		}

		act = sig;
	}

	if (pos) cout << "Yes\n";
	else cout << "No\n";

	return true;
}

