		y=p;
		split(f[p].l,val,x,f[p].l);
	}
	update(p);
}
int merge(int a,int b)
{
	if(!a||!b) return a+b;
	if(f[a].dat<f[b].dat)
	{
		f[a].r=merge(f[a].r,b);
		update(a);
		return a;
	}
	else
