  int N; cin >> N;
  vector<int> S(1 << N); rep(i, 1 << N) cin >> S[i];
  sort(range(S));
  while (S.size() >= 2) {
    int i = 0;
    int x = 0;
    vector<bool> removed(S.size());
    while (i < S.size()) {
      int j = i;
      while (i < S.size() && S[i] == S[j]) i++;
      if (i - j == 1) {
        if (x > 0) x--;
      } else {
        for (int k = i - j; k >= 0; k--) {
          if (max(0, x - (i - j) + k) + k <= S.size() - i) {
            for (int l = 0; l < k; l++) {
              removed[j + l] = true;
            }
            x = max(0, x - (i - j) + k);
            x += k;
            break;
          }
        }
      }
    }
    int cnt = 0;
    rep(i, S.size()) {
      if (removed[i]) cnt++;
    }
    int p = -1;
    rep(i, S.size()) {
      if (!removed[i] && cnt < S.size() / 2) {
        if (p == -1) {
          p = i;
        } else if (S[p] < S[i]) {
          removed[p] = true;
          p = -1;
          cnt++;
        }
      }
    }
    if (cnt < S.size() / 2) {
      cout << "No" << endl;
      return 0;
    }
    vector<int> nxt;
    rep(i, S.size()) if (!removed[i]) nxt.push_back(S[i]);
    S = nxt;
  }
  cout << "Yes" << endl;
}

