inline int countocc(vector <int> &v, int val)
{
	return upper_bound(all(v),val)-lower_bound(all(v),val);
}
bool solve(vector <int> &left, vector <int> &right)
{
	if (left.size()!=right.size()) return false;
	int l_big = left.back();
	int r_small = right.front();
	if (l_big < r_small) return true;
	if (l_big > r_small) return false;
	int ctlb = countocc(left, l_big);
	int ctrs = countocc(right, r_small);
	return ctlb <= right.size() - ctrs;
}

