struct SegmentTree{
    vll tree;
    int n;
    int n_ex;

    SegmentTree(const vll& vec){
        n = vec.size();
        int a = 1;
        while(a < n){
            a *= 2;
        }
        n_ex = a;
        // set tree
        // parent: floor((n-1)/2)
        // child: 2n+1, 2n+2
        // leaf: n+i-1
        rep(i, 2*n_ex-1) tree.emplace_back(0);
        rep(i, n){
            update(i, vec[i]);
        }
    }

    // corresponds to vec[i] = x;
    void update(int i, ll x){
        i += n_ex - 1;
        tree[i] = x;
        while(i > 0){
            i = (i - 1) / 2;
            if(tree[i*2+1] == tree[i*2+2]) pr(0);
            tree[i] = max(tree[i*2+1], tree[i*2+2]);
        }
    }

    // range minimum query min( [a, b) );
    ll query(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return 0;
        if(a <= l && r <= b) return tree[k];
        else{
            ll vl = query(a, b, k*2+1, l, (l+r)/2);
            ll vr = query(a, b, k*2+2, (l+r)/2, r);
            return max(vl, vr);
        }
    }
    // from outside
    ll query(int a, int b){
        return query(a, b, 0, 0, n_ex);
    }
};


