ll pow(ll a, ll n) {
  ll res = 1;
  while (n > 0) {
    if (n & 1) res *= a;
    a *= a;
    n >>= 1;
  }
  return res;
}

ll mod_pow(ll a, ll n, ll mod) {
  ll res = 1;
  while (n > 0) {
    if (n & 1) res = res * a % mod;
    a = a * a % mod;
    n >>= 1;
  }
  return res;
}

ll mod_inv(ll a, ll mod) {
  return mod_pow(a, mod - 2, mod);
}

ll mod_Com(int n, int k, int mod) {
  ll p = 1, q = 1;
  for (int i = n - k + 1; i <= n; i++)
    p = p * i % mod;
  for (int i = 2; i <= k; i++)
    q = q * i % mod;
  q = mod_inv(q, mod);
  return p * q % mod;
}

bool solve() {
  int n; cin >> n;
  int N = pow(2, n);
  set<int> S;
  map<int, int> cnt;
  int M = 0;
  for (int i = 0; i < N; i++) {
    int x; cin >> x;
    S.insert(-x);
    cnt[-x] += 1;
    M = min(-x, M);
  }
  if (cnt[M] > 1) {
    return false;
  }
  S.erase(M);
  vector<int> v;
  v.push_back(M);
  for (int i = 0; i < n; i++) {
    for (auto x: v) {
      auto y = S.upper_bound(x);
      if (y == S.end()) {
        return false;
      }
      cnt[*y] -= 1;
      if (cnt[*y] == 0) {
        S.erase(*y);
      }
      v.push_back(*y);
    }
  }
  return true;
}

int main() {
  if (solve()) {
    cout << "Yes" << endl;
  } else {
    cout << "No" << endl;
  }
}

