  live[0] = heaven.top();
  heaven.pop();

  bool valid = true;
  while(valid && !heaven.empty()){
    vector<int> unborn;
    vector<int> born;
    for(auto itr = live.rbegin(); itr != live.rend(); itr++){
      int slime = INF;
      while(!heaven.empty()){
        slime = heaven.top();
        heaven.pop();
        if(slime >= *itr){
          unborn.emplace_back(slime);
        }else break;
      }
      if(slime < *itr){
        born.emplace_back(slime);
      }else{
        valid = false;
        break;
