//セグ木 
//dat[i]を参照するときは i + sz - 1 
ll dat[1010000], sz;

void init(ll n) {
	sz = 1;
	while (sz < n)sz *= 2;
}

void update(ll k, ll a) { //場所(0-indexed), 値
	k += sz - 1;
	dat[k] = a;
	while (k > 0) {
		k = (k - 1) / 2;
		dat[k] = max(dat[k * 2 + 1], dat[k * 2 + 2]); //更新
	}
}

ll query(ll a, ll b, ll k, ll l, ll r) { //[a, b) 呼ぶとき (a, b, 0, 0, sz)
	if (r <= a or b <= l)return 0;
	if (a <= l and r <= b)return dat[k];
	ll v1 = query(a, b, k * 2 + 1, l, (l + r) / 2);
	ll v2 = query(a, b, k * 2 + 2, (l + r) / 2, r);
	return max(v1, v2); //戻り値
}

ll n, now = 1;
int main() {
	cin >> n;
	init((1ll << n) + 1);
	vector<ll> s(1ll << n);
	REP(i, 1ll << n) {
		cin >> s[i];
	}
	sort(ALL(s), greater<ll>());
	REP(i, 1ll << n) {
		update(i, s[i]);
	}
	REP(i, 1ll << n) {
		ll cnt = n - 1, c2 = -1;
		REP(j, 20) {
			if (i & (1ll << j)) c2 = j;
		}
		cnt -= c2;
		//cout << cnt << endl;
		ll a = query(now, now + cnt, 0, 0, sz);
		now += cnt;
		if (s[i] <= a) {
			cout << "No" << endl;
			return 0;
		}
	}
	cout << "Yes" << endl;
}

