    cin >> N;
    for (int i = 0; i < 1<<N; i++)
    {
        ll s; cin >> s;
        S.push_back(s);
    }
    // sort(S.begin(),S.end(),greater<ll>());
    sort(S.begin(),S.end());
}

bool pesudo_solve(){
    auto chk = [&](int n){
        int idx = 1<<n;
        for (int i = 0; i < idx; i++) if(S[i]<=S[i+idx]) return false;
        return true;
        };
    for (int i = 0; i < N; i++) if(!chk(i)) return false;
    return true;
}

bool solve(){
    vector<int> a;
    a.push_back(S.back());
    S.back() = -1;
    for (int i = 0; i < N; i++)
    {
        sort(a.begin(),a.end());
        vector<int> tmp = a;
        int idx = (1<<N)-1;
        while(idx>=0 && !tmp.empty()){
            if(S[idx]==-1){
                idx--; continue;
            }
            if(S[idx]<tmp.back()){
                a.push_back(S[idx]);
                S[idx] = -1;
                tmp.pop_back();
            }
            idx--;
        }
        if(!tmp.empty()) return false;
    }
    return true;
}



int main()
{
    input();
    string ans = solve()?"Yes":"No";
    cout << ans << endl;
    return 0;
}

