#define FOR(i, n, m) for (ll(i) = (m); (i) < (n); ++(i))
#define REP(i, n) FOR(i, n, 0)
#define OF64 std::setprecision(10)

const ll MOD = 1000000007;
const ll INF = (ll)1e15;

ll S[1000005];
ll N;
ll D[25];
ll E[30];

string solve()
{
    ll M = pow(2, N);
    sort(S, S + M, [](ll a, ll b) { return a > b; });

    // REP(i, M)
    // {
    //     cout << S[i] << " ";
    // }
    ll n = 0;
    ll m = 0;
    ll num = 1;
    E[N + 1] = 1;
    REP(i, M)
    {
        n++;
        if (i < M - 1 && S[i] == S[i + 1])
        {
            continue;
        }
        //cout << num << endl;
        //cout << n << endl;

        //! n体生成できる？
        //! num回操作ができる
        if (n > num)
        {
            return "No";
        }
        num -= n;
        //! 生成したn体が何回操作ができるか？
        memset(D, 0, sizeof(D));
        for (int i = N + 1; i > 0; --i)
        {
            ll k = std::min(E[i], n);
            D[i] += E[i] - k;
            D[i - 1] += k;
            n -= k;
        }
        REP(i, N + 2)
        {
            E[i] = D[i];
        }
        REP(i, N + 2)
        {
            num += E[i];
        }
        // REP(i, N + 2)
        // {
        //     cout << E[i] << "," << D[i] << ": ";
        // }
        //cout << endl;
        n = 0;
    }
    // cout << num << endl;
    if (num > 0)
        return "No";
    return "Yes";
}

int main()
{
    cin >> N;
    ll M = pow(2, N);
    REP(i, M)
    {
        cin >> S[i];
    }
    cout << solve() << endl;
    return 0;
}

