const int N = 1<<18;  // limit for array size
int n;  // array size
int t[2 * N];

void modify(int p, int value) {  // set value at position p
	for (t[p += n] = value; p > 1; p >>= 1) t[p >> 1] = max(t[p], t[p ^ 1]);
}

PII query(int l, int r) {  // max on interval [l, r)
	PII res;
	for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
		if (l & 1)
		{
			int v = t[l++];
			if (v > res.first)
				res = MP(v, l - 1);
		}
		if (r & 1)
		{
			int v = t[--r];
			if (v > res.first)
				res = MP(v, r);
		}
	}

	return res;
}

