using namespace std;
int n,S[1000000];
bool cmp(const int a,const int b){
    return a>b;
}

int main()
{
    scanf("%d",&n);
    int t = 1;for(int i=0;i<n;++i)t*=2;
    for(int i=0;i<t;++i)scanf("%d",S+i);
    sort(S,S+t,cmp);
    queue<pair<int,int>> que;
    que.push(pair<int,int>(S[0],n));
    bool yes = true;
    int now = 1;
    while(!que.empty()&&yes){
        pair<int,int> pt = que.front();
        que.pop();
        for(int i=0;i<pt.second;++i){
            if(S[now+i]<pt.first){
                que.push(pair<int,int>(S[now+i],pt.second-1));
            }else {
                yes=false;break;
            }
        }
        now+=pt.second;
    }
    if(yes)printf("Yes\n");
    else printf("No\n");
    return 0;
}

