int n, s[N];
bool v[N];
priority_queue<int> pq[2];
int main()
{
	int i, j;
	cin >> n;
	for (i = 0; i < 1 << n; i++) {
		scanf("%d", &s[i]);
	}
	sort(s, s + (1 << n), greater<int>());
	pq[0].push(s[0]);
	for (i = 0; i < n; i++) {
		for (j = 1; j < 1 << n; j++) {
			if (!v[j] && s[j] < pq[i % 2].top()) {
				v[j] = 1;
				pq[1 - i % 2].push(pq[i % 2].top());
				pq[1 - i % 2].push(s[j]);
				pq[i % 2].pop();
				if (pq[i % 2].empty()) break;
			}
		}
		if (!pq[i % 2].empty()) {puts("No"); return 0;}
	}
	puts("Yes");
    return 0;
}

