long two(long n){
  long tmp = 1;
  while(n > 0){
    tmp *= 2;
    n--;
  }
  return tmp;
}

long search_next(map<long,long> &nexthp, map<long,long> &hp_id, vector<long> &s,long now){
  long next_hp = nexthp.at(now);
  //cout << "nexthp is " << next_hp;
  long id = hp_id.at(next_hp);
  if(s.at(id) == next_hp){
    while(!que.empty()){
      long tmp = que.front();
      que.pop();
      nexthp.at(tmp) = next_hp;;
    }
    hp_id[next_hp] = id + 1;
    return s.at(id);
  }else{
    que.push(now);
    return search_next(nexthp,hp_id,s,next_hp);
  }
}

