    for(int x : s) {
        a[I[i++] + (1 << n)] = x;
    }
    bool can = true;
    for(int i = (1 << n) - 1; i >= 1 and can; i--) {
        can &= a[i << 1] != a[(i << 1) | 1];
        a[i] = max(a[i << 1], a[(i << 1) | 1]);
    }
    cout << (can ? "Yes" : "No") << endl;
    return 0;
}

