struct index_t {
    long long depth, num;
    bool operator==(index_t x) {
        return depth == x.depth && num == x.num;
    }
};

template<typename T>
class perfectBinaryTree {
private:
    long long depth;
    std::deque<T> v;

    inline long long index(long long depth, long long num) {
        assert(depth <= this->depth && depth >= 0);
        long long rest = (depth == 0 ? 0 : std::pow(2, depth) - 1);
        long long result = rest + num;
        assert(0 <= num && (rest == 0 || num <= rest));
        return result;
    }

    inline long long index(index_t x) { return index(x.depth, x.num); }

public:
    perfectBinaryTree(long long depth, T value) : depth(depth),
                                            v(std::pow(2, depth + 1) - 1, value) {}

    index_t parent(long long depth, long long num) {
        assert(depth >= 1 && depth <= this->depth
                    && num < std::pow(2, depth));
        return {depth - 1, num / 2};
    }

    index_t parent(index_t x) { return parent(x.depth, x.num); }

    index_t commonAncestor(index_t x, index_t y) {
        assert(x.depth >= 1 && x.depth <= this->depth
                    && x.num < std::pow(2, x.depth));
        assert(y.depth >= 1 && y.depth <= this->depth
                    && y.num < std::pow(2, y.depth));

        if (x.depth != y.depth) {
            long long d = abs(x.depth - y.depth);
            if (x.depth < y.depth) std::swap(x, y);
            assert(x.depth > y.depth);
            for (long long i = 0; i < d; ++i) x = parent(x.depth, x.num);
        }
        assert(x.depth == y.depth);
        long long i = log2(abs(x.num - y.num) + 1);

        while(x.num / (long long)std::pow(2, i) != y.num / (long long)std::pow(2, i)) ++i;
        return {x.depth - i, x.num / (long long)std::pow(2, i)};
    }

    index_t commonAncestor(long long depth1, long long num1, long long depth2, long long num2) {
        return commonAncestor({depth1, num1}, {depth2, num2});
    }

    T &operator[](index_t p) { return v[index(p.depth, p.num)]; }
};

