int main(void){
    cin.tie(0); ios::sync_with_stdio(false);

    long long N;

    cin >> N;

    map<ll, long long, std::greater<ll>> s;

    ll m = pow(2, N);

    for0(i, m) {
        long long x;
        cin >> x;
        ++s[x];
    }

    perfectBinaryTree<bool> b(N, false);

    auto color = [&](long long num){
                     index_t a = {N, num};
                     b[a] = true;
                     for0(i, N){
                         a = b.parent(a);
                         if (b[a]) break;
                         b[a] = true;
                     }
                 };

    long long i = N, j = 1;
    for(auto &x : s){
        long long const n = x.second;
        index_t coancestor;
        vector<long long> children;

        for0(k, n) {
            long long q = pow(2, i) * j - 1;
            if (b[{N, q}]){
                --k;
                q = -1;
            }

            ++j;
            if (j == pow(2, N - i) + 1) {
                --i;
                j = 1;
            }

            if (q == -1) continue;

            if (k == 0) {
                coancestor = {N, q};
                children.push_back(q);
                continue;
            }

            long long ii = i, jj = j;
            auto ac = b.commonAncestor({N, q}, coancestor);
            while(true) {
                // q!=-1 <=> ac is updated.
                if (q != -1 && b[ac]) {
                    children.push_back(q);
                    break;
                }

                if (ii == 0 && jj == pow(2, N)) {
                    cout << "No";
                    return 0;
                }

                q = pow(2, ii) * jj - 1;
                if (b[{N, q}]){
                    q = -1;
                }
                // update ii,jj
                ++jj;
                if (j == pow(2, N - ii)) {
                    --ii;
                    j = 1;
                }
                if (q != -1) {
                    ac = b.commonAncestor({N, q}, coancestor);
                }
            }
        }
        for(auto &c : children){
            color(c);
        }
    }
    cout << "Yes";

    return 0;
}

