bool solve() {
    int n; cin >> n;
    vi s(1<<n);
    rep (i, 1<<n) cin >> s[i];
    sort(all(s)); reverse(all(s));
    vi al = {s[0]};
    multiset<int> cand;
    FOR (i, 1, 1<<n) cand.insert(s[i]);

    rep (i, n) {
        vi cur = al;
        rep (j, 1<<i) {
            auto it = cand.lower_bound(cur[j]);
            if (it == cand.begin()) {
                cout << "No" << endl;
                exit(0);
            }
            --it;
            al.pb(*it);
            cand.erase(it);
        }
    }
    cout << "Yes" << endl;
}

