//------------------------------- Solver ------------------------------------//

void solve()
{
    int n;
    cin >> n;
    int m = 1 << n;
    aoi<int> pq;
    for (int i = 0; i < m; i++)
    {
        int a;
        cin >> a;
        pq.push(a);
    }
    akari<int> used = {pq.top()};
    pq.pop();
    for (int i = 0; i < n; i++)
    {
        akari<int> nused(used);
        aoi<int> npq;
        for (int j = 0; j < 1 << i; j++)
        {
            bool ok = 0;
            while (!pq.empty())
            {
                int b = pq.top();
                pq.pop();
                if (used[j] > b)
                {
                    ok = 1;
                    nused.push_back(b);
                    break;
                }
                else
                {
                    npq.push(b);
                }
            }
            if (!ok)
            {
                cout << "No" << endl;
                return;
            }
        }
        while (!pq.empty())
        {
            npq.push(pq.top());
            pq.pop();
        }
        swap(pq, npq);
        swap(used, nused);
        sort(used.begin(), used.end());
    }
    cout << "Yes" << endl;
}

int main()
{
    solve();
    return 0;
}

