#include"bits/stdc++.h"
using namespace std;
using ll = int64_t;

class Combination {
public:
    Combination(ll max_num, ll mod) {
        fact_.resize(max_num + 1, 1);
        inv_fact_.resize(max_num + 1, 1);
        mod_ = mod;
        for (ll i = 2; i <= max_num; i++) {
            fact_[i] = i * fact_[i - 1] % mod_;
            inv_fact_[i] = MODpow(fact_[i], mod_ - 2);
            assert(fact_[i] * inv_fact_[i] % mod_ == 1);
        }
    }
    ll operator()(ll n, ll m) const {
        if (m < 0 || m > n) return 0;
        return fact_[n] * inv_fact_[n - m] % mod_ * inv_fact_[m] % mod_;
    }
private:
    ll MODpow(ll n, ll m) const {
        ll result = 1;
        while (m) {
            if (m % 2 == 1) {
                result *= n;
                result %= mod_;
            }

            m /= 2;
            n *= n;
            n %= mod_;
        }

        return result;
    }

    vector<ll> fact_, inv_fact_;
    ll mod_;
};

int main() {
    ll N;
    cin >> N;
    ll pow_N = 1 << N;
    vector<ll> S(pow_N);
    for (ll i = 0; i < pow_N; i++) {
        cin >> S[i];
    }
    sort(S.rbegin(), S.rend());

    ll bound = S[0];
    ll num = 0;
    ll pascal_num = 1;
    ll next_num = 1;

    for (ll i = 0; i <= N; i++) {
        //next_numまでのうち
        ll next_bound = S[num] - 1;
        for (ll j = num; j < next_num; j++) {
            if (S[j] > bound) {
                cout << "No" << endl;
                return 0;
            }
            next_bound = min(next_bound, S[j]);
        }

        num = next_num;
        pascal_num = pascal_num * (N - i) / (i + 1);
        next_num += pascal_num;
        bound = next_bound;
    }

    cout << "Yes" << endl;
}

