multiset<int> st;
bool flag = true;
int dfs(int depth) {
	if (!depth) {
		int val = *st.begin();
		st.erase(st.begin());
		return val;
	}
	int maxi = 0;
	for (int i = depth; i > 0; --i)
		maxi = max(maxi, dfs(i - 1));
	auto ptr = st.upper_bound(maxi);
	if (ptr == st.end()) {
		flag = false;
		return 0;
	}
	else {
		st.erase(ptr);
		return *ptr;
	}
}
