int main()
{

    int N;
    cin >> N;

    int cnt = 1;
    cnt <<= N;

    multiset< int, greater<int> > S; 

    for (int i = 0; i < cnt; ++i) {
        int life;
        cin >> life;
        S.insert(life);
    }

    bool ok = true;
    multiset< int, greater<int> > curr; //! current slimes
    curr.insert(*S.begin());
    S.erase(S.begin());

    for (int i = 0; ok && i < N; ++i) { //! repeat N generations
        vector<int> newKids;
        auto ik = S.upper_bound(*curr.begin()); //! iterator to find new kids
        if (ik == S.end()) {
            ok = false;
        } else {
            for (int p : curr) { //! for each slime in the durrent generation
                while (ik != S.end() && p <= *ik) ++ik;
                if (ik == S.end()) {
                    ok = false;        
                } else {
                    newKids.push_back(*ik);
                    ++ik;
                }
            }
        }
        if (ok) {
            for (int k : newKids) {
                curr.insert(k);
                S.erase(k);
            }
        }
    }

    cout << (ok ? "Yes" : "No") << endl;

    return 0;
}

