const int BIGN = 270000;
int par[BIGN];
int mag[BIGN];
int rightmost[BIGN];

int find(int x) {
    if (x == par[x]) return x;
    return par[x] = find(par[x]);
}

void merge(int x, int y) {
    //cout << "merging " << x << " and " << y << '\n';
    x = find(x);
    y = find(y);
    if (mag[y] < mag[x]) swap(x,y);
    par[x] = y;
    mag[y] += mag[x];
    rightmost[y] = max(rightmost[x], rightmost[y]);
}

int n,m, a[BIGN];

int search(int x) {
    int k=m;
    for (int b=m; b>=1; b/=2) {
        while (k-b >= 0 && a[k-b] < x) k -= b;
    }
    if (k==m) return -1;
    int ret = rightmost[find(k)];
    if (ret != m-1) merge(ret, ret+1);
    return ret;
