                break;    
            } else {
                // cout << "\t\tkid = " << (*ik) << endl;
                newKids.push_back(*ik);
                ++ik;
            }
        }
        if (ok) {
            for (int k : newKids) {
                curr.insert(k);
                S.erase(S.find(k));
            }
        }
    }

    cout << (ok ? "Yes" : "No") << endl;

    return 0;
}

