{
	FILE *fin = NULL, *fout = NULL;
	//fin = freopen("input.txt", "r", stdin);
	//fout = freopen("output.txt", "w", stdout);

	scanf("%d", &N);
	int size = pow(2,N), S[S_MAX];
	for (int i = 0; i < size; i++){
		scanf("%d", S + i);
	}

	sort(S, S + size);

	fill(table, table + S_MAX, 0);
	int cur = S[0];
	tail = 0;
	for (int i = 0; i < size; i++){
		if (cur != S[i]){
			tail++;
			cur = S[i];
		}
		table[tail]++;
	}

	tail++;
	calc();

	//finalize
	if (NULL != fin) fclose(fin);
	if (NULL != fout) fclose(fout);

	return 0;
}

