ll pow(ll a, ll e) {
  if (a < 0 || e < 0) {
    return 0;
  }

  if (e == 0) {
    return 1;
  }

  if (e % 2 == 0) {
    ll half = pow(a, e / 2);
    return half * half;
  }

  return a * pow(a, e - 1);
}

void solve() {
  ll N;
  cin >> N;

  ll length = 1 << N;

  VL ss(length);
  rep(i, length) cin >> ss[i];

  sort(all(ss));

  rep(i, N) {
    ll half_length = ss.size() >> (i + 1);
    ll half_left_i = ss.size() - 1 - half_length;
    if (ss[half_left_i] == ss[half_left_i + 1]) drop("No");
  }

  cout << "Yes" << endl;
}

