        if (p == -1) {
          p = i;
        } else if (S[i] < S[p]) {
          removed[p] = true;
          p = -1;
          cnt++;
        }
      }
    }
    if (cnt < S.size() / 2) {
      cout << "No" << endl;
      return 0;
    }
    vector<int> nxt;
