using namespace std;
vector<int> arr;
struct node {
	int val;
	node* next[20];
	node():
		val(0), next{0} {};
};
node *t = new node();
void fill_num(node *p, int cur, int tar) {
	if (cur == tar) {
		p->val = arr.back();
		arr.pop_back();
		return;
	}
	for (int i = cur - 1; i >= 0; --i) {
		if (!p->next[i])
			p->next[i] = new node();
		fill_num(p->next[i], i, tar);
	}
}
bool check(node *p, int cur) {
	if (!cur)
		return true;
	for (int i = cur - 1; i >= 0; --i) {
		if (!check(p->next[i], i))
			return false;
	}
	return p->val > p->next[cur - 1]->val;
}
int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	int n, tmp;
	cin >> n;
	int bound = 1 << n;
	for (int i = 0; i < bound; ++i) {
		cin >> tmp;
		arr.push_back(tmp);
	}
	sort(arr.begin(), arr.end());
	reverse(arr.begin(), arr.end());
	for (int i = 0; i <= n; ++i)
		fill_num(t, n, i);
	if (check(t, n))
		cout << "Yes\n";
	else
		cout << "No\n";
	return 0;
}

