bool solve()
{
	int N;
	scanf("%d", &N);
	std::vector<int> S(1 << N);
	for (auto& e: S) scanf("%d", &e);
	std::sort(S.rbegin(), S.rend());
	int prev_r{1};
	for (int i{}; i < N; i++)
	{
		for (int j{}; j < prev_r; j++)
			if (S[prev_r + j] == S[j])
				return false;
		prev_r *= 2;
	}
	return true;
}

