template<typename T> struct has_itr {
  template<typename U> static auto check(U x) -> decltype(begin(x), end(x), true_type()); static false_type check(...);
  static bool constexpr value = decltype( check( declval<T>() ) )::value;
};
template <typename T, typename V, enable_if_t<!has_itr<T>::value, nullptr_t> = nullptr> void fill_v(T& t, const V& v) { t = v; }
template <typename T, typename V, enable_if_t< has_itr<T>::value, nullptr_t> = nullptr> void fill_v(T& t, const V& v) { for(auto&& e : t) fill_v(e, v); }
template <typename T, class F, enable_if_t<!has_itr<T>::value, nullptr_t> = nullptr> inline constexpr T& apply(T& t, const F& f) { return t = f(t); }
template <typename T, class F, enable_if_t< has_itr<T>::value, nullptr_t> = nullptr> inline constexpr auto& apply(T& t, const F& f) { for(auto&& e : t) apply(e, f); return t; }
template <typename T, class F, enable_if_t< has_itr<T>::value, nullptr_t> = nullptr> inline constexpr auto apply(T&& t, const F& f) { auto u = t; return apply(u, f); }

