vector<vector<ll>> comb;

void init_comb(int n) {
    comb = vector<vector<ll>>(n + 1, vector<ll>(n + 1));
    comb[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        comb[i][0] = 1;
        for (int j = 1; j <= n; ++j) {
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]);
        }
    }
}

