bool solve() {
  priority_queue<long long> pq;
  queue<P> qu;
  for(int i = 1; i < (1LL << n); ++i) pq.push(s[i]);
  qu.push({s[0], 0});
  while(!qu.empty()) {
    P now = qu.front();
    qu.pop();
    for(int i = now.se; i < n; ++i) {
      long long nextp = pq.top();
      pq.pop();
      if(nextp >= now.fi) return 0;
      qu.push({nextp, i + 1});
    }
  }
  return 1;
}

