using namespace std;


class QF {
	int n;
	int tot;
	vector<int> heap;
public:
	QF()
	{
		cin >> n;
		tot = 1 << n;
		heap.resize(tot + 1);
		heap[0] = 0;

		REP(i, tot)
			cin >> heap[i + 1];
	}
	void solve()
	{
		sort(heap.begin() + 1, heap.end(), greater<>());

		bool flag{ true };
		for (int i{ 1 }; i < tot + 1; i++)
		{
			if (2 * i > tot)
				break;

			if (heap[i] <= heap[2 * i] || heap[i] <= heap[2 * i + 1])
			{
				flag = false;
				break;
			}

		}

		if (flag)
			cout << "Yes" << endl;
		else
			cout << "No" << endl;
	}
};


int main()
{
	QF solution;
	solution.solve();

	return 0;
}

