#define ull unsigned long long
ull xorshiro[2]={0xcbe134025aac2d13,0x9e30d9a3f85a62c7};//適当な初期値
ull rnd(){
	ull s0=xorshiro[0],s1=xorshiro[1];
	s1^=s0;
	xorshiro[0]=((s0<<55)|(s0>> 9))^s1^(s1<<14);
	xorshiro[1]=((s1<<36)|(s1>>28));
	return xorshiro[0]+xorshiro[1];
}

typedef struct SETnode{
	struct SETnode*next,*pre,*up,*down;
	int cnt;
	ll x;
}SETnode;
typedef struct SET{
	int level;
	int cnt;
	SETnode*head;
}SET;

void SETinit(SET*s,int level){
	s->level=level;
	s->cnt=0;
	s->head=(SETnode*)calloc(level,sizeof(SETnode));
	for(int i=0;i<level;i++){
		SETnode*h=s->head+i;
		h->next=(SETnode*)calloc(1,sizeof(SETnode));
		if(i!=0)h->down=s->head+(i-1);
		if(i!=level-1)h->up=s->head+(i+1);
		h->x=-INF;	
	}
	for(int i=0;i<level;i++){
		SETnode*h=s->head+i;
		SETnode*t=h->next;
		t->pre=h;
		if(i!=0)t->down=h->down->next;
		if(i!=level-1)t->up=h->up->next;
		t->x=INF;
	}
}

SETnode*SETinssub(SETnode*crr,int level,ll x){
	while(crr->next->x < x)crr=crr->next;
	SETnode*d=0;
	if(level!=0)d=SETinssub(crr->down,level-1,x);
	if(level==0||(d!=0&&rnd()%2)){
		SETnode*new=calloc(1,sizeof(SETnode));
		new->pre=crr;
		new->next=crr->next;
		new->down=d;
		if(d)d->up=new;
		new->x=x;
		crr->next->pre=new;
		crr->next=new;
		return new;
	}else{
		return 0;
	}
}
void SETins(SET*s,ll x){
	int level=s->level;
	SETinssub(s->head+level-1,level-1,x);
	s->cnt++;
}
void SETdel(SET*s,ll x){
	SETnode*crr=s->head+(s->level)-1;
	while(crr){
		while(crr->next->x < x)crr=crr->next;
		if(crr->next->x == x)break;
		crr=crr->down;
	}
	if(!crr)return;
	crr=crr->next;
	while(crr){
		crr->pre->next=crr->next;
		crr->next->pre=crr->pre;
		SETnode*temp=crr->down;
		free(crr);
		crr=temp;
	}
	s->cnt--;
}

SETnode*SETlowerbound(SET*s,ll x){
	SETnode*crr=s->head+(s->level)-1;
	for(int i=s->level-1;i>=0;i--){
		while(crr->next->x < x)crr=crr->next;
		if(i)crr=crr->down;
	}
	return crr->next;
}
SETnode*SETupperbound(SET*s,ll x){
	SETnode*crr=s->head+(s->level)-1;
	for(int i=s->level-1;i>=0;i--){
		while(crr->next->x <= x)crr=crr->next;
		if(i)crr=crr->down;
	}
	return crr->next;
}
SETnode*SETtop(SET*s){return s->head->next;}
SETnode*SETend(SET*s){return SETlowerbound(s,INF);}

