int merge(long int a1[], long int a2[], long int a1_size, long int a2_size, long int a[])
{
	int i = 0, j = 0;

	while( (i < a1_size ) || (j < a2_size) ){
		if( (j >= a2_size ) || ( (i < a1_size) && (a1[i] > a2[j]) ) ) {
			a[i + j] = a1[i];
			i++;
		} else {
			a[i + j] = a2[j];
			j++;
		}
	}

	return 0;
}

int merge2(long int b1[], long int b2[], long int c1[], long int c2[], long int b1_size, long int b2_size, long int b[], long int c[])
{
	int i = 0, j = 0;


	while( (i < b1_size ) || (j < b2_size ) ) {
		if( (j >= b2_size ) || ( (i < b1_size) && (c1[i] > c2[j]) ) ) {
			b[i + j] = b1[i];
			c[i + j] = c1[i];
			i++;
		} else {
			b[i + j] = b2[j];
			c[i + j] = c2[j];
			j++;
		}
	}

	return 0;
}

int mergeSort(long int a[], long int number)
{
	int m = number / 2, n = number - m;
	long int a1[m];
	long int a2[n];
	int i, j;

	if(number > 1) {
		for(i = 0; i < m; i++) {
			a1[i] = a[i];
		}
		for(i = 0; i < n; i++) {
			a2[i] = a[m + i];
		}
		mergeSort(a1, m);
		mergeSort(a2, n);
		merge(a1, a2, m, n, a);
	}

	return 0;
}

int mergeSort2(long int b[], long int c[], long int number)
{
	int m = number / 2, n = number - m;
	long int b1[m];
	long int b2[n];
	long int c1[m];
	long int c2[n];
	int i, j;

	if(number > 1) {
		for(i = 0; i < m; i++) {
			b1[i] = b[i];
		}
		for(i = 0; i < n; i++) {
			b2[i] = b[m + i];
		}

		for(i = 0; i < m; i++) {
			c1[i] = c[i];
		}
		for(i = 0; i < n; i++) {
			c2[i] = c[m + i];
		}

		mergeSort2(b1, c1, m);
		mergeSort2(b2, c2, n);
		merge2(b1, b2, c1, c2, m, n, b, c);
	}

	return 0;
}

