    long long n;
    scanf("%lld",&n);
    n=power(n);
    long long a[n+1],b[n];
    for(long long i=1;i<n+1;i++){
        scanf("%lld",&a[i]);
        hsort(a,i);
    }
    for(long long i=1;i<n+1;i++){
        b[i-1]=a[1];
        a[1]=a[n+1-i];
        dheap(a,n-i);
    }
    if(b[0]>b[1]){
        if(judge(b,n)==0)printf("No\n");
        else printf("Yes\n");
    }
    else printf("No\n");
    return 0;
}

