typedef struct SETnode{
	struct SETnode*next,*pre,*up,*down;
	int cnt;
	ll x;
}SETnode;
typedef struct SET{
	int level;
	int cnt;
	SETnode**head;
}SET;

#define SETnodesmaxcnt 3<<18
int SETnodescnt=-1;
SETnode SETnodes[SETnodesmaxcnt];
SETnode*SETnodesptr[SETnodesmaxcnt];

SETnode*SETnodecalloc(){
	if(SETnodescnt==-1){
		SETnodescnt=SETnodesmaxcnt;
		for(int i=0;i<SETnodesmaxcnt;i++)SETnodesptr[i]=SETnodes+i;
	}
	if(SETnodescnt==0)exit(1);
	memset(SETnodesptr[--SETnodescnt],0,sizeof(SETnode));
	return SETnodesptr[SETnodescnt];
}
void SETnodefree(SETnode*n){SETnodesptr[SETnodescnt++]=n;}
#undef SETnodesmaxcnt

void SETinit(SET*s,int level){
	s->level=level;
	s->cnt=0;
	s->head=(SETnode**)calloc(level,sizeof(SETnode*));
	for(int i=0;i<level;i++)s->head[i]=SETnodecalloc();
	for(int i=0;i<level;i++){
		SETnode*h=s->head[i];
		h->next=SETnodecalloc();
		if(i!=0)h->down=s->head[i-1];
		if(i!=level-1)h->up=s->head[i+1];
		h->x=-INF;	
	}
	for(int i=0;i<level;i++){
		SETnode*h=s->head[i];
		SETnode*t=h->next;
		t->pre=h;
		if(i!=0)t->down=h->down->next;
		if(i!=level-1)t->up=h->up->next;
		t->x=INF;
	}
}
#undef SETnodesmaxcnt
SETnode*SETinssub(SETnode*crr,int level,ll x){
	while(crr->next->x < x)crr=crr->next;
	SETnode*d=0;
	if(level!=0)d=SETinssub(crr->down,level-1,x);
	if(level==0||(d!=0&&rnd()%2)){
		SETnode*new=SETnodecalloc();
		new->pre=crr;
		new->next=crr->next;
		new->down=d;
		if(d)d->up=new;
		new->x=x;
		crr->next->pre=new;
		crr->next=new;
		return new;
	}else{
		return 0;
	}
}
void SETins(SET*s,ll x){
	int level=s->level;
	SETinssub(s->head[level-1],level-1,x);
	s->cnt++;
}
void SETdel(SET*s,ll x){
	SETnode*crr=s->head[(s->level)-1];
	while(crr){
		while(crr->next->x < x)crr=crr->next;
		if(crr->next->x == x)break;
		crr=crr->down;
	}
	if(!crr)return;
	crr=crr->next;
	while(crr){
		crr->pre->next=crr->next;
		crr->next->pre=crr->pre;
		SETnode*temp=crr->down;
		SETnodefree(crr);
		crr=temp;
	}
	s->cnt--;
}

SETnode*SETlowerbound(SET*s,ll x){
	SETnode*crr=s->head[(s->level)-1];
	for(int i=s->level-1;i>=0;i--){
		while(crr->next->x < x)crr=crr->next;
		if(i)crr=crr->down;
	}
	return crr->next;
}
SETnode*SETupperbound(SET*s,ll x){
	SETnode*crr=s->head[(s->level)-1];
	for(int i=s->level-1;i>=0;i--){
		while(crr->next->x <= x)crr=crr->next;
		if(i)crr=crr->down;
	}
	return crr->next;
}
SETnode*SETtop(SET*s){return s->head[0]->next;}
SETnode*SETend(SET*s){return SETlowerbound(s,INF);}




