#include <stdio.h>

long long max(long long a,long long b){return(a>b)?a:b;}

void swap(long long *a,long long *b){
    long long c;
    c=*a;
    *a=*b;
    *b=c;
}

long long power(int n){
    long long res=1;
    for(long long i=0;i<n;i++){
        res*=2;
    }
    return res;
}

void hsort(long long* a,long long i){
    long long j=i;
    while(j>1){
        if(a[j]>a[j/2]){
            swap(&a[j],&a[j/2]);
            j/=2;
        }
        else break;
    }
}

void dheap(long long* a,long long n){
    long long i=1;
    while(i<=n/2){
        if(a[i]<max(a[2*i],a[2*i+1])){
            if(a[i*2]>a[i*2+1]){
                swap(&a[i*2],&a[i]);
                i*=2;
            }
            else{
                swap(&a[i],&a[2*i+1]);
                i=i*2+1;
            }
        }
        else break;
    }
}


int judge(long long*a,long long N){
    for(long long i=0;i<N;i++){
        for(long long j=0;j<power(i);j++){
            if(a[j]==a[j+power(i)])return 0;
        }
    }
    return 1;
}

int main(void){
    long long N;
    scanf("%lld",&N);
    int n=power(N);
    long long a[n+1],b[n];
    for(long long i=1;i<n+1;i++){
        scanf("%lld",&a[i]);
        hsort(a,i);
    }
    for(long long i=1;i<n+1;i++){
        b[i-1]=a[1];
        a[1]=a[n+1-i];
        dheap(a,n-i);
    }
    if(judge(b,N)==0)printf("No\n");
    else printf("Yes\n");
    return 0;
}

