fun List<Int>.canMultiply(n: Int = 1): Boolean {
    val idxBegin = Math.pow(2.0, (n - 1).toDouble()).toInt()

    for (i in 0 until idxBegin) {
        if (this[i] <= this[idxBegin + i]) return false
    }

    return true
}

