fun MutableList<Int>.canMultiply(children: MutableList<Int>): Boolean {
    val newChildren = mutableListOf<Int>()

    this.forEach { parent ->
        val childIdx = children.indexOfFirst { it < parent }
        if (childIdx == -1) {
            return false
        } else {
            newChildren.add(children[childIdx])
            children.removeAt(childIdx)
        }
    }
    this.addAll(newChildren)

    return true
}

