fun MutableList<Int>.multiply(children: MutableList<Int>): Boolean {
    var i = 0
    val newChildren = mutableListOf<Int>()

    val newChildrenIdx = this.forEach { parent ->
        val childIdx = children.slice(i..children.lastIndex)
            .indexOfFirst { it < parent }

        if (childIdx == -1) return false

        i += childIdx
        newChildren.add(children[i])
        children.removeAt(i)
    }

    this.addAll(newChildren)
    return true
}

