public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();

		int[] s = sc.nextIntArray(0x1 << n);

		PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
		for (int e : s) {
			pq.add(e);
		}

		List<Integer> done = new ArrayList<>();
		done.add(pq.remove());

		for (int i = 0; i < n; i++) {
			Queue<Integer> tmp = new ArrayDeque<>();
			Queue<Integer> done2 = new ArrayDeque<>();
			for (int j = 0, size = done.size(); j < size; j++) {
				int e = done.get(j);
				while (!pq.isEmpty() && pq.peek() >= e) {
					tmp.add(pq.remove());
				}

				if (pq.isEmpty()) {
					pr.println("No");
					return;
				}

				done2.add(pq.remove());
			}

			done.addAll(done2);
			Collections.sort(done, Collections.reverseOrder());
			pq.addAll(tmp);
		}

		pr.println("Yes");
	}

