public class Main {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);
    final int MOD = (int)1e9+7;
    long dup(long a, long b){return (a + b - 1) / b;}

    void solve() throws Exception{
        int N = in.nextInt();
        MultiSet<Integer> mset = new MultiSet<>();
        for(int i = 0; i < (1<<N); i++) mset.add(in.nextInt());

        PriorityQueue<Integer> pq = new PriorityQueue<>(Comparator.reverseOrder());
        pq.add(mset.last());
        mset.remove(mset.last());
        while(pq.size() != (1<<N)){
            PriorityQueue<Integer> tmp = new PriorityQueue<>(Comparator.reverseOrder());
            while(!pq.isEmpty()){
                Integer e1 = pq.remove();
                Integer e2 = mset.lower(e1);
                if(e2 == null){
                    out.println("No");
                    return;
                }
                mset.remove(e2);
                tmp.add(e1);
                tmp.add(e2);
            }
            pq = tmp;
        }
        out.println("Yes");
    }

    class MultiSet<T extends Comparable<T>>{
        TreeMap<T, Integer> map = new TreeMap<>();
        int num = 0;

        public boolean add(T e){
            if(map.containsKey(e)) map.put(e, map.get(e) + 1);
            else map.put(e, 1);
            num++;
            return true;
        }

        //要素eが集合に含まれない<=>mapにeのマッピングは存在しない
        public boolean remove(T e){
            if(!map.containsKey(e)) return false;
            int c = map.get(e);
            if(c == 1) map.remove(e);
            else map.put(e, c - 1);
            num--;
            return true;
        }

        public int size(){return num;}//map.size()ではなく、集合に追加された要素数を返す
        public boolean isEmpty(){return num == 0;}

        public boolean contains(T e){return map.containsKey(e);}
        public T lower(T e){return this.isEmpty() ? null : map.lowerKey(e);}     //max(<e)
        public T higher(T e){return this.isEmpty() ? null : map.higherKey(e);}   //min(e<)
        public T floor(T e){return this.isEmpty() ? null : map.floorKey(e);}     //max(<=e)
        public T ceiling(T e){return this.isEmpty() ? null : map.ceilingKey(e);} //min(e<=)
        public T first(){return this.isEmpty() ? null : map.firstKey();}         //min
        public T last(){return this.isEmpty() ? null : map.lastKey();}           //max
    }

