    TreeSet<int[]> set = new TreeSet<>((o1, o2) -> o1[0] == o2[0] ? o1[1] - o2[1] : o1[0] - o2[0]);
    for (int i = 0; i < m; i++) {
      set.add(new int[] {s[i], i});
    }


    int[] a = new int[m];
    a[0] = set.pollLast()[0];
    for (int i = 0; i < n; i++) {
