    public Solver() {

      int N = sc.nextInt();
      int M = 1<<N;

      int[] S = sc.nextIntArray(M, false);

      Array.sort(S);
      S = Array.reverse(S);
      int p = 0;
      for (int i=0; i<M; i++) {
        if (i == M-1 || S[i+1] != S[i]) S[i] = p++;
        else S[i] = p;
      }

      long[] count = new long[p];

      for (int i=0; i<M; i++) {
        count[S[i]]++;
      }

      if (count[0] > 1) {
        out.println("No");
        return;
      }

      long[] cur = new long[p];
      cur[0] = 1;
      for (int i=0; i<N; i++) {
        long next = 0;
        for (int j=0; j<p; j++) {
          long sum = next;
          if (cur[j] < count[j]) {
            if (cur[j] + sum <= count[j]) {
              next = cur[j];
              cur[j] += sum;
            } else {
              next += cur[j];
              next -= count[j] - cur[j];
              cur[j] = count[j];
            }
          } else {
            next += count[j];
          }
        }
      }

      boolean ans = true;
      for (int i=0; i<p; i++) {
        if (cur[i] != count[i]) {
          ans = false;
          break;
        }
      }

      out.println(ans ? "Yes" : "No");

    }

