public class Main {
    InputStream is;

    int __t__ = 1;
    int __f__ = 0;
    int __FILE_DEBUG_FLAG__ = __f__;
    String __DEBUG_FILE_NAME__ = "src/F1";

    FastScanner in;
    PrintWriter out;

    public void solve() {
        int n = in.nextInt();
        int all = 1 << n;
        long[] s = in.nextLongArray(all);
        Arrays.sort(s);
        for (int l = 0, r = all - 1; l < r; l++, r--) {
            long t = s[l];
            s[l] = s[r];
            s[r] = t;
        }

        PriorityQueue<Long>[] pqs = new PriorityQueue[n+1];
        for (int i = 0; i < pqs.length; i++) {
            pqs[i] = new PriorityQueue<>((l1, l2) -> Long.compare(l2, l1));
        }
        pqs[n].add(s[0]);
        for (int cur = 1; cur < all; cur++) {
            for (int i = n; i >= 1; i--) {
                if (!pqs[i].isEmpty() && pqs[i].peek() > s[cur]) {
                    long next = pqs[i].poll();
                    if (i != 1) {
                        pqs[i - 1].add(next);
                        pqs[i - 1].add(s[cur]);
                    }
                    break;
                }
                if (i == 1) {
                    System.out.println("No");
                    return;
                }
            }
        }
        System.out.println("Yes");
    }

