class Main
{
    public static void main(String[] args) throws IOException
    {
        Reader in = new Reader();
//        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        int n = in.nextInt();
        long[] A = new long[(int)Math.pow(2, n)];
        for (int i=0;i<A.length;i++)
        {
            A[i] = in.nextLong();
        }
        Arrays.sort(A);
        ArrayList<Integer> range = new ArrayList<>();
        for (int i=n - 1;i>=0;i--)
        {
            range.add((int)Math.pow(2, i));
        }
        ArrayList<Integer> cum = new ArrayList<>();
        cum.add(range.get(0));
        for (int i=1;i<range.size();i++)
            cum.add((int)cum.get(cum.size() - 1) + range.get(i));
        boolean flag = true;
        for (int i=0;i<A.length - 1;i++)
        {
            int x = i + 1;
            int add = search(x, cum, n);
            if (A[i + add] <= A[i])
            {
                flag = false;
                break;
            }
        }
        if (flag)
            System.out.println("Yes");
        else
            System.out.println("No");
    }
    public static int search(int idx, ArrayList<Integer> cum, int n)throws ArithmeticException
    {
        for(int i=0;i<cum.size();i++)
        {
            int g = cum.get(i);
            if (g >= idx)
            {
                return (int)Math.pow(2, n - (i + 1));
            }
        }
        throw new ArithmeticException();
    }
}
