class Solver {
  final int n;
  final int[] ss;

  Solver(int n, int[] ss) {
    this.n = n;
    this.ss = ss;
  }

  public boolean solve() {
    TreeMap<Integer, Integer> counter = new TreeMap<>();
    for (int s : ss) {
      counter.put(s, counter.getOrDefault(s, 0) + 1);
    }

    int[] binaryTreeCount = new int[n+1];
    binaryTreeCount[n] = 1;
    for (Map.Entry<Integer, Integer> entry : counter.descendingMap().entrySet()) {
      int key = entry.getKey();
      int value = entry.getValue();
      /*
      System.err.printf("%d %d\n", key, value);
      for (int i = 0; i <= n; i++) {
        System.err.printf("%d %d %d\n", i, 1<<i, binaryTreeCount[i]);
      }
      */
      int[] newBinaryTreeCount = new int[n+1];
      int index = n;
      for (int i = 0; i < value; i++) {
        while (index >= 0 && binaryTreeCount[index] == 0) {
          index--;
        }
        if (index < 0) {
          return false;
        }
        binaryTreeCount[index]--;
        for (int j = index-1; j >= 0; j--) {
          newBinaryTreeCount[j]++;
        }
      }

      for (int i = 0; i <= n; i++) {
        binaryTreeCount[i] += newBinaryTreeCount[i];
      }
    }
    return true;
  }
}

