    static class FManySlimes {
        public void solve(int testNumber, ScanReader in, PrintWriter out) {
            int n = in.scanInt();
            int[] ar = new int[1 << n];
            in.scanInt(ar, 1 << n);
            CodeHash.radixSort(ar);
            boolean flag = true;
