    static class FManySlimes {
        public void solve(int testNumber, ScanReader in, PrintWriter out) {
            int n = in.scanInt();
            int[] ar = new int[1 << n];
            in.scanInt(ar, 1 << n);
            CodeHash.radixSort(ar);
            boolean flag = true;
            ArrayList<Integer> current = new ArrayList<>();
            current.add(ar[(1 << n) - 1]);
            int ind = (1 << n) - 2;
            BSTCustom<Integer> bst = new BSTCustom<Integer>(true);
            for (int i = 0; i < n; i++) {
                Collections.sort(current, Collections.reverseOrder());
                ArrayList<Integer> temp = new ArrayList<>();
                for (int j : current) {
                    if (bst.size() > 0 && bst.lower_bound(j) != 0) {
                        int idd = (int) bst.lower_bound(j) - 1;
                        temp.add(bst.get(idd));
                        bst.remove(bst.get(idd));
                    } else {
