public class Main{
    public static void main(String[] args) throws IOException{
        MyReader r = new MyReader();

        int N = r.i();

        ArrayList<Integer> s = new ArrayList<>(1<<N);
        for(String i : r.ss())
            s.add(Integer.parseInt(i));

        s.sort((x, y) -> -x+y);
        ArrayList<Integer> list = new ArrayList<>(new HashSet<>(s));
        list.sort((x, y) -> -x+y);

        int[] leaf = {s.remove(0)};
        if(s.get(0) != list.get(0))
            list.remove(0);


        for(int h = 0; h < N; h++){
            int[] newLeaf = new int[leaf.length*2];
            int i = 0;
            for(int v : leaf){
                int w = s.get(0);
                if(w < v){
                    s.remove(0);
                    if(!s.isEmpty() && s.get(0) != list.get(0))
                        list.remove(0);
                } else if(list.size() == 1){
                    println("No");
                    return;
                } else {
                    w = list.get(1);
                    int id = binarySearch(s, w);
                    s.remove(id);
                    if(s.get(id-1) != w){
                        int size = s.size();
                        if(size <= id || id < size && s.get(id) != w)
                            list.remove(1);
                    }
                }
                newLeaf[i++] = v;
                newLeaf[i++] = w;
            }
            leaf = newLeaf;
        }
        println("Yes");
    }

    public static int binarySearch(ArrayList<Integer> list, int key){
        int left = 0;
        int right = list.size()-1;
        while(true){
            int middle = left + (right - left)/2;
            int value = list.get(middle);
            if(value == key){
                return middle;
            } else if(value > key){
                left = middle + 1;
            } else {
                right = middle - 1;
            }
            if(right < left)
                return  left < middle ? middle : left;
        }
    }

