    static class FManySlimes {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int[] a = in.readIntArray(1 << n);
            Arrays.sort(a);
            ArrayUtils.reverse(a);

            int[] b = new int[1 << n];
            boolean[] used = new boolean[1 << n];
            b[0] = a[0];
            int bIdx = 1;
            used[0] = true;
            for (int i = 0; i < n; i++) {
                int aIdx = 0;
                for (int j = 0; j < 1 << n; j++) {
                    if (used[j]) continue;
                    if (a[j] >= a[aIdx]) continue;
                    b[bIdx++] = a[j];
                    used[j] = true;
                    aIdx++;
                    if (aIdx == 1 << i) break;
                }
                if (aIdx < 1 << i) {
                    out.printLine("No");
                    return;
                }
            }
            out.printLine("Yes");
        }

