	//aとbの最小公倍数を返す
	static long lcm (long a, long b) {
		long temp;
		long c = a;
		c *= b;
		while((temp = a%b)!=0) {
			a = b;
			b = temp;
		}
		return (c/b);
	}

	//二項係数用の前処理
	static void COMinit(){
		//二項係数演算用前処理
		fac = new long[MAX+1];
		fac[0] = 1L;
		fac[1] = 1L;
		inv = new long[MAX+1];
		inv[1] = 1L;
		finv = new long[MAX+1];
		finv[0] = 1L;
		finv[1] = 1L;
		for(int i=2;i<MAX;i++){
			fac[i] = fac[i-1] * i % MOD;
			inv[i] = MOD - inv[(int)(MOD%i)] * (MOD/i) % MOD;
			finv[i] = finv[i-1] * inv[i] % MOD;
		}
		isPreprocessing = true;
	}

	//二項係数i_C_jをMODで割った余りを返す
	static long COM(int i, int j){
		if(i<j)return 0;
		if(i<0 || j<0)return 0;
		if(!isPreprocessing)COMinit();
		return fac[i] * (finv[j] * finv[i-j] % MOD) % MOD;
	}

}

import java.util.Arrays;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {

    static class Slime implements Comparable<Slime> {
        int health;
        int steps;

        public Slime(int health, int steps) {
            this.health = health;
            this.steps = steps;
        }

        @Override
        public int compareTo(Slime other) {
            int c = other.health - this.health;
            if (c == 0) c = other.steps - this.steps;
            return c;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();

        int[] S = new int[(1 << N)];
        for (int i = 0; i < S.length; i++) S[i] = sc.nextInt();

        Arrays.sort(S);

        PriorityQueue<Slime> slimes = new PriorityQueue<>();
        slimes.add(new Slime(S[S.length - 1], N));
        int next = S.length - 2;

        while (!slimes.isEmpty()) {
            Slime slime = slimes.poll();

            if (slime.steps == 0) continue;

            if (S[next] >= slime.health) {
                System.out.println("No");
                return;
            }

            for (int steps = slime.steps - 1; steps >= 0; steps--) {
                slimes.add(new Slime(S[next], steps));
                next--;
            }
        }

        System.out.println("Yes");
    }
}

