	void solve() {
		int n = 1 << scn.nextInt();
		int[] arr = scn.nextIntArray(n);
		Arrays.parallelSort(arr);
		arr = scn.reverse(arr);

		TreeMap<Integer, Integer> map = new TreeMap<>();
		for(int a : arr) {
			map.merge(a, 1, Integer::sum);
		}

		int[] q = new int[n];
		int[] c = new int[n];
		int p = 0;
		q[p] = map.lastKey();
		c[p++] = Integer.numberOfTrailingZeros(n);
		remove(map, map.lastKey());

		for(int i = 0; i < p; i++) {
			int u = q[i];

			int ch = c[i];
			while(ch-- > 0) {
				if(map.lowerKey(u) == null) {
					out.println("No");
					return;
				}
				int v = map.lowerKey(u);
				remove(map, v);

				q[p] = v;
				c[p++] = ch;
			}
		}

		out.println("Yes");
	}

	void remove(TreeMap<Integer, Integer> map, int val) {
		map.merge(val, -1, Integer::sum);
		if(map.get(val) == 0) {
			map.remove(val);
		}
	}


