			prev = arr[i];
		}
		list.add(count);
		int idx = 0;
		for (int i = n - 1; i >= 0; i--) {
			int max = (int)Math.pow(2, i);
			while (max > list.get(idx)) {
				max -= list.get(idx);
				idx++;
			}
			if (list.get(idx) >= max * 2) {
				System.out.println("No");
				return;
			}
			list.set(idx, max - list.get(idx));
		}
		System.out.println("Yes");
	}
}

