public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        int[] s = sc.ints(1 << n);
        IntTreeMap<Integer> map = new IntTreeMap<>();
        for (int e : s) {
            if (!map.containsKey(e)) map.put(e, 0);
            map.put(e, map.get(e) + 1);
        }
        for (int i = 0; i < n; i++) {
            var e = map.lastEntry();
            int k = e.getKey();
            var l = map.lowerEntry(k);
            if (l == null) {
                out.writeln("No");
                return;
            }
            int x = l.setValue(l.getValue() - 1);
            if (x == 0) map.remove(l.getKey());
        }
        out.writeln("Yes");
    }
}


