    void solve() {
        int n = in.nextInt();
        int m = 1 << n;
        int[] a = in.nextIntArray(m);
        Arrays.sort(a);
        PriorityQueue<Integer> queue = new PriorityQueue<>(Collections.reverseOrder());
        queue.add(a[m - 1]);
        int last = m - 1;
        for (int b = 0; b < n; b++) {
            int cnt = 1 << b;
            for (int i = last - 1; i >= last - cnt; i--) {
                if (a[i] >= queue.poll()) {
                    printf("No");
                    return;
                }
            }
            for (int i = m - 1; i >= last - cnt; i--) {
                queue.add(a[i]);
            }
            last = last - cnt;
        }
        printf("Yes");

    }

