					/*
					System.out.print("parent : ");
					for(int i = l / 2; i < l; i++) {
						System.out.print(as[i]);
					}
					System.out.println();
					System.out.print("child : ");
					for(int i = l; i < r; i++) {
						System.out.print(as[i]);
					}
					System.out.println();
					//*/

					for(int p = l / 2; p < l; p++) {
						final long left  = as[p * 2];
						final long right = as[Math.min(p * 2 + 1, r)];
						//System.out.println(as[p] + " : " + left + "," + right);

						if(as[p] <= left || as[p] <= right) { flag = true; break; }
					}

					if(flag) { break; }
				}

				l = r;
				r = Math.min(r * 2, 1 << N);
			}

			//System.out.println(Arrays.toString(as));
			System.out.println(flag ? "No" : "Yes");
		}
	}

