import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Comparator;
import java.util.Deque;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    static final Scanner sc = new Scanner(System.in);
    static final int MOD = (int) 1E9 + 7;

    public static void main(String[] args) {
        int N = nint();
        int pow = (int) Math.pow(2, N);
        int[] S = nints(pow); 
        Arrays.sort(S);

        PriorityQueue<Node> d = new PriorityQueue<Node>(Node.comp);
        Deque<Node> deq = new ArrayDeque<>();
        Node start = new Node(-1, N, N, null);
        deq.add(start);
        d.add(start);

        while (!deq.isEmpty()) {
            Node f = deq.poll();
            for (int i = f.n-1; i >= 0; i--) {
                Node child = new Node(-1, i, f.getD()-1, f);
                d.add(child);
                deq.add(child);
            }
        }

        Node[] nodes = new Node[pow];
        int idx = 0;
        while (!d.isEmpty()) {
            Node node = d.poll();
            node.v = S[idx];
            nodes[idx] = node;
            idx++;
        }

        for (int i = 0; i < pow; i++) {
            Node node = nodes[i];
            if (node.parent != null) {
                if (node.parent.v <= node.v) {
                    System.out.println("No");
                    return;
                }
            }
        }

        System.out.println("Yes");
    }
    public static class Node {
        Node parent;
        int v;
        int n;
        int d;
        public int getN() {return n;}
        public int getD() {return d;}
        public int getV() {return v;}
        public Node(int v, int n, int d, Node parent) {
            super();
            this.v = v;
            this.n = n;
            this.d = d;
            this.parent = parent;
        }

        public static Comparator<Node> comp = Comparator.comparing(Node::getN).thenComparing(Node::getD);

        public String toString() {
            return "n = " + n + ", d = " + d + ", v = " + v;
        }
    }

    private static long nlong() {
        return sc.nextLong();
    }

    private static int nint() {
        return sc.nextInt();
    }

    private static String nstr() {
        return sc.next();
    }

    private static char[] nchars() {
        return sc.next().toCharArray();
    }

    private static int[] nints(int n) {
        return nints(n, 0, 0);
    }

    private static int[] nints(int n, int padL, int padR) {
        int[] a = new int[padL + n + padR];
        for (int i = 0; i < n; i++)
            a[padL + i] = nint();
        return a;
    }

    private static char[][] nchars2(int h, int w) {
        return nchars2(h, w, 0);
    }

    private static char[][] nchars2(int h, int w, int pad) {
        char[][] a2 = new char[h + pad * 2][w + pad * 2];
        for (int i = 0; i < h; i++)
            System.arraycopy(nchars(), 0, a2[pad + i], pad, w);
        return a2;
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	void run() {
		FastScanner sc = new FastScanner();
		int N = sc.nextInt();
		long[] S = new long[1 << N];
		for (int i = 0; i < S.length; ++i) {
			S[i] = sc.nextLong();
		}
		Arrays.sort(S);
		class State implements Comparable<State> {
			long size;
			long res;

			public State(long size, long res) {
				this.size = size;
				this.res = res;
			}

			public int compareTo(State o) {
				return -Long.compare(size, o.size);
			};
		}
		PriorityQueue<State> pq = new PriorityQueue<>();
		pq.add(new State(S[S.length - 1], N));
		for (int i = S.length - 2; i >= 0; --i) {
			State state = pq.poll();
			if (state.size <= S[i]) {
				System.out.println("No");
				return;
			}
			--state.res;
			if (state.res > 0) {
				pq.add(state);
				pq.add(new State(S[i], state.res));
			}
		}
		System.out.println("Yes");
	}

	static void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

class FastScanner {
	private final InputStream in = System.in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;

	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		} else {
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}

	private int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	private static boolean isPrintableChar(int c) {
		return 33 <= c && c <= 126;
	}

	public boolean hasNext() {
		while (hasNextByte() && !isPrintableChar(buffer[ptr]))
			ptr++;
		return hasNextByte();
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	public long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			} else if (b == -1 || !isPrintableChar(b)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}

	public int nextInt() {
		long nl = nextLong();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)
			throw new NumberFormatException();
		return (int) nl;
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}
}

import java.io.*; 
import java.math.*;
