public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();
		int m = 0x1 << n;

		int[] s = sc.nextIntArray(m);



		Arrays.sort(s);

		List<Integer> list = new ArrayList<>(m);
		list.add(s[m - 1]);
		for (int i = 0; i < n; i++) {
			List<Integer> tmp = new ArrayList<>();
			for (int e : list) {
				tmp.add(e - 1);
			}

			list.addAll(tmp);
		}
		Collections.sort(list);

		for (int i = 0; i < m; i++) {
			if (s[i] > list.get(i)) {
				pr.println("No");
				return;
			}
		}

		pr.println("Yes");
	}

	// ---------------------------------------------------
	public static void main(String[] args) {
		sc = new Scanner(System.in);
		pr = new Printer(System.out);

		solve();

		pr.close();
		sc.close();
	}

	static class Scanner {
		BufferedReader br;

		Scanner (InputStream in) {
			br = new BufferedReader(new InputStreamReader(in));
		}

		private boolean isPrintable(int ch) {
			return ch >= '!' && ch <= '~';
		}

		private boolean isCRLF(int ch) {
			return ch == '\n' || ch == '\r' || ch == -1;
		}

		private int nextPrintable() {
			try {
				int ch;
				while (!isPrintable(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}

				return ch;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		String next() {
			try {
				int ch = nextPrintable();
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (isPrintable(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int nextInt() {
			try {
				// parseInt from Integer.parseInt()
				boolean negative = false;
				int res = 0;
				int limit = -Integer.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Integer.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				int multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		long nextLong() {
			try {
				// parseLong from Long.parseLong()
				boolean negative = false;
				long res = 0;
				long limit = -Long.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Long.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				long multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		float nextFloat() {
			return Float.parseFloat(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			try {
				int ch;
				while (isCRLF(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (!isCRLF(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int[] nextIntArray(int n) {
			int[] ret = new int[n];
			for (int i = 0; i < n; i++) {
				ret[i] = sc.nextInt();
			}

			return ret;
		}

		int[][] nextIntArrays(int m, int n) {
			int[][] ret = new int[m][n];
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					ret[j][i] = sc.nextInt();
				}
			}

			return ret;
		}

		void close() {
			try {
				br.close();
			} catch (IOException e) {
//				throw new NoSuchElementException();
			}
		}
	}

	static class Printer extends PrintWriter {
		Printer(OutputStream out) {
			super(out);
		}

		void printInts(int... a) {
			StringBuilder sb = new StringBuilder(32);
			for (int i = 0, size = a.length; i < size; i++) {
				if (i > 0) {
					sb.append(' ');
				}
				sb.append(a[i]);
			}

			println(sb);
		}

		void printLongs(long... a) {
			StringBuilder sb = new StringBuilder(64);
			for (int i = 0, size = a.length; i < size; i++) {
				if (i > 0) {
					sb.append(' ');
				}
				sb.append(a[i]);
			}

			println(sb);
		}

		void printStrings(String... a) {
			StringBuilder sb = new StringBuilder(32);
			for (int i = 0, size = a.length; i < size; i++) {
				if (i > 0) {
					sb.append(' ');
				}
				sb.append(a[i]);
			}

			println(sb);
		}
	}
}

import java.util.*;

import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
	public static void main(String[] args) throws IOException {
		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(reader);

		int N = Integer.parseInt(in.readLine());
		String[] tokens = in.readLine().split(" ");
		List<Long> S = new ArrayList<>(tokens.length);
		for (int i = 0; i < tokens.length; ++i) {
			S.add(Long.parseLong(tokens[i]));
		}
		Collections.sort(S, new Comparator<Long>() {
			@Override
			public int compare(Long o1, Long o2) {
				return Long.compare(o1, o2);
			}
		});
		// System.out.println(toStr(S.toArray(new Long[0])));

		Long[] array = new Long[1];
		array[0] = S.get(S.size() - 1);
		S.remove(S.size() - 1);
		for (int i = 0; i < N; ++i) {
			array = step(array, S);
			if (array == null) {
				break;
			}
		}
		// System.out.println(toStr(array));
		// arrayの検証
		/*
		 * for (int i = 0; i < N; ++i) { array = revStep(array); if (array == null) {
		 * break; } }
		 */
		if (array != null) {
			System.out.println("Yes");
		} else {
			System.out.println("No");
		}
	}

	static Long[] revStep(Long[] base) {
		// 条件チェック
		for (int i = 0; i < base.length; i += 2) {
			if (base[i] <= base[i + 1]) {
				return null;
			}
		}
		Long[] nexts = new Long[base.length / 2];
		for (int i = 0; i < nexts.length; ++i) {
			nexts[i] = base[i * 2];
		}

		return nexts;
	}

	static Long[] step(Long[] base, List<Long> list) {
		Long[] nexts = new Long[base.length * 2];
		// base要素のコピー
		for (int i = 0; i < base.length; ++i) {
			nexts[i * 2] = base[i];
		}
		// 追加
		for (int i = 1; i < nexts.length; i += 2) {
			Long val = search(list, nexts[i - 1]);
			if (val < 0) {
				return null;
			}
			nexts[i] = val;
		}
		// System.out.println(toStr(nexts));
		return nexts;
	}

	/*
	 * 
	 */
	static Long search(List<Long> list, Long val) {
		int index = Collections.binarySearch(list, val - 1L);
		if (index >= 0) {
			// その座標の値を採用 + 削除
			Long result = list.get(index);
			list.remove(index);
			return result;
		} else {
			int i = (index + 1) * -1;
			if (i == 0) {
				// 値がなかった
				return -1L;
			} else {
				// その値を採用
				i = Math.min(i, list.size() - 1);
				Long result = list.get(i);
				if(result >= val) {
					return -1L;
				}
				list.remove(i);
				return result;
			}
		}
	}

	static String toStr(Long[] array) {
		StringBuilder strBuilder = new StringBuilder();
		for (int i = 0; i < array.length; ++i) {
			strBuilder.append(" " + array[i]);
		}
		return strBuilder.toString();
	}
}

import java.util.Map;
import java.util.Scanner;
import java.util.TreeMap;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    TreeMap<Integer, Integer[]> map = new TreeMap<>();
    int n = sc.nextInt();
    int pow = (int) Math.pow(2, n);
    for (int i = 0; i < pow; i++) {
      map.computeIfAbsent(sc.nextInt(), a-> new Integer[]{0})[0]++;
    }
    boolean crct = true;
    for (Map.Entry<Integer, Integer[]> integerEntry : map.entrySet()) {
      if (integerEntry.equals(map.lastEntry())) {
        break;
      }
      final Integer integer = integerEntry.getValue()[0];
      if ((pow - integer < integer)) {
        crct = false;
        break;
      }
      pow -= integer;
    }
    System.out.println(crct ? "Yes" : "No");
  }
}

