public class Main {

	public static void main(String[] args) throws IOException {	
		try(final Scanner sc = new Scanner(System.in)){
			final int N = sc.nextInt();
			final int SIZE = 1 << N;

			long[] as = new long[SIZE];
			for(int i = 0; i < SIZE; i++) {
				as[i] = -sc.nextLong();
			}

			Arrays.sort(as);

			for(int i = 0; i < SIZE; i++) {
				as[i] = -as[i];
			}


			//System.out.println(Arrays.toString(as));
			PriorityQueue<Long> already = new PriorityQueue<Long>(Collections.reverseOrder());
			PriorityQueue<Long> remains = new PriorityQueue<Long>(Collections.reverseOrder());
			LinkedList<Long> next_already = new LinkedList<Long>();
			LinkedList<Long> remains_removed = new LinkedList<Long>();

			already.add(as[0]);
			for(int i = 1; i < SIZE; i++) {
				remains.add(as[i]);
			}

			boolean flag = false;
			while(!remains.isEmpty()) {
				next_already.clear();
				remains_removed.clear();

				while(!already.isEmpty()) {
					final long value = already.poll();

					while(!remains.isEmpty() && remains.peek() >= value) {
						remains_removed.add(remains.poll());
					}
					if(remains.isEmpty()) { flag = true; break; }

					next_already.add(remains.poll());
					next_already.add(value);
				}				
				if(flag) { break; }

				already.addAll(next_already);
				remains.addAll(remains_removed);
			}


			//System.out.println(Arrays.toString(as));
			System.out.println(flag ? "No" : "Yes");
		}
	}

	public static class Scanner implements Closeable {
		private BufferedReader br;
		private StringTokenizer tok;

		public Scanner(InputStream is) throws IOException {
			br = new BufferedReader(new InputStreamReader(is));
		}

		private void getLine() throws IOException {
			while(!hasNext()){
				tok = new StringTokenizer(br.readLine());
			}
		}

		private boolean hasNext() {
			return tok != null && tok.hasMoreTokens();
		}

		public String next() throws IOException {
			getLine();
			return tok.nextToken();
		}

		public int nextInt() throws IOException {
			return Integer.parseInt(next());
		}

		public long nextLong() throws IOException {
			return Long.parseLong(next());
		}

		public double nextDouble() throws IOException {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) throws IOException {
			final int[] ret = new int[n];
			for(int i = 0; i < n; i++){
				ret[i] = this.nextInt();
			}
			return ret;
		}

		public long[] nextLongArray(int n) throws IOException {
			final long[] ret = new long[n];
			for(int i = 0; i < n; i++){
				ret[i] = this.nextLong();
			}
			return ret;
		}

		public void close() throws IOException {
			br.close();
		}
	}
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Comparator;
import java.util.Deque;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    static final Scanner sc = new Scanner(System.in);
    static final int MOD = (int) 1E9 + 7;

    public static void main(String[] args) {
        int N = nint();
        int pow = (int) Math.pow(2, N);
        int[] S = nints(pow); 
        Arrays.sort(S);

        PriorityQueue<Node> d = new PriorityQueue<Node>(Node.comp);
        Deque<Node> deq = new ArrayDeque<>();
        Node start = new Node(-1, N, N, null);
        deq.add(start);
        d.add(start);

        while (!deq.isEmpty()) {
            Node f = deq.poll();
            for (int i = f.n-1; i >= 0; i--) {
                Node child = new Node(-1, i, f.getD()-1, f);
                d.add(child);
                deq.add(child);
            }
        }

        Node[] nodes = new Node[pow];
        int idx = 0;
        while (!d.isEmpty()) {
            Node node = d.poll();
            node.v = S[idx];
            nodes[idx] = node;
            idx++;
        }

        for (int i = 0; i < pow; i++) {
            Node node = nodes[i];
            if (node.parent != null) {
                if (node.parent.v <= node.v) {
                    System.out.println("No");
                    return;
                }
            }
        }

        System.out.println("Yes");
    }
    public static class Node {
        Node parent;
        int v;
        int n;
        int d;
        public int getN() {return n;}
        public int getD() {return d;}
        public int getV() {return v;}
        public Node(int v, int n, int d, Node parent) {
            super();
            this.v = v;
            this.n = n;
            this.d = d;
            this.parent = parent;
        }

        public static Comparator<Node> comp = Comparator.comparing(Node::getN).thenComparing(Node::getD);
    }

    private static long nlong() {
        return sc.nextLong();
    }

    private static int nint() {
        return sc.nextInt();
    }

    private static String nstr() {
        return sc.next();
    }

    private static char[] nchars() {
        return sc.next().toCharArray();
    }

    private static int[] nints(int n) {
        return nints(n, 0, 0);
    }

    private static int[] nints(int n, int padL, int padR) {
        int[] a = new int[padL + n + padR];
        for (int i = 0; i < n; i++)
            a[padL + i] = nint();
        return a;
    }

    private static char[][] nchars2(int h, int w) {
        return nchars2(h, w, 0);
    }

    private static char[][] nchars2(int h, int w, int pad) {
        char[][] a2 = new char[h + pad * 2][w + pad * 2];
        for (int i = 0; i < h; i++)
            System.arraycopy(nchars(), 0, a2[pad + i], pad, w);
        return a2;
    }
}

