	void solve() {
		int n = 1 << scn.nextInt();
		int[] arr = scn.nextIntArray(n);
		Arrays.parallelSort(arr);
		arr = scn.reverse(arr);

		int[] from = new int[n - 1], to = new int[n - 1];
		int[] bit = new int[n];
		bit[0] = -1;

		for(int i = 0, pos = 0; i < n; i++) {
			int b = bit[i] + 1;
			while(true) {
				int j = i + (1 << b);
				if(j >= n) {
					break;
				}
				from[pos] = i;
				to[pos] = j;
				pos++;

				bit[j] = b;

				b++;
			}
		}

		int[][] g = packD(n, from, to);
		for(int i = 0; i < n; i++) {
			for(int v : g[i]) {
				if(arr[v] >= arr[i]) {
					out.println("No");
					return;
				}
			}
		}
		out.println("Yes");
	}

	int[][] packD(int n, int[] from, int[] to) {
		int[][] g = new int[n][];
		int[] p = new int[n];
		for (int f : from)
			p[f]++;
		for (int i = 0; i < n; i++)
			g[i] = new int[p[i]];
		for (int i = 0; i < from.length; i++) {
			g[from[i]][--p[from[i]]] = to[i];
		}
		return g;
	}

