	public static void main(String[] args) throws IOException {	
		try(final Scanner sc = new Scanner(System.in)){
			final int N = sc.nextInt();
			final int SIZE = 1 << N;

			long[] as = new long[SIZE];
			for(int i = 0; i < 1 << N; i++) {
				as[i] = -sc.nextLong();
			}

			Arrays.sort(as);

			for(int i = 0; i < SIZE; i++) {
				as[i] = -as[i];
			}

			//System.out.println(Arrays.toString(as));
			boolean flag = false;
			for(int l = 0, r = 1; r <= SIZE; ) {
				final int len = r - l;
				for(int index = 0; index < len; index++) {
					final int currIndex = l + index;
					final int nextIndex = r + index;
					if(nextIndex >= SIZE) { break; }

					if(as[currIndex] <= as[nextIndex]) { flag = true; break; }
				}

				if(flag) { break; }
				if(r >= SIZE) { break; }
				r = Math.min(r * 2, SIZE);
			}

			//System.out.println(Arrays.toString(as));
			System.out.println(flag ? "No" : "Yes");
		}
	}

