import java.util.Arrays;
import java.util.PriorityQueue;

public class Main {

  private static void solve() {
    int n = ni();
    long[] s = nal(1 << n);
    Arrays.sort(s);
    for (int i = 0, j = (1 << n) - 1; i < j; i++, j--) {
      long tmp = s[i];
      s[i] = s[j];
      s[j] = tmp;
    }

    PriorityQueue<Long> q = new PriorityQueue<>((o1, o2) -> Long.compare(o2, o1));
    PriorityQueue<Long> p = new PriorityQueue<>((o1, o2) -> Long.compare(o2, o1));
    q.add(s[0]);
    int ptr = 1;
    for (int i = 1; i <= n; i++) {
      while (q.size() > 0) {
        long v = q.poll();
        if (s[ptr] < v) {
          p.add(v);
          p.add(s[ptr]);
        } else {
          System.out.println("No");
          return;
        }
        ptr++;
      }
      q.clear();
      PriorityQueue<Long> tmp = q;
      q = p;
      p = tmp;
    }
    System.out.println("Yes");

  }

