        FastScanner sc = new FastScanner(System.in);
        PriorityQueue<Integer> q = new PriorityQueue<Integer>(Comparator.reverseOrder());
        long mod = (long)1e9+7;
        int n = sc.nextInt();
        int max = (int)rep2(2,n,mod);
        for(int i = 0; i < max; i++){
            q.add(sc.nextInt());
        }
        ArrayList<Integer> now = new ArrayList<Integer>();
        Deque<Integer> dq = new ArrayDeque<Integer>();
        now.add(q.poll());
        for(int i = 0; i < n; i++){
            int roops = (int)rep2(2,i,mod);
            int min = Integer.MAX_VALUE;
            for(int j = 0; j < roops; j++){
                while(q.size() > 0 && now.get(j) <= q.peek()){
                    dq.add(q.poll());
                }
                if(q.isEmpty()){
                    System.out.println("No");
                    return;
                }
                now.add(q.poll());
            }
            while(dq.size() > 0){
                q.add(dq.pollLast());
            }
        }
        System.out.println("Yes");
    }

    private static long rep2(long b, long n, long mod){
        if(n == 0) return 1;
        long bn = rep2(b,n/2,mod);
        if(n % 2 == 0){
            return (bn*bn)%mod;
        }else{
            return (bn*bn)%mod*b%mod;
        }
    }
