public class Main {
	public static void main(String[] args) throws IOException {
		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(reader);

		int N = Integer.parseInt(in.readLine());
		int LEN = (int) (Math.pow(2, N));
		String[] tokens = in.readLine().split(" ");
		Long[] S = new Long[tokens.length];
		for (int i = 0; i < tokens.length; ++i) {
			S[i] = Long.parseLong(tokens[i]);
		}
		Arrays.sort(S, new Comparator<Long>() {
			@Override
			public int compare(Long o1, Long o2) {
				return -1 * Long.compare(o1, o2);
			}
		});
		boolean result = enable(S);
		if (result) {
			System.out.println("Yes");
		} else {
			System.out.println("No");
		}

	}

	static boolean enable(Long[] array) {
		if (array.length == 2) {
			if (array[0] <= array[1]) {
				return false;
			} else {
				return true;
			}
		}
		if (array[array.length / 2 - 1] <= array[array.length / 2]) {
			return false;
		}

		return enable(Arrays.copyOfRange(array, 0, array.length / 2));
	}

}

import java.util.*;
import java.util.stream.*;

public class Main {
	Scanner sc;
	int N, NN;
	Integer[] S;
	TreeSet<Slime> slimes;
	Slime[] indices;
	Comparator<Slime> order;

	static class Slime {
		int id, val;
		Slime(int id) {
			this.id = id;
		}
	}

	public Main() {
		sc = new Scanner(System.in);
		order = Comparator.comparingInt( (Slime s) -> (0x7fffffff & (-lsb(s.id))) ).
				thenComparingInt( s -> countOnes(s.id) ).
				thenComparingInt( s -> s.id );
	}

	private void calc() {
		N = sc.nextInt();
		NN = 1<<N;
		S = new Integer[NN];
		for (int i = 0; i < NN; i++) S[i] = sc.nextInt();
		Arrays.sort(S, Comparator.reverseOrder());
		slimes = new TreeSet<Slime>(order);
		indices = new Slime[NN];
		for (int i = 0; i < NN; i++) indices[i] = new Slime(i);
		slimes.add(indices[0]);
		indices[0].id = NN;

		for (int j = 0; j < NN; j++) {
			boolean found = false;
			for (Iterator<Slime> it = slimes.iterator(); it.hasNext();) {
				Slime s = it.next();
				if (j == 0 || indices[s.id ^ lsb(s.id)].val > S[j]) {
					s.val = S[j];
					it.remove();
					for (int l = (lsb(s.id) >>> 1); l > 0; l = l >>> 1)
						slimes.add(indices[(s.id | l)&(NN-1)]);
					found = true;
					break;
				}
			}
			if (!found) {
				System.out.println("No");
				return;
			}
		}
		System.out.println("Yes");
	}

	static int countOnes(int t) {
		t = (t & 0x55555555) + (t >> 1 & 0x55555555);
		t = (t & 0x33333333) + (t >> 2 & 0x33333333);
		t = (t & 0x0f0f0f0f) + (t >> 4 & 0x0f0f0f0f);
		t = (t & 0x00ff00ff) + (t >> 8 & 0x00ff00ff);
		return (t & 0x0000ffff) + (t >>16 & 0x0000ffff);
	}

	static int lsb(int t) {
		return t&(-t);
	}
	public static void main(String[] args) {
		new Main().calc();
	}
}

