        }
        new MergeSortLong().sort(A, 0, A.length - 1);
        ArrayList<Integer> range = new ArrayList<>();
        for (int i=n - 1;i>=0;i--)
        {
            range.add((int)Math.pow(2, i));
        }
        ArrayList<Integer> cum = new ArrayList<>();
        cum.add(range.get(0));
        for (int i=1;i<range.size();i++)
            cum.add(cum.get(cum.size() - 1) + range.get(i));
        boolean flag = true;
        for (int i=0;i<A.length - 1;i++)
        {
            int x = i + 1;
            int add = search(x, cum, n);
            if (A[i + add] == A[i])
            {
                flag = false;
                break;
            }
        }
        if (flag)
            System.out.println("Yes");
        else
            System.out.println("No");
    }
    public static int search(int idx, ArrayList<Integer> cum, int n)
    {
        for(int i=0;i<cum.size();i++)
        {
            if (cum.get(i) >= idx)
            {
                return (int)Math.pow(2, n - (i + 1));
            }
        }
        return -1;
    }
