        if(set.containsKey(value)){
            set.replace(value, set.get(value) + 1);
        } else{
            set.put(value, 1);
        }
    }

    public static void remove(TreeMap<Integer, Integer> set, int value){
        if(set.containsKey(value)){
            set.replace(value, set.get(value) - 1);
            if(set.get(value).equals(0)){
                set.remove(value);
            }
        } else {
