import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner sc = new FastScanner(System.in);
        PriorityQueue<Long> q = new PriorityQueue<Long>(Comparator.reverseOrder());
        long mod = (long)1e9+7;
        int n = sc.nextInt();
        int max = (int)rep2(2,n,mod);
        for(int i = 0; i < max; i++){
            q.add(sc.nextLong());
        }
        long now = q.poll();
        for(int i = 0; i < n; i++){
            int roops = (int)rep2(2,i,mod);
            if(now == q.peek()){
                System.out.println("No");
                return;
            }
            long tmp = 0;
            for(int j = 0; j < roops; j++){
                tmp = q.poll();
            }
            now = tmp;
        }
        System.out.println("Yes");
    }

    private static long rep2(long b, long n, long mod){
        if(n == 0) return 1;
        long bn = rep2(b,n/2,mod);
        if(n % 2 == 0){
            return (bn*bn)%mod;
        }else{
            return (bn*bn)%mod*b%mod;
        }
    }
}

class FastScanner {
    private BufferedReader reader = null;
    private StringTokenizer tokenizer = null;
    public FastScanner(InputStream in) {
        reader = new BufferedReader(new InputStreamReader(in));
        tokenizer = null;
    }

    public void close() throws Exception{
        this.reader.close();
        return;
    }

    public String next() {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public String nextLine() {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken("\n");
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public double nextDouble() {
         return Double.parseDouble(next());
    }

    public int[] nextIntArray(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = nextInt();
        return a;
    }

    public long[] nextLongArray(int n) {
        long[] a = new long[n];
        for (int i = 0; i < n; i++)
            a[i] = nextLong();
        return a;
    } 
}

import java.util.Arrays;
import java.util.LinkedList;
import java.util.Scanner;

public class Main {

    static class Slime {
        int health;
        int steps;

        public Slime(int health, int steps) {
            this.health = health;
            this.steps = steps;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();

        int[] S = new int[(1 << N)];
        for (int i = 0; i < (1 << N); i++) S[i] = sc.nextInt();

        Arrays.sort(S);


        LinkedList<Slime> queue = new LinkedList<>();
        queue.addFirst(new Slime(S[S.length - 1], N));
        int next = S.length - 2;

        while (!queue.isEmpty()) {
            Slime slime = queue.pollLast();

            if (slime.steps == 0) continue;

            if (S[next] >= slime.health) {
                System.out.println("No");
                return;
            }

            for (int steps = slime.steps - 1; steps >= 0; steps--) {
                queue.addFirst(new Slime(S[next], steps));
                next--;
            }
        }

        System.out.println("Yes");
    }
}

