    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        int[] s = sc.ints(1 << n);
        RadixSort.sortDescending(s);
        int[] t = new int[1 << (n + 1)];
        int m = 1 << n, h = 1 << ~-n;
        for (int i = 0; i < h; i++) {
            t[m + 2 * i] = s[i];
            t[m + 2 * i + 1] = s[h + i];
            if (s[i] == s[h + i]) {
                out.writeln("No");
                return;
            }
        }
        for (int i = m - 1; i > 0; i--) {
            t[i] = Math.max(t[i << 1 | 0], t[i << 1 | 1]);
            if (t[i << 1 | 0] == t[i << 1 | 1]) {
                out.writeln("No");
                return;
            }
        }
        out.writeln("Yes");
    }
}


