    PrintWriter out;

    public void solve() {
        int n = in.nextInt();
        int all = 1 << n;
        long[] s = in.nextLongArray(all);
        Arrays.sort(s);
        for (int l = 0, r = all - 1; l < r; l++, r--) {
            long t = s[l];
            s[l] = s[r];
            s[r] = t;
        }

        PriorityQueue<Long>[] pqs = new PriorityQueue[n+1];
        for (int i = 0; i < pqs.length; i++) {
            pqs[i] = new PriorityQueue<>((l1, l2) -> Long.compare(l2, l1));
        }
