import java.util.Arrays;
import java.util.PriorityQueue;
import java.io.FileInputStream;

public class Main {
    InputStream is;

    int __t__ = 1;
    int __f__ = 0;
    int __FILE_DEBUG_FLAG__ = __f__;
    String __DEBUG_FILE_NAME__ = "src/F1";

    FastScanner in;
    PrintWriter out;

    public void solve() {
        int n = in.nextInt();
        int all = 1 << n;
        long[] s = in.nextLongArray(all);
        Arrays.sort(s);
        for (int l = 0, r = all - 1; l < r; l++, r--) {
            long t = s[l];
            s[l] = s[r];
            s[r] = t;
        }

        PriorityQueue<State> pq = new PriorityQueue<>((s1, s2) -> {
            if (s1.x != s2.x) {
                return Long.compare(s2.x, s1.x);
            } else {
                return s2.cnt - s1.cnt;
            }
        });
        pq.add(new State(s[0], n));

        int cur = 1;
        while (!pq.isEmpty()) {
            State next = pq.poll();
            for (int i = 0; i < next.cnt; i++) {
                if (cur < all && next.x > s[cur]) {
                    pq.add(new State(s[cur], next.cnt - 1));
                    cur++;
                }
            }
        }
        System.out.println(cur == all ? "Yes" : "No");
    }

    class State {
        final long x;
        final int cnt;

        public State(long x, int cnt) {
            this.x = x;
            this.cnt = cnt;
        }
    }

