public class Main {

    static int N;
    static int[] S;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        S = sc.nextIntArray(1 << N);

        System.out.println(solve() ? "Yes" : "No");
    }

    static boolean solve() {
        S = shrink(S);

        int[] cnt = new int[1 << N];
        int max = 0;
        for (int i = 0; i < S.length; i++) {
            cnt[S[i]]++;
            max = Math.max(max, S[i]);
        }
        if( cnt[max] != 1 ) return false;

        int[] T = new int[1 << N];
        T[0] = max;
        cnt[max]--;

        TreeSet<Integer> set = new TreeSet<>();
        for (int i = 0; i < 1 << N; i++) {
            if( cnt[i] > 0 ) {
                set.add(i);
            }
        }

        for (int i = 0; i < N; i++) {
            int len = 1 << i;
            for (int j = 0; j < len; j++) {
                Integer lo = set.lower(T[j]);
                // debug(i, j, T[j], lo!=null?lo:"null");
                if( lo == null ) return false;

                T[j+len] = lo;
                cnt[lo]--;
                if( cnt[lo] == 0 ) set.remove(lo);
            }
        }
        return true;
    }

    public static int[] shrink(int[] a) {
        int n = a.length;
        long[] b = new long[n];
        for (int i = 0; i < n; i++) b[i] = (long) a[i] << 32 | i;
        Arrays.sort(b);
        int[] ret = new int[n];
        int p = 0;
        for (int i = 0; i < n; i++) {
            if (i > 0 && (b[i] ^ b[i - 1]) >> 32 != 0) p++;
            ret[(int) b[i]] = p;
        }
        return ret;
    }


