    static class ModInt{
        public static long mul(long... a) {
            long ret = 1;
            for (long c : a) {
                ret *= c;
                ret %= MOD;
            }
            return ret;
        }

        public static long div(long a, long... b) {
            long ret = a;
            for (long c : b) {
                ret *= inv(c);
                ret %= MOD;
            }
            return ret;
        }

        /**
         * Caluculate the value b s.t. a*b mod MOD = 1.
         * 
         * @param a
         * @return inverse of a
         */
        public static long inv(long a) {
            long b = MOD;
            long u = 1, v = 0;
            while (b >= 1) {
                long t = a / b;
                a -= t * b;
                long tmp1 = a;
                a = b;
                b = tmp1;
                u -= t * v;
                long tmp2 = u;
                u = v;
                v = tmp2;
            }
            u %= MOD;
            return u >= 0 ? u : u + MOD;
        }

        /**
         * Caluculate the combination nCr.
         * 
         * @param n left
         * @param r right
         * @return nCr
         */
        public static long comb(long n, long r) {
            if (n < r) {
                return 0;
            }
            r = Math.min(r, n - r);
            long res = 1;
            for (long d = 1; d <= r; d++) {
                res = div(mul(res, n--), d);
            }
            return res;
        }

        public static long[] fact(int n){
            long[] fact=new long[n+1];
            for(long i=0;i<=n;i++){
                if(i<=1){
                    fact[(int)i]=1;
                } else{
                    fact[(int)i]=mul(fact[(int)i-1], i);
                }
            }
            return fact;
        }
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            if (hasNextByte())
                return buffer[ptr++];
            else
                return -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        public boolean hasNext() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr]))
                ptr++;
            return hasNextByte();
        }

        public String next() {
            if (!hasNext())
                throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public long nextLong() {
            if (!hasNext())
                throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) {
                throw new NumberFormatException();
            }
            while (true) {
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                } else if (b == -1 || !isPrintableChar(b)) {
                    return minus ? -n : n;
                } else {
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }

        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)
                throw new NumberFormatException();
            return (int) nl;
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public void close(){
            try{
                in.close();
            } catch(Exception e){
                e.printStackTrace();
            }
        }
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner sc = new FastScanner(System.in);
        PriorityQueue<Long> q = new PriorityQueue<Long>(Comparator.reverseOrder());
        int n = sc.nextInt();
        int max = 1 << n;
        for(int i = 0; i < max; i++){
            q.add(sc.nextLong());
        }
        ArrayList<Long> now = new ArrayList<Long>();
        Deque<Long> dq = new ArrayDeque<Long>();
        now.add(q.poll());
        for(int i = 0; i < n; i++){
            int roops = 1 << i;
            for(int j = 0; j < roops; j++){
                while(q.size() > 0 && now.get(j) <= q.peek()){
                    dq.add(q.poll());
                }
                if(q.isEmpty()){
                    System.out.println("No");
                    return;
                }
                now.add(q.poll());
            }

            while(dq.size() > 0){
                q.add(dq.pollLast());
            }
        }
        System.out.println("Yes");
    }
}

class FastScanner {
    private BufferedReader reader = null;
    private StringTokenizer tokenizer = null;
    public FastScanner(InputStream in) {
        reader = new BufferedReader(new InputStreamReader(in));
        tokenizer = null;
    }

    public void close() throws Exception{
        this.reader.close();
        return;
    }

    public String next() {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public String nextLine() {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken("\n");
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public double nextDouble() {
         return Double.parseDouble(next());
    }

    public int[] nextIntArray(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = nextInt();
        return a;
    }

    public long[] nextLongArray(int n) {
        long[] a = new long[n];
        for (int i = 0; i < n; i++)
            a[i] = nextLong();
        return a;
    } 
}

import java.util.Scanner;
import java.util.*;

public class Main {
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();

    Map<Integer, Integer> map = new HashMap<>();

    int loopCount = (int)Math.pow(2, n);
    for(int i = 0; i < loopCount; i++){
      int si = sc.nextInt();
      Integer tmpCount = map.get(si);
      if(tmpCount == null){
        map.put(si, 1);
      }  else  {
        map.put(si, tmpCount + 1);
      }
    }
    List<Integer> list = new ArrayList<>(map.keySet());
    Collections.sort(list, Comparator.reverseOrder());
    if(map.get(list.get(0)) > 1){
      System.out.println("No");
      return;
    }
    // n回最大値をコピーできる
    int canCounter = n;
    int lCount = 1;
    for(int i:list){
      //System.out.println(i + ": " + map.get(i));
      if(canCounter < map.get(i)){
        System.out.println("No");
        return;
      }
      canCounter -= map.get(i);
      canCounter += n - 1;
      lCount++;
    }

    System.out.println("Yes");
  }
}

import java.util.*;
import java.util.stream.*;

public class Main {
	Scanner sc;
	int N;
	int NN;
	Integer[] S;
	TreeSet<Slime> slimes;
	Slime[] indexed;

	Comparator<Slime> hier = (a,b) -> {
		int ga = lsb(a.id);
		if (ga == 0) return -1;
		int gb = lsb(b.id);
		if (gb == 0) return 1;
		if (ga != gb) return gb-ga;
		int ba = countOnes(a.id);
		int bb = countOnes(b.id);
		if (ba != bb) return ba-bb;
		return Integer.compare(a.id, b.id);
	};

	static class Slime {
		int id, val;
		Slime(int id) {
			this.id = id;
		}
	}

	public Main() {
		sc = new Scanner(System.in);
	}

	private void calc() {
		N = sc.nextInt();
		NN = 1<<N;
		S = new Integer[NN];
		for (int i = 0; i < NN; i++) S[i] = sc.nextInt();
		Arrays.sort(S, Comparator.reverseOrder());
		slimes = new TreeSet<Slime>(hier);
		indexed = new Slime[NN];
		for (int i = 0; i < NN; i++) {
			indexed[i] = new Slime(i);
			slimes.add(indexed[i]);
		}
		int j = 1;
	lp:
		for (int i = 0; i < NN; i++) {
			if (i == 0) {
				Iterator<Slime> it = slimes.iterator();
				it.next().val = S[0];
				it.remove();
				continue;
			}
			for (Iterator<Slime> it = slimes.iterator(); !slimes.isEmpty();) {
				Slime s = it.next();
				Slime parent = indexed[s.id ^ lsb(s.id)];
				if (parent.val <= S[j]) {
					if ((s.id & 1) == 1) break;
					it = slimes.tailSet(indexed[lsb(s.id)>>>1], true).iterator();
					continue;
				}
				s.val = S[j++];
				it.remove();
				continue lp;
			}
			System.out.println("No");
			return;
		}
		System.out.println("Yes");
	}

	static int countOnes(int t) {
		t = (t & 0x55555555) + (t >> 1 & 0x55555555);
		t = (t & 0x33333333) + (t >> 2 & 0x33333333);
		t = (t & 0x0f0f0f0f) + (t >> 4 & 0x0f0f0f0f);
		t = (t & 0x00ff00ff) + (t >> 8 & 0x00ff00ff);
		return (t & 0x0000ffff) + (t >>16 & 0x0000ffff);
	}

	static int lsb(int t) {
		return t&(-t);
	}

	public static void main(String[] args) {
		new Main().calc();
	}
}

import java.util.Arrays;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner scn = new Scanner(System.in);
		int N = scn.nextInt();
		int SN = (int)Math.pow(2, N);
		long[] S = new long[SN];
		for(int i = 0;i < SN;i++) {
			S[i] = scn.nextLong();
		}
		Arrays.sort(S);
		PriorityQueue<Power> PQ = new PriorityQueue<Power>();

		PQ.add(new Power(S[SN-1],N));
		boolean can = true;
		for(int i = SN-2;i >=0;i--) {
			Power p = PQ.poll();
			if(p.v > S[i]) {
				p.num--;
				if(p.num!=0) {

					PQ.add(p);
					PQ.add(new Power(S[i],p.num));
				}
				continue;
			}
			can = false;
			break;
		}
		System.out.println(can?"Yes":"No");


	}

}

class Power implements Comparable<Power>{
	long v;
	int num;
	public Power(long v, int num) {
		this.v = v;
		this.num = num;
	}


	@Override
	public int compareTo(Power o) {
		if(this.v < o.v)return 1;
		if(this.v > o.v)return -1;
		if(this.num < o.num)return 1;
		if(this.num > o.num)return-1;

		return 0;
	}

}

