        }
        boolean works = true;
        ArrayList<Integer> use = new ArrayList<>();
        use.add(map.floorKey(Integer.MAX_VALUE));
        map.put(use.get(0), map.get(use.get(0)) - 1);
        OUTER:
        for (int i = 0; i < n; i++)
        {
            int shift = 1 << i;
            for (int j = 0; j < shift; j++)
            {
                Integer x = map.floorKey(use.get(j)-1);
                if (x == null)
