		int w = 1;

		do {
			for ( int i = 0 ; i < w ; i++ ) {
				if ( s[n-(p+i)-1] <= s[n-(p+w+i*2)-1] || s[n-(p+i)-1] <= s[n-(p+w+i*2+1)-1] ) {
					System.out.println("No");
					return;
				}
			}
			p += w ;
			w *= 2 ;
		} while ( p + w*3 < n ) ;
		System.out.println("Yes");
	}
}

