    static class FManySlimes {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int[] a = in.readIntArray(1 << n);

            int max = ArrayUtils.maxElement(a);

            int[] can = new int[1 << n];
            can[0] = max;
            int idx = 1;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 1 << i; j++) {
                    can[idx++] = can[j] - 1;
                }
            }

            Arrays.sort(a);
            Arrays.sort(can);
            for (int i = 0; i < 1 << n; i++) {
                if (a[i] > can[i]) {
                    out.printLine("No");
                    return;
                }
            }
            out.printLine("Yes");
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int[] readIntArray(int size) {
            int[] array = new int[size];
            for (int i = 0; i < size; i++) {
                array[i] = readInt();
            }
            return array;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static interface IntStream extends Iterable<Integer>, Comparable<IntStream> {
        public IntIterator intIterator();

        default public Iterator<Integer> iterator() {
            return new Iterator<Integer>() {
                private IntIterator it = intIterator();

                public boolean hasNext() {
                    return it.isValid();
                }

                public Integer next() {
                    int result = it.value();
                    it.advance();
                    return result;
                }
            };
        }

        default public int compareTo(IntStream c) {
            IntIterator it = intIterator();
            IntIterator jt = c.intIterator();
            while (it.isValid() && jt.isValid()) {
                int i = it.value();
                int j = jt.value();
                if (i < j) {
                    return -1;
                } else if (i > j) {
                    return 1;
                }
                it.advance();
                jt.advance();
            }
            if (it.isValid()) {
                return 1;
            }
            if (jt.isValid()) {
                return -1;
            }
            return 0;
        }

        default public int max() {
            int result = Integer.MIN_VALUE;
            for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
                int current = it.value();
                if (current > result) {
                    result = current;
                }
            }
            return result;
        }

    }

    static interface IntList extends IntReversableCollection {
        public abstract int get(int index);

        public abstract void removeAt(int index);

        default public IntIterator intIterator() {
            return new IntIterator() {
                private int at;
                private boolean removed;

                public int value() {
                    if (removed) {
                        throw new IllegalStateException();
                    }
                    return get(at);
                }

                public boolean advance() {
                    at++;
                    removed = false;
                    return isValid();
                }

                public boolean isValid() {
                    return !removed && at < size();
                }

                public void remove() {
                    removeAt(at);
                    at--;
                    removed = true;
                }
            };
        }

    }

    static interface IntIterator {
        public int value() throws NoSuchElementException;

        public boolean advance();

        public boolean isValid();

    }

    static interface IntCollection extends IntStream {
        public int size();

    }

    static class IntArray extends IntAbstractStream implements IntList {
        private int[] data;

        public IntArray(int[] arr) {
            data = arr;
        }

        public int size() {
            return data.length;
        }

        public int get(int at) {
            return data[at];
        }

        public void removeAt(int index) {
            throw new UnsupportedOperationException();
        }

    }

    static interface IntReversableCollection extends IntCollection {
    }

    static class ArrayUtils {
        public static int maxElement(int[] array) {
            return new IntArray(array).max();
        }

    }

    static abstract class IntAbstractStream implements IntStream {
        public String toString() {
            StringBuilder builder = new StringBuilder();
            boolean first = true;
            for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
                if (first) {
                    first = false;
                } else {
                    builder.append(' ');
                }
                builder.append(it.value());
            }
            return builder.toString();
        }

        public boolean equals(Object o) {
            if (!(o instanceof IntStream)) {
                return false;
            }
            IntStream c = (IntStream) o;
            IntIterator it = intIterator();
            IntIterator jt = c.intIterator();
            while (it.isValid() && jt.isValid()) {
                if (it.value() != jt.value()) {
                    return false;
                }
                it.advance();
                jt.advance();
            }
            return !it.isValid() && !jt.isValid();
        }

        public int hashCode() {
            int result = 0;
            for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
                result *= 31;
                result += it.value();
            }
            return result;
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

    }
}

import java.util.*;

import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
	public static void main(String[] args) throws IOException {
		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(reader);

		int N = Integer.parseInt(in.readLine());
		String[] tokens = in.readLine().split(" ");
		Long[] S = new Long[tokens.length];
		for (int i = 0; i < tokens.length; ++i) {
			S[i] = Long.parseLong(tokens[i]);
		}
		Arrays.sort(S, new Comparator<Long>() {
			@Override
			public int compare(Long o1, Long o2) {
				return -1 * Long.compare(o1, o2);
			}
		});
		// baseとなるqueを作成
		Deque<Long> que = new ArrayDeque<>(S.length);
		for (int i = 0; i < S.length; ++i) {
			que.addLast(S[i]);
		}
		Long[] array = new Long[1];
		array[0] = que.pollFirst();
		for (int i = 0; i < N; ++i) {
			array = step(array, que);
			if (array == null) {
				break;
			}
		}
		// System.out.println(toStr(array));
		// arrayの検証
		/*
		for (int i = 0; i < N; ++i) {
			array = revStep(array);
			if (array == null) {
				break;
			}
		}*/
		if (array != null) {
			System.out.println("Yes");
		} else {
			System.out.println("No");
		}
	}

	static Long[] revStep(Long[] base) {
		// 条件チェック
		for (int i = 0; i < base.length; i += 2) {
			if (base[i] <= base[i + 1]) {
				return null;
			}
		}
		Long[] nexts = new Long[base.length / 2];
		for (int i = 0; i < nexts.length; ++i) {
			nexts[i] = base[i * 2];
		}

		return nexts;
	}

	static Long[] step(Long[] base, Deque<Long> que) {
		Long[] nexts = new Long[base.length * 2];
		// base要素のコピー
		for (int i = 0; i < base.length; ++i) {
			nexts[i * 2] = base[i];
		}
		// 追加
		for (int i = 1; i < nexts.length; i += 2) {
			Long val = search(que, nexts[i - 1]);
			if (val < 0) {
				return null;
			}
			nexts[i] = val;
		}
		return nexts;
	}

	/*
	 * 
	 */
	static Long search(Deque<Long> que, Long val) {
		Deque<Long> temp = new ArrayDeque<>(que.size());
		Long result = -1L;
		while (!que.isEmpty()) {
			if (que.peekFirst() < val) {
				result = que.pollFirst();
				break;
			} else {
				temp.addLast(que.pollFirst());
			}
		}
		// 残りのものを戻す
		while (!temp.isEmpty()) {
			que.addFirst(temp.pollLast());
		}
		return result;
	}

	static String toStr(Long[] array) {
		StringBuilder strBuilder = new StringBuilder();
		for (int i = 0; i < array.length; ++i) {
			strBuilder.append(" " + array[i]);
		}
		return strBuilder.toString();
	}
}

