			ex = buf;
			noko = noko_buf;
			buf = new PriorityQueue<Long>(new MyComp());
			noko_buf = new PriorityQueue<Long>(new MyComp());
			while (!ex.isEmpty()) {
				long p = ex.poll();
				buf.add(p);
				while (!noko.isEmpty()) {
					long np = noko.poll();
					if (p > np) {
						buf.add(np);
						break;
					} else {
						noko_buf.add(np);
					}
				}

			}
			while (!noko.isEmpty()) {
