		TreeSet<Pair> set = new TreeSet<>();
		for (int i = 0; i < S.length - 1; i++) {
			set.add(new Pair(S[i], i));
		}
		assert set.size() == (1 << N) - 1;
		int[] oks = new int[1 << N];
		oks[0] = S[S.length - 1];

		boolean ok = true;
		outer: for (int i = 0; i < N; i++) {
			int lim = 1 << i;
			for (int j = 0; j < lim; j++) {
				int v = oks[j];
				// System.out.println("--" + v);
				Pair pop = set.lower(new Pair(v, 0));
				if (pop == null) {
