		 * 各スライムについて親を考える
		 * まず、最初の1体はS_0で良い
		 * ……シミュレーションで通らん？
		 */
		int N = io.nextInt();
		int[] S = io.nextInt(1 << N);
		Arrays.sort(S);
		for (int i = 0;i < S.length >> 1;++ i) { // あー、ライブラリ整備終わってないのが死だわ
			int tmp = S[i];
			S[i] = S[S.length - i - 1];
			S[S.length - i - 1] = tmp;
		}
		if (DEBUG) io.println(S);
		TreeMap<Integer, Integer> multiMap = new TreeMap<>(); // これもじゃん！
		for (int i = 0;i < N;++ i) {
			for (int j = 0;j < 1 << i;++ j) multiMap.merge(S[j], 1, (f, x)-> f + 1);
			if (DEBUG) io.println(multiMap);
			for (int j = 1 << i;j < 2 << i;++ j) {
				Entry<Integer, Integer> entry = multiMap.higherEntry(S[j]);
				if (entry == null || entry.getValue() == null) {
					io.println("No");
					return;
				}
				if (DEBUG) io.println(entry.getKey() + ":" + entry.getValue());
				if (entry.getValue() == 1) multiMap.remove(entry.getKey());
				else multiMap.replace(entry.getKey(), entry.getValue() - 1);
			}
			if (!multiMap.isEmpty()) System.exit(1);
			if (DEBUG) io.println("->" + multiMap);
		}
		io.println("Yes");
	}

