	private void solve(FastIO io) {
		/*
		 * author: 31536000
		 * ABC140 F問題
		 * 考察メモ
		 * まず集合は降順ソートして良い
		 * 最初の1体のHP>次の2体のHP>次の4体のHP>……は明らか
		 * で、ということはHPの状態についてDAG
		 * 各スライムについて親を考える
		 * まず、最初の1体はS_0で良い
		 * ……シミュレーションで通らん？
		 */
		int N = io.nextInt();
		int[] S = io.nextInt(1 << N);
		TreeMap<Integer, Integer> multiMap = new TreeMap<>(); // これライブラリ整備不足じゃん！
		for (int i : S) multiMap.merge(i, 1, (f, x) -> f + 1);
		ArrayList<Integer> slime = new ArrayList<>();
		slime.add(multiMap.lastKey());
		for (int i = 0;i < N;++ i) {
			for (int j = 0;j < 1 << i;++ j) {
				Entry<Integer, Integer> entry = multiMap.lowerEntry(slime.get(j));
				if (entry == null) {
					io.println("No");
					return;
				}
				if (entry.getValue() == 1) multiMap.remove(entry.getKey());
				else multiMap.replace(entry.getKey(), entry.getValue() - 1);
				slime.add(entry.getKey());
			}
		}
		io.println("Yes");
	}

