                int cnt = slime.Count;
                for(int j = 0; j < cnt; j++)
                {
                    int[] result = sDic.Where(a => slime[j] > a[0] && a[1] > 0).FirstOrDefault();
                    if(result == null)
                    {
                        Console.WriteLine("No");
                        Console.ReadLine();
                        return;
                    }
                    else
                    {
                        result[1]--;
                        slime.Add(result[0]);
                        if (result[1] == 0)
                        {
                            sDic.Remove(result);
                        }
                    }
                }
            }
            //出力
            if(sDic.Max(a => a[1])==0)
            {
                Console.WriteLine("Yes");
            }
            else
            {
                Console.WriteLine("No");
            }
            Console.ReadLine();
        }
    }
}

