            {
                res.Enqueue(s[i]);
            }

            slimes.Enqueue(res.Dequeue());
            while (res.Any())
            {
                var pq = new PriorityQueue<int>();

                while (slimes.Any())
                {
                    var sl = slimes.Dequeue();
                    var r = res.Dequeue();

                    if (r >= sl)
                    {
                        Console.WriteLine("No");
                        return;
                    }

                    pq.Enqueue(sl);
                    pq.Enqueue(r);
                }


                slimes = pq;
            }

            Console.WriteLine("Yes");
        }

        /// <summary>
        /// 優先度付きキュー(二分ヒープ)
        /// デフォルトは降順ソート
        /// </summary>
        class PriorityQueue<T>
        {
            static readonly int DefaultCapacity = 8;
            readonly List<T> Heap;
            readonly Comparison<T> Comparer;

            public PriorityQueue(int capacity, Comparison<T> comparer)
            {
                Heap = new List<T>(capacity);
                Comparer = comparer;
            }

            public PriorityQueue() : this(DefaultCapacity) { }
            public PriorityQueue(int capacity) : this(capacity, Comparer<T>.Default.Compare) { }
            public PriorityQueue(Comparison<T> comparer) : this(DefaultCapacity, comparer) { }

            /// <summary> 要素追加 </summary>
            public void Enqueue(T item)
            {
                var n = Heap.Count();
                Heap.Add(item);

                while (n > 0)
                {
                    var parent = (n - 1) / 2;
                    if (Comparer(Heap[parent], item) > 0) break;

                    Heap[n] = Heap[parent];
                    n = parent;
                }

                Heap[n] = item;
            }

            /// <summary> 要素追加 </summary>
            public void Push(T item) => Enqueue(item);

            /// <summary> 先頭の値を取得し削除する </summary>
            public T Dequeue()
            {
                if (!Heap.Any())
                {
                    throw new Exception();
                }
                var item = Heap[0];
                var last = Heap.Last();

                var n = Heap.Count() - 1;
                var parent = 0;
                var child = 2 * parent + 1;
                while (child < n)
                {
                    if (child + 1 < n && Comparer(Heap[child + 1], Heap[child]) > 0)
                    {
                        child++;
                    }

                    if (Comparer(last, Heap[child]) > 0) break;

                    Heap[parent] = Heap[child];
                    parent = child;
                    child = 2 * parent + 1;
                }

                Heap[parent] = last;
                Heap.RemoveAt(n);

                return item;
            }

            /// <summary> 先頭の値を取得し削除する </summary>
            public T Pop() => Dequeue();

            /// <summary>
            /// 先頭の値取得（削除はしない）
            /// </summary>
            public T Peek()
            {
                if (!this.Heap.Any()) throw new Exception();

                return this.Heap[0];
            }

            /// <summary>
            /// ヒープに格納されているアイテム数
            /// </summary>
            public int Count() => this.Heap.Count();

            /// <summary>
            /// 一つでも値が格納されているか
            /// </summary>
            public bool Any() => this.Heap.Any();
        }

        #region Main
