using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        int N = Utils.ReadInts()[0];
        int[] S = Utils.ReadInts();

        bool result = Solve(N, S);

        Utils.ReturnYesOrNo(result);
    }

    private static bool Solve(int n, int[] s)
    {
        s = s.OrderByDescending(a => a).ToArray();
        List<int> slimes = new List<int>();
        slimes.Add(s[0]);
        s[0] = int.MaxValue;
        int cnt = 0;
        for(int i = 1; i < s.Length;)
        {
            cnt++;
            int slimeNum = slimes.Count;
            for(int x = 0; x < slimeNum; x++)
            {
                bool exists = false;
                for(int y = 0; y < s.Length; y++)
                {
                    if (s[y] == int.MaxValue) continue;
                    if(s[y] < slimes[x])
                    {
                        exists = true;
                        slimes.Add(s[y]);
                        s[y] = int.MaxValue;
                        break;
                    }
                }
                if (!exists)
                {
                    return false;
                }
            }
            slimes = slimes.OrderByDescending(a => a).ToList();
            i = slimes.Count;
        }
        return (cnt == n);
    }
}

