        public void solve() {
            int n = sc.Int;
            var s = sc.IntArr;
            Array.Sort(s);
            Array.Reverse(s);
            var q = new PriorityQueue<int>[n];
            for (int i = 0; i < n; i++)
            {
                q[i] = new PriorityQueue<int>();
                q[i].Push(s[0]);
            }
            for (int i = 1; i < (1 << n); i++)
            {
                bool ok = false;
                for (int j = 0; j < n; j++)
                {
                    if (q[j].Count > 0 && q[j].Top > s[i]) {
                        q[j].Pop();
                        if (j + 1 < n) q[j + 1].Push(s[i]);
                        if (j + 2 < n) q[j + 2].Push(s[i]);
