            /// <remarks> <paramref name="a"/> は比較関数に対して昇順であることを仮定しています．この関数は O(log N) で実行されます．</remarks>
            public int UpperBound(T item) => BinarySearchImpl(item, false);

            void ICollection<T>.Add(T item) => this.Add(item);
            public int Add(T item)
            {
                var index = BinarySearch(item);
                if (index < 0)
                    index = ~index;
                list.Insert(index, item);
                return index;
            }

            public int IndexOf(T item)
            {
                var index = BinarySearch(item);
                if (index >= 0) return index;
                else return -1;
            }
            public bool Contains(T item) => BinarySearch(item) >= 0;
            public void Clear() => list.Clear();
            public void CopyTo(T[] array, int arrayIndex) => list.CopyTo(array, arrayIndex);

            public bool Remove(T item)
            {
                int index = this.IndexOf(item);
                if (index < 0)
                    return false;
                list.RemoveAt(index);
                return true;
            }

            IEnumerator IEnumerable.GetEnumerator() => this.GetEnumerator();
            public IEnumerator<T> GetEnumerator() => list.GetEnumerator();
            public void Insert(int index, T item) { throw new NotImplementedException(); }
            public void RemoveAt(int index) => list.RemoveAt(index);
        }


        class SortedCollectionSD<T> : ICollection<T>
        {
            SortedDictionary<T, int> dic;
            public T First => dic.Keys.First();
            public SortedCollectionSD() : this(Comparer<T>.Default) { }
            public SortedCollectionSD(IComparer<T> comparer) { dic = new SortedDictionary<T, int>(comparer); }
            public SortedCollectionSD(IEnumerable<T> original) : this(original, Comparer<T>.Default) { }
            public SortedCollectionSD(IEnumerable<T> original, IComparer<T> comparer) : this(comparer)
            {
                foreach (var item in original)
                    this.Add(item);
            }

            public bool IsReadOnly => false;
            public int Count { get; private set; } = 0;
            public void Add(T item)
            {
                if (dic.ContainsKey(item)) ++dic[item];
                else dic[item] = 1;
                Count++;
            }
            public void Clear() => dic.Clear();
            public bool Contains(T item) => dic.ContainsKey(item);
            public void CopyTo(T[] array, int arrayIndex) { throw new NotImplementedException(); }

            public bool Remove(T item)
            {
                int count;
                if (dic.TryGetValue(item, out count))
                {
                    Count--;
                    if (count > 1) --dic[item];
                    else dic.Remove(item);
                    return true;
                }
                else
                    return false;
            }

            IEnumerator IEnumerable.GetEnumerator() => this.GetEnumerator();
            public IEnumerator<T> GetEnumerator()
            {
                foreach (var pair in dic)
                    foreach (var item in Enumerable.Repeat(pair.Key, pair.Value))
                        yield return item;
            }
        }
