public partial class MultiSet<T>
{
    private Node root = null;
    private readonly IComparer<T> _comparer;

    public MultiSet() : this(Comparer<T>.Default)
    {
    }

    public MultiSet(IComparer<T> comparer)
    {
        _comparer = comparer;
    }

    virtual protected bool AllowMultiple { get { return true; } }

    public int Count { get { return root == null ? 0 : root.Count + root.LeftTotalCount + root.RightTotalCount; } }

    private Node FindNode(T value)
    {
        var node = root;
        while (node != null)
        {
            int cmp = _comparer.Compare(value, node.Value);
            if (cmp == 0)
            {
                return node;
            }
            node = (cmp < 0) ? node.Left : node.Right;
        }
        return null;
    }

    public bool Contains(T value)
    {
        var node = FindNode(value);
        return node != null;
    }

    public int CountOf(T value)
    {
        var node = FindNode(value);
        return node != null ? node.Count : 0;
    }

    public int IndexOfLowerBound(T value)
    {
        var node = root;
        int index = 0;
        while (node != null)
        {
            int cmp = _comparer.Compare(value, node.Value);
            if (cmp <= 0)
            {
                node = node.Left;
            }
            else
            {
                index += node.LeftTotalCount + node.Count;
                node = node.Right;
            }
        }
        return index;
    }

    public int IndexOfUpperBound(T value)
    {
        var node = root;
        int index = 0;
        while (node != null)
        {
            int cmp = _comparer.Compare(value, node.Value);
            if (cmp < 0)
            {
                node = node.Left;
            }
            else
            {
                index += node.LeftTotalCount + node.Count;
                node = node.Right;
            }
        }
        return index;
    }

    public T At(int index)
    {
        var node = root;
        while (node != null)
        {
            int leftCount = node.LeftTotalCount;
            if (leftCount <= index && index < leftCount + node.Count) return node.Value;
            if (index < leftCount)
            {
                node = node.Left;
            }
            else
            {
                index -= leftCount + node.Count;
                node = node.Right;
            }
        }
        throw new ArgumentOutOfRangeException("index");
    }

    public void Add(T value)
    {
        root = Add(root, value);
        root.Color = Node.BLACK;
    }

    private Node Add(Node h, T value)
    {
        if (h == null)
        {
            return new Node(value);
        }

        if (IsRed(h.Left) && IsRed(h.Right))
        {
            ColorFlip(h);
        }

        int cmp = _comparer.Compare(value, h.Value);
        if (cmp == 0)
        {
            if (AllowMultiple)
            {
                h.Count++;
                FixCount(h);
            }
        }
        else if (cmp <= 0)
        {
            h.Left = Add(h.Left, value);
            FixCount(h);
        }
        else
        {
            h.Right = Add(h.Right, value);
            FixCount(h);
        }

        if (IsRed(h.Right) && !IsRed(h.Left))
        {
            h = RotateLeft(h);
        }

        if (IsRed(h.Left) && IsRed(h.Left.Left))
        {
            h = RotateRight(h);
        }

        return h;
    }

    private Node RemoveLeftestNode(Node h)
    {
        if (h.Left == null)
        {
            return null;
        }

        if (!IsRed(h.Left) && !IsRed(h.Left.Left))
        {
            h = MoveRedLeft(h);
        }

        h.Left = RemoveLeftestNode(h.Left);
        return FixUp(h);
    }

    private bool TryReduceCount(Node h, T value, out int num)
    {
        num = 0;
        if (h == null)
        {
            return false;
        }

        int cmp = _comparer.Compare(value, h.Value);
        if (cmp == 0)
        {
            num = h.Count;
            if (h.Count > 1)
            {
                h.Count--;
                FixCount(h);
                return true;
            }
            return false;
        }
        if (TryReduceCount((cmp < 0) ? h.Left : h.Right, value, out num))
        {
            FixCount(h);
            return true;
        }
        return false;
    }


    public bool Remove(T value)
    {
        if (AllowMultiple)
        {
            int num;
            if (TryReduceCount(root, value, out num))
            {
                return true;
            }
            if (num == 0)
            {
                return false;
            }
        }
        else
        {
            if (!Contains(value))
            {
                return false;
            }
        }

        root = RemoveNode(root, value);
        if (root != null)
        {
            root.Color = Node.BLACK;
        }
        return true;
    }

    private Node RemoveNode(Node h, T value)
    {
        if (_comparer.Compare(value, h.Value) < 0)
        {
            if (h.Left == null)
            {
                throw new KeyNotFoundException("value");
            }

            if (!IsRed(h.Left) && !IsRed(h.Left.Left))
            {
                h = MoveRedLeft(h);
            }
            h.Left = RemoveNode(h.Left, value);
            FixCount(h);
        }
        else
        {
            if (IsRed(h.Left))
            {
                h = RotateRight(h);
            }

            if (h.Right == null)
            {
                if (_comparer.Compare(value, h.Value) == 0)
                {
                    return null;
                }

                throw new KeyNotFoundException("value");
            }

            if (!IsRed(h.Right) && !IsRed(h.Right.Left))
            {
                h = MoveRedRight(h);
            }

            if (_comparer.Compare(value, h.Value) == 0)
            {
                var minNode = GetLeftestNode(h.Right);
                h.Value = minNode.Value;
                h.Count = minNode.Count;
                h.Right = RemoveLeftestNode(h.Right);
                FixCount(h);
            }
            else
            {
                h.Right = RemoveNode(h.Right, value);
                FixCount(h);
            }
        }

        return FixUp(h);
    }


    private static Node MoveRedLeft(Node h)
    {
        ColorFlip(h);

        if (IsRed(h.Right.Left))
        {
            h.Right = RotateRight(h.Right);
            FixCount(h);
            h = RotateLeft(h);
            ColorFlip(h);
        }

        return h;
    }

    private static Node MoveRedRight(Node h)
    {
        ColorFlip(h);

        if (IsRed(h.Left.Left))
        {
            h = RotateRight(h);
            ColorFlip(h);
        }

        return h;
    }

    static private Node RotateLeft(Node h)
    {
        Node x = h.Right;
        h.Right = x.Left;
        x.Left = h;

        x.Color = h.Color;
        h.Color = Node.RED;
        FixCount(h);
        FixCount(x);
        return x;
    }

    private static Node RotateRight(Node h)
    {
        Node x = h.Left;
        h.Left = x.Right;
        x.Right = h;

        x.Color = h.Color;
        h.Color = Node.RED;
        FixCount(h);
        FixCount(x);
        return x;
    }

    private static bool IsRed(Node h)
    {
        return h != null && h.Color == Node.RED;
    }

    static private void ColorFlip(Node h)
    {
        h.Color = !h.Color;
        h.Left.Color = !h.Left.Color;
        h.Right.Color = !h.Right.Color;
    }

    static private Node GetLeftestNode(Node h)
    {
        while (h.Left != null)
        {
            h = h.Left;
        }
        return h;
    }

    static private Node FixUp(Node h)
    {
        if (IsRed(h.Right))
        {
            h = RotateLeft(h);
        }

        if (h.Left != null && IsRed(h.Left) && IsRed(h.Left.Left))
        {
            h = RotateRight(h);
        }

        if (IsRed(h.Left) && IsRed(h.Right))
        {
            ColorFlip(h);
        }
        FixCount(h);
        return h;
    }

    static private void FixCount(Node node)
    {
        node.TotalCount = node.Count + node.LeftTotalCount + node.RightTotalCount;
    }

    public void Debug()
    {
        if (root != null)
        {
            root.Debug();
        }
    }

    private class Node
    {
        public const bool RED = true;
        public const bool BLACK = false;
        public T Value;
        public bool Color = RED;
        public Node Left = null;
        public Node Right = null;
        public int Count = 1;
        public Node(T value)
        {
            this.Value = value;
        }

        public int TotalCount = 1;
        public int LeftTotalCount { get { return Left == null ? 0 : Left.TotalCount; } }
        public int RightTotalCount { get { return Right == null ? 0 : Right.TotalCount; } }

        public void Debug(string indent = "")
        {
            Console.WriteLine(indent + ":" + this.Value + " - " + Count + " - " + TotalCount);
            if (Left != null)
            {
                Left.Debug(indent + "L");
            }
            if (Right != null)
            {
                Right.Debug(indent + "R");
            }
        }
    }
}

