		public static void Solve(Scanner cin)
		{
			int n = cin.ReadInt();
			var s = cin.ReadIntArray(1 << n);
			var ms = new Set<int>();
			ms.IsMultiSet = true;

			foreach (var e in s)
			{
				ms.Add(e);
			}

			var now = new List<int>();

			int ad = ms.Max();
			now.Add(ad);
			ms.Remove(ad);

			var prev = new List<int>(now);
			bool ok = true;

			for (int i = 0; i < n; i++)
			{
				foreach (var e in prev)
				{
					int x = ms.LowerBound(e);

					if (x <= 0) ok = false;
					else
					{
						now.Add(ms[x - 1]);
						ms.Remove(ms[x - 1]);
					}
				}

				prev = new List<int>(now);
			}

			YesNo(ok);
		}

		public static void Main(string[] args)
		{
			var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
			Console.SetOut(sw);
			var cin = new Scanner();
			Solve(cin);
			Console.Out.Flush();
		}

