		public static int LowerBound<T>(T[] a, T v) where T : IComparable
		{
			var l = 0;
			var r = a.Length - 1;
			while (l <= r)
			{
				var mid = l + (r - l) / 2;
				var res = a[mid].CompareTo(v);
				if (res == -1) l = mid + 1;
				else r = mid - 1;
			}
			return l;
		}

		public static int LowerBound<T>(List<T> a, T v) where T : IComparable
		{
			var l = 0;
			var r = a.Count - 1;
			while (l <= r)
			{
				var mid = l + (r - l) / 2;
				var res = a[mid].CompareTo(v);
				if (res == -1) l = mid + 1;
				else r = mid - 1;
			}
			return l;
		}
	}

