class Program
{
    static void Main()
    {
        var n = ReadInts()[0];
        var vals = ReadInts();
        int cnt = 0;
        var result = Coloc(ref cnt, vals);


        Console.WriteLine(result && cnt == n ? "Yes" : "No");
        Console.ReadLine();
    }

    static bool Coloc(ref int cnt, int[] vals)
    {
        vals = (int[])vals.Clone();
        Array.Sort(vals, IntDisComparetor.Instance);

        var slimes = new List<int>(vals.Length);
        slimes.Add(vals[0]);
        vals[0] = int.MaxValue;
        for (int slimeNum = 1; slimeNum < vals.Length;)
        {
            cnt++;
            var index = 0;
            for (int i = 0; i < slimeNum; i++)
            {
                var item = slimes[i];
                index = Utils.FindFirstIndex(vals, p => p < item, index + 1);
                if (index < 0)
                    return false;

                slimes.Add(vals[index]);
                vals[index] = int.MaxValue;
            }
            slimes.Sort(IntDisComparetor.Instance);
            slimeNum = slimes.Count;
        }
        return true;
    }

    #region Utils
    static int[] ReadInts()
    {
        return Console.ReadLine().Split().Select(int.Parse).ToArray();
    }
    #endregion
}

