{
    public static int FindFirstIndex<T>(IList<T> source, Func<T, bool> func, int start)
    {
        for (int i = start; i < source.Count; i++)
        {
            if (func(source[i]))
            {
                var ret = source[i];
                return i;
            }
        }
        return -1;
    }
}

