public partial class MultiSet<T> : IEnumerable<T>
{
    private readonly Set<Tuple<T, int>> set;
    private int _nonce = 0;
    public MultiSet() : this(Comparer<T>.Default)
    {
    }

    public MultiSet(IComparer<T> comparer)
    {
        set = new Set<Tuple<T, int>>(new TupleComparer(comparer));
    }

    class TupleComparer : IComparer<Tuple<T, int>>
    {
        private readonly IComparer<T> _comparer;
        public TupleComparer(IComparer<T> comparer)
        {
            _comparer = comparer;
        }

        public int Compare(Tuple<T, int> x, Tuple<T, int> y)
        {
            var cmp = _comparer.Compare(x.Item1, y.Item1);
            if (cmp != 0) return cmp;
            return x.Item2.CompareTo(y.Item2);
        }
    }

    public int Count { get { return set.Count; } }

    public int CountOf(T value)
    {
        return IndexOfUpperBound(value) - IndexOfLowerBound(value);
    }

    public void Add(T value)
    {
        set.Add(Tuple.Create(value, _nonce++));
    }

    public T At(int index)
    {
        return set.At(index).Item1;
    }

    public void Remove(T value)
    {
        var index = IndexOfLowerBound(value);
        if (index < set.Count)
        {
            var v = set.At(index);
            if (v.Item1.Equals(value))
            {
                set.Remove(v);
            }
        }
    }

    public int IndexOfLowerBound(T value)
    {
        return set.IndexOfLowerBound(Tuple.Create(value, int.MinValue));
    }

    public int IndexOfUpperBound(T value)
    {
        return set.IndexOfUpperBound(Tuple.Create(value, int.MaxValue));
    }

    public IEnumerator<T> GetEnumerator()
    {
        foreach (var v in set)
        {
            yield return v.Item1;
        }
    }

    IEnumerator IEnumerable.GetEnumerator()
    {
        return GetEnumerator();
    }
}

public partial class Set<T>
{
    private Node root = null;
    private readonly IComparer<T> _comparer;

    public Set() : this(Comparer<T>.Default)
    {
    }

    public Set(IComparer<T> comparer)
    {
        _comparer = comparer;
    }

    virtual protected bool AllowMultiple { get { return true; } }

    public int Count { get { return root == null ? 0 : root.Count; } }

    public bool Contains(T value)
    {
        var node = root;
        while (node != null)
        {
            int cmp = _comparer.Compare(value, node.Value);
            if (cmp == 0)
            {
                return true;
            }
            node = (cmp < 0) ? node.Left : node.Right;
        }
        return false;
    }

    public int IndexOfLowerBound(T value)
    {
        var node = root;
        int index = 0;
        while (node != null)
        {
            int leftCount = node.Left == null ? 0 : node.Left.Count;
            int cmp = _comparer.Compare(value, node.Value);
            if (cmp <= 0)
            {
                node = node.Left;
            }
            else
            {
                index += leftCount + 1;
                node = node.Right;
            }
        }
        return index;
    }

    public int IndexOfUpperBound(T value)
    {
        var node = root;
        int index = 0;
        while (node != null)
        {
            int leftCount = node.Left == null ? 0 : node.Left.Count;
            int cmp = _comparer.Compare(value, node.Value);
            if (cmp < 0)
            {
                node = node.Left;
            }
            else
            {
                index += leftCount + 1;
                node = node.Right;
            }
        }
        return index;
    }

    public T At(int index)
    {
        var node = root;
        while (node != null)
        {
            int leftCount = node.Left == null ? 0 : node.Left.Count;
            if (index == leftCount) return node.Value;
            if (index < leftCount)
            {
                node = node.Left;
            }
            else
            {
                node = node.Right;
                index -= leftCount + 1;
            }
        }
        throw new ArgumentOutOfRangeException("index");
    }

    public void Add(T value)
    {
        root = Add(root, value);
        root.Color = Node.BLACK;
    }

    private Node Add(Node h, T value)
    {
        if (h == null)
        {
            return new Node(value);
        }

        if (IsRed(h.Left) && IsRed(h.Right))
        {
            ColorFlip(h);
        }

        int cmp = _comparer.Compare(value, h.Value);
        if (cmp == 0)
        {
            // do nothing
        }
        else if (cmp < 0)
        {
            h.Left = Add(h.Left, value);
            h.FixCount();
        }
        else
        {
            h.Right = Add(h.Right, value);
            h.FixCount();
        }

        if (IsRed(h.Right) && !IsRed(h.Left))
        {
            h = RotateLeft(h);
        }

        if (IsRed(h.Left) && IsRed(h.Left.Left))
        {
            h = RotateRight(h);
        }

        return h;
    }

    public void RemoveMin()
    {
        root = RemoveMin(root);
        if (root != null)
        {
            root.Color = Node.BLACK;
        }
    }

    private Node RemoveMin(Node h)
    {
        if (h.Left == null)
        {
            return null;
        }

        if (!IsRed(h.Left) && !IsRed(h.Left.Left))
        {
            h = MoveRedLeft(h);
        }

        h.Left = RemoveMin(h.Left);
        h.FixCount();
        return FixUp(h);
    }

    public void Remove(T value)
    {
        root = Remove(root, value);
        if (root != null)
        {
            root.Color = Node.BLACK;
        }
    }

    private Node Remove(Node h, T value)
    {
        if (_comparer.Compare(value, h.Value) < 0)
        {
            if (h.Left == null)
            {
                throw new KeyNotFoundException("value");
            }

            if (!IsRed(h.Left) && !IsRed(h.Left.Left))
            {
                h = MoveRedLeft(h);
            }
            h.Left = Remove(h.Left, value);
            h.FixCount();
        }
        else
        {
            if (IsRed(h.Left))
            {
                h = RotateRight(h);
            }

            if (h.Right == null)
            {
                if (_comparer.Compare(value, h.Value) == 0)
                {
                    return null;
                }

                throw new KeyNotFoundException("value");
            }

            if (!IsRed(h.Right) && !IsRed(h.Right.Left))
            {
                h = MoveRedRight(h);
            }

            if (_comparer.Compare(value, h.Value) == 0)
            {
                h.Value = Min(h.Right).Value;
                h.Right = RemoveMin(h.Right);
                h.FixCount();
            }
            else
            {
                h.Right = Remove(h.Right, value);
                h.FixCount();
            }
        }

        return FixUp(h);
    }

    private static Node MoveRedLeft(Node h)
    {
        ColorFlip(h);

        if (IsRed(h.Right.Left))
        {
            h.Right = RotateRight(h.Right);
            h.FixCount();
            h = RotateLeft(h);
            ColorFlip(h);
        }

        return h;
    }

    private static Node MoveRedRight(Node h)
    {
        ColorFlip(h);

        if (IsRed(h.Left.Left))
        {
            h = RotateRight(h);
            ColorFlip(h);
        }

        return h;
    }

    static private Node RotateLeft(Node h)
    {
        Node x = h.Right;
        h.Right = x.Left;
        x.Left = h;

        x.Color = h.Color;
        h.Color = Node.RED;
        h.FixCount();
        x.FixCount();
        return x;
    }

    private static Node RotateRight(Node h)
    {
        Node x = h.Left;
        h.Left = x.Right;
        x.Right = h;

        x.Color = h.Color;
        h.Color = Node.RED;
        h.FixCount();
        x.FixCount();
        return x;
    }

    private static bool IsRed(Node h)
    {
        return h != null && h.Color == Node.RED;
    }

    static private void ColorFlip(Node h)
    {
        h.Color = !h.Color;
        h.Left.Color = !h.Left.Color;
        h.Right.Color = !h.Right.Color;
    }

    static private Node Min(Node h)
    {
        while (h.Left != null)
        {
            h = h.Left;
        }
        return h;
    }

    static private Node FixUp(Node h)
    {
        if (IsRed(h.Right))
        {
            h = RotateLeft(h);
        }

        if (h.Left != null && IsRed(h.Left) && IsRed(h.Left.Left))
        {
            h = RotateRight(h);
        }

        if (IsRed(h.Left) && IsRed(h.Right))
        {
            ColorFlip(h);
        }
        h.FixCount();
        return h;
    }

    private class Node
    {
        public const bool RED = true;
        public const bool BLACK = false;
        public T Value;
        public bool Color = RED;
        public Node Left = null;
        public Node Right = null;
        public int Count = 1;
        public Node(T value)
        {
            this.Value = value;
        }

        public void FixCount()
        {
            this.Count = 1;
            if (Left != null) Count += Left.Count;
            if (Right != null) Count += Right.Count;
        }
    }
}

public partial class Set<T> : IEnumerable<T>
{
    public IEnumerator<T> GetEnumerator()
    {
        var node = root;
        var stack = new Stack<Node>();
        while (node != null || stack.Count > 0)
        {
            while (node != null)
            {
                stack.Push(node);
                node = node.Left;
            }
            node = stack.Pop();
            yield return node.Value;
            node = node.Right;
        }
    }

    IEnumerator IEnumerable.GetEnumerator()
    {
        return GetEnumerator();
    }
}

