static class CodeJam
{
    static bool Solve(int N, int[] S)
    {
        var days = new int[1 << N];
        Array.Sort(S, (a, b) => b.CompareTo(a));
        int n = 1;
        for (int i = 0; n < S.Length; ++i)
        {
            for (int j = 0; j < N - days[i]; ++j)
            {
                if (S[i] == S[n]) { return false; }
                days[n] = days[i] + j + 1;
                ++n;
            }
        }
        return true;
    }

    static void Main(string[] args)
    {
        int N = int.Parse(Console.ReadLine());
        int[] S = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        Console.WriteLine(Solve(N, S) ? "Yes" : "No");
    }
}

