    private static bool Solve(int n, int[] vals)
    {
        Array.Sort(vals, IntDisComparetor.Instance);
        List<int> slimes = new List<int>();
        slimes.Add(vals[0]);
        vals[0] = int.MaxValue;
        int cnt = 0;
        for(int slimeNum = 1; slimeNum < vals.Length;)
        {
            cnt++;
            int index = 0;
            for(int i = 0; i < slimeNum; i++)
            {
                bool exists = false;
                int item = slimes[i];
                for(int y = index + 1; y < vals.Length; y++)
                {
                    if (vals[y] == int.MaxValue) continue;
                    if(vals[y] < item)
                    {
                        exists = true;
                        slimes.Add(vals[y]);
                        vals[y] = int.MaxValue;
                        break;
                    }
                }
                if (!exists)
                {
                    return false;
                }
            }
            slimes.Sort(IntDisComparetor.Instance);
            slimeNum = slimes.Count;
        }
        return (cnt == n);
    }
}

