public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		var S = GetInts(1 << N);

		Array.Sort(S, (x, y) => y - x);
		var used = S.Take(1).ToList();
		var rest = S.Skip(1).ToList();

		for(int i = 0; i < N; i++)
		{
			rest.Sort((x, y) => y - x);
			used.Sort((x, y) => y - x);

			var nextRest = new List<int>();
			int head = 0;
			int cntRest = rest.Count;
			for(int j = 0; j < (1 << i); j++)
			{
				while(head < cntRest && rest[head] >= used[j])
					nextRest.Add(rest[head++]);

				if(head == cntRest)
				{
					WriteLine("No");
					return;
				}
				used.Add(rest[head++]);
			}
			nextRest.AddRange(rest.Skip(head));
			rest = nextRest;
		}
		WriteLine("Yes");
	}
}

