    class Program
    {
        static void Main(string[] args)
        {
            int second = Int16.Parse(Console.ReadLine())+1;
            double[] slimes = new double[ 18 ];
            double[] tmps   = new double[ second ];
            int tmp = 0;
            bool flag = true;
            double tmp2;

            foreach (string Hp in Regex.Split(Console.ReadLine(), @"\s+"))
            {
                slimes[Int16.Parse(Hp) - 1] += 1;
            }

            foreach(int num in Combination(second))
            {
                tmps[tmp] = num;
                tmp += 1;
            }

            int index = 0;
            for(int i = slimes.Length - 1; i >=0 ; --i)
            {
                tmps[index] -= slimes[i];
                //Console.WriteLine("{0} = {1} - {2}", tmp2, tmps[i], slimes[i]);
                if (tmps[index] < 0)
                {
                    flag = false;
                    break;
                }
                else if(tmps[index]==0)
                {
                    index++;
                }
            }
            Console.WriteLine(flag ? "Yes" : "No");
        }

        public static IEnumerable<double> Combination(int Num)
        {
            double num = Convert.ToDouble(Num);
            double rt_num = 1;
            for(int i=0; i < Num; ++i)
            {
                if (i == 0)
                {
                    yield return 1;
                }
                else
                {
                    rt_num *=(num - i) / i;
                    yield return rt_num;
                }
            }
            yield break;
        }
    }
}

