            とりあえず総エントロピー判定をしてみました。


        */

        Array.Sort(input);
        Array.Reverse(input);
        var goal = input.Length;
        var parentPoint = 0;
        var childrenPoint = 1;

        var remainEntropy = new int[input.Length];
        remainEntropy[parentPoint] = N;
        var totalEnt = N;

        while(true){

            for(int i = remainEntropy[parentPoint]; i > 0; i--){
                if(input[childrenPoint] >= input[parentPoint]){
                    Console.WriteLine("No");
                    return;
                }
                remainEntropy[childrenPoint] = i-1;
                totalEnt += i-1;
                totalEnt--;
                childrenPoint++;
                if(childrenPoint >= goal){
                    if(totalEnt == 0){
                        Console.WriteLine("Yes");
                        return;
                    }else{
                        Console.WriteLine("No");
                        return;
                    }
                }
            }
            remainEntropy[parentPoint] = 0;
            parentPoint++;


        }

    }

