class Program
{
    static void Main()
    {
        int N = Utils.ReadInts()[0];
        int[] S = Utils.ReadInts();

        bool result = Solve(N, S);

        Utils.ReturnYesOrNo(result);
    }

    private static bool Solve(int n, int[] s)
    {
        s = s.OrderByDescending(a => a).ToArray();
        List<int> slimes = new List<int>();
        slimes.Add(s[0]);
        s[0] = int.MaxValue;
        int cnt = 0;
        for(int slimeNum = 1; slimeNum < s.Length;)
        {
            cnt++;
            int index = 0;
            for(int i = 0; i < slimeNum; i++)
            {
                bool exists = false;
                int item = slimes[i];
                for(int y = index + 1; y < s.Length; y++)
                {
                    if (s[y] == int.MaxValue) continue;
                    if(s[y] < item)
                    {
                        exists = true;
                        slimes.Add(s[y]);
                        s[y] = int.MaxValue;
                        break;
                    }
                }
                if (!exists)
                {
                    return false;
                }
            }
            slimes = slimes.OrderByDescending(a => a).ToList();
            slimeNum = slimes.Count;
        }
        return (cnt == n);
    }
}

