                    {
                        Console.WriteLine("No");
                        Console.ReadLine();
                        return;
                    }
                    else
                    {
                        result[1]--;
                        slime.Add(result[0]);
                        if (result[1] == 0)
                        {
                            sDic.RemoveAll(a => a[0] == result[0]);
                        }
                    }
                }
            }
