using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Contest
{
    class Program
    {
        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());
            List<int> S = Console.ReadLine().Split(' ').Select(int.Parse).ToList();
            S = S.OrderByDescending(a => a).ToList();
            List<int> slime = new List<int>();
            slime.Add(S[0]);
            S.RemoveAt(0);
            Dictionary<int, int> sDic = new Dictionary<int, int>();
            foreach(var s in S)
            {
                if (sDic.ContainsKey(s))
                {
                    sDic[s]++;
                }
                else
                {
                    sDic.Add(s, 1);
                }
            }

            for(int i = 0; i < N; i++)
            {
                int cnt = slime.Count;
                for(int j = 0; j < cnt; j++)
                {
                    bool exists = false;
                    foreach(var s in sDic)
                    {
                        if(slime[j] > s.Key && s.Value > 0)
                        {
                            slime.Add(s.Key);
                            sDic[s.Key]--;
                            exists = true;
                            break;
                        }
                    }
                    if (!exists)
                    {
                        Console.WriteLine("No");
                        Console.ReadLine();
                        return;
                    }
                }
            }
            //出力
            bool exists2 = true;
            foreach(var s in sDic)
            {
                if(s.Value > 0)
                {
                    exists2 = false;
                    break;
                }
            }
            if(exists2)
            {
                Console.WriteLine("Yes");
            }
            else
            {
                Console.WriteLine("No");
            }
            Console.ReadLine();
        }
    }
}

