class Solver
{
    Scanner sc = new Scanner();
    //
    public void Solve()
    {
        var N = sc.Int;
        var ss = sc.ArrInt;
        Array.Sort(ss, (a, b) => b - a);
        for(var i = 0; i < N; i++)
        {
            var m = 1 << i;
            for (var j = 0; j < (1 << i); j++)
                if (ss[j] <= ss[j + m])
                    Fail("No");
        }
        WriteLine("Yes");
    }
}


