namespace AtCoder.Contest.F
{
	class Program
	{
		public static void Main(string[] args)
		{
			var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
			Console.SetOut(sw);

			Scanner cin = new Scanner();

			int n = cin.nextInt();
			var s = new List<int>(cin.ArrayInt(1 << n));
			var dic = new SortedDictionary<int, int>();

			foreach (var e in s)
			{
				if (dic.ContainsKey(e)) dic[e]++;
				else dic.Add(e, 1);
			}

			var now = new List<int>();
			var prev = new List<int>();
			int ad = dic.Keys.Max();
			now.Add(ad);
			dic[ad]--;
			if (dic[ad] == 0) dic.Remove(ad);

			prev = new List<int>(now);

			bool ok = true;

			for (int i = 0; i < n; i++)
			{
				foreach (var e in prev)
				{
					ad = dic.Keys.Max();
					if (e <= ad)
					{
						int x = ad;
						int y = dic[ad];

						dic.Remove(ad);
						try
						{
							ad = dic.Keys.Max();
						}
						catch
						{
							ok = false;
						}
						dic.Add(x, y);
					}
					now.Add(ad);
					dic[ad]--;
					if (dic[ad] == 0) dic.Remove(ad);
				}

				prev = new List<int>(now);
			}

			if (ok) Console.WriteLine("Yes");
			else Console.WriteLine("No");

			Console.Out.Flush();
		}
	}

	class Scanner
