namespace AtCorder
{
	public class Program
	{
		static void Main(string[] args)
		{
			Scanner cin = new Scanner();
			int n = cin.Int();
			int n2 = 2 << (n - 1);
			long[] s = new long[n2];
			for (int i = 0; i < n2; i++) {
				s[i] = cin.Long();
			}

			List<long> ps = s.OrderByDescending(x => x).ToList();
			List<long> temp = new List<long>();
			temp.Add(ps[0]);
			ps[0] = 0;
			for (int i = 0; i < n; i++) {
				var temp2 = temp.OrderByDescending(x => x).ToList();
				int cnt = 0;
				int index = 0;
				for (int j = 0; j < n2; j++) {
					if (ps[j] != 0 && ps[j] < temp2[index]) {
						++cnt;
						temp.Add(ps[j]);
						ps[j] = 0;
						index++;
						if (index >= temp2.Count()) {
							break;
						}
					}
				}

				if (cnt != temp2.Count()) {
					Console.WriteLine("No");
					return;
				}
			}

			Console.WriteLine("Yes");
		}
	}

	public class Scanner
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private string[] buf_;
		private int index_;

		public Scanner()
		{
			buf_ = new string[0];
			index_ = 0;
		}

		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = Console.ReadLine();
			while (st == "") {
				st = Console.ReadLine();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int()
		{
			return int.Parse(Next());
		}
		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

		public long Long()
		{
			return long.Parse(Next());
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Long() + add;
			}
			return Array;
		}

		public double Double()
		{
			return double.Parse(Next());
		}

		public double[] ArrayDouble(int N, double add = 0)
		{
			double[] Array = new double[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Double() + add;
			}
			return Array;
		}
	}
