using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Contest
{
    class Program
    {
        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());
            List<int> S = Console.ReadLine().Split(' ').Select(int.Parse).ToList();
            S = S.OrderByDescending(a => a).ToList();

            List<int> slime = new List<int>();
            slime.Add(S[0]);
            S.RemoveAt(0);
            List<int[]> sDic = new List<int[]>();
            foreach(var s in S)
            {
                if(sDic.Exists(a => a[0] == s))
                {
                    sDic.First(a => a[0] == s)[1]++;
                }
                else
                {
                    sDic.Add(new int[] { s, 1 });
                }
            }
            int check = slime.Count;
            for (int i = 0; i < N; i++)
            {
                int add = 0;
                for( int j =0; j < check; j++)
                {
                    add++;
                }
                check += add;
            }
            if(check != S.Count + 1)
            {
                Console.WriteLine("No");
                Console.ReadLine();
                return;
            }
            for (int i = 0; i < N; i++)
            {
                int cnt = slime.Count;
                for(int j = 0; j < cnt; j++)
                {
                    int[] result = sDic.Where(a => slime[j] > a[0] && a[1] > 0).FirstOrDefault();
                    if(result == null)
                    {
                        Console.WriteLine("No");
                        Console.ReadLine();
                        return;
                    }
                    else
                    {
                        result[1]--;
                        slime.Add(result[0]);
                        if (result[1] == 0)
                        {
                            sDic.RemoveAll(a => a[0] == result[0]);
                        }
                    }
                }
            }
            //出力
            if(sDic.Count == 0)
            {
                Console.WriteLine("Yes");
            }
            else
            {
                Console.WriteLine("No");
            }
            Console.ReadLine();
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
