static class CodeJam
{
    static bool Solve(int N, int[] S)
    {
        var days = new int[1 << N];
        Array.Sort(S, (a, b) => b.CompareTo(a));
        int n = 1;
        for (int i = 0; n < S.Length; ++i)
        {
            if (S[i] == S[n]) { return false; }
            for (int j = 0; j < N - days[i]; ++j)
            {
                days[n++] = days[i] + j + 1;
            }
        }
        return true;
    }

    static void Main(string[] args)
