using System;
using System.Linq;
using CompLib.Collections;
using CompLib.Util;

public class Program
{
    private int N;
    private int[] S;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        S = sc.IntArray();

        var map = new HashMap<int, int>();
        foreach (int i in S)
        {
            map[i]++;
        }

        var ar = map.ToArray();
        Array.Sort(ar, (l, r) => r.Key.CompareTo(l.Key));

        var size = new int[N + 1];
        size[N] = 1;

        foreach (var pair in ar)
        {
            int tmp = pair.Value;
            var next = new int[N + 1];
            for (int i = N; i >= 0 && tmp > 0; i--)
            {
                int min = Math.Min(tmp, size[i]);
                size[i] -= min;
                tmp -= min;
                for (int j = i - 1; j >= 0; j--)
                {
                    next[j] += min;
                }
            }

            if (tmp != 0)
            {
                Console.WriteLine("No");
                return;
            }

            for (int i = 0; i <= N; i++)
            {
                size[i] += next[i];
            }
        }

        Console.WriteLine("Yes");
    }

    public static void Main(string[] args) => new Program().Solve();
}

