namespace I_am_the_green_coder{
    class Inonoa{
        static void Main(){
            long n = ILongs()[0];
            long[] s = ILongs();
            long len = MathPow(2,n);

            Array.Sort(s);
            if(s[len-1]==s[len-2]){
                WriteLine("No");
                return;
            }
            for(int i=0;i<n-1;i++){
                for(long j=MathPow(2,i);j<MathPow(2,i+1);j++){
                    if(s[len-1-j]==s[len-1-j-MathPow(2,i+1)]){
                        WriteLine("No");
                        return;
                    }
                }
            }
            WriteLine("Yes");
        }

        static long MathPow(long m, long n){
            long re = 1;
            for(int i=0;i<n;i++){
                re *= m;
            }
            return re;
        }

        static readonly long MOD = 1000000007;

        ///<summary>a_1, a_2, a_3, ...みたいなの</summary>
        static long[] ILongs(){
            string[] s = ReadLine().Split();
            long[] re = new long[s.Length];
            for(long i=0;i<s.Length;i++){
                re[i] = long.Parse(s[i]);
            }
            return re;
        }

        ///<summary>xooxoxoxxoxo...みたいなの</summary>
        static char[] IChars(){
            return ReadLine().ToCharArray();
        }

        ///<summary>n m とかをちょっとはやくかくだけ</summary>
        static string[] IStrings(){
            return ReadLine().Split();
        }

        ///<summary>n行の入力を取ったり</summary>
        static long[][] ILongLongs(long n){
            long[][] re = new long[n][];
            for(long i=0;i<n;i++){
                string[] s = ReadLine().Split();
                re[i] = new long[s.Length];
                for(long j=0;j<s.Length;j++){
                    re[i][j] = long.Parse(s[j]);
                }
            }
            return re;
        }

