using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        var n = ReadInts()[0];
        var vals = ReadInts();
        var result = Coloc(n, vals);


        Console.WriteLine(result ? "Yes": "No");
    }

    static bool Coloc(int n, int[] vals)
    {
        Array.Sort(vals);
        Array.Reverse(vals);

        for (int slimeNum = 1; slimeNum < vals.Length; slimeNum <<= 1)
        {
            var sl = vals.SubArray(0, slimeNum);
            var left = vals.SubArray(slimeNum, slimeNum);
            if (sl.Zip(left, (s, l) => s > l).Any(p => !p))
                return false;
        }
        return true;
    }

    #region Utils
    static int[] ReadInts()
    {
        return Console.ReadLine().Split().Select(int.Parse).ToArray();
    }
    #endregion
}

