var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  buffer := make([]byte, 0)
  for true {
    line, isPrefix, err := reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func NextInt() int {
  n, _ := strconv.Atoi(NextLine())
  return n
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func Output() {
  _ = writer.Flush()
}

type Item struct {
  Priority int
  Entry interface{}
}
type Heap []*Item
func (H Heap) Len() int { return len(H) }
func (H Heap) Less(i, j int) bool { return H[i].Priority < H[j].Priority }
func (H Heap) Swap(i, j int) { H[i], H[j] = H[j], H[i] }
func (H *Heap) Pop() interface{} {
  Old := *H
  n := len(Old)
  item := Old[n - 1]
  *H = Old[0:n - 1]
  return item
}
func (H *Heap) Push(x interface{}) {
  item := x.(*Item)
  *H = append(*H, item)
}
type PriorityQueue struct {
  Comparator func(e interface{}) int
  Items Heap
}
func (PQ *PriorityQueue) Push(e interface{}) {
  item := Item{PQ.Comparator(e), e}
  heap.Push(&PQ.Items, &item)
}
func (PQ *PriorityQueue) Pop() interface{} {
  return heap.Pop(&PQ.Items).(*Item).Entry
}
func InitPQ(F func(interface{}) int) PriorityQueue {
  var H Heap
  return PriorityQueue{F, H}
}

func SearchIndex(S *[]int, s int) int {
  N := len((*S))
  if (*S)[0] < s { return 0 }
  if s <= (*S)[N - 1] { return -1 }
  low, high := 0, N - 1
  for 1 < high - low {
    med := (high + low) / 2
    if (*S)[med] < s {
      high = med
    } else {
      low = med
    }
  }
  return high
}

func main() {
  N := NextInt()
  S := NextIntVec()
  sort.Sort(sort.Reverse(sort.IntSlice(S)))
  F := func(e interface{}) int { return e.(int) }
  PQ := InitPQ(F)
  PQ.Push(S[0])
  S = S[1:]
  ans := "Yes"
  for i := 0; i < N; i++ {
    _PQ := InitPQ(F)
    for 0 < len(PQ.Items) {
      p := PQ.Pop().(int)
      idx := SearchIndex(&S, p)
      if idx < 0 {
        ans = "No"
        break
      }
      s := S[idx]
      S = append(S[:idx], S[idx + 1:]...)
      _PQ.Push(p)
      _PQ.Push(s)
    }
    PQ = _PQ
  }
  Write(ans)
  Output()
}

