// Point ...
type Point struct {
	x, y float64
}

func (p Point) cross(other *Point) float64 {
	return p.x*other.y - p.y*other.x
}

func (p Point) orthant() int {
	if p.x > 0 && p.y >= 0 {
		return 1
	}
	if p.x <= 0 && p.y > 0 {
		return 2
	}
	if p.x < 0 && p.y <= 0 {
		return 3
	}
	return 4
}

func (p Point) compare(other Point) bool {
	if p.orthant() == other.orthant() {
		switch p.orthant() {
		case 1:
			return p.cross(&other) <= 0
		case 2:
			return p.cross(&other) <= 0
		}
		return p.cross(&other) >= 0
	}
	return p.orthant() < other.orthant()
}

type PP []Point

func (a PP) Len() int           { return len(a) }
func (a PP) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a PP) Less(i, j int) bool { return a[i].compare(a[j]) }

