func Search(A *[]int, b int) int {
  N := len((*A))
  if (*A)[0] == b { return 0 }
  if (*A)[N - 1] == b { return N - 1 }
  high, low := N - 1, 0
  for high - low > 1 {
    med := (high - low) / 2
    if (*A)[med] == b { return med }
    if (*A)[med] < b {
      low = med
    } else {
      high = med
    }
  }
  return -1
}

