func pascal(n int) [][]int {
	p := make([][]int, n+1)

	for i := 0; i < n+1; i++ {
		p[i] = make([]int, n+1)
	}

	p[0][0] = 1
	for i := 1; i < n+1; i++ {
		for ii := 0; ii <= i; ii++ {
			if ii > 0 {
				p[i][ii] += p[i-1][ii-1]
			}
			if ii < i {
				p[i][ii] += p[i-1][ii]
			}
		}
	}

	return p
}

