    cnt := 1
    for S[i] == S[i + 1] {
      cnt++
      i++
    }
    if len(PQ.Items) < cnt {
      ans = "No"
      break
    }
    CC := make([]int, cnt)
    for j := range CC {
      CC[j] = PQ.Pop().(int)
    }
    for _, cc := range CC {
      for 1 < cc {
        cc /= 2
        PQ.Push(cc)
      }
    }
  }
  Write(ans)
  Output()
}

