		f := make([]bool, c)
		for {
			for l < c && f[l] {
				l++
			}
			if l == c {
				break
			}
			f[l] = true
			for r < c && (f[r] || s[l] == s[r]) {
				r++
			}
			if r == c {
				break
			}
			f[r] = true
			t = append(t, s[r])
			// debug(c, s[l], s[r])
		}
		if len(t) != c/2 {
			fmt.Fprintln(wr, "No")
			return
		}
		s = t
		// debug(s)
	}
	fmt.Fprintln(wr, "Yes")

}

func pow(a, n int) int {
	res := 1
	for n > 0 {
		if n&1 == 1 {
			res *= a
		}
		a *= a
		n >>= 1
	}
	return res
}

