class Slime {
  private children: Slime[] | null = null;
  constructor(
    public value: number,
    private numChildren: number,
    private remains: number[]
  ) {}

  getTerminalChildren(slime: Slime, acc: Slime[]): Slime[] {
    if (slime.children == null) {
      return acc.concat(slime);
    } else {
      return slime.children.reduce(
        (prev, child) => child.getTerminalChildren(child, prev),
        acc
      );
    }
  }

  makeChildren() {
    if (this.children == null && this.numChildren > 0) {
      this.children = [];
      for (let i = 0; i < this.numChildren; ++i) {
        const value = this.remains.pop()!;
        if (value < this.value) {
          const child = new Slime(
            value,
            this.numChildren - i - 1,
            this.remains
          );
          this.children.push(child);
        } else {
          ANS = "No";
        }
      }
    }
  }
}
