proc solve(N:int, P:seq[int]) =
  var v = newSeq[(int,int)]()
  for i in 0..<N:
    v.add((P[i],i))
  v.sort(cmp[(int,int)])
  v.reverse()
  var rbt = initSet[int]()
  var ans = 0
  for p in v:
    let i = p[1]
    var t = rbt.lowerBound(i)
    if rbt.len > 0:
      if t != rbt.`end`():
        var
          u = t
          v = t
          left = -1
          right = N
        --(u);++(v)
        if u != rbt.`end`(): left = *u
        if v != rbt.`end`(): right = *v
        ans += (right - *t) * (i - left) * p[0]
      --(t)
      if t != rbt.`end`():
        var
          u = t
          v = t
          left = -1
          right = N
        --(u);++(v)
        if u != rbt.`end`(): left = *u
        if v != rbt.`end`(): right = *v
        ans += (*t - left) * (right - i) * p[0]
    rbt.insert(i)
  echo ans

