const FU64Bit = false
when FU64Bit: # 範囲が1e9以内ならfalse (ほんのり速い)
  const FUBit = 4
  const FUMaxBit = 64
  const FUOffset = 1u shl 62
else: # 1073741824 == 1u shl 30 ≒ 1e9 より、 32bitあれば十分
  const FUBit = 6
  const FUMaxBit = 36
  const FUOffset = 0 # 1e9.uint + 10
# uint32(4Byte)の個数. 100MBくらい.
const poolMaxNum = 300_000_000u div ((1u shl FUBit) + 2u)
var npool : array[poolMaxNum shl FUBit,uint32] # count or child
var spool : array[poolMaxNum,uint] # S
var poolHead = 1.uint32
const NilIndex = 0
type FUSet = ref object
  root : uint32
  multi: bool
  size : uint
proc countLeadingZeroBits(x: culonglong): cint {.importc: "__builtin_clzll", cdecl.}
proc countTrailingZeroBits(x: culonglong): cint {.importc: "__builtin_ctzll", cdecl.}
proc newFUNode():uint32 =
  result = poolHead
  poolHead += 1
proc getH(x:uint,r:uint):uint{.inline.} = (x shr (r - FUBit)) and ((1u shl FUBit) - 1)
proc maxBit(x:uint):uint {.inline.}= 63.uint - cast[culonglong](x).countLeadingZeroBits().uint
proc minBit(x:uint):uint {.inline.}= cast[culonglong](x).countTrailingZeroBits().uint
proc child(x:uint32,i:uint):var uint32 {.inline.} = npool[(x shl FUBit).uint + i]
proc add(self:uint32,x:uint,r:uint,multi:bool = true) : bool =
  let h = x.getH(r)
  spool[self] = spool[self] or (1u shl h)
  if r <= FUBit : # 最下層
    result = multi or self.child(h) == 0
    if multi: self.child(h) += 1
    else: self.child(h) = 1
    return
  if self.child(h) == NilIndex:
    self.child(h) = newFUNode()
  return self.child(h).add(x,r - FUBit,multi)
proc find(self:uint32,x:uint,r:uint) : bool =
  let h = x.getH(r)
  if (spool[self] and (1u shl h)) == 0 : return false
  if r <= FUBit: return true
  return self.child(h).find(x,r-FUBit)
proc del(self:uint32,x:uint,r:uint) : bool =
  let h = x.getH(r)
  if (spool[self] and (1u shl h)) == 0 : return false
  if r <= FUBit:  # 最下層
    self.child(h) -= 1
    result = self.child(h) == 0
    if result:
      spool[self] = spool[self] and not (1u shl h)
  else:
    result = self.child(h).del(x,r-FUBit)
    if spool[self.child(h)] == 0:
      spool[self] = spool[self] and not (1u shl h)
proc min(self:uint32,r:uint) : uint =
  let h = spool[self].minBit()
  if r <= FUBit: return h
  return (h shl (r - FUBit)) + self.child(h).min(r-FUBit)
proc max(self:uint32,r:uint) : uint =
  let h = spool[self].maxBit()
  if r <= FUBit: return h
  return (h shl (r - FUBit)) + self.child(h).max(r-FUBit)
proc findGreater(self:uint32,x:uint,r:uint,including:bool,sameH:bool=true) : tuple[ok:bool,v:uint] =
  var h = if sameH : x.getH(r) else: spool[self].minBit()
  var S = if sameH : spool[self] and not ((1u shl h) - 1) else: spool[self]
  var i = h
  while S > 0u:
    defer:
      S = S and (not (1u shl i))
      if S > 0u: i = S.minBit()
    if (spool[self] and (1u shl i)) == 0 : continue
    if r <= FUBit:
      if sameH and not including and i == h: continue
      return (true,i)
    let (ok,v) = self.child(i).findGreater(x,r-FUBit,including,sameH and i == h)
    if ok: return (true, (i shl (r - FUBit)) + v)
  return (false,0u)
proc findLess(self:uint32,x:uint,r:uint,including:bool,sameH:bool=true) : tuple[ok:bool,v:uint] =
  var h = if sameH : x.getH(r) else: spool[self].maxBit()
  var S = if sameH : spool[self] and ((2u shl h) - 1) else: spool[self]
  var i = h
  while S > 0u:
    defer:
      S = S and (not (1u shl i))
      if S > 0u: i = S.maxBit()
    if (spool[self] and (1u shl i)) == 0 : continue
    if r <= FUBit:
      if sameH and not including and i == h: continue
      return (true,i)
    let (ok,v) = self.child(i).findLess(x,r-FUBit,including,sameH and i == h)
    if ok: return (true, (i shl (r - FUBit)) + v)
  return (false,0u)
