proc newFUSet*(multi:bool):FUSet =
  new(result)
  result.root = newFUNode()
  result.multi = multi
  result.size = 0
proc add*(self:FUSet,x:uint) =
  let ok = self.root.add(x + FUOffset,FUMaxBit,self.multi)
