proc contains*(self:FUSet,x:uint) : bool =
  self.root.find(x + FUOffset,FUMaxBit)
proc del*(self:FUSet,x:uint) =
  let ok = self.root.del(x + FUOffset,FUMaxBit)
  if ok: self.size -= 1
