proc max*(self:FUSet):uint =
  self.root.max(FUMaxBit) - FUOffset
proc findLess*(self:FUSet,x:uint,including:bool): tuple[ok:bool,v:uint] =
  let (ok,v) = self.root.findLess(x + FUOffset,FUMaxBit,including)
  if not ok: return (false,0u)
  return (true,v - FUOffset)
proc findGreater*(self:FUSet,x:uint,including:bool): tuple[ok:bool,v:uint] =
  let (ok,v) = self.root.findGreater(x + FUOffset,FUMaxBit,including)
  if not ok: return (false,0u)
  return (true,v - FUOffset)

