    if self.sameCount > 1:
      self.sameCount -= 1
      self.update()
    else:
      self = self.left.mergeImpl(self.right)
    return true
  if key < self.key:
    if self.left == nil : return false
    result = self.left.erase(key)
    self.update()
  else:
    if self.right == nil : return false
    result = self.right.erase(key)
    self.update()
