    var chunks = newSeq[Rbst[T]]() # 親
    while rbsts.len > 0:
      let now = rbsts.pop()
      if now == nil : continue
      if now.right != nil:
        rbsts.add now.right
      if (including and now.key >= key) or (not including and now.key > key):
        if now.left != nil:
          rbsts.add now.left
