  if key < self.key:
    if self.left == nil : return -1.. -1
    return self.left.isKth(key)
  if self.right == nil : return -1.. -1
  let llen = self.left.len + self.sameCount
  let r = self.right.isKth(key)
  return llen+r.a..llen+r.b
