const poolMaxNum = 100_000_000 div ((1 shl FUBit) + 2)
var npool : array[poolMaxNum shl FUBit,int32] # count or child
var spool : array[poolMaxNum,int] # S
var poolHead = 1.int32
const NilIndex = 0
