  let h = x.getH(r)
  if (spool[self] and (1 shl h)) == 0 : return false
  if r <= FUBit:  # 最下層
    self.child(h) -= 1
    result = self.child(h) == 0
    if result:
      spool[self] = spool[self] and not (1 shl h)
