from heapq import heapify, heappush, heappop


class BIT:
    def __init__(self, N):
        self.size = N
        self.tree = [0] * (N + 1)

    def sum(self, i):
        s = 0
        while i > 0:
            s += self.tree[i]
            i -= i & -i
        return s

    def add(self, i, x):
        while i <= self.size:
            self.tree[i] += x
            i += i & -i

    def __str__(self):
        return "BIT: [{}]".format(
            ", ".join(str(self.sum(i + 1) - self.sum(i))
                      for i in range(self.size))
        )

    def bisect_left(self, r):
        bit = self.tree
        if r == 0:
            return 0
        l = 1 << (r.bit_length() - 1)
        k = l // 2
        while r - l > 1:
            if bit[r] > bit[l]:
                l += k
            else:
                r = l
                l //= 2
            k //= 2
        return r if bit[r] > bit[l] else l


