def do(n,fathers):

    if n == N:
        return

    sons = list()
    for father in fathers:
        son = a.pop(bisect.bisect_left(a,father)-1)

        if son >= father:
            return
        else:
            sons.append(son)

    fathers.extend(sons)
    do(n+1,fathers)



