    def update(s, node=0):
        # 最下層まで探索が進んだ場合
        if 2**N - 1 <= node:
            return False
        left, right = 2*node + 1, 2*node + 2
        # 子の値が定義済の場合
        if tree[left] != 0 and tree[right] != 0:
            if s < tree[right]:
                if update(s, right):
                    return True
                else:
                    return update(s, left)
            else:
                return update(s, left)            
        # 子の値が未定義の場合
        else:
            if s >= tree[node]:
                return False
            else:
                tree[left] = tree[node]
                tree[right] = s
                return True

    for s in S[1:]:
        if not update(s):
            print('No')
            return

