  def __init__(self, val):
    self.child = []
    self.value = val

  def birth(self, score):
    if len(score) == 0:
      return True

    tmp = len(score)-1
    while self.value < score[tmp] and tmp>=0:
      tmp -= 1
    if tmp < 0:
      return False


    if self.value > score[tmp]:
      new_val = score.pop(tmp)
      self.child.append(Node(new_val))
    if len(self.child) > 0:
      for it in self.child[:-1]:
        it.birth(score)


