from collections import Counter


class PascalsTriangle:
    def __init__(self, N):
        self.N = N
        self._build()

    def __call__(self, n, r):
        if n > self.N:
            raise "INVALID INPUT: input n must be smaller than N"
        if r < 0 or r > self.N:
            return 0
        return self.nCr[n][r]

    def _build(self):
        tmp = [(1,)]
        for i in range(1, self.N + 1):
            nCi = tuple(1 if j in (0, i)
                        else tmp[-1][j-1] + tmp[-1][j] for j in range(i+1))
            tmp.append(nCi)
        self.nCr = tuple(tmp)


nCr = PascalsTriangle(20)


