use std::io::Read;
use std::str::SplitWhitespace;
use std::str::FromStr;

pub fn read_stdin() -> String {
    let mut s = String::new();
    ::std::io::stdin().read_to_string(&mut s).unwrap();
    s
}

pub trait Parse<T> {
    fn parse(&mut self) -> T;
}

impl<'a, T> Parse<T> for SplitWhitespace<'a>
where
    T: FromStr,
{
    fn parse(&mut self) -> T {
        let word = self.next().unwrap();
        word.parse().ok().unwrap()
    }
}

fn main() {
    let source = read_stdin();
    let mut iter = source.split_whitespace();
    let n: usize = iter.parse();
    let size = 2_u32.pow(n as u32) as usize;
    let mut v: Vec<u32> = (0..size).map(|_| iter.parse()).collect();
    v.sort();

    let last = v.len() - 1;
    let mut ss = Vec::with_capacity(size);
    ss.push(v[last]);
    v.remove(last);

    for i in 0..n {
        let s = 2_u32.pow(i as u32) as usize;
        for j in 0..s {
            if let Some(index) = v.iter().rposition(|&x| x < ss[j]) {
                ss.push(v[index]);
                v.remove(index);
            } else {
                println!("No");
                return;
            }
        }
    }

    println!("Yes");
}

