pub trait Parse<T> {
    fn parse(&mut self) -> T;
}

impl<'a, T> Parse<T> for SplitWhitespace<'a>
where
    T: FromStr,
{
    fn parse(&mut self) -> T {
        let word = self.next().unwrap();
        word.parse().ok().unwrap()
    }
}

fn main() {
    let source = read_stdin();
    let mut iter = source.split_whitespace();
    let n: usize = iter.parse();
    let size = 2_u32.pow(n as u32) as usize;
    let mut v: Vec<u32> = (0..size).map(|_| iter.parse()).collect();
    v.sort_by(|a, b| b.cmp(a));

    let mut dp = Vec::with_capacity(size);
    dp.push(v[0]);

    for i in 0..n {
        let s = 2_u32.pow(i as u32) as usize;
        for j in 0..s {
            if dp[j] > v[s + j] {
                dp.push(v[s + j]);
            } else {
                println!("No");
                return;
            }
        }
    }

    println!("Yes");
}

