fn solve(n: usize, mut a: Vec<i64>) -> bool {
    let m = a.len();
    a.sort();
    a.reverse();

    let INF = 100;
    let mut set = Treap::new();
    for i in 1..m {
        set.push((a[i], m-i)); // reverse 2nd index order to take from left
    }

    let m = a.len();
    let mut gen = vec![INF; m];
    gen[0] = 0;
    for i in 0..m {
        if gen[i] == INF {
            return false;
        }
        // debug!(i, a[i], gen[i]);
        for g in gen[i]+1..n+1 {
            if let Some((nu, idx)) = set.peek_less((a[i], 0)) {
                gen[m-idx] = g;
                set.remove((nu, idx));
                // debug!("set", idx, m-idx, g);
            } else {
                return false;
            }
        }
    }
    true
}

fn main() {
    input! {
        n: usize,
        a: [i64; 1<<n]
    };
    println!("{}", ifv!(solve(n, a), "Yes", "No"));
}

