fn vec<T, F: FnMut(usize) -> T>(n: usize, mut f: F) -> Vec<T> {
    (0..n).map(|i| f(i)).collect()
}

fn main() {
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let n: usize = scan(tokens);
    let size: usize = 1 << n;
    let mut s: Vec<usize> = vec(size, |_| scan(tokens));
    s.sort();
    s.reverse();
    for i in 0..n {
        let bit = 1 << i;
        for j in 0..bit {
            let mut k = j + bit;
            while k < size && {
                s.swap(j + bit, k);
                s[j] <= s[j + bit]
            } {
                k += 1;
            }
            if k == size {
                println!("No");
                return;
            }
        }
    }
    println!("Yes");
}

