fn main() {
    readls!(n = usize, mut ss = Vec<u32>);
    ss.sort_desc();
    let mut rests: Vec<_> = ss.into_iter().map(|s| Some(s)).collect();
    let mut borns = vec![rests[0].unwrap()];
    rests[0] = None;

    for _ in 0..n {
        borns.sort_desc();
        let prev_len = borns.len();
        let mut born_count = 0;

        for s in &mut rests {
            if born_count == prev_len {
                break;
            }

            if let Some(val) = s.clone() {
                if val < borns[born_count] {
                    borns.push(val);
                    *s = None;
                    born_count += 1;
                }
            }
        }

        if born_count < prev_len {
            println!("No");
            return;
        }
    }

    println!("Yes");
}

