    let mut a = read_vec::<i64>();
    let n2 = 1 << n;
    a.sort();
    let mut s = vec![];
    s.push(a[a.len() - 1]);
    let idx = a.len() - 1;
    a[idx] = -1;
    for i in 0..n {
        let mut p = s.clone();
        p.sort();
        let mut ai = (1 << n) - 1;
        while p.len() > 0 {
            if a[ai] == -1 {
                if ai == 0 {
                    break;
                }
                ai -= 1;
                continue;
            }
            if a[ai] < *p.last().unwrap() {
