use std::collections::VecDeque;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let mut v: Vec<u64> = sc.vec(1 << n);
    v.sort();

    let mut graph = vec![vec![]];
    for _ in 0..n {
        let s = graph.len();
        for i in 0..s {
            graph[i].push(s + i);
        }
        for _ in 0..s {
            graph.push(Vec::new());
        }
    }
    let mut depth = vec![0; graph.len()];
    depth[0] = 1;
    let mut q = VecDeque::new();
    q.push_back(0);
    while let Some(v) = q.pop_front() {
        for &next in graph[v].iter() {
            depth[next] = depth[v] + 1;
            q.push_back(next);
        }
    }

    let mut t = (0..graph.len())
        .map(|i| (depth[i], -(i as i64)))
        .collect::<Vec<_>>();
    t.sort();
    let mut cur = 0;
    let mut ans = vec![0; graph.len()];
    for (_, i) in t.into_iter().rev() {
        //        eprintln!(
        //            "i={} cur={} v={:?} graph={:?} depth={:?}",
        //            i, cur, v, graph, depth
        //        );
        ans[i] = v[cur];
        for &next in graph[i].iter() {
            assert_ne!(ans[next], 0);
            if ans[next] >= ans[i] {
                println!("No");
                return;
            }
        }
        cur += 1;
    }
    println!("Yes");
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

