    input
}

fn scan<'a, I: Iterator<Item = &'a str>, T: std::str::FromStr>(tokens: &mut I) -> T {
    tokens.next().unwrap().parse().ok().unwrap()
}

fn main() {
    use std::collections::BTreeMap;
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let n: usize = scan(tokens);
    let mut c = BTreeMap::new();
    for _ in 0..1 << n {
        let s: usize = scan(tokens);
        *c.entry(s).or_insert(0) += 1;
    }
    let mut q: Vec<usize> = vec![0; n + 1];
    let mut p: Vec<usize> = vec![0; n + 1];
    q[n] = 1;
    for &k in c.values().rev() {
        let mut k = k;
        for i in (0..n + 1).rev() {
            if k <= q[i] {
                p[i] = k;
                q[i] -= k;
                k = 0;
            } else {
                k -= q[i];
                p[i] = q[i];
                q[i] = 0;
            }
        }
        if k > 0 {
            println!("No");
            return;
        }
        let mut cumsum = 0;
        for i in (0..n + 1).rev() {
            q[i] += cumsum;
            cumsum += p[i];
        }
    }
    println!("Yes");
}

