fn main() {
    let source = read_stdin();
    let mut iter = source.split_whitespace();
    let n: usize = iter.parse();
    let size = 2_u32.pow(n as u32) as usize;
    let mut v: Vec<u32> = (0..size).map(|_| iter.parse()).collect();
    v.sort();

    let last = v.len() - 1;
    let mut dp = vec![vec![(0_u32, 0_usize); size + 1]; n + 1];
    dp[0][0] = (v[last], n);
    v.remove(last);

    let mut count = vec![0_usize; n + 1];
    count[0] = 1;
    for i in 0..n {
        for j in 0..count[i] {
            for k in 0..dp[i][j].1 {
                if let Some(index) = v.iter().rposition(|&x| x < dp[i][j].0) {
                    dp[i + 1][count[i + 1]] = (v[index], dp[i][j].1 - 1 - k);
                    v.remove(index);
                    count[i + 1] += 1;
                } else {
                    println!("No");
                    return;
                }
            }
        }
    }

    println!("Yes");
}

