        for i in (1..(n + 1)).rev() {
            if h[i].is_empty() {
                continue;
            }
            let v = h[i].pop().unwrap();
            if v > *s {
                h[i - 1].push(v);
                h[i - 1].push(*s);
                ok = true;
                break;
            } else {
                h[i].push(v);
            }
        }
        if !ok {
