fn binary_search_position(v: &[u32], x: u32) -> usize {
    let len = v.len();
    if len == 1 {
        return 0;
    }
    let i = len / 2;
    if x < v[i] {
        binary_search_position(&v[..i], x)
    } else {
        binary_search_position(&v[i..], x) + i
    }
}

