fn solve(n: usize, mut a: Vec<i64>) -> bool {
    let m = a.len();
    a.sort();
    a.reverse();

    let INF = 100;
    let mut set = Treap::new();
    for i in 1..m {
        set.push((a[i], i));
    }

    let m = a.len();
    let mut gen = vec![INF; m];
    gen[0] = 0;

    let mut level = BinaryHeap::new();
    level.push((a[0], 0));
    for lv in 0..n {
        let mut next_level = BinaryHeap::new();
        while let Some((ai, i)) = level.pop() {
            // debug!(lv, ai, i);
            if let Some((nu, idx)) = set.peek_less((ai, 0)) {
                assert_eq!(gen[idx], INF);
                gen[idx] = lv+1;
                gen[i] = lv+1;
                set.remove((nu, idx));
                next_level.push((ai, i));
                next_level.push((nu, idx));
            } else {
                // debug!("not found", lv, ai, i);
                return false;
            }
        }
        level = next_level;
    }

    for i in 0..m {
        if gen[i] != n {
            return false;
        }
    }
    true
}

fn main() {
    input! {
        n: usize,
        a: [i64; 1<<n]
    };
    println!("{}", ifv!(solve(n, a), "Yes", "No"));
}

