fn solve() {

    input!{
        n:usize,
        s:[i64;1<<n],
    }
    let mut s = s; s.sort(); s.reverse();
    let smax = vec_max(&s);
    let mut cmp = vec![];
    let mut k = 1;
    let mut cur = smax;
    while cmp.len() < (1<<(n-1)) {
        for _ in 0..k {
            cmp.push(cur);
        }
        cur -= 1;
        k <<= 1;
    }
    cmp.push(cur);

    let mut ok = true;
    for i in 0..1<<n {
        if !(s[i]<=cmp[i]) {
            ok = false;
        }
    }
    if ok {
        println!("Yes");
    } else {
        println!("No");
    }
}
fn vec_max<T: Ord + Clone>(xs: &[T]) -> T {
    let mut v = &xs[0];
    for x in xs {
        if x > v {
            v = x;
        }
    }
    v.clone()
}

