fn solve(last: u32, rest: &mut Vec<u32>, n: usize) -> bool {
    if n == 0 { true } else {
        let mut children = Vec::new();
        for _ in 0..n {
            let child = rest.pop().unwrap();
            if child >= last {
                return false;
            }
            children.push(child);
        }
        (1..).zip(children).all(|(i, child)| solve(child, rest, n-i))
    }
}

