fn main() {
    let source = read_stdin();
    let mut iter = source.split_whitespace();
    let n: usize = iter.parse();
    let size = 2_u32.pow(n as u32) as usize;
    let mut v: Vec<u32> = (0..size).map(|_| iter.parse()).collect();
    v.sort();

    let last = v.len() - 1;
    let mut dp = vec![vec![(0_u32, 0_usize); n + 1]; n + 1];
    dp[0][0] = (v[last], n);
