        for j in 0..count[i] {
            for k in 0..dp[i][j].1 {
                if let Some(index) = v.iter().rposition(|&x| x < dp[i][j].0) {
                    dp[i + 1][count[i + 1]] = (v[index], dp[i][j].1 - 1 - k);
                    v.remove(index);
                    count[i + 1] += 1;
                } else {
                    println!("No");
                    return;
                }
            }
        }
    }

    println!("Yes");
}

use std::collections::VecDeque;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let mut v: Vec<u64> = sc.vec(1 << n);
    v.sort();

    let mut graph = vec![vec![]];
    for _ in 0..n {
        let s = graph.len();
        for i in 0..s {
            graph[i].push(s + i);
        }
        for _ in 0..s {
            graph.push(Vec::new());
        }
    }
    let mut depth = vec![0; graph.len()];
    depth[0] = 1;
    let mut q = VecDeque::new();
    q.push_back(0);
    while let Some(v) = q.pop_front() {
        for &next in graph[v].iter() {
            depth[next] = depth[v] + 1;
            q.push_back(next);
        }
    }

    let mut t = (0..graph.len())
        .map(|i| (depth[i], -(i as i64), i))
        .collect::<Vec<_>>();
    t.sort();
    let mut cur = 0;
    let mut ans = vec![0; graph.len()];
    for (_, _, i) in t.into_iter().rev() {
        //        eprintln!(
        //            "i={} cur={} v={:?} graph={:?} depth={:?}",
        //            i, cur, v, graph, depth
        //        );
        ans[i] = v[cur];
        for &next in graph[i].iter() {
            assert_ne!(ans[next], 0);
            if ans[next] >= ans[i] {
                println!("No");
                return;
            }
        }
        cur += 1;
    }
    println!("Yes");
}

