struct Comb {
    fac: Vec<u64>,
    finv: Vec<u64>,
    inv: Vec<u64>,
    m: u64,
}

impl Comb {
    fn new(n: usize, m: u64) -> Comb {
        let mut fac = vec![0u64; n];
        let mut finv = vec![0u64; n];
        let mut inv = vec![0u64; n];

        fac[0] = 1;
        fac[1] = 1;
        finv[0] = 1;
        finv[1] = 1;
        inv[1] = 1;

        for i in 2..n {
            fac[i] = fac[(i - 1) as usize] * i as u64 % m;
            inv[i] = m - inv[(m % i as u64) as usize] * (m / i as u64) % m;
            finv[i] = finv[(i - 1) as usize] * inv[i] % m;
        }
        Comb {
            fac: fac,
            finv: finv,
            inv: inv,
            m: m,
        }
    }
    fn calc(&self, n: usize, k: usize) -> u64 {
        if n < k {
            return 0;
        }

        return self.fac[n] * (self.finv[k] * self.finv[n - k] % self.m) % self.m;
    }
}

const MOD: u64 = 1_000_000_000 + 7;
fn main() {
    input! {
        n: usize,
        s: [usize; 2i32.pow(n as u32)],
    }
    let mut dict = HashMap::new();
    for &s_ in &s {
        *dict.entry(s_).or_insert(0) += 1;
    }
    let mut v = vec![];
    for (k_, v_) in dict {
        v.push((k_, v_));
    }
    v.sort();
    v.reverse();

    let comb = Comb::new(n + 2, MOD);

    let mut ans = "Yes";
    let mut car = 0;
    for i in 0..min(v.len(), n + 1) {
        let acc = comb.calc(n, i);
        if v[i].1 > acc + car {
            ans = "No";
        } else {
            car = acc + car - v[i].1;
        }
    }
    println!("{}", ans);
}

