fn solve() {
    input!{
        N:usize,
        s:[i64;1<<N],
    }
    let mut s=s;
    s.sort();

    let mut parents=vec![s.pop().unwrap()];
    // dbg!(&s,&parents);

    // M=1<<N
    // O(logM)
    'outer: loop {
        let mut new_parents = vec![];
        // O(M)
        for &par in &parents {
            if s.is_empty() {
                break 'outer;
            }
            // dbg!(&s);
            let res = {
                let mut bs = BinarySearch {
                    p: |i:usize| {
                        s[i]>=par
                    },
                    lower:0,
                    upper:s.len()-1,
                };
                bs.search()
            };
            // dbg!(res);
            if res.0.is_none() {
                println!("No");
                return;
            } else {
                // needs shifting 
                let x = s.remove(res.0.unwrap());
                new_parents.push(x);
            }
        }
        parents.append(&mut new_parents);
        // O(logM)
        parents.sort();
        parents.reverse();
    }

    println!("Yes");
}
struct BinarySearch<F> {
    p: F,
    lower: usize,
    upper: usize,
}
impl<F: Fn(usize) -> bool> BinarySearch<F> {
    fn search(&self) -> (Option<usize>, usize) {
        let lower = self.lower as i32;
        let upper = self.upper as i32;
        let mut lb = lower - 1;
        let mut ub = upper + 1;
        while ub - lb > 1 {
            let mid = (lb + ub) / 2;
            if (self.p)(mid as usize) {
                ub = mid;
            } else {
                lb = mid;
            }
        }
        let former = if lb < 0 { None } else { Some(lb as usize) };
        let latter = ub as usize;
        (former, latter)
    }
}
