            if let Some(&(nv, nindex)) = rests
                .range((Included(&(0, 0)), Excluded(&(v, 0))))
                .rev()
                .next()
            {
                nslimes.push(nv);
                rests.remove(&(nv, nindex));
            } else {
                println!("No");
                return;
            }
        }
        slimes = nslimes;
    }
    println!("Yes");
}

