fn solve() {
    let n = get!(usize);
    let mut s = get!([usize]);

    s.sort();
    let mut parents = vec![s[(1 << n) - 1]];
    let mut cands = BTreeMap::new();
    for e in s {
        *cands.entry(e).or_insert(0) += 1;
    }
    for _ in 0..n {
        let mut new_parents = Vec::new();
        for &p in &parents {
            let mut zero = None;
            for (key, value) in cands.iter_mut().rev() {
                if *key < p {
                    *value -= 1;
                    new_parents.push(*key);
                    if *value == 0 {
                        zero = Some(*key);
                    }
                }
            }
            if let Some(key) = zero {
                cands.remove(&key);
            }
        }
        parents.extend(&new_parents);
    }

    if parents.len() == 1 << n {
        println!("Yes");
    } else {
        println!("No");
    }
}

