fn solve(mut s: Vec<usize>) -> bool {
    s.sort();
    s.reverse();

    let mut len = 1;
    dbg!(&s);

    while len * 2 <= s.len() {
        for i in 0..len {
            if s[i] == s[len + i] {
                return false;
            }
        }
        len *= 2;
    }
    true
