    pub trait BinarySearchExt<T> {
        fn lower_bound_by<F: Fn(&T) -> bool>(&self, f: F) -> usize;
        fn lower_bound(&self, x: &T) -> usize;
        fn upper_bound(&self, x: &T) -> usize;
    }
    impl<T: Ord> BinarySearchExt<T> for [T] {
        fn lower_bound_by<F: Fn(&T) -> bool>(&self, f: F) -> usize {
            let mut low = 0;
            let mut high = self.len();
            while low < high {
                let mid = (low + high) / 2;
                if f(&self[mid]) {
                    high = mid;
                } else {
                    low = mid + 1;
                }
            }
            low
        }
        fn lower_bound(&self, x: &T) -> usize {
            self.lower_bound_by(|y| x <= y)
        }
        fn upper_bound(&self, x: &T) -> usize {
            self.lower_bound_by(|y| x < y)
        }
    }

    pub trait AtSliceExt<T> {
        fn rotate(&mut self, mid: usize);
    }
    impl<T> AtSliceExt<T> for [T] {
        fn rotate(&mut self, mid: usize) {
            {
                let (l, r) = self.split_at_mut(mid);
                l.reverse();
                r.reverse();
            }
            self.reverse()
        }
    }

    fn divisors<F: FnMut(usize)>(n: usize, mut f: F) {
        fn divisors_by<F: FnMut(usize)>(fs: &[(usize, usize)], mut n: usize, f: &mut F) {
            if fs.is_empty() {
                f(n);
                return;
            }
            let (p, c) = fs[0];
            for _ in 0..c + 1 {
                divisors_by(&fs[1..], n, f);
                n *= p;
            }
        }
        divisors_by(&factorize(n), 1, &mut f)
    }

    fn factorize(mut n: usize) -> Vec<(usize, usize)> {
        assert!(n != 0);

        fn try_push_factor(n: &mut usize, f: usize, fs: &mut Vec<(usize, usize)>) -> bool {
            let mut c = 0;
            while *n % f == 0 {
                *n /= f;
                c += 1;
            }
            if c != 0 {
                fs.push((f, c));
                true
            } else {
                false
            }
        }
        let mut fs = Vec::new();

        try_push_factor(&mut n, 2, &mut fs);
        let mut f = 3;
        let mut end = (n as f64).sqrt() as usize + 1;
        while f < end {
            if try_push_factor(&mut n, f, &mut fs) {
                end = (n as f64).sqrt() as usize + 1;
            }
            f += 2;
        }
        if n != 1 {
            fs.push((n, 1));
        }
        fs
    }

