    impl<T> VecVec32<T> {
        #[inline]
        pub fn new(len: usize, capacity: usize) -> Self {
            assert!(capacity < u32::max_value() as usize);
            VecVec32 {
                hs: vec![0; len],
                vs: Vec::with_capacity(capacity),
            }
        }

        #[inline]
        pub fn push(&mut self, idx: usize, value: T) {
            self.vs.push((value, self.hs[idx]));
            self.hs[idx] = self.vs.len() as u32;
        }

        #[inline]
        pub fn len(&self) -> usize {
            self.hs.len()
        }

        #[inline]
        pub fn get(&self, idx: usize) -> VecVec32Iter<T> {
            VecVec32Iter {
                s: self,
                i: self.hs[idx],
            }
        }
    }
    pub struct VecVec32Iter<'a, T: 'a> {
        s: &'a VecVec32<T>,
        i: u32,
    }
    impl<'a, T: 'a> Iterator for VecVec32Iter<'a, T> {
        type Item = &'a T;

        #[inline]
        fn next(&mut self) -> Option<Self::Item> {
            if self.i == 0 {
                None
            } else {
                let i = self.i as usize - 1;
                self.i = self.s.vs[i].1;
                Some(&self.s.vs[i].0)
            }
        }
    }

    pub fn gcd(a: usize, b: usize) -> usize {
        fn f(a: usize, b: usize) -> usize {
            let r = a % b;
            if r == 0 {
                b
            } else {
                f(b, r)
            }
        }
        f(max(a, b), min(a, b))
    }

    struct Array2<T> {
        len: (usize, usize),
        items: Vec<T>,
    }
    impl<T> Array2<T> {
        #[inline]
        fn new(len: (usize, usize), value: T) -> Self
        where
            T: Clone,
        {
            Array2 {
                len: len,
                items: vec![value; len.0 * len.1],
            }
        }
        #[inline]
        fn idx(&self, i: (usize, usize)) -> usize {
            assert!(i.0 < self.len.0);
            assert!(i.1 < self.len.1);
            i.0 + i.1 * self.len.0
        }
    }

    impl<T> Index<(usize, usize)> for Array2<T> {
        type Output = T;

        #[inline]
        fn index(&self, index: (usize, usize)) -> &T {
            &self.items[self.idx(index)]
        }
    }
    impl<T> IndexMut<(usize, usize)> for Array2<T> {
        #[inline]
        fn index_mut(&mut self, index: (usize, usize)) -> &mut T {
            let idx = self.idx(index);
            &mut self.items[idx]
        }
    }

    #[derive(PartialEq, PartialOrd)]
    pub struct OrdF64(pub f64);

    impl OrdF64 {
        pub fn new(value: f64) -> Self {
            assert!(!value.is_nan());
            OrdF64(value)
        }
    }

    impl Eq for OrdF64 {}
    impl Ord for OrdF64 {
        fn cmp(&self, other: &Self) -> Ordering {
            self.partial_cmp(&other).unwrap()
        }
    }

    pub fn binary_search<F: Fn(usize) -> bool>(len: usize, f: F) -> usize {
        let mut low = 0;
        let mut high = len;
        while low < high {
            let mid = (low + high) / 2;
            if f(mid) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        low
    }
}

