fn solve(mut parents: Vec<u32>, mut rest: Vec<u32>) -> bool {
    if rest.is_empty() { true } else {
        for i in 0..parents.len() {
            let child = rest.pop().unwrap();
            if child >= parents[i] {
                return false;
            }
            parents.push(child)
        }
        solve(parents, rest)
    }
}

