use std::collections::{BTreeMap, BinaryHeap};
use std::io::Read;
use std::ops::AddAssign;

fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut iter = buf.split_whitespace();
    let n: usize = iter.next().unwrap().parse().unwrap();
    let S: Vec<i32> = (0..(1 << n))
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();
    let mut counter: BTreeMap<i32, usize> = BTreeMap::new();

    for s in S {
        counter.entry(s).or_insert(0).add_assign(1);
    }

    let mut ranges = BinaryHeap::new();
    ranges.push(1 << n);

    for key in counter.keys().rev() {
        let &count = counter.get(key).unwrap();
        if count > ranges.len() {
            println!("No");
            return;
        } else {
            for _ in 0..count {
                let top = ranges.pop().unwrap();
                let left = (top - 1) / 2;
                let right = top - 1 - left;
                if left > 0 {
                    ranges.push(left);
                }

                if right > 0 {
                    ranges.push(right);
                }
            }
        }
    }
    println!("Yes");
}

