macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, $var:ident $($r:tt)*) => {
        let $var = parse_val!($it, usize);
        parse!($it $($r)*);
    };
}

#[allow(unused_macros)]
macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, ($($t: tt),*)) => {
        ($(parse_val!($it, $t)),*)
    };
    ($it: ident, u1) => {
        $it.next().unwrap().parse::<usize>().unwrap() -1
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, s: [usize; 1 << n]);
    let mut s: BTreeSet<(usize, usize)> = s.into_iter().enumerate().map(|(i, x)| (x, i)).collect();
    let si = *s.iter().rev().next().unwrap();
    let mut fixed = vec![si.0];
    s.remove(&si);
    let mut added = vec![];
    for i in 0..n {
        let mut cur = 0;
        let mut iter = s.iter().rev();
        added.clear();
        'outer: while cur < 1 << i {
            for &si in iter.by_ref() {
                if fixed[cur] > si.0 {
                    added.push(si);
                    cur += 1;
                    continue 'outer;
                }
            }
            println!("{}", "No");
            return;
        }
        for &a in &added {
            fixed.push(a.0);
            s.remove(&a);
        }
    }
    println!("{}", "Yes");
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

