pub trait Monoid {
    type T: Clone + PartialEq + std::fmt::Debug;
    fn id() -> Self::T;
    fn op(a: &Self::T, b: &Self::T) -> Self::T;
}
struct MIN;
impl Monoid for MIN {
    type T = u64;
    fn id() -> Self::T {
        INF_U64
    }
    fn op(a: &Self::T, b: &Self::T) -> Self::T {
        min(*a, *b)
    }
}

struct SqrtDecomposition<M: Monoid> {
    sqrt_N: usize,
    sub: Vec<M::T>,
    a: Vec<M::T>,
}
impl<M: Monoid> SqrtDecomposition<M> {
    //fn new(N: usize) -> SqrtDecomposition<M> {
    fn new(a: &Vec<M::T>) -> SqrtDecomposition<M> {
        let sqrt_N = (a.len() + 511) / 512;
        let mut sub = vec![M::id(); sqrt_N];
        let mut b = vec![M::id(); sqrt_N * 512];
        for i in 0..a.len() {
            b[i] = a[i].clone();
            sub[i / 512] = M::op(&sub[i / 512], &b[i]);
        }
        SqrtDecomposition {
            sqrt_N: sqrt_N,
            sub: sub,
            a: b,
        }
    }
    fn update(&mut self, i: usize, v: M::T) {
        let sub_index = i / 512;
        self.a[i] = v;
        let s = sub_index * 512;
        let e = sub_index * 512 + 512;
        self.sub[sub_index] = M::id();
        for j in s..e {
            self.sub[sub_index] = M::op(&self.sub[sub_index], &self.a[j]);
        }
    }
    fn query(&mut self, l: usize, r: usize) -> M::T {
        let sub_index = l / 512;
        let mut ret = M::id();
        for i in sub_index..self.sqrt_N {
            let s = i * 512;
            let e = i * 512 + 512;
            if l >= s && e <= r {
                ret = M::op(&ret, &self.sub[i]);
            } else {
                for j in s..e {
                    ret = M::op(&ret, &self.a[j]);
                }
            }
        }
        ret
    }
    fn query_custom<T>(
        &mut self,
        l: usize,
        r: usize,
        //check: fn(M::T) -> bool,
        check: T,
    ) -> Option<(M::T, usize)>
    where
        T: Fn(&M::T) -> bool,
    {
        let sub_index = l / 512;
        let mut ret = M::id();
        let mut index = 0;
        'outer: for i in sub_index..self.sqrt_N {
            let s = i * 512;
            let e = i * 512 + 512;

            if check(&self.sub[i]) {
                for j in s..e {
                    if check(&self.a[j]) {
                        ret = self.a[j].clone();
                        index = j;
                        break 'outer;
                    }
                }
            }
        }
        if ret == M::id() {
            return None;
        } else {
            return Some((ret, index));
        }
    }
}

