use std::collections::BinaryHeap;
fn solve() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let mut m: usize = 1 << n;
    let mut a: Vec<i32> = sc.vec(m);
    a.sort();
    let mut s = vec![];
    s.push(a[m - 1]);
    a[m - 1] = -1;

    for _ in 0..n {
        let mut p = s.clone();
        p.sort();
        let mut ai = m - 1;
        while p.len() > 0 {
            if a[ai] == -1 {
                if ai == 0 {
                    break;
                }
                ai -= 1;
                continue;
            }

            if a[ai] < p[p.len() - 1] {
                s.push(a[ai]);
                p.pop().unwrap();
                a[ai] = -1;
            }
            if ai == 0 {
                break;
            }
            ai -= 1;
        }
        if p.len() > 0 {
            println!("No");
            return;
        }
    }
    println!("Yes");
}

fn main() {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024) // 64MB
        .spawn(|| solve())
        .unwrap()
        .join()
        .unwrap();
}

