    for i in 0..n {
        let ys = xs[..xs.len() / 2].to_vec();
        let zs = xs[xs.len() / 2..].to_vec();
        for k in 0..ys.len() {
            if ys[k] >= zs[k] {
                writeln!(buf, "No");
