    let S: Vec<i32> = (0..(1 << n))
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();
    let mut counter = BTreeMap::new();

    for s in S {
        counter.entry(s).or_insert(0).add_assign(1);
    }

    let mut ranges = BinaryHeap::new();
    ranges.push(1 << n);
    for key in counter.keys().rev() {
        let &count = counter.get(key).unwrap();
        if count > ranges.len() {
            println!("No");
            return;
        } else {
            let mut tmp = vec![];
            for _ in 0..count {
                let top = ranges.pop().unwrap();
                let left = (top - 1) / 2;
                let right = top - 1 - left;
                if left > 0 {
                    tmp.push(left);
                }

                if right > 0 {
                    tmp.push(right);
                }
            }
            ranges.extend(tmp);
        }
    }
    println!("Yes");
}

