static BINARY: &'static str = "";
static PATH: &'static str = "/tmp/a.out";

fn main() {
    let gz = run(BINARY, "/usr/bin/base64", &["-d"]);
    let bin = run(gz, "/bin/gunzip", &[]);
    let mut file = File::create(PATH).unwrap();
    file.write_all(&bin).unwrap();
    let mut permissions = file.metadata().unwrap().permissions();
    drop(file);
