fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, s: [usize; 1 << n]);
    let mut s: BTreeSet<(usize, usize)> = s.into_iter().enumerate().map(|(i, x)| (x, i)).collect();
    let si = *s.iter().rev().next().unwrap();
    let mut fixed = vec![si.0];
    s.remove(&si);
    for i in 0..n {
        for j in 0..(1 << i) {
            if let Some(&si) = s.range(..(fixed[j], 0)).rev().next() {
                s.remove(&si);
                fixed.push(si.0);
            } else {
                println!("{}", "No");
                return;
            }
        }
    }
    assert_eq!(fixed.len(), 1 << n);
    assert_eq!(s.len(), 0);
    println!("{}", "Yes");
}

