fn solve() {
    let n = get!(usize);
    let mut s = get!([usize]);

    s.sort();
    let mut parents = vec![s[(1 << n) - 1]];
    let mut cands = s.into_iter().take((1 << n) - 1).collect::<Vec<_>>();
    for _ in 0..n {
        let mut new_parents = Vec::new();
        for &p in &parents {
            let mut new_cands = Vec::new();
            while let Some(next) = cands.pop() {
                if p > next {
                    new_parents.push(next);
                    break;
                } else {
                    new_cands.push(next);
                }
            }
            for e in new_cands.into_iter().rev() {
                cands.push(e);
            }
        }
        parents.extend(&new_parents);
    }

    if parents.len() == 1 << n {
        println!("Yes");
    } else {
        println!("No");
    }
}

