fn solve() {
    input!{
        N:usize,
        s:[i64;1<<N],
    }
    let mut s=s;
    s.sort();

    let mut parents=vec![s.pop()];
    // dbg!(&s,&parents);

    // M=1<<N
    // O(logM)
    'outer: loop {
        let mut new_parents = vec![];
        // O(M)
        for &p in &parents {
            if s.is_empty() {
                break 'outer;
            }

            let x=s.pop();
            // dbg!(&p,x);
            if p>x {
                new_parents.push(x);
            } else {
                println!("No");
                return;
            }
        }
        parents.append(&mut new_parents);
        // O(logM)
        parents.sort();
        parents.reverse();
    }

    println!("Yes");
}
fn solve0() {
    input!{
        N:usize,
        s:[i64;1<<N],
    }
    let mut s=s;
    s.sort();
    // dbg!(&s);
    // [i,j)
    let test=|i:usize,j:usize| {
        let n=(j-i)/2;
        let i0=i;
        let i1=i+n;
        for k in 0..n {
            if s[i0+k]>=s[i1+k] {
                return false
            }
        }
        return true
    };
    let mut ok=true;
    let mut i=0;
    let mut j=s.len();
    while j-i>=2 {
        //dbg!((i,j));
        if !test(i,j) {
            ok=false;
            break;
        }
        let n=j-i;
        i=i+n/2;
    }
    if ok {
        println!("Yes");
    } else {
        println!("No");
    }
}

