fn solve(mut parents: Vec<u32>, mut ss: Vec<Option<u32>>, n: usize) -> bool {
    for _ in 0..n {
        let len = parents.len();
        let mut i = 0;
        for s in ss.iter_mut().rev() {
            match s.clone() {
                None => continue,
                Some(x) => {
                    if x < parents[i] {
                        parents.push(x);
                        *s = None;
                        i += 1;
                        if i == len {
                            break;
                        }
                    }
                }
            }
        }
        if i < len {
            return false;
        }
    }
    true
}

